/*
 * Raspberry Pi 4 Model B - MLX91219 Current Sensor via ADS1115 ADC
 *
 * Hardware:
 *   - MLX91219 analog output -> ADS1115 AIN0
 *   - ADS1115 SDA/SCL -> Pi GPIO2/GPIO3 (I2C bus 1)
 *   - ADS1115 ADDR -> GND (I2C address 0x48)
 *
 * The MLX91219 is a Hall-effect current sensor with an analog output.
 * It has a sensitivity of 40 mV/A and a zero-current offset centered
 * at mid-supply.  The ADS1115 is used to digitize this analog signal.
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:    sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants (datasheet) ---- */
#define ADS1115_ADDR        0x48
#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/* Config register bit fields */
#define ADS1115_CFG_OS      0x8000  /* Operational status / single-shot start */
#define ADS1115_CFG_MUX_AIN0 0x4000 /* AIN0 single-ended (MUX[2:0]=100) */
#define ADS1115_CFG_PGA_4_096 0x0200 /* PGA = ±4.096 V (PGA[2:0]=001) */
#define ADS1115_CFG_MODE_SS  0x0100 /* Single-shot mode (MODE=1) */
#define ADS1115_CFG_DR_128  0x0080 /* Data rate 128 SPS (DR[2:0]=100) */
#define ADS1115_CFG_CQUE_NONE 0x0003 /* Disable comparator (CQUE=11) */

#define ADS1115_PGA_4_096_V 4.096
#define ADS1115_MAX_COUNT   32767.0  /* 16-bit signed, single-ended positive */

/* ---- MLX91219 constants ---- */
#define MLX91219_SENSITIVITY_MV_PER_A  40.0
#define MLX91219_ZERO_CURRENT_OFFSET_MV 250.0  /* Mid-supply offset */

#define I2C_BUS          1
#define SAMPLE_PERIOD_US 500000  /* 500 ms */
#define MAX_CONSEC_ERRORS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (big-endian on bus).    */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteI2CBlockData(handle, reg, &buf[1], 2) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (big-endian on bus).   */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X) failed\n", reg);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion and wait for completion.           */
static int ads1115_trigger_and_wait(int handle)
{
    uint16_t config = ADS1115_CFG_OS
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4_096
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) < 0)
        return -1;

    /* Poll the OS bit (bit 15) until it reads 1 (conversion done).
     * Timeout after ~100 ms (128 SPS -> ~8 ms per conversion). */
    for (int i = 0; i < 12; i++) {
        uint16_t cfg;
        if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & ADS1115_CFG_OS)
            return 0;
        gpioDelay(8000);  /* 8 ms */
    }
    fprintf(stderr, "[WARN] ADS1115 conversion timeout\n");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read the current in amperes.  Returns 0 on success, -1 on error.    */
static int read_current(int handle, double *current_out)
{
    if (ads1115_trigger_and_wait(handle) < 0)
        return -1;

    uint16_t raw;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &raw) < 0)
        return -1;

    /* Convert raw 16-bit signed value to signed int16_t */
    int16_t signed_raw = (int16_t)raw;

    /* Compute voltage: signed_raw * (PGA_V / 32768) */
    double voltage = (double)signed_raw * (ADS1115_PGA_4_096_V / 32768.0);

    /* Convert voltage to current using MLX91219 transfer function:
     *   I = (V - V_offset) / sensitivity
     *   V_offset = 0.25 V (mid-supply) -> 250 mV
     */
    double current = (voltage - (MLX91219_ZERO_CURRENT_OFFSET_MV / 1000.0))
                   / (MLX91219_SENSITIVITY_MV_PER_A / 1000.0);

    *current_out = current;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at ADS1115 address 0x48 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading the config register */
    uint16_t cfg_check;
    if (ads1115_read_reg(g_i2c_handle, ADS1115_REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "[FATAL] ADS1115 not responding at 0x%02X\n", ADS1115_ADDR);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 Current Monitor (ADS1115 @ 0x%02X)\n", ADS1115_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    int consecutive_errors = 0;

    while (g_running) {
        double current;
        if (read_current(g_i2c_handle, &current) == 0) {
            printf("Current: %.3f A\n", current);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "[ERROR] Failed to read current (attempt %d/%d)\n",
                    consecutive_errors, MAX_CONSEC_ERRORS);
            if (consecutive_errors >= MAX_CONSEC_ERRORS) {
                fprintf(stderr, "[FATAL] Max consecutive errors reached. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean up */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

