#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADC_CHANNEL 0
#define ADC_GAIN 0x0200  /* +/-4.096V */
#define ADC_MODE_SINGLE 0x0100
#define ADC_DR_128SPS 0x0080
#define ADC_OS_BEGIN 0x8000
#define ADC_CQUE_NONE 0x0003
#define TEMP_THRESHOLD 60.0
#define DEBOUNCE_MS 50
#define POLL_DELAY_US 100000
#define BUZZER_DURATION_US 2000000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t flame_event = 0;
static volatile uint32_t last_flame_tick = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0);
    return 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }
    /* Config: OS=1, MUX=AIN0, PGA=+/-4.096V, MODE=single, DR=128SPS, CQUE=none */
    uint16_t config = ADC_OS_BEGIN | (ADC_CHANNEL << 12) | ADC_GAIN |
                      ADC_MODE_SINGLE | ADC_DR_128SPS | ADC_CQUE_NONE;
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, cfg, 3) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp) {
    if (i2c_handle < 0) return -1;
    char reg = ADS1115_REG_CONFIG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Failed to set ADS1115 config register: %s\n", strerror(errno));
        return -1;
    }
    char buf[2];
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read ADS1115 config: %s\n", strerror(errno));
        return -1;
    }
    uint16_t config = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    if (!(config & 0x8000)) {
        /* Conversion not complete yet; wait and retry */
        gpioDelay(10000);
        return -1;
    }
    /* Re-select conversion register to read raw value */
    reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Failed to set ADS1115 conversion register: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to read ADS1115 conversion: %s\n", strerror(errno));
        return -1;
    }
    int16_t raw = (int16_t)(((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1]);
    /* PGA = +/-4.096V -> 1 bit = 125 uV; 16-bit signed, 0 at 0V */
    float voltage = (float)raw * 0.000125f;
    /* Linear map: 0V -> 20C, 3.3V -> 80C */
    *temp = 20.0f + (voltage / 3.3f) * 60.0f;
    return 0;
}

static void flame_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    if (level == 0) {  /* Falling edge = flame detected */
        uint32_t elapsed = tick - last_flame_tick;
        if (elapsed >= (uint32_t)(DEBOUNCE_MS * 1000)) {
            flame_event = 1;
            last_flame_tick = tick;
        }
    }
}

static void log_event(const char *msg) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s: %s\n", ts, msg);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() != 0) return 1;
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }
    log_file = fopen("fire_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open fire_log.txt: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, flame_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on GPIO%d\n", FLAME_SENSOR_PIN);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame = gpioRead(FLAME_SENSOR_PIN);
        float temp = 0.0f;
        int temp_ok = (read_temperature(&temp) == 0);

        if (flame_event) {
            flame_event = 0;
            if (flame == 0) {
                if (temp_ok && temp > TEMP_THRESHOLD) {
                    log_event("Flame and high temperature detected!");
                    gpioWrite(BUZZER_PIN, 1);
                    gpioDelay(BUZZER_DURATION_US);
                    gpioWrite(BUZZER_PIN, 0);
                } else if (flame == 0) {
                    log_event("Flame detected!");
                }
            }
        } else if (temp_ok && temp > TEMP_THRESHOLD) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Temperature exceeds threshold: %.2f C", temp);
            log_event(msg);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioSetISRFuncEx(FLAME_SENSOR_PIN, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

