#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* Calibration parameters for the MICS-4514 CO sensor.
 * These are placeholders; replace with actual calibration data
 * from the sensor datasheet for accurate readings. */
static const float CO_R0 = 10000.0f;   /* Sensor resistance in clean air (Ohms) */
static const float CO_VCC = 3.3f;      /* ADC reference voltage (V) */
static const float CO_ADC_MAX = 32767.0f; /* 16-bit ADC full-scale (counts) */
static const float CO_PPM_MAX = 1000.0f; /* Maximum expected CO concentration (PPM) */

/* Log file path */
static const char *log_file = LOG_FILE;

/* Global variables for graceful shutdown */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Function to read raw 16-bit ADC value from the sensor via I2C.
 * Returns 0 on success, -1 on error. */
static int read_sensor_raw(uint16_t *raw_value) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C handle is invalid.\n");
        return -1;
    }

    /* Read 2 bytes from the sensor register (placeholder address 0x00) */
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: I2C read failed (expected 2 bytes, got %d).\n", bytes_read);
        return -1;
    }

    *raw_value = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    return 0;
}

/* Function to convert raw ADC value to CO concentration in PPM.
 * Uses a logarithmic calibration curve. */
static float convert_to_ppm(uint16_t raw_value) {
    if (raw_value == 0) {
        return 0.0f;
    }

    /* Convert raw ADC value to voltage */
    float voltage = (float)raw_value / CO_ADC_MAX * CO_VCC;

    /* Convert voltage to sensor resistance (assuming a voltage divider or
     * transimpedance amplifier; replace with actual transfer function) */
    float sensor_resistance = voltage * 10.0f; /* Example: R_load = 10 Ohms */

    /* Calculate CO concentration using a logarithmic calibration curve.
     * This is a placeholder; replace with the actual calibration curve
     * from the sensor datasheet. */
    float ratio = sensor_resistance / CO_R0;
    float log_ratio = log10f(ratio);
    float ppm = powf(10.0f, (log_ratio * 2.0f) - 1.0f); /* Example curve */

    /* Clamp the result to the expected range */
    if (ppm < 0.0f) ppm = 0.0f;
    if (ppm > CO_PPM_MAX) ppm = CO_PPM_MAX;

    return ppm;
}

/* Function to log the CO concentration to a file */
static void log_co_concentration(float ppm) {
    FILE *fp = fopen(log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s for writing.\n", log_file);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(fp);
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d.\n", I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not set SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not set SIGTERM handler.\n");
    }

    printf("CO Sensor Monitoring Started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t raw_value = 0;

        if (read_sensor_raw(&raw_value) == 0) {
            float ppm = convert_to_ppm(raw_value);
            log_co_concentration(ppm);
            printf("CO Concentration: %.2f PPM\n", ppm);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        /* Sleep for the sample interval, checking running flag every second */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    /* Clean up resources */
    printf("\nShutting down...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

