#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x2A
#define READ_INTERVAL_SEC 5
#define ALERT_THRESHOLD 25.0f
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int handle, uint16_t *co_raw, uint16_t *no2_raw) {
    char buf[4];
    int bytes_read = i2cReadDevice(handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *co_raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *no2_raw = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

static float calculate_co_ppm(uint16_t co_raw) {
    return (float)co_raw * 0.01f;
}

static int log_co_level(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, CO: %.2f PPM\n", timestamp, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", ALERT_LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, ALERT: CO level exceeded threshold (%.2f PPM > %.2f PPM)\n", timestamp, co_ppm, ALERT_THRESHOLD);
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("CO Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t co_raw, no2_raw;
        if (read_sensor_data(i2c_handle, &co_raw, &no2_raw) == 0) {
            float co_ppm = calculate_co_ppm(co_raw);
            if (log_co_level(co_ppm) != 0) {
                fprintf(stderr, "Warning: failed to log CO level\n");
            }
            if (co_ppm > ALERT_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Warning: failed to log alert\n");
                }
            }
        } else {
            fprintf(stderr, "Sensor read failed, retrying in %d seconds...\n", READ_INTERVAL_SEC);
        }
        gpioSleep(PI_TIME_RELATIVE, READ_INTERVAL_SEC, 0);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

