#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define ADC_REG 0x00
#define SAMPLE_INTERVAL_US 100000
#define MIC_SENSITIVITY_DBV_PER_PA -38.0
#define REFERENCE_PRESSURE_PA 20e-6
#define ERROR_VALUE -999.0

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double calculate_spl(int16_t raw_data) {
    double voltage = (double)raw_data / 32768.0;
    double pressure = voltage * 100.0e-3;
    double spl = 20.0 * log10(fabs(pressure / REFERENCE_PRESSURE_PA));
    return spl;
}

static int read_mic_data(int i2c_handle, int16_t *out_data) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ADC_REG, buf, 2);
    if (result != 2) {
        return -1;
    }
    *out_data = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static void log_data(double spl1, double spl2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("audio_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening audio_log.txt");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, spl1, spl2);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, MIC1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for mic1 at 0x%02X\n", MIC1_ADDR);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, MIC2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for mic2 at 0x%02X\n", MIC2_ADDR);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Acoustic Leak Detection System started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t raw_data1 = 0, raw_data2 = 0;
        double spl1 = 0.0, spl2 = 0.0;

        if (read_mic_data(i2c_handle1, &raw_data1) != 0) {
            fprintf(stderr, "Error reading mic1 data\n");
            spl1 = ERROR_VALUE;
        } else {
            spl1 = calculate_spl(raw_data1);
        }

        if (read_mic_data(i2c_handle2, &raw_data2) != 0) {
            fprintf(stderr, "Error reading mic2 data\n");
            spl2 = ERROR_VALUE;
        } else {
            spl2 = calculate_spl(raw_data2);
        }

        log_data(spl1, spl2);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    return 0;
}

