#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define THRESHOLD 0.7
#define SAMPLE_INTERVAL_US 1000 // 1 ms
#define SAMPLE_WINDOW_MS 100
#define NUM_SAMPLES (SAMPLE_WINDOW_MS * 1000 / SAMPLE_INTERVAL_US)

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_mic(int channel);
double calculate_rms(int *samples, int num_samples);
void check_threshold(double rms1, double rms2);
void log_data(double rms1, double rms2);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read data from the MCP3008 ADC via SPI
int read_mic(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI command format for single-ended mode
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00;

    int handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }

