#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define OVERCURRENT_THRESHOLD 50.0 // Amperes
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define ADC_VREF 5.0 // Volts
#define ADC_MAX 32767.0 // 16-bit signed max for single-ended
#define MLX91204_V_MIN 0.5 // Volts
#define MLX91204_V_MAX 4.5 // Volts
#define MLX91204_I_MAX 100.0 // Amperes

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

// ADS1115 Config: A0 single-ended, PGA 4.096V, 128 SPS, continuous
#define ADS1115_CONFIG_BASE 0x8000 // Bit 15: Operational status (1 = start conversion)
#define ADS1115_CONFIG_MUX_A0 0x4000 // Bits 14-12: AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // Bits 11-9: PGA 4.096V
#define ADS1115_CONFIG_DR_128SPS 0x0080 // Bits 7-5: 128 SPS
#define ADS1115_CONFIG_CQUE_NONE 0x0003 // Bits 1-0: Disable comparator

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_ads1115_raw(int *raw_value);
float convert_to_current(int raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Initialize I2C communication with ADS1115
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %s\n", I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }

    // Configure ADS1115: A0 single-ended, PGA 4.096V, 128 SPS, continuous
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_A0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE;
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

// Read raw ADC value from ADS1115 channel A0
int read_ads1115_raw(int *raw_value) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    char data_buf[2];

    // Write pointer to conversion register
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register: %s\n", strerror(errno));
        return -1;
    }

    // Read 2 bytes of conversion data
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115: %s\n", strerror(errno));
        return -1;
    }

    *raw_value = (data_buf[0] << 8) | data_buf[1];
    return 0;
}

// Convert raw ADC value to current (Amperes)
float convert_to_current(int raw_value) {
    float voltage = (float)raw_value / ADC_MAX * ADC_VREF;
    if (voltage < MLX91204_V_MIN) {
        return 0.0;
    }
    if (voltage > MLX91204_V_MAX) {
        return MLX91204_I_MAX;
    }
    return (voltage - MLX91204_V_MIN) / (MLX91204_V_MAX - MLX91204_V_MIN) * MLX91204_I_MAX;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average of values in circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    control_led(0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer current_buffer = {0};
    current_buffer.head = 0;
    current_buffer.count = 0;

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_value;
        if (read_ads1115_raw(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(&current_buffer, current);

            float average_current = calculate_average(&current_buffer);
            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);

            if (average_current > OVERCURRENT_THRESHOLD) {
                control_led(1);
                printf("OVERCURRENT DETECTED! LED ON\n");
            } else {
                control_led(0);
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

