#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define LOG_FILE "moisture_log.csv"
#define SAMPLE_INTERVAL 5
#define NUM_SENSORS 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int spi_fd, struct gpiod_line *cs_line, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS line");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to de-assert CS line");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float map_adc_to_moisture(int adc_value) {
    if (adc_value < 0) return 0.0f;
    if (adc_value > 1023) return 100.0f;
    return (float)adc_value / 1023.0f * 100.0f;
}

static int log_data(const char *filename, float moisture1, float moisture2) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return 1;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("Failed to get CS line (GPIO8)");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "mcp3008-cs", 1) < 0) {
        perror("Failed to request CS line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &(uint32_t){SPI_SPEED}) < 0) {
        perror("Failed to set SPI speed");
        goto cleanup;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    int file_exists = (fp != NULL);
    if (fp) fclose(fp);

    if (!file_exists) {
        fp = fopen(LOG_FILE, "w");
        if (fp) {
            fprintf(fp, "Timestamp,Moisture1,Moisture2\n");
            fclose(fp);
        } else {
            perror("Failed to create log file");
            goto cleanup;
        }
    }

    printf("Starting moisture monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_values[NUM_SENSORS];
        int read_errors = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            adc_values[i] = read_mcp3008(spi_fd, cs_line, i);
            if (adc_values[i] < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                read_errors++;
            }
        }

        if (read_errors == NUM_SENSORS) {
            fprintf(stderr, "All sensor reads failed, skipping sample.\n");
        } else {
            float moisture1 = map_adc_to_moisture(adc_values[0]);
            float moisture2 = map_adc_to_moisture(adc_values[1]);

            if (log_data(LOG_FILE, moisture1, moisture2) < 0) {
                fprintf(stderr, "Error logging data.\n");
            } else {
                printf("Moisture1: %.2f%%, Moisture2: %.2f%%\n", moisture1, moisture2);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

cleanup:
    printf("\nCleaning up...\n");
    close(spi_fd);
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    return 0;
}

