#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define VREF 3.3
#define MAX_ADC_VALUE 1023
#define LOG_FILE "current_log.csv"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *shutdown_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    shutdown_line = gpiod_chip_get_line(chip, MOTOR_SHUTDOWN_PIN);
    if (!shutdown_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(shutdown_line, "motor_shutdown", 1) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", MOTOR_SHUTDOWN_PIN, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        shutdown_line = NULL;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (spi_fd < 0) return -1;

    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI read attempt %d failed: %s\n", attempt + 1, strerror(errno));
        usleep(10000);
    }

    return -1;
}

static double adc_to_current(int adc_value) {
    double voltage = (double)adc_value / (double)MAX_ADC_VALUE * VREF;
    return (voltage - OFFSET) / SENSITIVITY;
}

static int log_current(double current) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Current(A)\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f\n", timestamp, current);
    fclose(fp);
    return 0;
}

static void shutdown_motor(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 0);
        printf("Motor shutdown triggered (GPIO%d LOW)\n", MOTOR_SHUTDOWN_PIN);
    }
}

static void enable_motor(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        printf("Motor re-enabled (GPIO%d HIGH)\n", MOTOR_SHUTDOWN_PIN);
    }
}

static void cleanup(void) {
    if (shutdown_line) {
        gpiod_line_set_value(shutdown_line, 1);
        gpiod_line_release(shutdown_line);
        shutdown_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        close(spi_fd);
        spi_fd = -1;
        return 1;
    }

    printf("MLX91211 Current Sensor Interface (libgpiod + spidev)\n");
    printf("Sensor: MLX91211 via MCP3008 ADC on SPI0 (CE0)\n");
    printf("Motor shutdown pin: GPIO%d\n", MOTOR_SHUTDOWN_PIN);
    printf("Overcurrent threshold: %.1f A\n", OVERCURRENT_THRESHOLD);
    printf("Sampling every %d second(s)\n", SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit\n\n");

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double current = adc_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current reading\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected: %.2f A > %.1f A\n", current, OVERCURRENT_THRESHOLD);
            shutdown_motor();
            sleep(SAMPLE_INTERVAL);
            enable_motor();
        } else {
            printf("Current: %.2f A\n", current);
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

