#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0   /* seconds */
#define MAX_CONSEC_ERR 10

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the 16-bit pressure value from the MLX90817                   */
/* Returns 0 on success (stores raw value in *out), -1 on error        */
/* ------------------------------------------------------------------ */
static int read_pressure_raw(uint16_t *out)
{
    char buf[2];
    int  bytes;

    if (out == NULL) {
        return -1;
    }

    /* Point to the pressure register */
    if (i2cWriteByte(g_i2c_handle, PRESSURE_REG) < 0) {
        fprintf(stderr, "Error: i2cWriteByte (reg 0x%02X) failed\n",
                PRESSURE_REG);
        return -1;
    }

    /* Small delay so the sensor has time to clock out the data */
    time_sleep(0.001);

    /* Read two bytes (big-endian on the wire) */
    bytes = i2cReadDevice(g_i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error: i2cReadDevice returned %d (expected 2)\n",
                bytes);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw 16-bit value to kPa                                      */
/* ------------------------------------------------------------------ */
static float convert_to_kPa(uint16_t raw)
{
    return ((float)raw / 65535.0f) * 500.0f;
}

/* ------------------------------------------------------------------ */
/* Write one CSV row with an ISO 8601 UTC timestamp                    */
/* ------------------------------------------------------------------ */
static int log_pressure(float pressure_kPa)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t raw;
    float    pressure_kPa;
    int      consecutive_errors = 0;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C device ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file once ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if the file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error: cannot write header to log file\n");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    printf("MLX90817 pressure logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (read_pressure_raw(&raw) == 0) {
            pressure_kPa = convert_to_kPa(raw);
            if (log_pressure(pressure_kPa) != 0) {
                fprintf(stderr, "Warning: failed to log reading\n");
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: pressure read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Fatal: %d consecutive I2C failures — "
                                "sensor may be absent or bus error.\n",
                        consecutive_errors);
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

