/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t raw;
    float    pressure_kPa;
    int      consecutive_errors = 0;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C device ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file once ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if the file is empty */
    if (ftell(g_log_file) == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            fprintf(stderr, "Error: cannot write header to log file\n");
            cleanup();
            return EXIT_FAILURE;
        }
        fflush(g_log_file);
    }

    printf("MLX90817 pressure logger started. Logging to %s every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (read_pressure_raw(&raw) == 0) {
            pressure_kPa = convert_to_kPa(raw);
            if (log_pressure(pressure_kPa) != 0) {
                fprintf(stderr, "Warning: failed to log reading\n");
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: pressure read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSEC_ERR) {
                fprintf(stderr, "Fatal: %d consecutive I2C failures — "
                                "sensor may be absent or bus error.\n",
                        consecutive_errors);
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

