#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0f
#define MAX_RETRIES 3

/* ADS1115 config: single-shot, AIN0 single-ended, gain 2/3 (6.144V FSR),
   128 SPS, no comparator, start conversion */
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_2_048 0x0200
#define ADS1115_CONFIG_DR_128 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG (ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0 | \
                        ADS1115_CONFIG_PGA_2_048 | ADS1115_CONFIG_DR_128 | \
                        ADS1115_CONFIG_CQUE_NONE)

#define ADC_VREF 6.144f
#define ADC_MAX 32767.0f
#define PRESSURE_V_MIN 0.0f
#define PRESSURE_V_MAX 5.0f
#define PRESSURE_KPA_MIN 0.0f
#define PRESSURE_KPA_MAX 400.0f
#define TEMP_V_MIN 1.0f
#define TEMP_V_MAX 2.0f
#define TEMP_C_MIN 0.0f
#define TEMP_C_MAX 100.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int16_t read_ads1115_channel(int handle, uint16_t mux) {
    uint16_t config = ADS1115_CONFIG | mux;
    char cfg[3];
    cfg[0] = ADS1115_REG_CONFIG;
    cfg[1] = (config >> 8) & 0xFF;
    cfg[2] = config & 0xFF;

    if (i2cWriteDevice(handle, cfg, 3) < 0) return -1;

    gpioDelay(10000); /* 10 ms conversion wait */

    char reg[1] = { ADS1115_REG_CONVERSION };
    if (i2cWriteDevice(handle, reg, 1) < 0) return -1;

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;

    return (int16_t)((data[0] << 8) | data[1]);
}

static float convert_adc_to_pressure(int16_t adc) {
    float voltage = (float)adc * ADC_VREF / ADC_MAX;
    if (voltage < PRESSURE_V_MIN) voltage = PRESSURE_V_MIN;
    if (voltage > PRESSURE_V_MAX) voltage = PRESSURE_V_MAX;
    return (voltage - PRESSURE_V_MIN) * (PRESSURE_KPA_MAX - PRESSURE_KPA_MIN) /
           (PRESSURE_V_MAX - PRESSURE_V_MIN) + PRESSURE_KPA_MIN;
}

static float convert_adc_to_temperature(int16_t adc) {
    float voltage = (float)adc * ADC_VREF / ADC_MAX;
    if (voltage < TEMP_V_MIN) voltage = TEMP_V_MIN;
    if (voltage > TEMP_V_MAX) voltage = TEMP_V_MAX;
    return (voltage - TEMP_V_MIN) * (TEMP_C_MAX - TEMP_C_MIN) /
           (TEMP_V_MAX - TEMP_V_MIN) + TEMP_C_MIN;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", ADS1115_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 Pressure Sensor Interface (ADS1115 ADC)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int16_t pressure_adc = -1, temp_adc = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && running) {
            pressure_adc = read_ads1115_channel(i2c_handle, ADS1115_CONFIG_MUX_AIN0);
            if (pressure_adc >= 0) break;
            retries++;
            gpioDelay(100000); /* 100 ms backoff */
        }

        if (pressure_adc < 0) {
            fprintf(stderr, "Error: Failed to read pressure ADC after %d retries.\n", MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            sleep(1);
            continue;
        }

        retries = 0;
        while (retries < MAX_RETRIES && running) {
            temp_adc = read_ads1115_channel(i2c_handle, ADS1115_CONFIG_MUX_AIN0 + 1);
            if (temp_adc >= 0) break;
            retries++;
            gpioDelay(100000);
        }

        if (temp_adc < 0) {
            fprintf(stderr, "Error: Failed to read temperature ADC after %d retries.\n", MAX_RETRIES);
            gpioWrite(LED_GPIO, 0);
            sleep(1);
            continue;
        }

        float pressure = convert_adc_to_pressure(pressure_adc);
        float temperature = convert_adc_to_temperature(temp_adc);

        printf("Pressure: %.2f kPa, Temperature: %.2f C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        sleep(1);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

