#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define GPIO_SHUTDOWN 27
#define OVERCURRENT_THRESHOLD 10.0
#define SENSOR_SENSITIVITY 0.066
#define VCC 3.3
#define ADC_MAX 1024.0
#define SAMPLE_INTERVAL_US 100000

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return ((double)adc_value / ADC_MAX) * VCC;
}

static double voltage_to_current(double voltage) {
    return (voltage - (VCC / 2.0)) / SENSOR_SENSITIVITY;
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file);
    }
    printf("%s: %s\n", timestamp, event);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_SHUTDOWN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0);
    log_file = fopen("current_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    log_event("Program started");
    while (!terminate) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            log_event("ADC read error");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        double voltage = adc_to_voltage(adc);
        if (voltage < 0.0) {
            log_event("Voltage conversion error");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        double current = voltage_to_current(voltage);
        char log_buf[128];
        snprintf(log_buf, sizeof(log_buf), "Current: %.2f A", current);
        log_event(log_buf);
        if (current > OVERCURRENT_THRESHOLD) {
            log_event("OVERCURRENT DETECTED! Shutting down motor.");
            gpioWrite(GPIO_SHUTDOWN, 1);
            log_event("Motor shutdown triggered.");
            break;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

