#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0
#define SPI_SPEED      1000000          /* 1 MHz */
#define SPI_FLAGS      0                /* mode 0, active-low CE */
#define ADC_CHANNEL    0                /* MCP3008 channel 0 */
#define LOG_FILE       "methane_log.txt"
#define LEAK_THRESHOLD 1000.0f          /* PPM */
#define MAX_PPM        5000.0f          /* calibration scale */
#define SAMPLE_PERIOD  1                /* seconds */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (dummy for clocking data out)
     * Result: ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float adc_to_ppm(int adc_value)
{
    return ((float)adc_value / 1023.0f) * MAX_PPM;
}

static void log_reading(float ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %.2f PPM\n", ts, ppm);
    fclose(fp);
}

static void check_leak(float ppm)
{
    if (ppm > LEAK_THRESHOLD) {
        fprintf(stderr, "ALARM: Methane leak detected! Concentration: %.2f PPM\n", ppm);
    }
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Methane monitoring started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- main loop --- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            /* SPI error already reported; back off briefly and retry */
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float ppm = adc_to_ppm(adc);
        log_reading(ppm);
        check_leak(ppm);

        sleep(SAMPLE_PERIOD);
    }

    /* --- graceful shutdown --- */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

