#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_CONFIG_BASE 0x8000 // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0 0x4000 // AIN0 vs GND
#define ADS1115_CONFIG_PGA_4_096V 0x0200 // +/-4.096V range
#define ADS1115_CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define ADS1115_CONFIG_DR_128SPS 0x0080 // 128 SPS
#define ADS1115_CONFIG_CQUE_NONE 0x0003 // Disable comparator
#define ADS1115_CONFIG (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

#define VOLTAGE_OFFSET 0.5 // Volts at 0 kPa
#define VOLTAGE_SENSITIVITY 0.1 // Volts per kPa
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_ads1115_raw(int *raw_value);
double raw_to_voltage(int raw_value);
double voltage_to_pressure(double voltage);
int log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Initialize I2C communication with ADS1115
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw 16-bit value from ADS1115
int read_ads1115_raw(int *raw_value) {
    char config_buf[3];
    char reg_buf[2];
    char data_buf[2];
    int result;

    // Write config to start a single conversion
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    config_buf[2] = ADS1115_CONFIG & 0xFF;
    result = i2cWriteDevice(i2c_handle, config_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Error writing config to ADS1115: %d\n", result);
        return -1;
    }

    // Wait for conversion to complete (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Set pointer to conversion register
    reg_buf[0] = ADS1115_REG_CONVERSION;
    result = i2cWriteDevice(i2c_handle, reg_buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error setting conversion register pointer: %d\n", result);
        return -1;
    }

    // Read 2 bytes
    result = i2cReadDevice(i2c_handle, data_buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading conversion data: %d\n", result);
        return -1;
    }

    *raw_value = (data_buf[0] << 8) | data_buf[1];
    return 0;
}

// Convert raw ADC value to voltage
double raw_to_voltage(int raw_value) {
    // 16-bit signed, +/-4.096V range -> 1 bit = 125 uV
    return ((double)raw_value / 32767.0) * 4.096;
}

// Convert voltage to pressure (kPa) using linear transfer function
double voltage_to_pressure(double voltage) {
    return (voltage - VOLTAGE_OFFSET) / VOLTAGE_SENSITIVITY;
}

// Log pressure reading with timestamp to file
int log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int raw_value;
        if (read_ads1115_raw(&raw_value) == 0) {
            double voltage = raw_to_voltage(raw_value);
            double pressure = voltage_to_pressure(voltage);

            // Validate pressure range (0-100 kPa)
            if (pressure >= 0.0 && pressure <= 100.0) {
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Error logging pressure.\n");
                }
            } else {
                fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Error reading pressure data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

