#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3208_CS 8
#define HUMIDITY_CHANNEL 0
#define TEMPERATURE_CHANNEL 1
#define HUMIDITY_THRESHOLD 80.0
#define SUPPLY_VOLTAGE 5.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SENDER "sender@example.com"

#define BETA 3950.0
#define R0 10000.0
#define T0 298.15
#define RREF 10000.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    gpioWrite(MCP3208_CS, 0);
    int ret = spiXfer(spi_handle, tx, rx, 3);
    gpioWrite(MCP3208_CS, 1);
    if (ret != 3) return -1;
    return ((rx[1] & 0x0F) << 8) | rx[2];
}

float read_humidity() {
    int raw = read_mcp3208(HUMIDITY_CHANNEL);
    if (raw < 0) return -1.0;
    float voltage = (raw / 4095.0) * SUPPLY_VOLTAGE;
    return (voltage - 0.824) / 0.0315;
}

float read_temperature() {
    int raw = read_mcp3208(TEMPERATURE_CHANNEL);
    if (raw < 0) return -1.0;
    float vtherm = (raw / 4095.0) * SUPPLY_VOLTAGE;
    float rtherm = RREF * (SUPPLY_VOLTAGE / vtherm - 1.0);
    float t = 1.0 / (BETA / (log(rtherm / R0) + BETA / T0) + 1.0 / T0) - 273.15;
    return t;
}

void send_email_alert(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\n\nHumidity: %.2f%%, Temperature: %.2fC\" | ssmtp %s",
             humidity, temperature, EMAIL_RECIPIENT);
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "[%s] Failed to send email alert\n", timestamp);
    }
}

void log_data(float humidity, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "[%s] Error: Log file not open\n", timestamp);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(MCP3208_CS, PI_OUTPUT);
    gpioWrite(MCP3208_CS, 1);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    while (running) {
        float humidity = read_humidity();
        float temperature = read_temperature();
        if (humidity < 0 || temperature < -50) {
            fprintf(stderr, "Sensor read error, retrying...\n");
            sleep(5);
            continue;
        }
        log_data(humidity, temperature);
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }
        sleep(60);
    }
    if (log_file) fclose(log_file);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

