#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define CS_PIN 8

#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2

#define SUPPLY_VOLTAGE 3.3
#define SENSITIVITY 0.3
#define ZERO_G_OFFSET 1.65
#define IMPACT_THRESHOLD 2.0
#define SAMPLE_RATE 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    gpioWrite(CS_PIN, 0);
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    gpioWrite(CS_PIN, 1);

    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_acceleration(int adc_value) {
    double voltage = (double)adc_value / 1023.0 * SUPPLY_VOLTAGE;
    return (voltage - ZERO_G_OFFSET) / SENSITIVITY;
}

static void log_data(int x, int y, int z, double mag) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.2f\n", timestamp, x, y, z, mag);
    fflush(log_file);
}

static void detect_impact(double mag) {
    if (mag > IMPACT_THRESHOLD) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,IMPACT DETECTED,%.2f\n", timestamp, mag);
        fflush(log_file);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(CS_PIN, 1);

    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("ADXL335 impact logger started. Press Ctrl+C to stop.\n");

    while (running) {
        int x = read_mcp3008(ADXL335_X_CHANNEL);
        int y = read_mcp3008(ADXL335_Y_CHANNEL);
        int z = read_mcp3008(ADXL335_Z_CHANNEL);

        if (x < 0 || y < 0 || z < 0) {
            fprintf(stderr, "ADC read error, skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double x_g = calculate_acceleration(x);
        double y_g = calculate_acceleration(y);
        double z_g = calculate_acceleration(z);
        double mag = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);

        log_data(x, y, z, mag);
        detect_impact(mag);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

