/*
 * Si1172-A30-GMR Optical Heart Rate Sensor reader for Raspberry Pi Zero W
 * Uses pigpio for I2C communication on bus 1, address 0x49.
 *
 * NOTE: The Si1172 requires a proprietary algorithm to convert raw PPG
 * samples into HR and SpO2 values. This program reads the 16-bit IR and
 * RED ADC values from the FIFO as proxy data and logs them as HR (bpm)
 * and SpO2 (%). For a production SpO2 measurement, use the Silicon Labs
 * Si1172 SDK with the appropriate calibration and algorithm.
 *
 * Build: gcc -Wall -o si1172_reader si1172_reader.c -lpigpio -lrt
 * Run:   sudo ./si1172_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x49
#define LOG_FILE       "biometric_log.csv"
#define SAMPLE_PERIOD  1.0  /* seconds */

/* Si1172 register addresses (command-based protocol) */
#define REG_COMMAND    0xC0
#define REG_FIFO_DATA  0xC1
#define REG_DATA0      0xC2
#define REG_DATA1      0xC3
#define REG_DATA2      0xC4

/* Command codes for the Si1172 command register */
#define CMD_RESET      0x01
#define CMD_START      0x02
#define CMD_READ_FIFO  0x03

/* Error codes */
#define ERR_OK         0
#define ERR_I2C        1
#define ERR_SENSOR     2

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a command byte to the Si1172 command register                 */
/* ------------------------------------------------------------------ */
static int si1172_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByteData(handle, REG_COMMAND, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(cmd=0x%02X) failed: %d\n",
                cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers     */
/* ------------------------------------------------------------------ */
static int si1172_read16(int handle, uint8_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadWordData(reg=0x%02X) failed: %d\n",
                reg, rc);
        return -1;
    }
    /* pigpio returns the word as (high_byte << 8) | low_byte */
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1172 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1172_init(int handle)
{
    /* 1. Software reset */
    if (si1172_write_cmd(handle, CMD_RESET) < 0)
        return -1;
    time_sleep(0.025);  /* allow reset to complete */

    /* 2. Start measurement */
    if (si1172_write_cmd(handle, CMD_START) < 0)
        return -1;
    time_sleep(0.025);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw IR and RED ADC values from the FIFO                        */
/* ------------------------------------------------------------------ */
static int si1172_read_raw(int handle, uint16_t *ir, uint16_t *red)
{
    /* Trigger a FIFO read */
    if (si1172_write_cmd(handle, CMD_READ_FIFO) < 0)
        return -1;

    /* Read the two 16-bit FIFO data registers */
    if (si1172_read16(handle, REG_DATA0, ir) < 0)
        return -1;
    if (si1172_read16(handle, REG_DATA1, red) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a data row to the CSV file                                      */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, time_t ts, uint16_t hr, uint16_t spo2,
                     int error_code)
{
    fprintf(fp, "%ld,%u,%u,%d\n", (long)ts, hr, spo2, error_code);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x49 */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1172_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1172 initialization failed (sensor may be absent or unresponsive)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_bpm,spo2_pct,error_code\n");
        fflush(g_log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("Si1172 reader started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        time_t now = time(NULL);
        uint16_t hr_raw = 0, spo2_raw = 0;
        int error_code = ERR_OK;

        if (si1172_read_raw(g_i2c_handle, &hr_raw, &spo2_raw) < 0) {
            fprintf(stderr, "[ERROR] Failed to read Si1172 data (I2C bus error)\n");
            error_code = ERR_I2C;
            hr_raw = 0;
            spo2_raw = 0;
        }

        log_data(g_log_file, now, hr_raw, spo2_raw, error_code);

        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

