#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0

#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int read_mic(int channel) {
    unsigned char tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

int main(int argc, char *argv[]) {
    float gain = 1.0;
    int opt;

    while ((opt = getopt(argc, argv, "g:")) != -1) {
        switch (opt) {
            case 'g':
                gain = atof(optarg);
                if (gain <= 0) {
                    fprintf(stderr, "Gain must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-g gain]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("mic1, mic2, noise_cancelled\n");

    while (running) {
        int mic1 = read_mic(MIC1_CHANNEL);
        int mic2 = read_mic(MIC2_CHANNEL);

        if (mic1 < 0 || mic2 < 0) {
            fprintf(stderr, "Error reading microphones, exiting\n");
            break;
        }

        int noise_cancelled = (int)((float)(mic1 - mic2) * gain);
        printf("%d, %d, %d\n", mic1, mic2, noise_cancelled);
        fflush(stdout);

        gpioDelay(1000);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

