#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define ADC_CHANNEL 0
#define LED_GPIO    17
#define WATER_LEVEL_HIGH 75
#define WATER_LEVEL_LOW  70
#define LOG_FILE    "water_levels.json"
#define SAMPLE_INTERVAL_US 5000000
#define SPI_TRANSFER_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", pigpio_error(ret));
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float adc_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0f * 100.0f;
}

static void log_water_level(float percentage) {
