#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MAX_RECIPIENT 100
#define MAX_CONFIG 100
#define MAX_EMAIL 512
#define TIMESTAMP_LEN 20

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    if (max_raw <= min_raw) {
        fprintf(stderr, "Invalid calibration range: max_raw=%d, min_raw=%d\n", max_raw, min_raw);
        return -1.0f;
    }
    float moisture = 100.0f - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw) * 100.0f);
    if (moisture < 0.0f) moisture = 0.0f;
    if (moisture > 100.0f) moisture = 100.0f;
    return moisture;
}

static int log_data(const char *filename, float moisture) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[TIMESTAMP_LEN];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture);
    fclose(fp);
    return 0;
}

static int send_email_alert(const char *recipient, const char *config_file) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[TIMESTAMP_LEN];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char email_body[MAX_EMAIL];
    snprintf(email_body, sizeof(email_body),
             "Subject: Plant Moisture Alert\n\n"
             "Plant moisture level is below threshold.\n"
             "Timestamp: %s\n"
             "Recipient: %s\n",
             timestamp, recipient);

    char command[MAX_EMAIL + 128];
    snprintf(command, sizeof(command),
             "echo \"%s\" | msmtp -C \"%s\" \"%s\"",
             email_body, config_file, recipient);

    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("popen");
        return -1;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        fprintf(stderr, "%s", buffer);
    }

    int status = pclose(fp);
    if (status == -1) {
        perror("pclose");
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 8) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_raw> <max_raw> <moisture_threshold> <logging_interval> <recipient_email> <msmtp_config_file>\n", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_raw = atoi(argv[3]);
    int max_raw = atoi(argv[4]);
    int moisture_threshold = atoi(argv[5]);
    int logging_interval = atoi(argv[6]);
    char *recipient = argv[7];
    char *msmtp_config = argv[8];

    if (min_raw < 0 || max_raw < 0 || moisture_threshold < 0 || logging_interval <= 0) {
        fprintf(stderr, "Invalid numeric arguments\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int raw_value = read_mcp3008(spi_handle, adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            float moisture = calculate_moisture(raw_value, min_raw, max_raw);
            if (moisture < 0.0f) {
                fprintf(stderr, "Failed to calculate moisture\n");
            } else {
                if (log_data("plant_data.txt", moisture) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
                if (moisture < (float)moisture_threshold) {
                    if (send_email_alert(recipient, msmtp_config) != 0) {
                        fprintf(stderr, "Failed to send email alert\n");
                    }
                }
            }
        }
        sleep(logging_interval);
    }

    cleanup();
    return 0;
}

