        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 8) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_raw> <max_raw> <moisture_threshold> <logging_interval> <recipient_email> <msmtp_config_file>\n", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int min_raw = atoi(argv[3]);
    int max_raw = atoi(argv[4]);
    int moisture_threshold = atoi(argv[5]);
    int logging_interval = atoi(argv[6]);
    char *recipient = argv[7];
    char *msmtp_config = argv[8];

    if (min_raw < 0 || max_raw < 0 || moisture_threshold < 0 || logging_interval <= 0) {
        fprintf(stderr, "Invalid numeric arguments\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, 500000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed on channel %d\n", spi_channel);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int raw_value = read_mcp3008(spi_handle, adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
        } else {
            float moisture = calculate_moisture(raw_value, min_raw, max_raw);
            if (moisture < 0.0f) {
                fprintf(stderr, "Failed to calculate moisture\n");
            } else {
                if (log_data("plant_data.txt", moisture) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
                if (moisture < (float)moisture_threshold) {
                    if (send_email_alert(recipient, msmtp_config) != 0) {
                        fprintf(stderr, "Failed to send email alert\n");
                    }
                }
            }
        }
        sleep(logging_interval);
    }

    cleanup();
    return 0;
}

