#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0       // SPI0 CE0
#define SPI_SPEED 1000000   // 1 MHz
#define ADC_CHANNEL 0       // MCP3008 CH0
#define VREF 3.3            // Reference voltage
#define ADC_MAX 1023        // 10-bit ADC max value
#define SAMPLE_INTERVAL 1   // Seconds

// Pressure sensor parameters (0.1 bar to 1.5 bar = 10 kPa to 150 kPa)
#define MIN_PRESSURE 10.0   // kPa
#define MAX_PRESSURE 150.0  // kPa
#define MIN_VOLTAGE 0.5     // V
#define MAX_VOLTAGE 4.5     // V

// Global variables
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: Start bit (1), Single-ended mode (1), Channel select (3 bits)
    unsigned char tx_buf[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buf[3] = {0, 0, 0};

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buf[1] & 3) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert voltage to pressure (kPa)
float voltage_to_pressure(float voltage) {
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Warning: Voltage %.3fV out of sensor range (%.1fV to %.1fV)\n", 
                voltage, MIN_VOLTAGE, MAX_VOLTAGE);
        return -1.0; // Indicate error
    }

    float pressure = MIN_PRESSURE + (voltage - MIN_VOLTAGE) * (MAX_PRESSURE - MIN_PRESSURE) / (MAX_VOLTAGE - MIN_VOLTAGE);
    return pressure;
}

// Function to log data with timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f kPa\n", timestamp, pressure);
    fflush(stdout);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("MLX90823 Pressure Sensor Reader\n");
    printf("Reading every %d second(s). Press Ctrl+C to exit.\n", SAMPLE_INTERVAL);

    // Main loop
    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Validate ADC value range
        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value * VREF / ADC_MAX;

        // Detect sensor-absent conditions (stuck at 0V or 3.3V)
        if (voltage == 0.0 || voltage == VREF) {
            fprintf(stderr, "Warning: Sensor may be absent or disconnected (voltage = %.3fV)\n", voltage);
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);
        if (pressure < 0) {
            fprintf(stderr, "Error: Invalid pressure reading\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Log data
        log_data(pressure);

        // Wait for next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

