#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MAX30102_ADDR 0x57

#define REG_INTR_STATUS_1 0x00
#define REG_INTR_STATUS_2 0x01
#define REG_INTR_ENABLE_1 0x02
#define REG_INTR_ENABLE_2 0x03
#define REG_FIFO_WR_PTR 0x04
#define REG_OVF_COUNTER 0x05
#define REG_FIFO_RD_PTR 0x06
#define REG_FIFO_DATA 0x07
#define REG_FIFO_CONFIG 0x08
#define REG_MODE_CONFIG 0x09
#define REG_SPO2_CONFIG 0x0A
#define REG_LED1_PA 0x0C
#define REG_LED2_PA 0x0D
#define REG_PART_ID 0xFF

#define EXPECTED_PART_ID 0x15
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    return i2cWriteByteData(i2c_handle, reg, val);
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc != (int)len) return -1;
    return 0;
}

static int max30102_init(void) {
    uint8_t part_id;
    if (i2c_read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID register.\n");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x%02X).\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (i2c_write_reg(REG_MODE_CONFIG, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to reset device.\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2c_write_reg(REG_INTR_ENABLE_1, 0x00) != 0 ||
        i2c_write_reg(REG_INTR_ENABLE_2, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to clear interrupts.\n");
        return -1;
    }

    if (i2c_write_reg(REG_FIFO_WR_PTR, 0x00) != 0 ||
        i2c_write_reg(REG_OVF_COUNTER, 0x00) != 0 ||
        i2c_write_reg(REG_FIFO_RD_PTR, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to initialize FIFO pointers.\n");
        return -1;
    }

    if (i2c_write_reg(REG_FIFO_CONFIG, 0x4F) != 0) {
        fprintf(stderr, "Error: Failed to configure FIFO.\n");
        return -1;
    }

    if (i2c_write_reg(REG_MODE_CONFIG, 0x03) != 0) {
        fprintf(stderr, "Error: Failed to set SpO2 mode.\n");
        return -1;
    }

    if (i2c_write_reg(REG_SPO2_CONFIG, 0x27) != 0) {
        fprintf(stderr, "Error: Failed to configure SPO2.\n");
        return -1;
    }

    if (i2c_write_reg(REG_LED1_PA, 0x24) != 0 ||
        i2c_write_reg(REG_LED2_PA, 0x24) != 0) {
        fprintf(stderr, "Error: Failed to set LED pulse amplitudes.\n");
        return -1;
    }

    return 0;
}

static int read_fifo_sample(uint32_t *red, uint32_t *ir) {
    uint8_t buf[6];
    if (i2c_read_burst(REG_FIFO_DATA, buf, 6) != 0) return -1;
    *red = ((uint32_t)buf[0] << 16) | ((uint32_t)buf[1] << 8) | buf[2];
    *ir  = ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | buf[5];
    return 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s: %s\n", ts, msg);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, MAX30102_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (max30102_init() != 0) {
        fprintf(stderr, "Error: MAX30102 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    uint32_t red_buf[100], ir_buf[100];
    int buf_idx = 0;
    int buf_fill = 0;

    while (!terminate) {
        uint32_t red, ir;
        if (read_fifo_sample(&red, &ir) != 0) {
            fprintf(stderr, "Error: I2C read failed.\n");
            log_event("I2C read error");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        red_buf[buf_idx] = red;
        ir_buf[buf_idx] = ir;
        buf_idx = (buf_idx + 1) % 100;
        if (buf_idx == 0) buf_fill = 100;

        if (buf_fill == 100) {
            uint32_t max_ir = 0;
            int peak_idx = -1;
            for (int i = 0; i < 100; i++) {
                if (ir_buf[i] > max_ir) {
                    max_ir = ir_buf[i];
                    peak_idx = i;
                }
            }

            if (peak_idx >= 0) {
                int hr = 0;
                for (int i = 0; i < 100; i++) {
                    if (ir_buf[i] > ir_buf[(i + 1) % 100] && ir_buf[i] > ir_buf[(i + 99) % 100]) {
                        hr++;
                    }
                }
                hr = hr * 6;

                double ratio = (double)red_buf[peak_idx] / (double)ir_buf[peak_idx];
                double spo2 = 110.0 - 25.0 * ratio;

                if (spo2 < 95.0 || hr > 100) {
                    char msg[256];
                    snprintf(msg, sizeof(msg), "SpO2: %.2f%%, HR: %d BPM", spo2, hr);
                    log_event(msg);
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

