#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define ADS1115_REG_CONV 0x00
#define ADS1115_REG_CFG  0x01
#define ADS1115_CFG_BASE 0x8483  /* MUX=0x4 (A0 vs GND), PGA=0x0 (4.096V), single-shot */
#define ADS1115_CFG_OS   0x8000  /* assert OS bit to start conversion */

#define RELAY_PIN       17
#define REED_PIN        27
#define LOG_FILE        "/var/log/door_events.log"
#define NUM_BASELINE    10
#define POLL_MS         200
#define RELAY_ON_MS     3000
#define SAMPLE_DELAY_MS 50

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *reed_line = NULL;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { perror("fopen log"); return; }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, 2) != 2) return -1;
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_distance(void) {
    uint16_t cfg = ADS1115_CFG_BASE | ADS1115_CFG_OS;
    if (i2c_write16(i2c_fd, ADS1115_REG_CFG, cfg) < 0) return -1;
    for (int i = 0; i < 100; i++) {
        uint16_t cfg_r;
        if (i2c_read16(i2c_fd, ADS1115_REG_CFG, &cfg_r) < 0) return -1;
        if (cfg_r & 0x8000) break;
        usleep(1000);
        if (i == 99) return -1;
    }
    uint16_t raw;
    if (i2c_read16(i2c_fd, ADS1115_REG_CONV, &raw) < 0) return -1;
    int16_t val = (int16_t)raw;
    if (val < 0) val = 0;
    return (int)val;
}

static float calibrate_threshold(void) {
    float sum = 0.0f;
    int valid = 0;
    for (int i = 0; i < NUM_BASELINE; i++) {
        int d = read_distance();
        if (d < 0) { log_event("baseline read failed"); continue; }
        sum += (float)d;
        valid++;
        usleep(SAMPLE_DELAY_MS * 1000);
    }
    if (valid == 0) { log_event("no valid baseline samples"); return 0.0f; }
    float avg = sum / valid;
    float thr = avg * 0.8f;
    char msg[128];
    snprintf(msg, sizeof(msg), "calibrated threshold: %.2f (avg %.2f)", thr, avg);
    log_event(msg);
    return thr;
}

static void cleanup(void) {
    if (relay_line) gpiod_line_set_value(relay_line, 0);
    if (reed_line)  gpiod_line_release(reed_line);
    if (relay_line) gpiod_line_release(relay_line);
    if (chip)       gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE"); close(i2c_fd); return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) { perror("gpiod_chip_open"); close(i2c_fd); return 1; }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    reed_line  = gpiod_chip_get_line(chip, REED_PIN);
    if (!relay_line || !reed_line) { perror("gpiod_chip_get_line"); cleanup(); return 1; }

    if (gpiod_line_request_output(relay_line, "door_relay", 0) < 0) {
        perror("gpiod_line_request_output relay"); cleanup(); return 1;
    }
    if (gpiod_line_request_input(reed_line, "door_reed") < 0) {
        perror("gpiod_line_request_input reed"); cleanup(); return 1;
    }

    float threshold = calibrate_threshold();
    if (threshold <= 0.0f) { log_event("calibration failed, using default"); threshold = 1000.0f; }

    log_event("system started");

    while (running) {
        int dist = read_distance();
        if (dist < 0) {
            log_event("sensor read error");
            usleep(POLL_MS * 1000);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "distance: %d", dist);
        log_event(msg);

        if ((float)dist < threshold) {
            log_event("proximity detected, energizing relay");
            if (gpiod_line_set_value(relay_line, 1) < 0) {
                perror("relay set"); log_event("relay set failed");
            } else {
                usleep(RELAY_ON_MS * 1000);
                if (gpiod_line_set_value(relay_line, 0) < 0) {
                    perror("relay reset"); log_event("relay reset failed");
                }
                int reed = gpiod_line_get_value(reed_line);
                if (reed < 0) { perror("reed read"); log_event("reed read error"); }
                else if (reed == 0) {
                    log_event("door opened");
                } else {
                    log_event("door not opened");
                }
            }
        }
        usleep(POLL_MS * 1000);
    }

    log_event("shutting down");
    cleanup();
    return 0;
}

