#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "irrigation.log"
#define MAX_RETRIES 3
#define DRY_RAW 200
#define WET_RAW 800

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fclose(fp);
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Invalid MCP3008 channel");
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (ret == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        char buf[128];
        snprintf(buf, sizeof(buf), "SPI transfer failed (attempt %d/%d), ret=%d", attempt + 1, MAX_RETRIES, ret);
        log_message(buf);
        gpioDelay(100000);
    }
    log_message("SPI read failed after all retries");
    return -1;
}

static float raw_to_moisture(int raw) {
    if (raw < 0) return 0.0f;
    if (raw > 1023) raw = 1023;
    float pct = 100.0f * (float)(raw - DRY_RAW) / (float)(WET_RAW - DRY_RAW);
    if (pct < 0.0f) pct = 0.0f;
    if (pct > 100.0f) pct = 100.0f;
    return pct;
}

static void control_pump(int on) {
    gpioWrite(PUMP_GPIO, on ? 1 : 0);
    char buf[64];
    snprintf(buf, sizeof(buf), "Pump %s", on ? "activated" : "deactivated");
    log_message(buf);
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float moisture_threshold = 30.0f;
    int pump_duration = 10;
    int sleep_interval = 60;
    int opt;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't': moisture_threshold = atof(optarg); break;
            case 'd': pump_duration = atoi(optarg); break;
            case 's': sleep_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Irrigation system started");

    while (running) {
        int raw = read_mcp3008(MCP3008_CHANNEL);
        if (raw < 0) {
            log_message("Sensor read error, skipping cycle");
        } else {
            float moisture = raw_to_moisture(raw);
            char buf[128];
            snprintf(buf, sizeof(buf), "Moisture: %.2f%% (raw=%d)", moisture, raw);
            log_message(buf);

            if (moisture < moisture_threshold) {
                log_message("Moisture below threshold, activating pump");
                control_pump(1);
                gpioDelay(pump_duration * 1000000);
                control_pump(0);
            }
        }
        if (running) {
            gpioDelay(sleep_interval * 1000000);
        }
    }

    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

