#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00
#define GPIO_PIN 27
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define SAMPLE_INTERVAL_US 1000000
#define VCC 3.3
#define ZERO_FIELD_V 2.5
#define SENSITIVITY_V_PER_G 0.0014

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    double buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, double value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static double cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / cb->count;
}

static int read_ads1115_raw(int handle, int16_t *raw) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = 0xC3; /* MUX=AIN0, PGA=4.096V, single-shot */
    config[2] = 0xE3; /* 128 SPS, continuous */
    if (i2cWriteDevice(handle, config, 3) < 0) return -1;
    gpioDelay(10000);
    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(handle, reg, 1) < 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *raw = (int16_t)((data[0] << 8) | data[1]);
    return 0;
}

static double voltage_to_gauss(double voltage) {
    if (voltage < 0.0 || voltage > VCC) return NAN;
    return (voltage - ZERO_FIELD_V) / SENSITIVITY_V_PER_G;
}

int main(void) {
    openlog("hall_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X", I2C_BUS, ADS1115_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", GPIO_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    CircularBuffer cb;
    cb_init(&cb);

    syslog(LOG_INFO, "Hall monitor started (threshold %.1f Gauss)", THRESHOLD_GAUSS);

    while (running) {
        int16_t raw;
        if (read_ads1115_raw(i2c_handle, &raw) < 0) {
            syslog(LOG_ERR, "ADC read failed");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double voltage = (raw / 32767.0) * 4.096;
        if (voltage < 0.0 || voltage > VCC) {
            syslog(LOG_WARNING, "Invalid voltage %.4f V", voltage);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double gauss = voltage_to_gauss(voltage);
        if (isnan(gauss)) {
            syslog(LOG_WARNING, "Invalid Gauss value");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        cb_add(&cb, gauss);
        double avg = cb_average(&cb);

        if (avg > THRESHOLD_GAUSS) {
            syslog(LOG_INFO, "Threshold exceeded: %.2f Gauss (avg of %d samples)", avg, cb.count);
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        syslog(LOG_INFO, "Gauss: %.2f, Avg: %.2f, Samples: %d", gauss, avg, cb.count);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    gpioWrite(GPIO_PIN, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

