    if (gpioSetMode(PWM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle on GPIO%d\n", PWM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d (handle=%d)\n",
                SPI_CHANNEL, spi_handle);
        gpioPWM(PWM_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MCP3008 ADC reading on SPI0 CE0, PWM on GPIO18 (1 kHz, 10-bit).\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            /* Transient SPI error: keep PWM at current value, retry next cycle */
            gpioDelay(SAMPLE_US);
            continue;
