        /* Map 0-1023 ADC to 0-PWM_RANGE duty cycle */
        int duty = (adc_value * PWM_RANGE) / 1023;

        if (gpioPWM(PWM_GPIO, duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed for duty %d\n", duty);
        }

        printf("ADC: %4d  PWM duty: %4d\n", adc_value, duty);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioPWM(PWM_GPIO, 0);
    spiClose(spi_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

