#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD 30
#define MOISTURE_HYSTERESIS 35
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_soil_monitor"
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define SAMPLE_INTERVAL 60
#define ADC_MAX 1023
#define ADC_MIN 0
#define ADC_DRY 700
#define ADC_WET 300

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static MQTTClient client;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) return -1;
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0};
    if (spiXfer(spi_handle, tx, rx, 3) != 3) return -1;
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int adc_to_moisture(int adc) {
    if (adc < ADC_MIN || adc > ADC_MAX) return -1;
    int m = 100 - ((adc - ADC_WET) * 100) / (ADC_DRY - ADC_WET);
    if (m < 0) m = 0; if (m > 100) m = 100;
    return m;
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) return -1;
    pump_state = state;
    syslog(LOG_INFO, "Relay %s", state ? "ON" : "OFF");
    return 0;
}

static void mqtt_connect(void) {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed");
        return;
    }
    if (MQTTClient_subscribe(client, MQTT_CONTROL_TOPIC, 1) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT subscribe failed");
        MQTTClient_disconnect(client, 1000);
    } else {
        syslog(LOG_INFO, "MQTT connected");
    }
}

static void mqtt_publish(int moisture) {
    char payload[16];
    snprintf(payload, sizeof(payload), "%d", moisture);
    MQTTClient_message msg = MQTTClient_message_initializer;
    msg.payload = payload;
    msg.payloadlen = (int)strlen(payload);
    msg.qos = 1;
    msg.retained = 0;
    if (MQTTClient_publishMessage(client, MQTT_TOPIC, &msg, NULL) != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed");
    }
}

static void mqtt_message_arrived(void *ctx, char *topic, int topicLen, MQTTClient_message *msg) {
    (void)ctx; (void)topicLen;
    if (msg->payloadlen > 0 && msg->payload) {
        char cmd = *(char *)msg->payload;
        if (cmd == '1' && pump_state == 0) {
            set_relay(1);
        } else if (cmd == '0' && pump_state == 1) {
            set_relay(0);
        }
    }
}

static void cleanup(void) {
    if (pump_state) set_relay(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (client) {
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    MQTTClient_create(&client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_setCallbacks(client, NULL, NULL, mqtt_message_arrived, NULL);
    mqtt_connect();

    while (running) {
        int adc = read_adc(ADC_CHANNEL);
        if (adc < 0) {
            syslog(LOG_ERR, "ADC read failed");
        } else if (adc < ADC_MIN || adc > ADC_MAX) {
            syslog(LOG_ERR, "Sensor absent: ADC=%d", adc);
        } else {
            int moisture = adc_to_moisture(adc);
            syslog(LOG_INFO, "Moisture: %d%% (ADC=%d)", moisture, adc);
            mqtt_publish(moisture);
            if (moisture < MOISTURE_THRESHOLD && pump_state == 0) {
                set_relay(1);
            } else if (moisture > MOISTURE_HYSTERESIS && pump_state == 1) {
                set_relay(0);
            }
        }
        sleep(SAMPLE_INTERVAL);
    }
    cleanup();
    return 0;
}

