#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define VREF            3.3f
#define ADC_MAX         1024.0f    /* 10-bit ADC: 0..1023 */
#define SAMPLE_MS       500

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int spi_init(int *fd_out)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int mcp3008_read(int fd, uint8_t channel, uint16_t *raw_out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI command (3 bytes):
     *   Byte 0: 0x01                         Start bit
     *   Byte 1: (0x08 | channel) << 4        SGL/DIFF=1 (single-ended) + channel
     *   Byte 2: 0x00                         Don't care (clocks out low 2 bits)
     *
     * Response (3 bytes):
     *   Byte 0: undefined
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bit 0 = MSB of result
     *   Byte 2: bits 7..0 = lower 8 bits of result
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)(rx[1] & 0x03) << 8) | (uint16_t)rx[2];
    *raw_out = raw;
    return 0;
}

int main(void)
{
    int fd = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init(&fd) < 0) {
        return EXIT_FAILURE;
    }

    printf("MCP3008 channel 0 reader (SPI0 CE0, 1 MHz, mode 0)\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw = 0;
        if (mcp3008_read(fd, 0, &raw) < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            float voltage = (float)raw * VREF / ADC_MAX;
            printf("Raw: %4u  Voltage: %.3f V\n", raw, voltage);
            fflush(stdout);
        }
        usleep(SAMPLE_MS * 1000);
    }

    if (fd >= 0) {
        close(fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

