#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_event(int noise_level, int duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Noise Level: %d, Duty Cycle: %d\n", timestamp, noise_level, duty_cycle);
    fclose(fp);
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE) < 0 || gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = SPI_SPEED;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    while (running) {
        int noise_level = read_mcp3008(spi_fd, 0);
        if (noise_level < 0) {
            fprintf(stderr, "Error reading noise level, skipping iteration\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        int duty_cycle = 0;
        if (noise_level > NOISE_THRESHOLD) {
            duty_cycle = (noise_level - NOISE_THRESHOLD) * PWM_RANGE / (1023 - NOISE_THRESHOLD);
            if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
            if (duty_cycle < 0) duty_cycle = 0;
        }

        if (gpioPWM(MOTOR1_GPIO, duty_cycle) < 0 || gpioPWM(MOTOR2_GPIO, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        if (noise_level > NOISE_THRESHOLD) {
            log_event(noise_level, duty_cycle);
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

