#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"
#define PWM_FREQ 100
#define PWM_RANGE 100
#define SAMPLE_INTERVAL_US 5000000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d\n", channel);
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int map_adc_to_valve(int adc_value) {
    if (adc_value < 0) return 0;
    if (adc_value > 1023) adc_value = 1023;
    return 100 - (int)(((float)adc_value / 1023.0f) * 100.0f);
}

static void log_data(int s0, int s1, int s2, int avg, int valve) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, S0=%d, S1=%d, S2=%d, Avg=%d, Valve=%d\n",
            ts, s0, s1, s2, avg, valve);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);
    gpioPWM(VALVE_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int s0 = read_mcp3008(0);
        int s1 = read_mcp3008(1);
        int s2 = read_mcp3008(2);
        int count = 0;
        int sum = 0;
        if (s0 >= 0) { sum += s0; count++; }
        if (s1 >= 0) { sum += s1; count++; }
        if (s2 >= 0) { sum += s2; count++; }
        if (count == 0) {
            fprintf(stderr, "All sensors failed, skipping cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        int avg = sum / count;
        int valve = map_adc_to_valve(avg);
        gpioPWM(VALVE_GPIO, valve);
        log_data(s0, s1, s2, avg, valve);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioPWM(VALVE_GPIO, 0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

