#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 10000000
#define MIN_FREQ 220.0
#define MAX_FREQ 880.0
#define MIN_VOLUME 0.0
#define MAX_VOLUME 1.0
#define CONFIG_FILE "theremin_config.txt"
#define ECHO_TIMEOUT_US 30000

static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *trig_line = NULL;
static struct gpiod_line *echo_line = NULL;
static int spi_fd = -1;
static int pwm_exported = 0;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

void cleanup() {
    if (trig_line) gpiod_line_release(trig_line);
    if (echo_line) gpiod_line_release(echo_line);
    if (chip) gpiod_chip_close(chip);
    if (spi_fd >= 0) close(spi_fd);
    if (pwm_exported) {
        FILE *fp = fopen("/sys/class/pwm/pwmchip0/unexport", "w");
        if (fp) { fprintf(fp, "%d", PWM_CHANNEL); fclose(fp); }
    }
}

int init_gpio() {
    chip = gpiod_chip_open_by_number(0);
    if (!chip) { perror("gpiod_chip_open"); return -1; }
    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig_line || !echo_line) { perror("gpiod_chip_get_line"); return -1; }
    if (gpiod_line_request_output(trig_line, "theremin", 0) < 0) { perror("gpiod_line_request_output trig"); return -1; }
    if (gpiod_line_request_input(echo_line, "theremin") < 0) { perror("gpiod_line_request_input echo"); return -1; }
    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) { perror("open SPI"); return -1; }
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) { perror("SPI_IOC_WR_MODE"); return -1; }
    int bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) { perror("SPI_IOC_WR_BITS_PER_WORD"); return -1; }
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) { perror("SPI_IOC_WR_MAX_SPEED_HZ"); return -1; }
    return 0;
}

int init_pwm() {
    FILE *fp;
    fp = fopen("/sys/class/pwm/pwmchip0/export", "w");
    if (!fp) { perror("export pwm"); return -1; }
    fprintf(fp, "%d", PWM_CHANNEL);
    fclose(fp);
    pwm_exported = 1;
    usleep(100000);
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) { perror("set period"); return -1; }
    fprintf(fp, "%d", PWM_PERIOD_NS);
    fclose(fp);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) { perror("set duty_cycle"); return -1; }
    fprintf(fp, "0");
    fclose(fp);
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", PWM_CHANNEL);
    fp = fopen(path, "w");
    if (!fp) { perror("set enable"); return -1; }
    fprintf(fp, "1");
    fclose(fp);
    return 0;
}

float read_distance() {
    gpiod_line_set_value(trig_line, 0);
    usleep(2);
    gpiod_line_set_value(trig_line, 1);
    usleep(10);
    gpiod_line_set_value(trig_line, 0);
    struct timespec start, end;
    long long start_ns, end_ns;
    int timeout = ECHO_TIMEOUT_US;
    while (gpiod_line_get_value(echo_line) == 0) {
        if (--timeout <= 0) return -1.0;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &start);
    timeout = ECHO_TIMEOUT_US;
    while (gpiod_line_get_value(echo_line) == 1) {
        if (--timeout <= 0) return -1.0;
        usleep(1);
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
    long long diff = end_ns - start_ns;
    return (float)diff / 58.0;
}

float read_photoresistor() {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) { perror("SPI_IOC_MESSAGE"); return -1.0; }
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return (float)adc / 1023.0;
}

float map_value(float x, float in_min, float in_max, float out_min, float out_max) {
    return (x - in_min) * (out_max - out_min) / (in_max - in_min) + out_min;
}

void set_pwm_duty(float duty) {
    if (duty < MIN_VOLUME) duty = MIN_VOLUME;
    if (duty > MAX_VOLUME) duty = MAX_VOLUME;
    int duty_ns = (int)(duty * PWM_PERIOD_NS);
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", PWM_CHANNEL);
    FILE *fp = fopen(path, "w");
    if (fp) { fprintf(fp, "%d", duty_ns); fclose(fp); }
}

void save_config(float freq, float vol) {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (fp) { fprintf(fp, "%.2f,%.2f\n", freq, vol); fclose(fp); }
}

void load_config(float *freq, float *vol) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp) {
        if (fscanf(fp, "%f,%f", freq, vol) != 2) { *freq = 0; *vol = 0; }
        fclose(fp);
    } else { *freq = 0; *vol = 0; }
}

int main() {
    signal(SIGINT, signal_handler);
    if (init_gpio() < 0) { cleanup(); return 1; }
    if (init_spi() < 0) { cleanup(); return 1; }
    if (init_pwm() < 0) { cleanup(); return 1; }
    float freq = 0, vol = 0;
    load_config(&freq, &vol);
    while (running) {
        float dist = read_distance();
        if (dist < 0) { usleep(100000); continue; }
        float freq_new = map_value(dist, 20.0, 400.0, MAX_FREQ, MIN_FREQ);
        float vol_new = read_photoresistor();
        if (vol_new < 0) { usleep(100000); continue; }
        if (freq_new != freq || vol_new != vol) {
            set_pwm_duty(vol_new);
            freq = freq_new;
            vol = vol_new;
            save_config(freq, vol);
        }
        usleep(10000);
    }
    cleanup();
    return 0;
}

