#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000
#define SAMPLE_INTERVAL_S 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int read_aqi(void);
void control_fan(int aqi);
void log_data(int aqi);
void signal_handler(int signal);
int initialize(void);
void cleanup(void);

// Function to read from MCP3008 ADC (single-ended, channel 0-7)
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 SPI protocol:
    // Byte 0: Start bit (0x01)
    // Byte 1: Single-ended mode (0x08) | channel select (0x00-0x07) << 4
    // Byte 2: Don't care (0x00)
    tx_buf[0] = 0x01;
    tx_buf[1] = 0x08 | (channel << 4);
    tx_buf[2] = 0x00;

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed with error: %d\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from response bytes 1 and 2
    // rx_buf[1] contains the two most significant bits in its lower 2 bits
    // rx_buf[2] contains the eight least significant bits
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to calculate AQI from ADC value (linear mapping 0-500)
int read_aqi(void) {
    int adc_value = read_mcp3008(0); // Read from channel 0
    if (adc_value < 0) {
        return -1;
    }

