#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define MCP3008_CHANNEL 0
#define PPM_PER_ADC_UNIT 0.5f
#define ALCOHOL_THRESHOLD 50.0f
#define SOBRIETY_THRESHOLD 20.0f
#define LOG_FILE "alcohol_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int read_mcp3008(int fd, int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((channel << 4) | 0x80), 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static float calculate_ppm(int adc_value) {
    return (float)adc_value * PPM_PER_ADC_UNIT - 10.0f;
}

static const char *classify_alcohol_level(float ppm) {
    if (ppm > ALCOHOL_THRESHOLD) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < SOBRIETY_THRESHOLD) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

static void log_data(FILE *log_file, float ppm, const char *classification) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting UTC time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f PPM, %s\n", timestamp, ppm, classification);
    fflush(log_file);
}

static void log_error(FILE *log_file, const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting UTC time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    int spi_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    if (spi_init(&spi_fd) < 0) {
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = -1;
        int retries = 0;
        int read_ok = 0;

        while (retries < MAX_RETRIES && program_running) {
            if (read_mcp3008(spi_fd, MCP3008_CHANNEL, &adc_value) == 0) {
                read_ok = 1;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_MS * 1000);
            }
        }

        if (!read_ok) {
            log_error(log_file, "Failed to read ADC after multiple retries.");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (adc_value == 0 || adc_value == 1023) {
            log_error(log_file, "Sensor absent or disconnected (ADC stuck at 0 or 1023).");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float ppm = calculate_ppm(adc_value);
        const char *classification = classify_alcohol_level(ppm);

        log_data(log_file, ppm, classification);
        printf("ADC: %d, PPM: %.2f, %s\n", adc_value, ppm, classification);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    ret = 0;

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Alcohol sensor monitoring stopped.\n");
    return ret;
}

