#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>

// Motor 1 GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2 GPIO pins
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 ADC channels for potentiometers
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// Speed limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion profile timing
#define ACCELERATION_TIME 2
#define DECELERATION_TIME 2
#define HOLD_TIME 2
#define PAUSE_TIME 5

// Global flag for graceful shutdown
volatile sig_atomic_t program_running = 1;

// SPI handle
int spi_handle = -1;

// Function prototypes
int read_potentiometer(int channel);
float map_potentiometer_to_speed(int pot_value);
void set_motor_speed(int motor_enable, int motor_direction, int speed);
void motion_profile();
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    // Stop motors
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);

    // Close SPI
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    // Terminate pigpio
    gpioTerminate();
}

// Function to read the potentiometer value from the MCP3008
int read_potentiometer(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: start bit (1), single-ended mode (1), channel select (3 bits)
    unsigned char tx_buffer[3] = {1, (8 + channel) << 4, 0};
    unsigned char rx_buffer[3] = {0, 0, 0};

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed for channel %d (returned %d)\n", channel, result);
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 3) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map the potentiometer value to a speed factor using a logarithmic function
float map_potentiometer_to_speed(int pot_value) {
    if (pot_value < 0 || pot_value > 1023) {
        fprintf(stderr, "Invalid potentiometer value: %d\n", pot_value);
        return 0.0f;
    }

    // Logarithmic mapping: maps 0-1023 to 0.1-1.0
    float speed_factor = 0.1f + (float)pot_value / 10230.0f;
    return speed_factor;
}

// Function to set the motor speed and direction
void set_motor_speed(int motor_enable, int motor_direction, int speed) {
    // Set direction
    gpioWrite(motor_direction, speed > 0 ? 1 : 0);

    // Set speed using PWM
    gpioPWM(motor_enable, abs(speed));
}

// Function to execute the motion profile
void motion_profile() {
    int pot1_value, pot2_value;
    float speed_factor1, speed_factor2;
    int motor1_speed, motor2_speed;

    // Acceleration phase
    for (int i = 0; i <= ACCELERATION_TIME * 10 && program_running; i++) {
        pot1_value = read_potentiometer(POT1_CHANNEL);
        pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometer values during acceleration.\n");
            cleanup();
            exit(1);
        }

        speed_factor1 = map_potentiometer_to_speed(pot1_value);
        speed_factor2 = map_potentiometer_to_speed(pot2_value);

        motor1_speed = (int)(MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor1);
        motor2_speed = (int)(MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor2);

        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, motor1_speed);
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, -motor2_speed);

        gpioDelay(100000); // 100ms delay
    }

    // Hold phase
    for (int i = 0; i < HOLD_TIME * 10 && program_running; i++) {
        pot1_value = read_potentiometer(POT1_CHANNEL);
        pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometer values during hold.\n");
            cleanup();
            exit(1);
        }

        speed_factor1 = map_potentiometer_to_speed(pot1_value);
        speed_factor2 = map_potentiometer_to_speed(pot2_value);

        motor1_speed = (int)(MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor1);
        motor2_speed = (int)(MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor2);

        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, motor1_speed);
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, -motor2_speed);

        gpioDelay(100000); // 100ms delay
    }

    // Deceleration phase
    for (int i = 0; i <= DECELERATION_TIME * 10 && program_running; i++) {
        pot1_value = read_potentiometer(POT1_CHANNEL);
        pot2_value = read_potentiometer(POT2_CHANNEL);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error reading potentiometer values during deceleration.\n");
            cleanup();
            exit(1);
        }

        speed_factor1 = map_potentiometer_to_speed(pot1_value);
        speed_factor2 = map_potentiometer_to_speed(pot2_value);

        motor1_speed = (int)(MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor1);
        motor2_speed = (int)(MIN_SPEED + (MAX_SPEED - MIN_SPEED) * speed_factor2);

        set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, motor1_speed);
        set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, -motor2_speed);

        gpioDelay(100000); // 100ms delay
    }

    // Pause
    for (int i = 0; i < PAUSE_TIME * 10 && program_running; i++) {
        gpioDelay(100000); // 100ms delay
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        motion_profile();
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

