#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LED_PIN 17
#define SAMPLE_INTERVAL_US 10000
#define DEBOUNCE_DELAY_US 10000
#define CALIBRATION_TIME_S 5
#define THRESHOLD_PERCENTAGE 10.0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calibrate(int duration_s) {
    double sum = 0.0;
    int count = 0;
    int sample;

    printf("Calibrating for %d seconds...\n", duration_s);
    for (int i = 0; i < duration_s * 10 && running; i++) {
        sample = read_mcp3008(0);
        if (sample < 0) {
            fprintf(stderr, "Calibration read error\n");
            return -1.0;
        }
        sum += sample;
        count++;
        gpioDelay(100000);
    }

    if (count == 0) {
        fprintf(stderr, "No samples during calibration\n");
        return -1.0;
    }

    double avg = sum / count;
    printf("Calibration complete. Average ambient level: %.2f\n", avg);
    return avg;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
