        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    if (gpiod_line_request_set_value(cs_req, CS_GPIO_LINE, 0) < 0) {
        fprintf(stderr, "Failed to drive CS low: %s\n", strerror(errno));
        return -1;
    }

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        gpiod_line_request_set_value(cs_req, CS_GPIO_LINE, 1);
        return -1;
    }

    if (gpiod_line_request_set_value(cs_req, CS_GPIO_LINE, 1) < 0) {
        fprintf(stderr, "Failed to drive CS high: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

int main(void)
{
    int spi_fd = -1;
    FILE *log_file = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *cs_req = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    struct gpiod_line_settings *settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE);

    struct gpiod_line_config *line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    unsigned int offset = CS_GPIO_LINE;
    if (gpiod_line_config_add_line_settings(line_cfg, &offset, 1, settings) < 0) {
        fprintf(stderr, "Failed to configure CS line: %s\n", strerror(errno));
        goto cleanup;
    }

    cs_req = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (!cs_req) {
        fprintf(stderr, "Failed to request CS line: %s\n", strerror(errno));
        goto cleanup;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    struct timespec next_sample;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next_sample);

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, cs_req, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, continuing\n");
            struct timespec ts = {0, 1000000000L / SAMPLE_RATE_HZ};
            nanosleep(&ts, NULL);
            continue;
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
        long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

        if (fprintf(log_file, "%lld|%d\n", timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
            break;
        }

        struct timespec sleep_ts = {0, 1000000000L / SAMPLE_RATE_HZ};
        if (nanosleep(&sleep_ts, NULL) < 0 && errno != EINTR) {
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            break;
        }

        next_sample.tv_nsec += 1000000000L / SAMPLE_RATE_HZ;
        if (next_sample.tv_nsec >= 1000000000L) {
            next_sample.tv_sec += 1;
            next_sample.tv_nsec -= 1000000000L;
        }
        clock_nanosleep(CLOCK_MONOTONIC_RAW, TIMER_ABSTIME, &next_sample, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (cs_req) {
        gpiod_line_request_release(cs_req);
    }
    if (line_cfg) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings) {
        gpiod_line_settings_free(settings);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

