#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0        // SPI mode 0, active low CS

#define MCP3008_CS 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2

#define SENSITIVITY 0.3f   // 300 mV/g
#define ZERO_G_BIAS 1.5f   // 1.5V at 0g
#define VREF 3.3f          // Reference voltage

#define SAMPLE_RATE 10     // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)

// Kalman Filter Parameters
#define Q 0.001f
#define R 0.1f

// Global Variables
static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

// Kalman Filter State
typedef struct {
    float x, P;
} kalman_state_t;

static kalman_state_t kf_x = {0.0f, 1.0f};
static kalman_state_t kf_y = {0.0f, 1.0f};
static kalman_state_t kf_z = {0.0f, 1.0f};

// Function Prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float kalman_filter(float measurement, kalman_state_t *state);
void signal_handler(int signal);
void cleanup();

// Signal Handler
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

// Read from MCP3008 ADC via SPI
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // MCP3008 SPI command: Start bit (1), Single-ended mode (1), Channel select (3 bits)
    // tx[0] = 0x01 (Start bit)
    // tx[1] = (0x08 | channel) << 4 (Single-ended + channel)
    // tx[2] = 0x00 (Dummy byte for clocking data out)
    char tx[3] = {0x01, (char)((0x08 | channel) << 4), 0x00};
    char rx[3] = {0};

    gpioWrite(MCP3008_CS, 0); // Assert CS
    int result = spiXfer(spi_handle, tx, rx, 3);
    gpioWrite(MCP3008_CS, 1); // Deassert CS

    if (result != 3) {
        fprintf(stderr, "Error: SPI transaction failed (returned %d)\n", result);
        return -1;
    }

    // Extract 10-bit ADC value from rx[1] and rx[2]
    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * VREF / 1024.0f;
}

// Convert voltage to acceleration (g)
float voltage_to_acceleration(float voltage) {
    return (voltage - ZERO_G_BIAS) / SENSITIVITY;
}

// Kalman Filter Update
float kalman_filter(float measurement, kalman_state_t *state) {
    float predicted_state = state->x;
    float predicted_error = state->P + Q;

    float kalman_gain = predicted_error / (predicted_error + R);
    state->x = predicted_state + kalman_gain * (measurement - predicted_state);
    state->P = (1.0f - kalman_gain) * predicted_error;

    return state->x;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure CS pin as output and set high (inactive)
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 Kalman Filter Demo (SPI via MCP3008)\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        // Read ADC values
        int adc_x = read_mcp3008(ADC_CHANNEL_X);
        int adc_y = read_mcp3008(ADC_CHANNEL_Y);
        int adc_z = read_mcp3008(ADC_CHANNEL_Z);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Error: Failed to read ADC values. Retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        // Convert to voltage and acceleration
        float voltage_x = adc_to_voltage(adc_x);
        float voltage_y = adc_to_voltage(adc_y);
        float voltage_z = adc_to_voltage(adc_z);

        float accel_x = voltage_to_acceleration(voltage_x);
        float accel_y = voltage_to_acceleration(voltage_y);
        float accel_z = voltage_to_acceleration(voltage_z);

        // Apply Kalman filter
        float filtered_x = kalman_filter(accel_x, &kf_x);
        float filtered_y = kalman_filter(accel_y, &kf_y);
        float filtered_z = kalman_filter(accel_z, &kf_z);

        // Print results
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", filtered_x, filtered_y, filtered_z);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

