#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

#define VCC 3.3
#define V_QUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define MIN_MT -100.0
#define MAX_MT 100.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static double calculate_magnetic_field(double voltage) {
    return (voltage - V_QUIESCENT) / SENSITIVITY;
}

static int log_data(FILE *fp, double m1, double m2, double m3) {
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", m1, m2, m3) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    const unsigned int offsets[3] = {SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO};
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", offsets[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "drv5055_hall") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n", offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Starting magnetic field monitoring. Press Ctrl+C to exit.\n");

    while (program_running) {
        double voltages[3];
        int read_error = 0;

        for (int i = 0; i < 3; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n", offsets[i], strerror(errno));
                read_error = 1;
                break;
            }
            voltages[i] = (val == 1) ? VCC : 0.0;
        }

        if (read_error) {
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        double fields[3];
        for (int i = 0; i < 3; i++) {
            fields[i] = calculate_magnetic_field(voltages[i]);
            if (fields[i] < MIN_MT || fields[i] > MAX_MT) {
                fprintf(stderr, "Warning: Sensor %d out of range: %.2f mT\n", i + 1, fields[i]);
            }
        }

        if (log_data(log_fp, fields[0], fields[1], fields[2]) != 0) {
            fprintf(stderr, "Logging failed, continuing...\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    printf("\nExiting gracefully.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (log_fp) {
        fclose(log_fp);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

