#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

static volatile int running = 1;
static int spi_handle = -1;

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel");
        return -1;
    }
    unsigned char tx[3] = {0x01, (unsigned char)((0x08 | channel) << 4), 0x00};
    unsigned char rx[3] = {0, 0, 0};
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        log_event("SPI transfer failed");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

void control_pump(int on) {
    gpioWrite(PUMP_GPIO, on ? 1 : 0);
    char msg[64];
    snprintf(msg, sizeof(msg), "Pump %s", on ? "ON" : "OFF");
    log_event(msg);
}

void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    log_event("Program terminated");
}

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }
    log_event("Program started");
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    int pump_on = 0;
    while (running) {
        int moisture = read_mcp3008(0);
        if (moisture < 0) {
            log_event("Failed to read moisture sensor");
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture level: %d", moisture);
            log_event(msg);
            if (moisture < MOISTURE_THRESHOLD && !pump_on) {
                control_pump(1);
                pump_on = 1;
            } else if (moisture >= MOISTURE_THRESHOLD && pump_on) {
                control_pump(0);
                pump_on = 0;
            }
        }
        sleep(60);
    }
    cleanup();
    return 0;
}

