        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed, skipping sample\n");
        } else {
            float temp = adc_to_celsius(adc);
            printf("Temperature: %.2f °C\n", temp);
            buffer[idx] = temp;
            idx = (idx + 1) % BUFFER_SIZE;
            log_temperature(temp);
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

