#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define I2C_DEV "/dev/i2c-1"
#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int bh1750_read_light(int fd, float *lux) {
    uint8_t buf[2];
    if (write(fd, (uint8_t[]){0x10}, 1) != 1) return -1;
    usleep(180000);
    if (read(fd, buf, 2) != 2) return -1;
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int mcp3008_read_channel(int fd, uint8_t channel, uint16_t *value) {
    if (channel > 7) return -1;
    uint8_t tx[3] = {0x01, (uint8_t)(0x80 | (channel << 4)), 0x00};
    uint8_t rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) return -1;
    *value = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static void log_data(float light, uint16_t sound) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Light: %.2f, Sound: %u\n", ts, light, sound);
    fclose(fp);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEV, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    uint8_t spi_mode = SPI_MODE_0;
    uint8_t spi_bits = 8;
    uint32_t spi_speed = 1000000;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_mode) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi_bits) < 0 ||
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi_speed) < 0) {
        fprintf(stderr, "Error configuring SPI: %s\n", strerror(errno));
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    while (running) {
        float light = 0.0f;
        uint16_t sound = 0;
        int light_ok = bh1750_read_light(i2c_fd, &light);
        int sound_ok = mcp3008_read_channel(spi_fd, 0, &sound);

        if (light_ok == 0 && sound_ok == 0) {
            log_data(light, sound);
        } else {
            fprintf(stderr, "Sensor read error: light=%d, sound=%d\n", light_ok, sound_ok);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    close(i2c_fd);
    close(spi_fd);
    return 0;
}

