#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_FLAGS 0  /* mode 0, active-low CE */
#define MCP3008_CHANNEL 0
#define MCP4725_ADDR 0x62
#define DAC_MAX_VOLTAGE 3.3
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

/* Globals for cleanup */
static int spi_handle = -1;
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int init_spi(void);
static int init_i2c(void);
static int read_mcp3008(int channel, int *adc_value);
static double adc_to_temperature(int adc_value);
static double temperature_to_voltage(double temperature);
static int write_dac_voltage(double voltage);
static void log_data(int adc_value, double temperature, double voltage);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize SPI for MCP3008 */
static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/* Initialize I2C for MCP4725 */
static int init_i2c(void) {
    i2c_handle = i2cOpen(1, MCP4725_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1, addr 0x%02X: %s\n",
                MCP4725_ADDR, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

/* Read 10-bit value from MCP3008 single-ended channel */
static int read_mcp3008(int channel, int *adc_value) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: start bit (0x01)
     * Byte 1: SGL/DIFF=1 (single) + D2 D1 D0 channel, upper nibble
     * Byte 2: don't care (clocks out low 2 bits)
     */
    char tx_buf[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx_buf[3] = { 0 };

    int ret = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(ret));
        return -1;
    }

    /* 10-bit result: lower 2 bits of rx_buf[1] + 8 bits of rx_buf[2] */
    *adc_value = ((rx_buf[1] & 0x03) << 8) | (rx_buf[2] & 0xFF);
    return 0;
}

/* Convert ADC value (0-1023) to temperature in Celsius */
static double adc_to_temperature(int adc_value) {
    return TEMP_MIN + ((double)adc_value / 1023.0) * (TEMP_MAX - TEMP_MIN);
}

/* Map temperature to DAC output voltage (0V-3.3V) */
static double temperature_to_voltage(double temperature) {
    return (temperature - TEMP_MIN) / (TEMP_MAX - TEMP_MIN) * DAC_MAX_VOLTAGE;
}

/* Write DAC voltage via MCP4725 I2C command */
static int write_dac_voltage(double voltage) {
    if (voltage < 0.0 || voltage > DAC_MAX_VOLTAGE) {
        fprintf(stderr, "DAC voltage %.2fV out of range [0, %.1f]\n",
                voltage, DAC_MAX_VOLTAGE);
        return -1;
    }

    uint16_t code = (uint16_t)((voltage / DAC_MAX_VOLTAGE) * 4095.0);
    char buf[2];
    buf[0] = 0x40;  /* write DAC register, no EEPROM */
    buf[1] = (char)(code >> 4);

    int ret = i2cWriteDevice(i2c_handle, buf, 2);
    if (ret < 0) {
        fprintf(stderr, "I2C write to DAC failed: %s\n", pigpio_error(ret));
        return -1;
    }
    return 0;
}

/* Log one data row to file and stdout */
static void log_data(int adc_value, double temperature, double voltage) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n",
            timestamp, adc_value, temperature, voltage);
    fflush(log_file);

    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.2f V\n",
           timestamp, adc_value, temperature, voltage);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Release all resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        spiClose(spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = 0;
        int read_ok = 0;

        /* Retry on transient SPI errors */
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (read_mcp3008(MCP3008_CHANNEL, &adc_value) == 0) {
                read_ok = 1;
                break;
            }
            fprintf(stderr, "ADC read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);  /* 100 ms backoff */
        }

        if (!read_ok) {
            fprintf(stderr, "ADC read failed after %d attempts; skipping cycle\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double temperature = adc_to_temperature(adc_value);
        double voltage = temperature_to_voltage(temperature);

        /* Retry on transient DAC errors */
        int write_ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            if (write_dac_voltage(voltage) == 0) {
                write_ok = 1;
                break;
            }
            fprintf(stderr, "DAC write attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            gpioDelay(100000);
        }

        if (!write_ok) {
            fprintf(stderr, "DAC write failed after %d attempts; skipping logging\n", MAX_RETRIES);
        } else {
            log_data(adc_value, temperature, voltage);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
