#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24
#define NUM_RELAYS 4
#define ACTIVATION_DELAY_SEC 1
#define SEQUENCE_DELAY_SEC 1

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[NUM_RELAYS] = {NULL};
static const int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
static volatile sig_atomic_t keep_running = 1;

static void cleanup_and_exit(int exit_code) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (relay_lines[i]) {
            gpiod_line_set_value(relay_lines[i], 0);
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(exit_code);
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    // Open the default gpiochip (gpiochip0 on RPi 3B+)
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        cleanup_and_exit(EXIT_FAILURE);
    }

    // Request each relay line as output, initially LOW (relays off)
    for (int i = 0; i < NUM_RELAYS; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", relay_pins[i]);
            cleanup_and_exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(relay_lines[i], "relay-sequencer", 0) < 0) {
            perror("Failed to request line as output");
            cleanup_and_exit(EXIT_FAILURE);
        }
    }

    // Install signal handlers for graceful shutdown
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        cleanup_and_exit(EXIT_FAILURE);
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        for (int i = 0; i < NUM_RELAYS && keep_running; i++) {
            // Activate relay
            if (gpiod_line_set_value(relay_lines[i], 1) < 0) {
                perror("Failed to set relay HIGH");
                cleanup_and_exit(EXIT_FAILURE);
            }
            printf("Relay %d activated\n", i + 1);

            // Wait for activation duration
            sleep(ACTIVATION_DELAY_SEC);

            // Deactivate relay
            if (gpiod_line_set_value(relay_lines[i], 0) < 0) {
                perror("Failed to set relay LOW");
                cleanup_and_exit(EXIT_FAILURE);
            }
            printf("Relay %d deactivated\n", i + 1);

            // Wait before next relay
            sleep(SEQUENCE_DELAY_SEC);
        }
    }

    printf("\nShutting down...\n");
    cleanup_and_exit(EXIT_SUCCESS);
    return 0;
}

