#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Motor driver GPIO pins */
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Rain sensor threshold (0-10) */
#define RAIN_THRESHOLD 5

/* Motor run duration (seconds) */
#define MOTOR_RUN_TIME 3

/* Log file path */
#define LOG_FILE "rain_log.txt"

/* Global state */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int read_rain_sensor(int channel);
static void control_motor(int direction, int speed);
static void close_window(void);
static void open_window(void);
static void log_rain_level(int rain_level);
static void signal_handler(int signal);
static void cleanup(void);

/* Read rain sensor via MCP3008 ADC (single-ended, channel 0-7) */
static int read_rain_sensor(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3];
    unsigned char rx[3];

    /* MCP3008 single-ended read: start bit, config byte, don't-care */
    tx[0] = 0x01;
    tx[1] = (0x08 | channel) << 4;
    tx[2] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + all 8 bits of rx[2] */
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* Drive motor: direction 1 = forward, 0 = reverse, speed 0-255 */
static void control_motor(int direction, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 255) speed = 255;

    if (direction == 1) {
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
    } else {
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
    }
    gpioPWM(MOTOR_ENA, speed);
}

/* Close window: drive forward for MOTOR_RUN_TIME seconds */
static void close_window(void) {
    printf("Closing window...\n");
    control_motor(1, 150);
    time_sleep(MOTOR_RUN_TIME);
    control_motor(0, 0);
    printf("Window closed.\n");
}

/* Open window: drive reverse for MOTOR_RUN_TIME seconds */
static void open_window(void) {
    printf("Opening window...\n");
    control_motor(0, 150);
    time_sleep(MOTOR_RUN_TIME);
    control_motor(0, 0);
    printf("Window opened.\n");
}

/* Log rain level with timestamp */
static void log_rain_level(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open\n");
        return;
    }

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup: stop motor, close SPI, close log, terminate pigpio */
static void cleanup(void) {
    control_motor(0, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor GPIOs */
    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_ENA, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set motor GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    int window_open = 1;  /* 1 = open, 0 = closed */

    while (program_running) {
        int rain_value = read_rain_sensor(0);
        if (rain_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            time_sleep(1.0);
            continue;
        }

        /* Convert 10-bit ADC (0-1023) to rain level (0-10):
         * ADC 1023 -> dry -> rain level 0
         * ADC 0    -> wet -> rain level 10
         * Linear mapping: rain_level = 10 - (rain_value / 1023.0) * 10
         */
        int rain_level = (int)(10.0 - (rain_value / 1023.0) * 10.0);
        if (rain_level < 0) rain_level = 0;
        if (rain_level > 10) rain_level = 10;

        log_rain_level(rain_level);

        if (rain_level >= RAIN_THRESHOLD && window_open) {
            close_window();
            window_open = 0;
        } else if (rain_level < RAIN_THRESHOLD && !window_open) {
            open_window();
            window_open = 1;
        }

        time_sleep(1.0);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

