#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define CLAP_THRESHOLD 700
#define LED_GPIO 16
#define SAMPLE_GPIO 26
#define SAMPLE_COUNT 10
#define SAMPLE_DELAY_US 100
#define LED_ON_TIME_MS 500
#define DEBOUNCE_TIME_MS 50
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_clap_level(void) {
    int sum = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        gpioWrite(SAMPLE_GPIO, 1);
        gpioDelay(SAMPLE_DELAY_US);
        int val = gpioRead(SAMPLE_GPIO);
        gpioWrite(SAMPLE_GPIO, 0);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", SAMPLE_GPIO);
            return -1;
        }
        sum += val;
        gpioDelay(SAMPLE_DELAY_US);
    }
    return sum / SAMPLE_COUNT;
}

static void trigger_led(void) {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(LED_ON_TIME_MS * 1000);
    gpioWrite(LED_GPIO, 0);
}

static void log_detection(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s: Clap detected!\n", timestamp);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    if (gpioSetMode(SAMPLE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set sample GPIO %d as output\n", SAMPLE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SAMPLE_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize sample GPIO %d low\n", SAMPLE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detection started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    uint32_t last_trigger = 0;

    while (running) {
        int level = read_clap_level();
        if (level < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (level > CLAP_THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_trigger > DEBOUNCE_TIME_MS * 1000) {
                trigger_led();
                log_detection();
                last_trigger = now;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

