            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (level > CLAP_THRESHOLD) {
            uint32_t now = gpioTick();
            if (now - last_trigger > DEBOUNCE_TIME_MS * 1000) {
                trigger_led();
                log_detection();
                last_trigger = now;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

