}

static int gpio_export(int pin) {
    char buf[64];
    int fd, len;
    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening export: %s\n", strerror(errno));
        return -1;
    }
    len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error exporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin) {
    char buf[64];
    int fd, len;
    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening unexport: %s\n", strerror(errno));
        return -1;
    }
    len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        fprintf(stderr, "Error unexporting GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening direction for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "Error setting direction for GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening value for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    if (write(fd, value ? "1" : "0", 1) != 1) {
        fprintf(stderr, "Error setting value for GPIO %d: %s\n", pin, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_get_value(int pin) {
    char path[64];
    int fd, val;
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening value for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    val = read(fd, path, 1);
    close(fd);
    if (val != 1) {
        fprintf(stderr, "Error reading value for GPIO %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return (path[0] == '1') ? 1 : 0;
}

