    time_t t;
    struct tm *tm_info;
    char timestamp[20];
    t = time(NULL);
    tm_info = localtime(&t);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%s, %.2f\n", timestamp, distance);
    fclose(fp);
}

