    sigaction(SIGTERM, &sa, NULL);
    if (gpio_export(GPIO_PIN) != 0) {
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        gpio_unexport(GPIO_PIN);
        return 1;
    }
    while (running) {
        value = gpio_get_value(GPIO_PIN);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO value, retrying...\n");
            sleep(1);
            continue;
