#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LED_GPIO 21
#define THRESHOLD 10.0
#define VCC 3.3
#define SENSITIVITY_MV_PER_MT 2.5
#define ADC_MAX 1023
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_DELAY_US 100000

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };
    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_voltage(int adc_value) {
    return (double)adc_value * VCC / (double)ADC_MAX;
}

static double voltage_to_magnetic_field(double voltage) {
    double quiescent = VCC / 2.0;
    return (voltage - quiescent) * 1000.0 / SENSITIVITY_MV_PER_MT;
}

static void log_data(double magnetic_field) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Magnetic Field: %.2f mT\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, magnetic_field);
    } else {
        fprintf(fp, "Timestamp error, Magnetic Field: %.2f mT\n", magnetic_field);
    }
    fclose(fp);
}

static void control_led(double magnetic_field) {
    gpioWrite(LED_GPIO, (magnetic_field > THRESHOLD) ? 1 : 0);
}

