#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (GPIO8)            */
#define SPI_SPEED      1000000    /* 1 MHz                                 */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                 */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0        */
#define ADC_MAX        1023       /* 10-bit ADC full-scale                  */
#define VREF           5.0        /* MCP3008 VREF tied to Pi 5V rail        */
#define VDD            5.0        /* MLX91211 VDD from Pi 5V pin            */
#define ZERO_CURRENT_V 2.5        /* MLX91211 output at 0 A (VDD/2)        */
#define FULL_SCALE_A   50.0       /* MLX91211 full-scale current (A)       */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms between samples                */

/* ------------------------------- Globals --------------------------------- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* --------------------------- Function prototypes ------------------------- */
static int  read_adc(int channel, int *out_raw);
static float convert_to_current(int raw);
static void log_current(float current);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- ADC read -------------------------------- */
/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (raw stored in *out_raw), -1 on SPI error.
 */
static int read_adc(int channel, int *out_raw)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_raw == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = 0x80 | (channel << 4)      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *out_raw = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* --------------------------- Current conversion -------------------------- */
static float convert_to_current(int raw)
{
    float voltage = ((float)raw / (float)ADC_MAX) * VREF;
    float current = ((voltage - ZERO_CURRENT_V) / ZERO_CURRENT_V) * FULL_SCALE_A;
    return current;
}

/* ------------------------------- Logging --------------------------------- */
static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open; cannot log current.\n");
    }
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("MLX91211 current monitor started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (program_running) {
        int raw = 0;
        if (read_adc(ADC_CHANNEL, &raw) != 0) {
            fprintf(stderr, "ADC read error; skipping sample.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = convert_to_current(raw);

        /* Sanity-check voltage range */
        float voltage = ((float)raw / (float)ADC_MAX) * VREF;
        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr, "Warning: voltage %.3f V out of range; skipping.\n",
                    voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_current(current);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

