    unsigned char tx[3] = { 0x01, (unsigned char)(0x80 | (channel << 4)), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *out_raw = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* --------------------------- Current conversion -------------------------- */
static float convert_to_current(int raw)
{
    float voltage = ((float)raw / (float)ADC_MAX) * VREF;
    float current = ((voltage - ZERO_CURRENT_V) / ZERO_CURRENT_V) * FULL_SCALE_A;
    return current;
}

/* ------------------------------- Logging --------------------------------- */
static void log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %.2f A\n", timestamp, current);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not open; cannot log current.\n");
    }
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("MLX91211 current monitor started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (program_running) {
        int raw = 0;
        if (read_adc(ADC_CHANNEL, &raw) != 0) {
            fprintf(stderr, "ADC read error; skipping sample.\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float current = convert_to_current(raw);

        /* Sanity-check voltage range */
        float voltage = ((float)raw / (float)ADC_MAX) * VREF;
        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr, "Warning: voltage %.3f V out of range; skipping.\n",
                    voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        log_current(current);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

