#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define POLL_INTERVAL_S 1

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_debounced(struct gpiod_line *line) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            return -1;
        }
        if (val == 0) low_count++;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }
    return (low_count >= (DEBOUNCE_SAMPLES / 2 + 1)) ? 0 : 1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("gpiod_chip_get_line (GPIO4)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("gpiod_chip_get_line (GPIO17)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line1, "b5w-sensor1") < 0) {
        perror("gpiod_line_request_input (GPIO4)");
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "b5w-sensor2") < 0) {
        perror("gpiod_line_request_input (GPIO17)");
        goto cleanup;
    }

    printf("Monitoring B5W-DB01 sensors on GPIO4 and GPIO17. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor_debounced(line1);
        int s2 = read_sensor_debounced(line2);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error, exiting.\n");
            goto cleanup;
        }

        printf("Sensor 1: %s | Sensor 2: %s\n",
               s1 ? "no object" : "object present",
               s2 ? "no object" : "object present");

        if (s1 == 0 && s2 == 0) {
            printf("ALERT: Both sensors detect object\n");
        }

        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

