#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    int channel;
    int baud;
} spi_config_t;

static int read_mcp3008(int channel);
static double calculate_moisture_level(int adc_value);
static int log_data(double moisture_level);
static void signal_handler(int signal);
static int spi_setup(spi_config_t config);

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = 0x80 | (channel << 4);
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

static double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return 100.0 - ((double)(adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
}

static int log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);
    return 0;
}

static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

static int spi_setup(spi_config_t config) {
    spi_handle = spiOpen(config.channel, config.baud, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", config.channel, spi_handle);
        return -1;
    }
    return 0;
}

int main(void) {
    spi_config_t spi_config = {SPI_CHANNEL, SPI_BAUD};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_setup(spi_config) != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);

        if (log_data(moisture_level) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        printf("Moisture Level: %.2f%%\n", moisture_level);

        sleep(READ_DELAY);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

