    if (snprintf(filename, sizeof(filename), "%s/%04d%02d%02d_%02d%02d%02d.jpg",
                 IMAGE_DIR, timeinfo.tm_year + 1900, timeinfo.tm_mon + 1,
                 timeinfo.tm_mday, timeinfo.tm_hour, timeinfo.tm_min, timeinfo.tm_sec) >= (int)sizeof(filename)) {
        syslog(LOG_ERR, "Filename too long");
        return -1;
    }

    if (snprintf(command, sizeof(command),
                 "libcamera-still -o %s --width %d --height %d --nopreview",
                 filename, IMAGE_WIDTH, IMAGE_HEIGHT) >= (int)sizeof(command)) {
        syslog(LOG_ERR, "Command buffer too small");
        return -1;
    }

    pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        char *argv[] = {"libcamera-still", "-o", filename, "--width", "1280", "--height", "720", "--nopreview", NULL};
        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp libcamera-still failed: %s", strerror(errno));
        _exit(127);
    }

    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (exit status %d)", WIFEXITED(status) ? WEXITSTATUS(status) : -1);
    return -1;
}

int main(void) {
    int last_state = 0;
    int ret = 0;

    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register signal handler: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    if (ensure_image_dir() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Motion detector started (PIR on GPIO%d)", PIR_GPIO);
    last_state = gpioRead(PIR_GPIO);

    while (running) {
        int current_state = gpioRead(PIR_GPIO);

        if (current_state != last_state) {
            gpioDelay(DEBOUNCE_DELAY_US);
            current_state = gpioRead(PIR_GPIO);

            if (current_state == 1) {
                syslog(LOG_INFO, "Motion detected on GPIO%d", PIR_GPIO);
                if (capture_image() != 0) {
                    syslog(LOG_ERR, "Failed to capture image");
                }
            }
            last_state = current_state;
        }

        gpioDelay(POLL_DELAY_US);
    }

    syslog(LOG_INFO, "Motion detector shutting down");
    gpioTerminate();
    closelog();
    return ret;
}

