#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define DEFAULT_WIDTH  640
#define DEFAULT_HEIGHT 480
#define DEFAULT_COUNT  10
#define MAX_FILENAME  64
#define MAX_BUFFERS   10

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int open_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

static int init_device(int fd, int width, int height) {
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_GREY) {
        fprintf(stderr, "Camera did not accept GREY format\n");
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        return -1;
    }

    void *start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (start == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_frame(int fd, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    struct timeval tv = { .tv_sec = 2, .tv_usec = 0 };

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "select failed: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(buffer, 1, buf.bytesused, stdout) != buf.bytesused) {
        fprintf(stderr, "fwrite failed: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(int fd, void *buffer, size_t buffer_size, int streaming) {
    if (streaming) stop_streaming(fd);
    if (buffer && buffer_size > 0) {
        munmap(buffer, buffer_size);
    }
    if (fd >= 0) close(fd);
}

int main(int argc, char *argv[]) {
    const char *device = DEFAULT_DEVICE;
    int width = DEFAULT_WIDTH;
    int height = DEFAULT_HEIGHT;
    int count = DEFAULT_COUNT;

    if (argc > 1) device = argv[1];
    if (argc > 2) width = atoi(argv[2]);
    if (argc > 3) height = atoi(argv[3]);
    if (argc > 4) count = atoi(argv[4]);

    if (width <= 0 || height <= 0 || count <= 0) {
        fprintf(stderr, "Usage: %s [device] [width] [height] [count]\n", argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open_device(device);
    if (fd < 0) return EXIT_FAILURE;

    if (init_device(fd, width, height) < 0) {
        cleanup(fd, NULL, 0, 0);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd) < 0) {
        cleanup(fd, NULL, 0, 0);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF initial failed: %s\n", strerror(errno));
        cleanup(fd, NULL, 0, 1);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < count && !g_stop; i++) {
        void *buffer = NULL;
        size_t buffer_size = 0;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) continue;
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            break;
        }

        buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffer == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            break;
        }
        buffer_size = buf.length;

        char filename[MAX_FILENAME];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", i + 1);
        FILE *fp = fopen(filename, "wb");
        if (!fp) {
            fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
            munmap(buffer, buffer_size);
            break;
        }

        if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
            fprintf(stderr, "fwrite failed: %s\n", strerror(errno));
            fclose(fp);
            munmap(buffer, buffer_size);
            break;
        }
        fclose(fp);
        munmap(buffer, buffer_size);

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            break;
        }
    }

    cleanup(fd, NULL, 0, 1);
    return EXIT_SUCCESS;
}

