    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    stream->fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (stream->fd < 0) {
        fprintf(stderr, "Cannot open /dev/video0: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(stream->fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "/dev/video0 is not a video capture device\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "/dev/video0 does not support streaming I/O\n");
        return -1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(stream->fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    CLEAR(req);
    req.count = MAX_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(stream->fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    stream->n_buffers = req.count;
    for (unsigned int i = 0; i < stream->n_buffers; i++) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(stream->fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
            return -1;
        }

        stream->buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, stream->fd, buf.m.offset);
        if (stream->buffers[i] == MAP_FAILED) {
            fprintf(stderr, "mmap failed: %s\n", strerror(errno));
            return -1;
        }
        stream->buffer_sizes[i] = buf.length;
    }

    for (unsigned int i = 0; i < stream->n_buffers; i++) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;
        if (xioctl(stream->fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(stream->fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_frame(CameraStream *stream) {
    struct v4l2_buffer buf;
    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(stream->fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) return 1;
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= stream->n_buffers) {
        fprintf(stderr, "Invalid buffer index: %u\n", buf.index);
        return -1;
    }

    unsigned int frame_size = buf.bytesused;
    unsigned int num_fragments = (frame_size + PAYLOAD_SIZE - 1) / PAYLOAD_SIZE;
    unsigned int last_frag_size = frame_size % PAYLOAD_SIZE;
    last_frag_size = (last_frag_size == 0) ? PAYLOAD_SIZE : last_frag_size;

    for (unsigned int frag = 0; frag < num_fragments; frag++) {
        unsigned int payload_len = (frag == num_fragments - 1) ? last_frag_size : PAYLOAD_SIZE;
        FrameHeader header;
        header.frame_index = stream->frame_count;
        header.fragment_index = frag;
        header.total_fragments = num_fragments;
        header.payload_size = payload_len;

        size_t dgram_size = HEADER_SIZE + payload_len;
        char *dgram = malloc(dgram_size);
        if (!dgram) {
            fprintf(stderr, "malloc failed for datagram\n");
            return -1;
        }

        memcpy(dgram, &header, HEADER_SIZE);
        memcpy(dgram + HEADER_SIZE, stream->buffers[buf.index] + frag * PAYLOAD_SIZE, payload_len);

        if (sendto(stream->sock, dgram, dgram_size, 0, (struct sockaddr *)&stream->addr, sizeof(stream->addr)) < 0) {
            fprintf(stderr, "sendto failed: %s\n", strerror(errno));
            free(dgram);
            return -1;
        }
        free(dgram);
    }

    if (xioctl(stream->fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        return -1;
    }

    stream->frame_count++;
    return 0;
}

static void cleanup(CameraStream *stream) {
    if (stream->fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(stream->fd, VIDIOC_STREAMOFF, &type);
        for (unsigned int i = 0; i < stream->n_buffers; i++) {
            if (stream->buffers[i] != NULL && stream->buffers[i] != MAP_FAILED) {
                munmap(stream->buffers[i], stream->buffer_sizes[i]);
                stream->buffers[i] = NULL;
            }
        }
        close(stream->fd);
        stream->fd = -1;
    }
    if (stream->sock >= 0) {
        close(stream->sock);
        stream->sock = -1;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    g_stream.server_ip = argv[1];
    g_stream.server_port = atoi(argv[2]);
    if (g_stream.server_port <= 0 || g_stream.server_port > 65535) {
        fprintf(stderr, "Invalid port: %s\n", argv[2]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    CLEAR(sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_camera(&g_stream) < 0) {
        cleanup(&g_stream);
        return EXIT_FAILURE;
    }

    g_stream.sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_stream.sock < 0) {
        fprintf(stderr, "socket failed: %s\n", strerror(errno));
        cleanup(&g_stream);
        return EXIT_FAILURE;
    }

    CLEAR(g_stream.addr);
    g_stream.addr.sin_family = AF_INET;
    g_stream.addr.sin_port = htons(g_stream.server_port);
    if (inet_pton(AF_INET, g_stream.server_ip, &g_stream.addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid IP address: %s\n", g_stream.server_ip);
        cleanup(&g_stream);
        return EXIT_FAILURE;
    }

    printf("Streaming to %s:%d\n", g_stream.server_ip, g_stream.server_port);

    while (!g_stream.stop) {
        int ret = capture_frame(&g_stream);
        if (ret < 0) {
            fprintf(stderr, "Capture error, exiting\n");
            break;
        }
        if (ret == 1) {
            usleep(10000);
            continue;
        }
        usleep(30000);
    }

    printf("\nShutting down...\n");
    cleanup(&g_stream);
    return EXIT_SUCCESS;
}

