    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal\n");
            goto cleanup;
        }
        fprintf(stderr, "Error in select: %s\n", strerror(errno));
        goto cleanup;
    } else if (r == 0) {
        fprintf(stderr, "Error: Frame capture timeout\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    if (stop) {
        fprintf(stderr, "Interrupted during capture\n");
        goto cleanup;
    }

    rgb = malloc(WIDTH * HEIGHT * CHANNELS);
    if (!rgb) {
        fprintf(stderr, "Error allocating RGB buffer\n");
        goto cleanup;
    }

    int y, u, v;
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            int idx = (i * WIDTH + j) * 2;
            y = buffer[idx];
            u = buffer[idx + 1];
            v = buffer[idx + 3];

            int r1 = y + 1.140 * (v - 128);
            int g1 = y - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            int b1 = y + 2.032 * (u - 128);

            rgb[(i * WIDTH + j) * 3] = (r1 < 0) ? 0 : (r1 > 255) ? 255 : r1;
            rgb[(i * WIDTH + j) * 3 + 1] = (g1 < 0) ? 0 : (g1 > 255) ? 255 : g1;
            rgb[(i * WIDTH + j) * 3 + 2] = (b1 < 0) ? 0 : (b1 > 255) ? 255 : b1;
        }
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (save_jpeg(rgb, WIDTH, HEIGHT, QUALITY, filename) == 0) {
        printf("Saved: %s\n", filename);
        ret = 0;
    } else {
        fprintf(stderr, "Error saving JPEG\n");
    }

cleanup:
    if (buffer) {
        munmap(buffer, buf.length);
    }
    if (rgb) {
        free(rgb);
    }
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        close(fd);
    }
    return ret;
}

