#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_RESOLUTIONS 64
#define MAX_FRAME_RATES 32

static void print_resolutions(const struct v4l2_frmsizeenum *sizes, int count) {
    printf("Supported Resolutions:\n");
    for (int i = 0; i < count; i++) {
        if (sizes[i].type != V4L2_FRMSIZE_TYPE_DISCRETE)
            continue;
        printf("  %ux%u\n", sizes[i].discrete.width, sizes[i].discrete.height);
    }
}

static void print_frame_rates(const struct v4l2_frmivalenum *intervals, int count, unsigned int width, unsigned int height) {
    printf("  Frame rates for %ux%u:\n", width, height);
    for (int i = 0; i < count; i++) {
        if (intervals[i].width != width || intervals[i].height != height)
            continue;
        if (intervals[i].type != V4L2_FRMIVAL_TYPE_DISCRETE)
            continue;
        printf("    %.2f fps\n", intervals[i].discrete.numerator / (float)intervals[i].discrete.denominator);
    }
}

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Camera: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Bus info: %s\n", cap.bus_info);

    struct v4l2_frmsizeenum sizes;
    memset(&sizes, 0, sizeof(sizes));
    sizes.index = 0;
    sizes.type = V4L2_FRMSIZE_TYPE_DISCRETE;

    printf("\nSupported Resolutions:\n");
    int res_count = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &sizes) == 0 && res_count < MAX_RESOLUTIONS) {
        if (sizes.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %ux%u\n", sizes.discrete.width, sizes.discrete.height);
            res_count++;
        }
        sizes.index++;
    }
    if (errno != EINVAL)
        fprintf(stderr, "Warning: frame size enumeration failed: %s\n", strerror(errno));

    struct v4l2_frmivalenum intervals;
    memset(&intervals, 0, sizeof(intervals));
    intervals.index = 0;
    intervals.type = V4L2_FRMIVAL_TYPE_DISCRETE;

    printf("\nSupported Frame Rates:\n");
    int frame_rates_found = 0;
    for (int i = 0; i < res_count; i++) {
        intervals.index = 0;
        intervals.type = V4L2_FRMIVAL_TYPE_DISCRETE;
        intervals.width = sizes.discrete.width;
        intervals.height = sizes.discrete.height;

        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &intervals) == 0) {
            if (intervals.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
                printf("  %ux%u: %.2f fps\n", intervals.width, intervals.height,
                       intervals.discrete.numerator / (float)intervals.discrete.denominator);
                frame_rates_found++;
            }
            intervals.index++;
        }
        if (errno != EINVAL)
            fprintf(stderr, "Warning: frame interval enumeration failed for %ux%u: %s\n",
                    sizes.discrete.width, sizes.discrete.height, strerror(errno));
        sizes.index++;
    }

    if (frame_rates_found == 0)
        printf("  (No frame rates reported)\n");

    struct v4l2_queryctrl ctrl;
    memset(&ctrl, 0, sizeof(ctrl));
    ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) == 0) {
        printf("\nAutofocus: %s\n", ctrl.minimum ? "Supported" : "Not supported");
    } else if (errno == EINVAL) {
        printf("\nAutofocus: Not supported\n");
    } else {
        fprintf(stderr, "Warning: could not query autofocus control: %s\n", strerror(errno));
    }

    close(fd);
    return EXIT_SUCCESS;
}

