#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_SERVO_PIN   4
#define TILT_SERVO_PIN  5
#define UP_BUTTON_PIN   6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define SERVO_CENTER    1500
#define SERVO_STEP      10
#define LOOP_DELAY_US   50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo(int pin, int pulse) {
    if (pulse < SERVO_MIN_PULSE || pulse > SERVO_MAX_PULSE) {
        fprintf(stderr, "Error: pulse %d out of range on pin %d\n", pulse, pin);
        return -1;
    }
    if (gpioServo(pin, pulse) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with internal pull-ups */
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    /* Initialize servos to center */
    int pan_pos = SERVO_CENTER;
    int tilt_pos = SERVO_CENTER;
    if (set_servo(PAN_SERVO_PIN, pan_pos) != 0 ||
        set_servo(TILT_SERVO_PIN, tilt_pos) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt control ready.\n");
    printf("  Pan servo : GPIO%d\n", PAN_SERVO_PIN);
    printf("  Tilt servo: GPIO%d\n", TILT_SERVO_PIN);
    printf("  Up button : GPIO%d\n", UP_BUTTON_PIN);
    printf("  Down btn  : GPIO%d\n", DOWN_BUTTON_PIN);
    printf("  Left btn  : GPIO%d\n", LEFT_BUTTON_PIN);
    printf("  Right btn : GPIO%d\n", RIGHT_BUTTON_PIN);
    printf("  Center position: pan=%d us, tilt=%d us\n", pan_pos, tilt_pos);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int up =   gpioRead(UP_BUTTON_PIN);
        int down = gpioRead(DOWN_BUTTON_PIN);
        int left = gpioRead(LEFT_BUTTON_PIN);
        int right = gpioRead(RIGHT_BUTTON_PIN);

        if (up == 0) {
            pan_pos += SERVO_STEP;
            if (pan_pos > SERVO_MAX_PULSE) pan_pos = SERVO_MAX_PULSE;
        }
        if (down == 0) {
            pan_pos -= SERVO_STEP;
            if (pan_pos < SERVO_MIN_PULSE) pan_pos = SERVO_MIN_PULSE;
        }
        if (left == 0) {
            tilt_pos -= SERVO_STEP;
            if (tilt_pos < SERVO_MIN_PULSE) tilt_pos = SERVO_MIN_PULSE;
        }
        if (right == 0) {
            tilt_pos += SERVO_STEP;
            if (tilt_pos > SERVO_MAX_PULSE) tilt_pos = SERVO_MAX_PULSE;
        }

        if (set_servo(PAN_SERVO_PIN, pan_pos) != 0 ||
            set_servo(TILT_SERVO_PIN, tilt_pos) != 0) {
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop PWM and release pigpio */
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

