#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_MS 2000
#define POLL_INTERVAL_MS 100
#define SNAPSHOT_WIDTH 640
#define SNAPSHOT_HEIGHT 480
#define SNAPSHOT_QUALITY 85
#define MOTION_STATUS 1
#define NO_MOTION_STATUS 0
#define CAPTURE_DIR "motion_captures"
#define TIMESTAMP_LEN 32
#define FILENAME_LEN 64
#define JSON_BUF_LEN 512

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_snapshot(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s -w %d -h %d -q %d --nopreview 2>/dev/null",
        filename, SNAPSHOT_WIDTH, SNAPSHOT_HEIGHT, SNAPSHOT_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: snapshot command too long\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
