static int send_data(const char *filename, const char *server_ip, int server_port) {
    char url[256];
    int ret = snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);
    if (ret < 0 || (size_t)ret >= sizeof(url)) {
        fprintf(stderr, "Error: URL too long\n");
        return -1;
    }

    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size < 0) {
        perror("ftell");
        fclose(fp);
        return -1;
    }
    fseek(fp, 0, SEEK_SET);

    char *file_data = malloc((size_t)file_size);
    if (!file_data) {
        fprintf(stderr, "Error: out of memory\n");
        fclose(fp);
        return -1;
    }

    size_t bytes_read = fread(file_data, 1, (size_t)file_size, fp);
