static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int ensure_directory(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", path);
        return -1;
    }
    if (mkdir(path, 0755) != 0) {
        perror("mkdir");
        return -1;
    }
    return 0;
}

static int capture_snapshot(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "libcamera-still -o %s -w %d -h %d -q %d --nopreview 2>/dev/null",
        filename, SNAPSHOT_WIDTH, SNAPSHOT_HEIGHT, SNAPSHOT_QUALITY);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: snapshot command too long\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        perror("system");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: libcamera-still failed (status=%d)\n", status);
        return -1;
    }
    return 0;
}

static int send_data(const char *filename, const char *server_ip, int server_port) {
    char url[256];
    int ret = snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);
    if (ret < 0 || (size_t)ret >= sizeof(url)) {
        fprintf(stderr, "Error: URL too long\n");
        return -1;
    }

    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size < 0) {
        perror("ftell");
        fclose(fp);
        return -1;
    }
    fseek(fp, 0, SEEK_SET);

    char *file_data = malloc((size_t)file_size);
    if (!file_data) {
        fprintf(stderr, "Error: out of memory\n");
        fclose(fp);
        return -1;
    }

    size_t bytes_read = fread(file_data, 1, (size_t)file_size, fp);
    fclose(fp);
    if (bytes_read != (size_t)file_size) {
        fprintf(stderr, "Error: incomplete read\n");
        free(file_data);
        return -1;
    }

    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Error: curl_easy_init failed\n");
        free(file_data);
        return -1;
