#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
        fflush(log_fp);
    }
}

static int capture_image(const char *filename) {
    char command[512];
    snprintf(command, sizeof(command),
             "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview",
             filename);
    int ret = system(command);
    if (ret == -1) {
        log_event("system() failed to launch libcamera-still");
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "libcamera-still exited with status %d", WEXITSTATUS(ret));
        log_event(buf);
        return -1;
    }
    return 0;
}

static int generate_filename(char *buf, size_t buflen) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) return -1;
    if (strftime(buf, buflen, "%Y%m%d_%H%M%S_%3N.jpg", &tm) == 0) return -1;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
    int ret = EXIT_FAILURE;

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(line, "pir-motion") < 0) {
        perror("gpiod_line_request_falling_edge_events");
        goto cleanup;
    }

    log_event("Motion capture system started");
    printf("Motion capture system started. Press Ctrl+C to exit.\n");

    while (running) {
        int ev = gpiod_line_event_wait(line, &ts);
        if (ev < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_wait");
            break;
        }
        if (ev == 0) continue;

        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            if (errno == EINTR) continue;
            perror("gpiod_line_event_read");
            break;
        }

        if (event.event_type != GPIOD_LINE_EVENT_FALLING_EDGE) continue;

        char filename[256];
        if (generate_filename(filename, sizeof(filename)) != 0) {
            log_event("Failed to generate filename");
            continue;
        }

        char fullpath[512];
        snprintf(fullpath, sizeof(fullpath), "%s/%s", IMAGE_DIR, filename);

        if (capture_image(fullpath) == 0) {
            char msg[512];
            snprintf(msg, sizeof(msg), "Motion detected, image saved: %s", fullpath);
            log_event(msg);
            printf("%s\n", msg);
        } else {
            log_event("Failed to capture image");
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) {
        log_event("Motion capture system stopped");
        fclose(log_fp);
    }
    return ret;
}

