#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "cropped.yuv"
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 1

static volatile sig_atomic_t stop_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    stop_flag = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, unsigned char **buffer, size_t *buffer_size) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    fd_set fds;
    struct timeval tv;
    int r;

    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }
    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device did not accept YUYV format\n");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    *buffer_size = buf.length;
    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        perror("mmap");
        *buffer = NULL;
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        munmap(*buffer, *buffer_size);
        *buffer = NULL;
        return -1;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        munmap(*buffer, *buffer_size);
        *buffer = NULL;
        return -1;
    }

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;
    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal\n");
        } else {
            perror("select");
        }
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(*buffer, *buffer_size);
        *buffer = NULL;
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(*buffer, *buffer_size);
        *buffer = NULL;
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(*buffer, *buffer_size);
        *buffer = NULL;
        return -1;
    }

    if (buf.bytesused < (size_t)(FRAME_WIDTH * FRAME_HEIGHT * 2)) {
        fprintf(stderr, "Captured frame too small: %u bytes\n", buf.bytesused);
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(*buffer, *buffer_size);
        *buffer = NULL;
        return -1;
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        munmap(*buffer, *buffer_size);
        *buffer = NULL;
        return -1;
    }

    return 0;
}

static int crop_and_save(const unsigned char *frame, int width, int height,
                         int crop_x, int crop_y, int crop_width, int crop_height,
                         const char *output_file) {
    FILE *fp = fopen(output_file, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    if (crop_x < 0 || crop_y < 0 || crop_x + crop_width > width || crop_y + crop_height > height) {
        fprintf(stderr, "Invalid crop region\n");
        fclose(fp);
        return -1;
    }

    int bytes_per_macroblock = 4;
    int bytes_per_row = width * bytes_per_macroblock;
    int bytes_to_skip = (crop_x * bytes_per_macroblock) + (crop_y * bytes_per_row);
    int bytes_to_copy = crop_width * bytes_per_macroblock * crop_height;

    unsigned char *cropped = malloc(bytes_to_copy);
    if (!cropped) {
        perror("malloc");
        fclose(fp);
        return -1;
    }

    const unsigned char *src = frame + bytes_to_skip;
    unsigned char *dst = cropped;
    for (int i = 0; i < crop_height; i++) {
        memcpy(dst, src, crop_width * bytes_per_macroblock);
        src += bytes_per_row;
        dst += crop_width * bytes_per_macroblock;
    }

    if (fwrite(cropped, 1, bytes_to_copy, fp) != bytes_to_copy) {
        perror("fwrite");
        free(cropped);
        fclose(fp);
        return -1;
    }

    free(cropped);
    fclose(fp);
    return 0;
}

int main(void) {
    int fd = -1;
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (capture_frame(fd, &buffer, &buffer_size) < 0) {
        if (buffer) munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    if (stop_flag) {
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    if (crop_and_save(buffer, FRAME_WIDTH, FRAME_HEIGHT,
                       CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT,
                       OUTPUT_FILE) < 0) {
        munmap(buffer, buffer_size);
        close(fd);
        return EXIT_FAILURE;
    }

    munmap(buffer, buffer_size);
    close(fd);
    printf("Cropped frame saved to %s\n", OUTPUT_FILE);
    return EXIT_SUCCESS;
}

