#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define NEUTRAL_ANGLE 90
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define STEP 5
#define DELAY_MS 100

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int angle_to_pulse(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range (%d-%d)\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE));
}

int set_servo_angle(int gpio, int angle) {
    int pulse = angle_to_pulse(angle);
    if (pulse < 0) return -1;
    if (gpioPWM(gpio, pulse) != 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 1;
    }

    signal(SIGINT, handle_signal);

    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    printf("Pan-Tilt Camera Mount\n");
    printf("Use arrow keys to move. 'q' to quit.\n");

    while (keep_running) {
        printf("\nPan: %d, Tilt: %d\n", pan_angle, tilt_angle);
        fflush(stdout);

        char input = getchar();
        if (input == EOF) break;

        switch (input) {
            case 'a':
                pan_angle -= STEP;
                if (pan_angle < MIN_ANGLE) pan_angle = MIN_ANGLE;
                break;
            case 'd':
                pan_angle += STEP;
                if (pan_angle > MAX_ANGLE) pan_angle = MAX_ANGLE;
                break;
            case 'w':
                tilt_angle += STEP;
                if (tilt_angle > MAX_ANGLE) tilt_angle = MAX_ANGLE;
                break;
            case 's':
                tilt_angle -= STEP;
                if (tilt_angle < MIN_ANGLE) tilt_angle = MIN_ANGLE;
                break;
            case 'q':
                keep_running = 0;
                break;
            default:
                continue;
        }

        if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
            fprintf(stderr, "Error setting pan servo\n");
        }
        if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
            fprintf(stderr, "Error setting tilt servo\n");
        }

        gpioDelay(DELAY_MS * 1000);
    }

    // Set servos to neutral before exit
    set_servo_angle(PAN_GPIO, NEUTRAL_ANGLE);
    set_servo_angle(TILT_GPIO, NEUTRAL_ANGLE);
    gpioTerminate();
    printf("\nServos set to neutral, exiting.\n");
    return 0;
}

