        fprintf(stderr, "I2C write error: command 0x%02X\n", cmd);
        return -1;
    }
    return 0;
}

static int oled_data(const unsigned char *data, int len) {
    char buf[129];
    buf[0] = OLED_DATA;
    if (len > 128) len = 128;
    memcpy(buf + 1, data, len);
    if (i2cWriteDevice(i2c_handle, buf, len + 1) != (len + 1)) {
        fprintf(stderr, "I2C write error: data block (%d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int oled_init(void) {
    if (oled_command(0xAE) < 0) return -1;
    if (oled_command(0xD5) < 0) return -1;
    if (oled_command(0x80) < 0) return -1;
    if (oled_command(0xA8) < 0) return -1;
    if (oled_command(0x3F) < 0) return -1;
    if (oled_command(0xD3) < 0) return -1;
    if (oled_command(0x00) < 0) return -1;
    if (oled_command(0x40) < 0) return -1;
    if (oled_command(0x8D) < 0) return -1;
    if (oled_command(0x14) < 0) return -1;
    if (oled_command(0x20) < 0) return -1;
    if (oled_command(0x00) < 0) return -1;
    if (oled_command(0xA1) < 0) return -1;
    if (oled_command(0xC8) < 0) return -1;
    if (oled_command(0xDA) < 0) return -1;
    if (oled_command(0x12) < 0) return -1;
    if (oled_command(0x81) < 0) return -1;
    if (oled_command(0xCF) < 0) return -1;
    if (oled_command(0xD9) < 0) return -1;
    if (oled_command(0xF1) < 0) return -1;
    if (oled_command(0xDB) < 0) return -1;
    if (oled_command(0x40) < 0) return -1;
    if (oled_command(0xA4) < 0) return -1;
    if (oled_command(0xA6) < 0) return -1;
    if (oled_command(0xAF) < 0) return -1;
    return 0;
}

static int oled_clear(void) {
    unsigned char buf[129];
    buf[0] = OLED_DATA;
    memset(buf + 1, 0x00, 128);
    for (int page = 0; page < 8; page++) {
        if (oled_command(0xB0 + page) < 0) return -1;
        if (oled_command(0x00) < 0) return -1;
        if (oled_command(0x10) < 0) return -1;
        if (oled_data(buf + 1, 128) < 0) return -1;
    }
    return 0;
}

static int oled_set_cursor(int col, int row) {
    if (oled_command(0xB0 + row) < 0) return -1;
    if (oled_command(0x00 + (col & 0x0F)) < 0) return -1;
    if (oled_command(0x10 + ((col >> 4) & 0x0F)) < 0) return -1;
    return 0;
}

static int oled_print_char(int col, int row, char c) {
    if (oled_set_cursor(col, row) < 0) return -1;
    unsigned char glyph[5];
    if (c >= ' ' && c <= '~') {
        memcpy(glyph, font5x7[c - ' '], 5);
    } else {
        memcpy(glyph, font5x7['?' - ' '], 5);
    }
    return oled_data(glyph, 5);
}

static int oled_print_string(int col, int row, const char *str) {
    int ret = 0;
    while (*str && ret == 0) {
        ret = oled_print_char(col, row, *str++);
        col += 6;
    }
    return ret;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fclose(fp);
        return -2;
    }
    fclose(fp);
    return temp / 1000;
}

static int read_cpu_usage(void) {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        return -1;
    }
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int ret = fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                     &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);
    if (ret != 10) {
        return -2;
    }
    static unsigned long long prev_idle = 0, prev_total = 0;
    unsigned long long idle_total = idle + iowait;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    if (prev_total == 0) {
        prev_idle = idle_total;
        prev_total = total;
        return 0;
    }
    unsigned long long diff_idle = idle_total - prev_idle;
    unsigned long long diff_total = total - prev_total;
    prev_idle = idle_total;
    prev_total = total;
    if (diff_total == 0) return 0;
    return (int)(((diff_total - diff_idle) * 100ULL) / diff_total);
}

static void display_error(const char *msg) {
    oled_clear();
    oled_print_string(0, 0, "ERROR");
    oled_print_string(0, 1, msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OLED_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (oled_init() < 0) {
        fprintf(stderr, "OLED init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (oled_clear() < 0) {
        fprintf(stderr, "OLED clear failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        int temp = read_cpu_temp();
        int usage = read_cpu_usage();

        oled_clear();

        if (temp < 0) {
            display_error("TEMP READ ERR");
        } else {
            char buf[16];
            snprintf(buf, sizeof(buf), "Temp: %d C", temp);
            oled_print_string(0, 0, buf);
        }

        if (usage < 0) {
            display_error("USAGE READ ERR");
        } else {
            char buf[16];
            snprintf(buf, sizeof(buf), "Usage: %d%%", usage);
            oled_print_string(0, 1, buf);
        }

        time_sleep(1.0);
    }

    oled_clear();
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

