#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static double total_volume = 0.0;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level == 1) {
        pulse_count++;
    }
}

static void lcd_strobe(int data) {
    if (i2c_handle < 0) return;
    i2cWriteByte(i2c_handle, data | ENABLE | LCD_BACKLIGHT);
    usleep(2000);
    i2cWriteByte(i2c_handle, (data & ~ENABLE) | LCD_BACKLIGHT);
    usleep(20000);
}

static void lcd_byte(int bits, int mode) {
    if (i2c_handle < 0) return;
    int high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;
    i2cWriteByte(i2c_handle, high);
    lcd_strobe(high);
    i2cWriteByte(i2c_handle, low);
    lcd_strobe(low);
}

static void lcd_init(void) {
    if (i2c_handle < 0) return;
    usleep(50000);
    lcd_byte(0x33, LCD_CMD);
    lcd_byte(0x32, LCD_CMD);
    lcd_byte(0x28, LCD_CMD);
    lcd_byte(0x0C, LCD_CMD);
    lcd_byte(0x06, LCD_CMD);
    lcd_byte(0x01, LCD_CMD);
    usleep(2000);
}

static void lcd_clear(void) {
    if (i2c_handle < 0) return;
    lcd_byte(0x01, LCD_CMD);
    usleep(2000);
}

static void lcd_set_cursor(int col, int row) {
    if (i2c_handle < 0) return;
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    lcd_byte(addr, LCD_CMD);
}

static void lcd_print(const char *str) {
    if (i2c_handle < 0) return;
    while (*str) {
        lcd_byte((unsigned char)*str++, LCD_CHR);
    }
}

static void log_data(double flow_rate, double volume) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Flow Rate: %.2f L/min, Volume: %.2f L\n", timestamp, flow_rate, volume);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n", LCD_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    lcd_init();

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
        int current_count = pulse_count;
        pulse_count = 0;

        double flow_rate = (current_count / PULSES_PER_LITER) * 60.0;
        total_volume += flow_rate / 60.0;

        log_data(flow_rate, total_volume);

        if (i2c_handle >= 0) {
            lcd_clear();
            lcd_set_cursor(0, 0);
            char line1[20];
            snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
            lcd_print(line1);

            lcd_set_cursor(0, 1);
            char line2[20];
            snprintf(line2, sizeof(line2), "Vol: %.2f L", total_volume);
            lcd_print(line2);
        }
    }

    printf("\nShutting down...\n");
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Shutting down...");

    gpioSetAlertFunc(FLOW_SENSOR_GPIO, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

