    g_spi_handle = spiOpen(SPI_CS, SPI_SPEED_HZ, SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI0 CE0: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Anemometer GPIO --- */
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN);
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set anemometer ISR on GPIO%d\n", ANEMOMETER_GPIO);
        spiClose(g_spi_handle);
