/*
 * Raspberry Pi 4 Model B — Real-time Wind Speed & Direction Monitor
 *
 * Hardware:
 *   - 16x2 LCD (PCF8574 I2C backpack) at I2C address 0x27, bus 1
 *   - Anemometer pulse counter on GPIO17 (rising edge, 500 ms window)
 *   - MCP3008 ADC on SPI0/CE0, mode 0, 1 MHz, channel 0 (wind vane)
 *
 * Build: gcc -O2 -Wall -o wind_monitor wind_monitor.c -lpigpio -lrt
 * Run:   sudo ./wind_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define LCD_I2C_ADDR        0x27
#define LCD_BUS             1
#define ANEMOMETER_GPIO     17
#define ANEMOMETER_PULSES   500          /* pulses per 500 ms window */
#define WIND_VANE_ADC_CH    0
#define SPI_SPEED_HZ        1000000      /* 1 MHz */
#define SPI_BITS_PER_WORD   8
#define SPI_MODE            0
#define SPI_CS              0            /* CE0 */
#define SAMPLE_PERIOD_US    500000       /* 500 ms */
#define ADC_MAX             1023
#define ADC_MIN             0
#define WIND_DIR_MAX        359
#define WIND_SPEED_PER_PULSE 0.5f        /* m/s per pulse */
#define ADC_STUCK_THRESHOLD 10           /* consecutive stuck readings before warning */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_spi_handle = -1;

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- LCD Helpers ------------------------------- */
static int lcd_write_byte(int handle, uint8_t val)
{
    if (i2cWriteByte(handle, val) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int lcd_send_command(int handle, uint8_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd & 0xF0), (uint8_t)((cmd << 4) & 0xF0) };
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        fprintf(stderr, "I2C write (command) failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000); /* 2 ms */
    return 0;
}

static int lcd_send_data(int handle, uint8_t data)
{
    uint8_t buf[2] = { (uint8_t)(data | 0x01), (uint8_t)((data | 0x01) << 4) };
    if (i2cWriteDevice(handle, (char *)buf, 2) < 0) {
        fprintf(stderr, "I2C write (data) failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(2000); /* 2 ms */
    return 0;
}

static int lcd_init(int handle)
{
    gpioDelay(50000); /* wait > 40 ms after power-on */

    /* Force 4-bit mode (HD=1, RW=0, RS=0) */
    if (lcd_send_command(handle, 0x30) < 0) return -1;
    gpioDelay(5000); /* 5 ms */
    if (lcd_send_command(handle, 0x30) < 0) return -1;
    gpioDelay(150);  /* 150 us */
    if (lcd_send_command(handle, 0x30) < 0) return -1;
    gpioDelay(5000); /* 5 ms */

    /* Set 4-bit mode, 2-line, 5x8 font */
    if (lcd_send_command(handle, 0x20) < 0) return -1;
    gpioDelay(5000); /* 5 ms */

    if (lcd_send_command(handle, 0x28) < 0) return -1; /* 2-line */
    if (lcd_send_command(handle, 0x08) < 0) return -1; /* display off */
    if (lcd_send_command(handle, 0x01) < 0) return -1; /* clear */
    gpioDelay(2000); /* 2 ms */
    if (lcd_send_command(handle, 0x06) < 0) return -1; /* entry mode: inc, no shift */
    if (lcd_send_command(handle, 0x0C) < 0) return -1; /* display on, cursor off */
    return 0;
}

static int lcd_clear(int handle)
{
    return lcd_send_command(handle, 0x01);
}

static int lcd_set_cursor(int handle, int col, int row)
{
    int addr = (row == 0) ? 0x80 + col : 0xC0 + col;
    return lcd_send_command(handle, (uint8_t)addr);
}

static int lcd_print(int handle, const char *text)
{
    for (int i = 0; text[i] != '\0'; i++) {
        if (lcd_send_data(handle, (uint8_t)text[i]) < 0)
            return -1;
    }
    return 0;
}

/* ----------------------------- Anemometer -------------------------------- */
static volatile int g_pulse_count = 0;

static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static float calculate_wind_speed(int pulses)
{
    return (float)pulses * WIND_SPEED_PER_PULSE;
}

/* ----------------------------- Wind Vane (MCP3008) ----------------------- */
static int read_wind_vane(int spi_handle)
{
    /*
     * MCP3008 single-ended read: 3 bytes.
     * Byte 0: 0x01 (start bit)
     * Byte 1: 0x80 | (channel << 4) (single-ended + channel)
     * Byte 2: 0x00 (don't care)
     * Result: bits 9..0 in ((rx[1] & 0x03) << 8) | rx[2]
     */
    char tx[3] = { 0x01, (char)(0x80 | (WIND_VANE_ADC_CH << 4)), 0x00 };
    char rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_handle, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static int map_adc_to_wind_dir(int adc_value)
{
    if (adc_value < 0) return -1;
    return (int)(((float)adc_value / (float)ADC_MAX) * WIND_DIR_MAX);
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C LCD --- */
    g_i2c_handle = i2cOpen(LCD_BUS, LCD_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %s\n",
                LCD_BUS, LCD_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init(g_i2c_handle) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SPI0 CE0 for MCP3008 --- */
    g_spi_handle = spiOpen(SPI_CS, SPI_SPEED_HZ, SPI_MODE);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI0 CE0: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Anemometer GPIO --- */
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_DOWN);
    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set anemometer ISR on GPIO%d\n", ANEMOMETER_GPIO);
        spiClose(g_spi_handle);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Wind speed and direction monitor started. Press Ctrl+C to exit.\n");

    int stuck_count = 0;
    int last_adc = -1;

    while (g_running) {
        /* Reset pulse counter for this window */
        g_pulse_count = 0;

        /* Wait for the 500 ms window to elapse */
        gpioDelay(SAMPLE_PERIOD_US);

        int pulses = g_pulse_count;
        float wind_speed = calculate_wind_speed(pulses);
        int adc_value = read_wind_vane(g_spi_handle);
        int wind_dir = -1;

        if (adc_value >= 0) {
            wind_dir = map_adc_to_wind_dir(adc_value);
            stuck_count = 0;
        } else {
            stuck_count++;
