    lcd_send_command(handle, 0x0C);
    usleep(5000);
    lcd_send_command(handle, 0x06);
    usleep(5000);
    lcd_send_command(handle, 0x01);
    usleep(2000);
    return 0;
}

static int lcd_clear(int handle) {
    if (lcd_send_command(handle, 0x01) < 0) return -1;
    usleep(2000);
    return 0;
}

static int lcd_set_cursor(int handle, int row, int col) {
    int addr = (row == 0) ? 0x80 : 0xC0;
    addr += col;
    return lcd_send_command(handle, (unsigned char)addr);
}

static int lcd_print(int handle, const char *str) {
    while (*str) {
        if (lcd_send_data(handle, (unsigned char)*str) < 0) return -1;
        str++;
    }
    return 0;
}

static void cleanup(void) {
    if (lcd_handle >= 0) {
        lcd_clear(lcd_handle);
        i2cClose(lcd_handle);
        lcd_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(FLOW_SENSOR_GPIO, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    lcd_handle = i2cOpen(1, LCD_I2C_ADDR, 0);
    if (lcd_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x%02X: %s\n", LCD_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (lcd_init(lcd_handle) < 0) {
        fprintf(stderr, "LCD initialization failed\n");
        cleanup();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    time_t last_display_time = time(NULL);
    int no_flow_count = 0;

    while (running) {
        usleep(POLL_INTERVAL_US);

        int current_count = pulse_count;
        pulse_count = 0;

        double flow_rate = (double)current_count / PULSES_PER_LITER;
        time_t now = time(NULL);

        if (difftime(now, last_display_time) >= 1.0) {
            char line1[LCD_WIDTH + 1];
            char line2[LCD_WIDTH + 1];

            snprintf(line1, sizeof(line1), "Flow Rate:");
            snprintf(line2, sizeof(line2), "%.2f L/min", flow_rate);

            if (lcd_clear(lcd_handle) < 0) {
                fprintf(stderr, "LCD clear failed\n");
            } else {
                lcd_set_cursor(lcd_handle, 0, 0);
                lcd_print(lcd_handle, line1);
                lcd_set_cursor(lcd_handle, 1, 0);
                lcd_print(lcd_handle, line2);
            }

            last_display_time = now;
            no_flow_count = 0;
        } else {
            if (flow_rate == 0.0) {
                no_flow_count++;
                if (no_flow_count > 10) {
                    fprintf(stderr, "Warning: No flow detected for extended period\n");
                    no_flow_count = 0;
                }
            } else {
                no_flow_count = 0;
            }
        }

        if (current_count > MAX_PULSES_PER_INTERVAL) {
            fprintf(stderr, "Warning: Sensor overflow detected (%d pulses)\n", current_count);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

