#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define SCAN_DELAY_US 800

static const unsigned int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const unsigned int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *row_lines[NUM_ROWS];
static struct gpiod_line *col_lines[NUM_COLS];
static volatile sig_atomic_t keep_running = 1;

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) gpiod_line_release(col_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
}

static void signal_handler(int sig) {
    (void)sig;
    keep_running = 0;
}

static int setup_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(row_lines[i], "led_matrix", 0) < 0) {
            fprintf(stderr, "Failed to request row line %u as output\n", row_pins[i]);
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(col_lines[i], "led_matrix", 1) < 0) {
            fprintf(stderr, "Failed to request col line %u as output\n", col_pins[i]);
            return -1;
        }
    }

    return 0;
}

static void scan_display(const int matrix[NUM_ROWS][NUM_COLS]) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            if (gpiod_line_set_value(row_lines[row], matrix[row][col]) < 0) {
                perror("Failed to set row value");
                return;
            }
            if (gpiod_line_set_value(col_lines[col], !matrix[row][col]) < 0) {
                perror("Failed to set col value");
                return;
            }
        }
        usleep(SCAN_DELAY_US);
    }
}

static void create_wave_left_to_right(int matrix[NUM_ROWS][NUM_COLS], int frame) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            matrix[row][col] = 0;
        }
    }

    int wave_width = 3;
    int offset = frame % (NUM_COLS + 1 - wave_width);
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < wave_width; col++) {
            if (col >= offset && col < offset + wave_width) {
                matrix[row][col] = 1;
            }
        }
    }
}

static void create_wave_right_to_left(int matrix[NUM_ROWS][NUM_COLS], int frame) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            matrix[row][col] = 0;
        }
    }

    int wave_width = 3;
    int offset = frame % (NUM_COLS + 1 - wave_width);
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = NUM_COLS - 1; col >= 0; col--) {
            if (col >= offset && col < offset + wave_width) {
                matrix[row][col] = 1;
            }
        }
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (setup_gpio() < 0) {
        cleanup();
        return 1;
    }

    int matrix[NUM_ROWS][NUM_COLS];
    int frame = 0;

    while (keep_running) {
        create_wave_left_to_right(matrix, frame);
        scan_display(matrix);
        usleep(100000);

        if (!keep_running) break;

        create_wave_right_to_left(matrix, frame);
        scan_display(matrix);
        usleep(100000);

        frame++;
    }

    cleanup();
    return 0;
}

