/*
 * VL53L3CX Time-of-Flight Multi-Target Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), address 0x29
 * Library: pigpio
 *
 * NOTE: The VL53L3CX requires a proprietary firmware download (firmware
 *       loading) that is not exposed in the public ST Ultra Lite Driver
 *       (ULD) API. This program implements the full I2C communication
 *       layer and the minimal application logic needed to read distance
 *       measurements. The proprietary firmware download is stubbed out
 *       with a comment; in a production environment, the full ST ULD
 *       stack must be built and linked with this application.
 *
 * Build:  gcc -O2 -Wall -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C address ---- */
#define VL53L3CX_ADDR 0x29

/* ---- ST ULD register map (simplified for this example) ---- */
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L3CX_REG_SYSTEM_MODE_START_STOP   0x0000
#define VL53L3CX_REG_SYSTEM_INTERRUPT_CLEAR   0x0086
#define VL53L3CX_REG_RESULT_RANGE_STATUS      0x0089
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK  0x009E
#define VL53L3CX_REG_RESULT_PEAK_SIGNAL_RATE  0x00A0
#define VL53L3CX_REG_RESULT_AMBIENT_RATE     0x00A2
#define VL53L3CX_REG_RESULT_SIGMA            0x00A4
#define VL53L3CX_REG_RESULT_DISTANCE         0x00A6
#define VL53L3CX_REG_RESULT_SPAD_NB          0x00A8
#define VL53L3CX_REG_RESULT_RANGE_STATUS_2   0x00AC

/* ---- Expected model ID ---- */
#define VL53L3CX_MODEL_ID 0xEA

/* ---- Timing ---- */
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define MAX_TARGETS      4

/* ---- Globals ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
