#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_IRQ_STATUS 0x21
#define SI1145_REG_IRQ_ENABLE 0x0F
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_RATE 0x0A
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27
#define SI1145_PART_ID      0x45
#define SI1145_HW_KEY_VAL   0x17
#define SI1145_CMD_RESET    0x01
#define SI1145_CMD_PSALS_AUTO 0x0F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_proximity(int handle, uint16_t *prox) {
    uint8_t lo, hi;
    if (i2c_read_reg(handle, SI1145_REG_PS1_DATA0, &lo) < 0) return -1;
    if (i2c_read_reg(handle, SI1145_REG_PS1_DATA1, &hi) < 0) return -1;
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_ambient_light(int handle, uint16_t *als) {
    uint8_t lo, hi;
    if (i2c_read_reg(handle, SI1145_REG_ALS_VIS_DATA0, &lo) < 0) return -1;
    if (i2c_read_reg(handle, SI1145_REG_ALS_VIS_DATA1, &hi) < 0) return -1;
    *als = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1145(int handle) {
