#define SI1145_ADDR        0x60
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY  0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_CH_LIST 0x4F
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x18
#define SI1145_REG_PS1_DATA1 0x19
#define SI1145_REG_COMMAND 0x30

#define SI1145_PART_ID     0x45
#define SI1145_HW_KEY_VAL  0x17
#define SI1145_CH_LIST_EN  0x81
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE  0x07

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int si1145_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int si1145_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int si1145_read_word(uint8_t reg_low, uint16_t *value) {
    uint8_t lo, hi;
    if (si1145_read_reg(reg_low, &lo) < 0) return -1;
    if (si1145_read_reg(reg_low + 1, &hi) < 0) return -1;
    *value = (uint16_t)((hi << 8) | lo);
    return 0;
