#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define DISTANCE_THRESHOLD 15.0
#define LOG_FILE "distance_log.txt"
#define POLL_INTERVAL_SEC 60
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_MS 30
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_S 34300.0

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(FILE *log_fp, const char *msg) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_fp, "%s: %s\n", ts, msg);
    fflush(log_fp);
}

static int trigger_sensor(struct gpiod_line *trig) {
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    return 0;
}

static long long elapsed_us(const struct timespec *start, const struct timespec *end) {
    return (long long)(end->tv_sec - start->tv_sec) * 1000000LL +
           (end->tv_nsec - start->tv_nsec) / 1000LL;
}

static int measure_distance(struct gpiod_line *echo, double *distance_out) {
    struct timespec t_start, t_now;
    long long elapsed_ns;

    if (clock_gettime(CLOCK_MONOTONIC, &t_start) < 0) return -1;

    /* Wait for echo rising edge */
    while (program_running) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) return -1;
        if (val == 1) break;
        if (clock_gettime(CLOCK_MONOTONIC, &t_now) < 0) return -1;
        elapsed_ns = (t_now.tv_sec - t_start.tv_sec) * 1000000000LL +
                     (t_now.tv_nsec - t_start.tv_nsec);
        if (elapsed_ns > (long long)(ECHO_TIMEOUT_MS * 1000000)) return -1;
    }
    if (!program_running) return -1;

    struct timespec echo_rise = t_now;

    /* Wait for echo falling edge */
    while (program_running) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) return -1;
        if (val == 0) break;
        if (clock_gettime(CLOCK_MONOTONIC, &t_now) < 0) return -1;
        elapsed_ns = (t_now.tv_sec - echo_rise.tv_sec) * 1000000000LL +
                     (t_now.tv_nsec - echo_rise.tv_nsec);
        if (elapsed_ns > (long long)(ECHO_TIMEOUT_MS * 1000000)) return -1;
    }
    if (!program_running) return -1;

    struct timespec echo_fall = t_now;
    long long pulse_us = elapsed_us(&echo_rise, &echo_fall);

    if (pulse_us <= 0) return -1;

    double distance = (pulse_us / 1000000.0) * SOUND_SPEED_CM_PER_S / 2.0;
    *distance_out = distance;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    log_event(log_fp, "Program started");

    while (program_running) {
        if (trigger_sensor(trig) < 0) {
            log_event(log_fp, "Error: trigger pulse failed");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        double distance = 0.0;
        int rc = measure_distance(echo, &distance);

        if (rc == -1) {
            log_event(log_fp, "Error: echo timeout or sensor absent");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Warning: distance %.2f cm out of range [%.1f-%.1f]",
                     distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            log_event(log_fp, msg);
        } else {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %.2f cm", distance);
            log_event(log_fp, msg);

            if (distance < DISTANCE_THRESHOLD) {
                log_event(log_fp, "Time to water the plant!");
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_event(log_fp, "Program exiting");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (log_fp) fclose(log_fp);
    return ret;
}

