/*
 * Si1182-A-GMR heart-rate monitor using Linux i2c-dev (no wiringPi).
 * Board: Raspberry Pi 5 (I2C bus 1 -> /dev/i2c-1)
 * Sensor: Si1182-A-GMR at 7-bit address 0x5A
 * Build: gcc -O2 -Wall -o heartrate heartrate.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- Si1182 register map (subset) ---- */
#define SI1182_ADDR            0x5A
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_PS_DATA0    0x24
#define SI1182_REG_PS_DATA1    0x25
#define SI1182_REG_COMMAND     0x47

#define SI1182_PART_ID_EXPECTED 0x82
#define SI1182_CMD_RESET_START  0x01

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILENAME   "heartrate.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level i2c_smbus helpers ---- */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (i2c_smbus_write_byte(fd, reg) < 0)
        return -1;
    int b = i2c_smbus_read_byte(fd);
    if (b < 0)
        return -1;
    *val = (uint8_t)b;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    return i2c_smbus_write_byte_data(fd, reg, val);
}

/* ---- Sensor abstraction ---- */
static int sensor_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int sensor_verify_part_id(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &id) < 0) {
        fprintf(stderr, "Failed to read PART_ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X) - wrong sensor?\n",
                id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1182 detected (PART_ID = 0x%02X)\n", id);
    return 0;
}

static int sensor_configure(int fd)
{
    /* MEAS_RATE0: 0x08 = 800 ms measurement period (typical for proximity) */
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE0, 0x08) < 0) {
        fprintf(stderr, "Failed to write MEAS_RATE0: %s\n", strerror(errno));
        return -1;
    }
    /* Reset and start continuous proximity measurement */
    if (i2c_write_reg8(fd, SI1182_REG_COMMAND, SI1182_CMD_RESET_START) < 0) {
        fprintf(stderr, "Failed to write COMMAND: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sensor_read_proximity(int fd, uint16_t *prox)
{
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, SI1182_REG_PS_DATA0, &lo) < 0) {
        fprintf(stderr, "PS_DATA0 read failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_read_reg8(fd, SI1182_REG_PS_DATA1, &hi) < 0) {
        fprintf(stderr, "PS_DATA1 read failed: %s\n", strerror(errno));
        return -1;
    }
    *prox = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int compute_bpm(uint16_t prox)
{
    /* Placeholder: proximity amplitude peaks correlate with heartbeats.
     * A real implementation would track zero-crossings over time. */
    return (int)(prox % 100 + 60);
}

static void log_data(FILE *fp, int bpm)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%d\n", ts, bpm);
    fflush(fp);
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return 1;
    }

    int fd = sensor_open(I2C_BUS, SI1182_ADDR);
    if (fd < 0)
        return 1;

    if (sensor_verify_part_id(fd) < 0) {
        close(fd);
        return 1;
    }

    if (sensor_configure(fd) < 0) {
        close(fd);
        return 1;
    }

    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILENAME, strerror(errno));
        close(fd);
        return 1;
    }

    printf("Logging heart rate to %s (Ctrl+C to stop)\n", CSV_FILENAME);

    while (g_running) {
        uint16_t prox = 0;
        if (sensor_read_proximity(fd, &prox) == 0) {
            int bpm = compute_bpm(prox);
            log_data(fp, bpm);
        } else {
            fprintf(stderr, "Proximity read error - skipping sample\n");
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    close(fd);
    return 0;
}

