#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR             0x29
#define GPIO_TRIGGER              17
#define I2C_BUS                  1
#define LOG_FILE                 "distance_log.txt"
#define MEASUREMENT_TIMEOUT_MS   100
#define POLL_INTERVAL_US         1000

/* VL53L0X register addresses */
#define REG_SYSRANGE_START       0x00
#define REG_RESULT_INTERRUPT_STATUS 0x13
#define REG_RESULT_RANGE_STATUS  0x14
#define REG_SYSTEM_INTERRUPT_CLEAR 0x0B

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %d\n", reg, len, rc);
    }
    return rc;
}

static int vl53l0x_init(int handle)
{
    /* Verify sensor presence at 0x29 */
    int id = i2cReadByteData(handle, 0x010F);
    if (id < 0) {
        fprintf(stderr, "VL53L0X not responding at 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }
    if ((id & 0x0F) != 0x05) {
        fprintf(stderr, "Unexpected VL53L0X ID: 0x%02X\n", id);
        return -1;
    }

    /* Recommended init sequence from ST/Adafruit datasheets */
    if (i2c_write_byte(handle, 0x88, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x80, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0xFF, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0x00, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x91, 0x3C) < 0) return -1;
    if (i2c_write_byte(handle, 0x00, 0x01) < 0) return -1;
    if (i2c_write_byte(handle, 0xFF, 0x00) < 0) return -1;
    if (i2c_write_byte(handle, 0x80, 0x00) < 0) return -1;

    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[14];

    /* Start a single measurement */
    if (i2c_write_byte(handle, REG_SYSRANGE_START, 0x01) < 0)
        return -1;

    /* Poll RESULT_INTERRUPT_STATUS bit 0 until set (data ready) */
    for (int i = 0; i < MEASUREMENT_TIMEOUT_MS; i++) {
        status = (uint8_t)i2cReadByteData(handle, REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) return -1;
        if (status & 0x01) break;
        gpioDelay(POLL_INTERVAL_US);
    }

    if (!(status & 0x01)) {
        fprintf(stderr, "Measurement timeout\n");
        return -1;
    }

    /* Read 14-byte result block starting at REG_RESULT_RANGE_STATUS */
    if (i2c_read_block(handle, REG_RESULT_RANGE_STATUS, data, sizeof(data)) < 0)
        return -1;

    /* Clear interrupt to allow next measurement */
    if (i2c_write_byte(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Distance is 16-bit, bytes 10-11 (little-endian) */
    *distance_mm = (uint16_t)((data[10] << 8) | data[11]);
    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) return;
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) return;

    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

