{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L0X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X ranging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(GPIO_TRIGGER) == 0) {
            uint16_t distance = 0;
            if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
                log_distance(g_log_file, distance);
                printf("Distance: %u mm\n", distance);
            } else {
                fprintf(stderr, "Read failed\n");
            }
            /* Wait for rising edge before next trigger */
            while (g_running && gpioRead(GPIO_TRIGGER) == 0)
                gpioDelay(1000);
        }
        gpioDelay(1000);
    }

    printf("\nShutting down...\n");
    if (g_log_file)  fclose(g_log_file);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

