#include <pigpio.h>

#define I2C_BUS        1
#define CH101_ADDR     0x45
#define TRIGGER_REG    0x00
#define DISTANCE_REG   0x02
#define SAMPLE_US      200000   /* 200 ms */
#define MEASURE_US     50000    /* 50 ms  */
#define LOG_FILE       "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_distance(int handle, int *distance_mm)
{
    char trigger = 0x01;
    char buf[2];
    int  rc;

    /* Trigger a measurement */
    rc = i2cWriteByteData(handle, TRIGGER_REG, trigger);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData (trigger) failed: %d\n", rc);
        return -1;
    }

    /* Wait for the measurement to complete */
    gpioDelay(MEASURE_US);

    /* Read 2 bytes of distance data */
    rc = i2cReadI2CBlockData(handle, DISTANCE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed: %d\n", rc);
        return -1;
    }

    *distance_mm = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t     t;
    struct tm  tm;

    time(&t);
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
}

int main(void)
{
    int  handle = -1;
    FILE *log_fp = NULL;
    char ts[32];
    int  distance;
    int  rc;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to CH101 */
    handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed: %d\n", handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Starting distance measurements (Ctrl-C to stop)...\n");

    while (g_running) {
        if (read_distance(handle, &distance) == 0) {
            get_timestamp(ts, sizeof(ts));
            fprintf(log_fp, "%s, %d\n", ts, distance);
            fflush(log_fp);
            printf("%s, Distance: %d mm\n", ts, distance);
        } else {
            fprintf(stderr, "Warning: distance read failed, skipping sample\n");
        }

        gpioDelay(SAMPLE_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (log_fp)  fclose(log_fp);
    if (handle >= 0) i2cClose(handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

