        fprintf(stderr, "Error setting LED GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        float distance;
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Sensor read failed, retrying...\n");
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    gpioWrite(LED_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

