#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define ALS_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadWordData(handle, reg);
        if (result >= 0) {
            *value = (uint16_t)result;
            return 0;
        }
        fprintf(stderr, "I2C read attempt %d failed for register 0x%02X: %d\n", attempt + 1, reg, result);
        gpioDelay(10000);
    }
    return -1;
}

static int log_data(FILE *fp, uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Starting Si1182-GMR sensor logging. Press Ctrl+C to stop.\n");

    while (program_running) {
        uint16_t proximity = 0;
        uint16_t ambient_light = 0;
        int prox_ok = read_register16(i2c_handle, PROXIMITY_REG, &proximity);
        int als_ok = read_register16(i2c_handle, ALS_REG, &ambient_light);

        if (prox_ok == 0 && als_ok == 0) {
            if (log_data(log_file, proximity, ambient_light) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data (proximity=%d, ambient=%d)\n", prox_ok, als_ok);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

