#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x50
#define LOG_FILE "intrusion_log.txt"
#define THRESHOLD_MM 1000
#define SAMPLES_PER_CYCLE 10
#define SAMPLE_DELAY_MS 100
#define MEAS_DELAY_MS 10
#define I2C_RETRY_COUNT 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void msleep(unsigned int ms) {
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_frame(uint8_t *data, size_t len) {
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        ssize_t ret = write(i2c_fd, data, len);
        if (ret == (ssize_t)len) return 0;
        if (ret < 0) {
            fprintf(stderr, "I2C write attempt %d failed: %s\n", attempt + 1, strerror(errno));
        } else {
            fprintf(stderr, "I2C write attempt %d short write: %zd/%zu bytes\n", attempt + 1, ret, len);
        }
        msleep(10);
    }
    return -1;
}

static int i2c_read_frame(uint8_t *data, size_t len) {
    for (int attempt = 0; attempt < I2C_RETRY_COUNT; attempt++) {
        ssize_t ret = read(i2c_fd, data, len);
        if (ret == (ssize_t)len) return 0;
        if (ret < 0) {
            fprintf(stderr, "I2C read attempt %d failed: %s\n", attempt + 1, strerror(errno));
        } else {
            fprintf(stderr, "I2C read attempt %d short read: %zd/%zu bytes\n", attempt + 1, ret, len);
        }
        msleep(10);
    }
    return -1;
}

static int read_distance(uint16_t *distance_mm) {
    uint8_t cmd[4] = {0x50, 0x0A, 0x00, 0x01};
    uint8_t resp[15];

    if (i2c_write_frame(cmd, sizeof(cmd)) != 0) {
        fprintf(stderr, "Failed to send measurement command to sensor.\n");
        return -1;
    }

    msleep(MEAS_DELAY_MS);

    if (i2c_read_frame(resp, sizeof(resp)) != 0) {
        fprintf(stderr, "Failed to read response from sensor.\n");
        return -1;
    }

    if (resp[0] != 0x50) {
        fprintf(stderr, "Invalid response header: 0x%02X (expected 0x50)\n", resp[0]);
        return -1;
    }

    *distance_mm = ((uint16_t)resp[11] << 8) | resp[12];
    return 0;
}

static void log_intrusion(uint16_t distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fp != NULL) {
        fprintf(log_fp, "%s, Distance: %u mm\n", timestamp, distance_mm);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus " I2C_BUS);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to acquire I2C bus access / talk to sensor at 0x50");
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t total_distance = 0;
        int valid_samples = 0;

        for (int i = 0; i < SAMPLES_PER_CYCLE; i++) {
            uint16_t distance;
            if (read_distance(&distance) == 0) {
                total_distance += distance;
                valid_samples++;
            } else {
                fprintf(stderr, "Error reading distance from sensor.\n");
            }
            if (i < SAMPLES_PER_CYCLE - 1) msleep(SAMPLE_DELAY_MS);
        }

        if (valid_samples > 0) {
            uint16_t avg_distance = (uint16_t)(total_distance / valid_samples);
            printf("Average distance: %u mm\n", avg_distance);

            if (avg_distance < THRESHOLD_MM) {
                printf("Intrusion detected! Logging event...\n");
                log_intrusion(avg_distance);
            }
        } else {
            fprintf(stderr, "No valid samples in this cycle.\n");
        }

        msleep(SAMPLE_DELAY_MS);
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    return 0;
}

