#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L0X_ADDR             0x29
#define VL53L0X_REG_SYSRANGE_START  0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x0B
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0xC0
#define VL53L0X_MODEL_ID          0xEE

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_byte(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int handle, uint8_t reg, uint16_t *val) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read word error (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)rc;
    return 0;
}

static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_byte(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        return -1;
    }
    if (model_id != VL53L0X_MODEL_ID) {
        fprintf(stderr, "VL53L0X model ID mismatch: got 0x%02X, expected 0x%02X\n",
                model_id, VL53L0X_MODEL_ID);
        return -1;
    }
    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm) {
    if (i2c_write_byte(handle, VL53L0X_REG_SYSRANGE_START, 0x01) != 0) {
        return -1;
    }

    for (int i = 0; i < 100; i++) {
        uint8_t status = 0;
        if (i2c_read_byte(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
        if (i == 99) {
            fprintf(stderr, "VL53L0X measurement timeout\n");
            return -1;
        }
    }

    uint16_t raw = 0;
    if (i2c_read_word(handle, VL53L0X_REG_RESULT_RANGE_STATUS, &raw) != 0) {
        return -1;
    }

    if (i2c_write_byte(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        return -1;
    }

    *distance_mm = raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l0x_init(handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(handle, &distance) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];
            localtime_r(&now, &tm_info);
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
            printf("%s Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

