#define SI1182_ADDR        0x39
#define SI1182_REG_CONFIG  0x18
#define SI1182_REG_IRQ     0x25
#define SI1182_REG_PROX_L  0x2A
#define SI1182_REG_PROX_H  0x2B

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int si1182_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int si1182_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int si1182_read_prox(int handle, uint16_t *prox)
{
    int lsb = si1182_read_reg(handle, SI1182_REG_PROX_L);
    if (lsb < 0) return -1;
    int msb = si1182_read_reg(handle, SI1182_REG_PROX_H);
    if (msb < 0) return -1;
    *prox = (uint16_t)((msb << 8) | lsb);
    return 0;
}

static int si1182_wait_data_ready(int handle, uint32_t timeout_ms)
{
    uint32_t elapsed = 0;
    const uint32_t step = 10;
    while (elapsed < timeout_ms) {
        int irq = si1182_read_reg(handle, SI1182_REG_IRQ);
        if (irq < 0) return -1;
        if (irq & 0x01) return 0;
        gpioDelay(step * 1000);
        elapsed += step;
    }
    fprintf(stderr, "Timeout waiting for data-ready\n");
    return -1;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(1, SI1182_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at addr 0x%02X: %d\n", SI1182_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe: try a read of the CONFIG register to confirm the sensor is present. */
    int cfg = si1182_read_reg(handle, SI1182_REG_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "Si1182 not responding at 0x%02X (sensor absent or bus error)\n", SI1182_ADDR);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable proximity mode by writing 0x01 to CONFIG. */
    if (si1182_write_reg(handle, SI1182_REG_CONFIG, 0x01) < 0) {
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si1182 initialised (CONFIG=0x%02X). Reading proximity every 500 ms...\n", cfg);

    while (g_running) {
        if (si1182_wait_data_ready(handle, 2000) < 0) {
            /* Sensor absent or bus error: exit cleanly. */
            break;
        }

        uint16_t prox;
        if (si1182_read_prox(handle, &prox) < 0) {
            fprintf(stderr, "Proximity read failed; continuing.\n");
        } else {
            printf("Proximity: %u\n", prox);
        }

        gpioDelay(500000); /* 500 ms */
    }

    i2cClose(handle);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

