#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_ADDR 0x44
#define I2C_BUS 1

#define REG_SYSTEM_CONFIG 0x00
#define REG_CHANNEL_CONFIG 0x01
#define REG_DISTANCE 0x02
#define REG_AMBIENT 0x03
#define REG_ERROR_FLAGS 0x04

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_register(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

int write_register(int handle, uint8_t reg, uint16_t value) {
    char buf[2];
    buf[0] = (value >> 8) & 0xFF;
    buf[1] = value & 0xFF;
    int result = i2cWriteI2CBlockData(handle, reg, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int init_opt3101(int handle) {
    if (write_register(handle, REG_SYSTEM_CONFIG, 0x0001) != 0) return -1;
    if (write_register(handle, REG_CHANNEL_CONFIG, 0x0000) != 0) return -1;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_opt3101(i2c_handle) != 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        uint16_t distance, ambient, error_flags;

        if (read_register(i2c_handle, REG_DISTANCE, &distance) != 0) {
            fprintf(stderr, "Failed to read distance\n");
        } else if (read_register(i2c_handle, REG_AMBIENT, &ambient) != 0) {
            fprintf(stderr, "Failed to read ambient light\n");
        } else if (read_register(i2c_handle, REG_ERROR_FLAGS, &error_flags) != 0) {
            fprintf(stderr, "Failed to read error flags\n");
        } else {
            printf("Distance: %u mm, Ambient: %u, Error Flags: 0x%04X\n", distance, ambient, error_flags);
        }

        gpioDelay(500000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

