/*
 * HC-SR04 Ultrasonic Distance Sensor - Raspberry Pi 3 Model B+
 * Library: pigpio (modern, actively maintained)
 *
 * Wiring:
 *   VCC  -> 5V  (Pin 2 or 4)
 *   GND  -> GND (Pin 6)
 *   TRIG -> GPIO 17 (BCM, Pin 11)
 *   ECHO -> GPIO 18 (BCM, Pin 12) via 1 kOhm resistor for 5V->3.3V protection
 *
 * NOTE: The HC-SR04 operates at 5V logic levels. The Raspberry Pi GPIO
 *       pins are 3.3V tolerant only. A series 1 kOhm resistor on the
 *       echo line clamps the 5V signal to ~3.3V, preventing damage to
 *       the Pi's GPIO inputs.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse width            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait                 */
#define MAX_PULSE_US     38000       /* 38 ms max valid pulse (5 m round trip) */
#define SAMPLE_PERIOD_S  1           /* 1 second between readings            */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (SIGINT / SIGTERM)            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
