#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0f
#define RANGE_BINS 64
#define RANGE_RES_M 0.0486f
#define LOG_FILE "intrusion_log.csv"
#define MAGIC_WORD_SIZE 8
#define RANGE_DATA_SIZE (RANGE_BINS * 2)
#define FRAME_SIZE (MAGIC_WORD_SIZE + RANGE_DATA_SIZE)

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(const char *device, speed_t baud) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 1;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_exact(int fd, uint8_t *buf, size_t len) {
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            return -1;
        }
        if (n == 0) return 0;
        total += (size_t)n;
    }
    return 1;
}

static int find_magic_word(int fd, uint8_t *buf, size_t len) {
    size_t match = 0;
    while (running) {
        uint8_t byte;
        ssize_t n = read(fd, &byte, 1);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read magic");
            return -1;
        }
        if (n == 0) return 0;
        if (byte == MAGIC_WORD[match]) {
            match++;
            if (match == len) return 1;
        } else {
            match = 0;
        }
    }
    return 0;
}

static int process_range_profile(const uint8_t *data) {
    int16_t range_profile[RANGE_BINS];
    for (int i = 0; i < RANGE_BINS; i++) {
        range_profile[i] = (int16_t)((uint16_t)data[i * 2] | ((uint16_t)data[i * 2 + 1] << 8));
    }

    float min_distance = 9999.0f;
    for (int i = 0; i < RANGE_BINS; i++) {
        float dist = (float)i * RANGE_RES_M;
        if (range_profile[i] > 0 && dist < min_distance) {
            min_distance = dist;
        }
    }

    if (min_distance < DISTANCE_THRESHOLD) {
        printf("Intrusion detected! Distance: %.2f meters\n", min_distance);
        if (gpioWrite(GPIO_LED, 1) < 0) {
            fprintf(stderr, "Failed to turn on LED\n");
        }
        gpioDelay(2000000);
        if (gpioWrite(GPIO_LED, 0) < 0) {
            fprintf(stderr, "Failed to turn off LED\n");
        }
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info);
        if (log_file) {
            fprintf(log_file, "%s,%.2f\n", ts, min_distance);
            fflush(log_file);
        }
        return 1;
    }
    return 0;
}

static void cleanup(void) {
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    printf("Radar intrusion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (find_magic_word(uart_fd, (uint8_t *)MAGIC_WORD, MAGIC_WORD_SIZE) <= 0) {
            if (!running) break;
            continue;
        }

        uint8_t frame[FRAME_SIZE];
        if (read_exact(uart_fd, frame, FRAME_SIZE) <= 0) {
            if (!running) break;
            fprintf(stderr, "Incomplete frame read\n");
            continue;
        }

        if (memcmp(frame, MAGIC_WORD, MAGIC_WORD_SIZE) != 0) {
            fprintf(stderr, "Magic word mismatch\n");
            continue;
        }

        process_range_profile(frame + MAGIC_WORD_SIZE);
    }

    cleanup();
    return 0;
}

