        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_LED, 0);

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    printf("Radar intrusion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        if (find_magic_word(uart_fd, (uint8_t *)MAGIC_WORD, MAGIC_WORD_SIZE) <= 0) {
            if (!running) break;
            continue;
        }

        uint8_t frame[FRAME_SIZE];
        if (read_exact(uart_fd, frame, FRAME_SIZE) <= 0) {
            if (!running) break;
            fprintf(stderr, "Incomplete frame read\n");
            continue;
        }

        if (memcmp(frame, MAGIC_WORD, MAGIC_WORD_SIZE) != 0) {
            fprintf(stderr, "Magic word mismatch\n");
            continue;
        }

        process_range_profile(frame + MAGIC_WORD_SIZE);
    }

    cleanup();
    return 0;
}

