    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("gpiod_chip_get_line(sensor)");
        goto cleanup;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("gpiod_chip_get_line(buzzer)");
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        perror("gpiod_line_request_input(sensor)");
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        perror("gpiod_line_request_output(buzzer)");
        goto cleanup;
    }

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    int last_sensor_value = -1;
    int last_buzzer_state = -1;

    while (program_running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
