        if (gpiod_line_set_value(buzzer_line, buzzer_state) < 0) {
            perror("gpiod_line_set_value(buzzer)");
            break;
        }

        if (sensor_value != last_sensor_value || buzzer_state != last_buzzer_state) {
            log_event(log_file, sensor_value, buzzer_state);
            last_sensor_value = sensor_value;
            last_buzzer_state = buzzer_state;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    printf("Obstacle detection stopped.\n");
    return ret;
}

