#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x69
#define GPIO_ALERT      17
#define DIST_THRESHOLD  10.0f
#define LOG_FILE        "distance_log.txt"
#define SAMPLE_US       100000  /* 100 ms */
#define POLL_US         10000   /* 10 ms  */

/* ICU-20201 register addresses */
#define REG_DIST_HIGH   0x31
#define REG_DIST_LOW    0x32

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int read_distance(int handle, float *distance_out)
{
    int high, low;

    high = i2cReadByteData(handle, REG_DIST_HIGH);
    if (high < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", REG_DIST_HIGH, high);
        return -1;
    }

    low = i2cReadByteData(handle, REG_DIST_LOW);
    if (low < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", REG_DIST_LOW, low);
        return -1;
    }

    /* 16-bit big-endian distance value (cm) */
    int distance_raw = (high << 8) | low;

    /* Sanity range check: 0 cm to 400 cm (typical ICU-20201 range) */
    if (distance_raw < 0 || distance_raw > 400) {
        fprintf(stderr, "Distance out of range: %d\n", distance_raw);
        return -1;
    }

    *distance_out = (float)distance_raw;
    return 0;
}

static int log_distance(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", ts, distance);
    fclose(fp);
    return 0;
}

static void trigger_alert(float distance)
{
    if (distance < DIST_THRESHOLD) {
        gpioWrite(GPIO_ALERT, 1);
        gpioDelay(500000); /* 500 ms pulse */
        gpioWrite(GPIO_ALERT, 0);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", GPIO_ALERT);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_ALERT, 0);

    printf("ICU-20201 distance monitor started. Logging to %s\n", LOG_FILE);
    printf("Alert on GPIO%d when distance < %.1f cm. Press Ctrl+C to exit.\n",
           GPIO_ALERT, DIST_THRESHOLD);

    while (g_running) {
        float distance;

        if (read_distance(g_i2c_handle, &distance) == 0) {
            if (log_distance(distance) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
            trigger_alert(distance);
        } else {
            fprintf(stderr, "Sensor read failed; retrying next cycle\n");
        }

        /* Sleep 100 ms in 10 ms slices so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(POLL_US);
        }
    }

    /* Cleanup */
    gpioWrite(GPIO_ALERT, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

