#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_ADDR             0x29
#define I2C_BUS                  1
#define LOG_FILE                 "distance_log.csv"
#define POLL_TIMEOUT_MS          100
#define LOOP_DELAY_MS            100
#define STOP_THRESHOLD_MM        300
#define APPROACH_THRESHOLD_MM    600
#define SLOW_THRESHOLD_MM        1200

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define REG_SOFT_RESET              0x0000
#define REG_SYSTEM_MODE_START       0x0007
#define REG_SYSRANGE_START          0x0000
#define REG_RESULT_INT_STATUS       0x013
#define REG_RESULT_RANGE_STATUS     0x0078
#define REG_SYSTEM_INTERRUPT_CLEAR  0x0014
#define REG_MODEL_ID                0x010F

#define EXPECTED_MODEL_ID          0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then a single byte value. */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/* Write a 16-bit register address, then read n bytes. */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *buf, int n)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) failed at reg 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, n) != n) {
        fprintf(stderr, "I2C read failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;
    if (vl53l1x_read_reg(handle, REG_MODEL_ID, &model_id, 1) != 0)
        return -1;
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /* Software reset */
    if (vl53l1x_write_reg8(handle, REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms */

    /* Start continuous back-to-back ranging */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_MODE_START, 0x01) != 0)
        return -1;

    return 0;
}

static int vl53l1x_wait_data_ready(int handle, int timeout_ms)
{
    uint8_t status = 0;
    int elapsed = 0;
    const int step = 5;

    while (elapsed < timeout_ms) {
        if (vl53l1x_read_reg(handle, REG_RESULT_INT_STATUS, &status, 1) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        gpioDelay(step * 1000); /* microseconds */
        elapsed += step;
    }
    return -1; /* timeout */
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t buf[2];
    if (vl53l1x_wait_data_ready(handle, POLL_TIMEOUT_MS) != 0)
        return -1;

    if (vl53l1x_read_reg(handle, REG_RESULT_RANGE_STATUS, buf, 2) != 0)
        return -1;

    *distance_mm = ((uint16_t)buf[0] << 8) | buf[1];

    /* Clear interrupt so next measurement can signal */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return 0;
}

static void log_distance(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL)
        return;
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0)
        return;

    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

static void parking_assistance(uint16_t distance_mm)
{
    if (distance_mm < STOP_THRESHOLD_MM)
        printf("STOP\n");
    else if (distance_mm < APPROACH_THRESHOLD_MM)
        printf("APPROACH\n");
    else if (distance_mm < SLOW_THRESHOLD_MM)
        printf("SLOW\n");
    else
        printf("CLEAR\n");
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,distance_mm\n");
        fflush(g_log_file);
    }

    printf("Parking assistance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
            log_distance(g_log_file, distance);
            parking_assistance(distance);
        } else {
