#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS        1
#define I2C_ADDR       0x45
#define LED_GPIO       18
#define SAMPLE_US      100000   /* 100 ms */
#define RETRY_COUNT    3
#define RETRY_DELAY_US 10000    /* 10 ms */
#define MIN_DISTANCE   50.0f
#define MAX_DISTANCE   500.0f
#define MIN_FREQ_HZ    10.0f
#define MAX_FREQ_HZ    1.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_with_retry(int handle, uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "I2C read attempt %d/%d failed (rc=%d): %s\n",
                attempt + 1, RETRY_COUNT, rc, strerror(errno));
        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_write_with_retry(int handle, const uint8_t *buf, uint32_t len)
{
    for (int attempt = 0; attempt < RETRY_COUNT; attempt++) {
        int rc = i2cWriteDevice(handle, (char *)buf, len);
        if (rc == (int)len)
            return 0;
        fprintf(stderr, "I2C write attempt %d/%d failed (rc=%d): %s\n",
                attempt + 1, RETRY_COUNT, rc, strerror(errno));
        if (attempt < RETRY_COUNT - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read distance from CH201.
 * Returns 0 on success (distance stored in *out_mm), -1 on failure.
 */
static int read_distance(int handle, float *out_mm)
{
    uint8_t cmd = 0x01;          /* dummy command to trigger measurement */
    uint8_t data[2];

    if (i2c_write_with_retry(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Failed to send measurement command\n");
        return -1;
    }

    gpioDelay(5000);            /* 5 ms measurement settle */

    if (i2c_read_with_retry(handle, data, 2) != 0) {
        fprintf(stderr, "Failed to read distance data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *out_mm = (float)raw;
    return 0;
}

static float map_distance_to_frequency(float distance_mm)
{
    if (distance_mm <= MIN_DISTANCE)
        return MAX_FREQ_HZ;
    if (distance_mm >= MAX_DISTANCE)
        return MIN_FREQ_HZ;
    return MAX_FREQ_HZ -
           ((distance_mm - MIN_DISTANCE) /
            (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_FREQ_HZ - MIN_FREQ_HZ);
}

static void log_data(float distance_mm, float frequency_hz)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Distance: %.2f mm, Blink Frequency: %.2f Hz\n",
           ts, distance_mm, frequency_hz);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    int led_state = 0;
    int half_cycles = 0;

    while (g_running) {
        float distance_mm = 0.0f;
        if (read_distance(g_i2c_handle, &distance_mm) != 0) {
            fprintf(stderr, "Read failed; continuing\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float freq = map_distance_to_frequency(distance_mm);
        log_data(distance_mm, freq);

        /* Half-cycle blink: one on/off cycle per sample period */
        led_state = !led_state;
        gpioWrite(LED_GPIO, led_state);
        half_cycles++;

        /* If frequency is 0 Hz (too close), skip the second half-cycle */
        if (freq > 0.0f) {
            int half_period_us = (int)(500000.0f / freq);
            if (half_period_us > 0) {
                gpioDelay(half_period_us);
                led_state = !led_state;
                gpioWrite(LED_GPIO, led_state);
                half_cycles++;
            }
        }

        /* If we did two half-cycles, the full period is elapsed; reset */
        if (half_cycles >= 2)
            half_cycles = 0;
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

