#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x49
#define REG_MEAS_TRIGGER  0x04
#define REG_MEAS_STATUS   0x06
#define REG_DIST_HIGH     0x08
#define REG_DIST_LOW      0x09
#define MEAS_TRIGGER_VAL  0x01
#define DATA_READY_BIT    0x01
#define POLL_TIMEOUT_MS   50
#define SAMPLE_PERIOD_MS  500
#define LOG_FILE          "distance_log.csv"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ch101_trigger_and_read(int fd, uint16_t *distance_mm) {
    if (i2c_write_reg8(fd, REG_MEAS_TRIGGER, MEAS_TRIGGER_VAL) < 0)
        return -1;

    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += 5) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if (status & DATA_READY_BIT) {
            uint16_t dist;
            if (i2c_read_reg16(fd, REG_DIST_HIGH, &dist) < 0)
                return -1;
            *distance_mm = dist;
            return 0;
        }
        usleep(5000);
    }

    fprintf(stderr, "CH-101 measurement timeout\n");
    return -1;
}

static void log_data(FILE *fp, uint16_t distance_mm) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%u\n", ts, distance_mm);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# CH-101 distance log started\n");
    fflush(g_log_fp);

    while (g_running) {
        uint16_t dist;
        if (ch101_trigger_and_read(g_i2c_fd, &dist) == 0) {
            log_data(g_log_fp, dist);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error\n");
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

