    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# CH-101 distance log started\n");
    fflush(g_log_fp);

    while (g_running) {
        uint16_t dist;
        if (ch101_trigger_and_read(g_i2c_fd, &dist) == 0) {
            log_data(g_log_fp, dist);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error\n");
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
    }
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

