#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define VL53L5CX_ADDR  0x29

#define NUM_ZONES      64
#define POLL_MS        500

/* VL53L5CX register addresses (16-bit, big-endian on the bus) */
#define REG_SYSTEM_START  0x0000
#define REG_SYSTEM_MODE   0x0001
#define REG_ZONE_CONFIG   0x0002
#define REG_ZONE_DATA     0x0010

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address + 1 data byte via i2c-dev */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value) {
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Write a 16-bit register address + 2 data bytes (big-endian) via i2c-dev */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value) {
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address + 1 data byte via i2c-dev */
static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *out) {
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read_reg8 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

/* Read a 16-bit register address + 2 data bytes (big-endian) via i2c-dev */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out) {
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "i2c_read_reg16 write(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16 read(0x%04X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int vl53l5cx_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, REG_SYSTEM_START, &id) != 0) {
        fprintf(stderr, "Failed to read system ID\n");
        return -1;
    }
    printf("VL53L5CX detected (system ID: 0x%02X)\n", id);

    /* Configure 8x8 zone grid (64 zones) */
    if (i2c_write_reg16(fd, REG_ZONE_CONFIG, 0x0008) != 0) {
        fprintf(stderr, "Failed to set zone config\n");
        return -1;
    }

    /* Start continuous ranging */
    if (i2c_write_reg8(fd, REG_SYSTEM_MODE, 0x01) != 0) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
    }

    return 0;
}

static int read_zone_data(int fd, uint16_t *distances) {
    for (int i = 0; i < NUM_ZONES; i++) {
        uint16_t reg = REG_ZONE_DATA + (uint16_t)(i * 2);
        if (i2c_read_reg16(fd, reg, &distances[i]) != 0) {
            fprintf(stderr, "Failed to read zone %d\n", i);
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", VL53L5CX_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (vl53l5cx_init(fd) != 0) {
        fprintf(stderr, "VL53L5CX initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("VL53L5CX initialized. Reading 64-zone data every %d ms. Press Ctrl+C to exit.\n", POLL_MS);

    while (g_running) {
        uint16_t distances[NUM_ZONES];
        if (read_zone_data(fd, distances) != 0) {
            fprintf(stderr, "Read error, continuing...\n");
        } else {
            printf("--- 64-Zone Distance Data ---\n");
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("Zone %2d: %5u mm\n", i, distances[i]);
            }
            printf("-----------------------------\n");
        }
        usleep(POLL_MS * 1000);
    }

    printf("\nExiting...\n");
    /* Stop ranging */
    i2c_write_reg8(fd, REG_SYSTEM_MODE, 0x00);
    close(fd);
    return EXIT_SUCCESS;
}

