/* VL53L4CX register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET       0x7FFF
#define REG_SYSTEM_START     0x0009
#define REG_INT_STATUS       0x0046
#define REG_DISTANCE_H       0x0096
#define REG_DISTANCE_L       0x0097

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address followed by a single data byte. */
static int vl53l4cx_write_reg(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address followed by a single data byte. */
static int vl53l4cx_read_reg(int handle, uint16_t reg, uint8_t *value) {
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

