#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD_MM 100
#define POLL_DELAY_US 500000

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define REG_SOFT_RESET 0x0001
#define REG_I2C_SLAVE_DEVICE_ADDRESS 0x0001
#define REG_SYSTEM_MODE_START 0x0007
#define REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a 16-bit register address followed by a 1-byte value */
static int vl53l1x_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Write a 16-bit register address followed by a 2-byte value (big-endian) */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value) {
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

/* Read a 16-bit register address followed by reading `len` bytes */
static int vl53l1x_read_reg(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char addr_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) != 0) {
        return -1;
    }
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    /* Soft reset */
    if (vl53l1x_write_reg8(handle, REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to write SOFT_RESET (sensor may be absent)\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle */

    /* Set I2C slave address (default is 0x29; keep it) */
    if (vl53l1x_write_reg8(handle, REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR) != 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address\n");
        return -1;
    }

    /* Start continuous ranging mode */
    if (vl53l1x_write_reg8(handle, REG_SYSTEM_MODE_START, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging\n");
        return -1;
    }

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

static int read_distance_mm(int handle) {
    uint8_t buf[2];
    if (vl53l1x_read_reg(handle, REG_RESULT_FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to read distance register\n");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

static void control_buzzer(int state) {
    gpioWrite(BUZZER_GPIO, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    control_buzzer(0);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int buzzer_active = 0;

    while (running) {
        int distance = read_distance_mm(i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Warning: I2C read error, re-initializing sensor...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); /* 100 ms backoff */
            i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Failed to re-open I2C bus\n");
                break;
            }
            if (init_vl53l1x(i2c_handle) != 0) {
                fprintf(stderr, "Error: Re-initialization failed\n");
                break;
            }
            buzzer_active = 0;
            control_buzzer(0);
            continue;
        }

        printf("Distance: %d mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_MM) {
            if (!buzzer_active) {
                control_buzzer(1);
                buzzer_active = 1;
            }
        } else {
            if (buzzer_active) {
                control_buzzer(0);
                buzzer_active = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    control_buzzer(0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

