#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   17

#define SPEED_OF_SOUND 343.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      -90
#define MAX_ANGLE      90
#define SERVO_MIN_PULSE 1000
#define SERVO_MAX_PULSE 2000
#define TIMEOUT_US     50000
#define LOOP_DELAY_US  200000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t timeout_start = gpioTick();

    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_start) > TIMEOUT_US) return -1.0;
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_start) > TIMEOUT_US) return -1.0;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    return (double)diff / 1000000.0 * SPEED_OF_SOUND / 2.0;
}

static int distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) distance = MIN_DISTANCE;
    if (distance > MAX_DISTANCE) distance = MAX_DISTANCE;
    return (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
}

static int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    int pulse = SERVO_MIN_PULSE + (int)((angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE));
    return gpioServo(SERVO_PIN, pulse);
}

static void log_data(double distance, int angle) {
    FILE *fp = fopen("sensor_data.log", "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %.2f cm, Angle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
