#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <mqueue.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_US 50000
#define MQ_NAME "/distance_queue"
#define MQ_MAX_MSGS 10
#define MQ_MSG_SIZE 32

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE_START 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static mqd_t mq = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write error at reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write error setting reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != len) {
        fprintf(stderr, "I2C read error from reg 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Failed to read model ID\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0xEA)\n", model_id);
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance) {
    uint8_t status = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 0) return -1;

    if (!(status & 0x01)) {
        return 1;
    }

    uint8_t buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, buf, 2) != 0) return -1;

    *distance = (buf[0] << 8) | buf[1];
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (mq != (mqd_t)-1) {
        mq_close(mq);
        mq = (mqd_t)-1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = MQ_MAX_MSGS;
    attr.mq_msgsize = MQ_MSG_SIZE;
    attr.mq_curmsgs = 0;

    mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        cleanup();
        return 1;
    }

    printf("VL53L1X ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        int distance = 0;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);

        if (ret == 0) {
            char msg[MQ_MSG_SIZE];
            snprintf(msg, sizeof(msg), "Distance: %d mm", distance);
            if (mq_send(mq, msg, strlen(msg), 0) == -1) {
                perror("mq_send");
            }

            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else if (ret < 0) {
            fprintf(stderr, "I2C communication error\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

