#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define BUZZER_PIN  22

#define SPEED_OF_SOUND 34300.0f   /* cm/s */
#define MIN_DISTANCE   2.0f       /* cm */
#define MAX_DISTANCE   400.0f     /* cm */
#define BUZZER_THRESHOLD 30.0f    /* cm */
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000     /* 30 ms */
#define LOOP_DELAY_US    100000    /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_seen  = 0;
static volatile int      g_reading_ok = 0;
static volatile float    g_distance   = 0.0f;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)userdata;
    if (gpio != ECHO_PIN)
        return;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0) {
        if (g_start_tick != 0) {
            g_end_tick   = tick;
            g_echo_seen  = 1;
            g_reading_ok = 1;
        }
    }
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input.\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output.\n", BUZZER_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on echo pin %d.\n", ECHO_PIN);
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize trigger pin low.\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize buzzer pin low.\n");
        return -1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert function on echo pin %d.\n", ECHO_PIN);
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    g_start_tick = 0;
    g_end_tick   = 0;
    g_echo_seen  = 0;
    g_reading_ok = 0;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set trigger HIGH.\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set trigger LOW.\n");
    }
}

static float calculate_distance(uint32_t start, uint32_t end)
{
    uint32_t diff = end - start;  /* handles 32-bit tick wraparound */
    float time_s = (float)diff / 1000000.0f;
    return (time_s * SPEED_OF_SOUND) / 2.0f;
}

static void control_buzzer(float distance)
{
    if (distance < BUZZER_THRESHOLD) {
        if (gpioWrite(BUZZER_PIN, 1) < 0) {
            fprintf(stderr, "Warning: failed to turn buzzer ON.\n");
        }
    } else {
        if (gpioWrite(BUZZER_PIN, 0) < 0) {
            fprintf(stderr, "Warning: failed to turn buzzer OFF.\n");
        }
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        trigger_sensor();

        uint32_t wait_start = gpioTick();
        while (!g_reading_ok && g_running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Error: echo timeout - sensor absent or no object detected.\n");
                g_reading_ok = 0;
                break;
            }
            gpioDelay(100);
        }

        if (g_reading_ok && g_echo_seen) {
            float dist = calculate_distance(g_start_tick, g_end_tick);
            if (dist >= MIN_DISTANCE && dist <= MAX_DISTANCE) {
                g_distance = dist;
                printf("Distance: %.2f cm\n", g_distance);
            } else {
                fprintf(stderr, "Error: distance out of range: %.2f cm\n", dist);
                g_reading_ok = 0;
            }
        } else if (g_reading_ok) {
            fprintf(stderr, "Error: echo pulse not captured.\n");
        }

        control_buzzer(g_distance);
        gpioDelay(LOOP_DELAY_US);
    }

    gpioWrite(BUZZER_PIN, 0);
