#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define VL53L1X_ADDR 0x29
#define I2C_BUS 1
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"
#define MQTT_BROKER "tcp://localhost:1883"
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_TOPIC "gate_control"
#define MQTT_QOS 1
#define MAX_RETRIES 3

#define VL53L1X_REG_SOFT_RESET 0x0003
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static MQTTClient mqtt_client;
static volatile sig_atomic_t running = 1;

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file);
    }
    printf("%s: %s\n", timestamp, event);
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = {(reg >> 8) & 0xFF, reg & 0xFF, value};
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, int len) {
    char reg_buf[2] = {(reg >> 8) & 0xFF, reg & 0xFF};
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(10000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int read_distance(int handle) {
    uint8_t status_buf[1];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, status_buf, 1) != 1) return -1;
    if ((status_buf[0] & 0x01) == 0) return -1;
    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 2) return -1;
    return (dist_buf[0] << 8) | dist_buf[1];
}

static void control_servo(int angle) {
    int pulse_width = 500 + (angle * 2000 / 180);
    gpioServo(SERVO_PIN, pulse_width);
}

static void open_gate(void) {
    control_servo(90);
    log_event("Gate opened");
}

static void close_gate(void) {
    control_servo(0);
    log_event("Gate closed");
}

static void mqtt_message_arrived(void *context, char *topicName, int topicLen, MQTTClient_message *message) {
    (void)context; (void)topicLen;
    char payload[256];
    strncpy(payload, (char *)message->payload, message->payloadlen);
    payload[message->payloadlen] = '\0';
    printf("Received message: %s\n", payload);
    if (strcmp(payload, "force_open") == 0) {
        open_gate();
    } else if (strcmp(payload, "force_close") == 0) {
        close_gate();
    } else if (strcmp(payload, "status_request") == 0) {
        int dist = read_distance(i2c_handle);
        if (dist < 0) {
            log_event("Sensor read error");
        } else {
            char log_msg[128];
            snprintf(log_msg, sizeof(log_msg), "Distance: %d cm", dist);
            log_event(log_msg);
        }
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L1X init failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_event("Program started");
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    MQTTClient_create(&mqtt_client, MQTT_BROKER, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    if (MQTTClient_connect(mqtt_client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "MQTT connect failed\n");
        cleanup();
        return 1;
    }
    MQTTClient_subscribe(mqtt_client, MQTT_TOPIC, MQTT_QOS);
    MQTTClient_setCallbacks(mqtt_client, NULL, NULL, mqtt_message_arrived, NULL);
    while (running) {
        int dist = read_distance(i2c_handle);
        if (dist < 0) {
            log_event("Sensor read error");
            gpioDelay(1000000);
            continue;
        }
        if (dist < DISTANCE_THRESHOLD) {
            open_gate();
        } else {
            close_gate();
        }
        gpioDelay(1000000);
    }
    cleanup();
    return 0;
}

