/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 * Library: pigpio (C API)
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16)
 *   ECHO -> GPIO 24 (physical pin 18) via voltage divider (5V -> 3.3V)
 *
 * NOTE: The HC-SR04 ECHO pin outputs 5V logic. The Raspberry Pi GPIO
 * inputs are 3.3V tolerant only. A voltage divider (e.g., 1k/2k) or
 * logic-level converter (e.g., 74HC125) must be used to drop the ECHO
 * signal to 3.3V before connecting it to the Pi.
 *
 * Build: gcc -Wall -Wextra -O2 -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* 10 us trigger pulse            */
#define MEASURE_PERIOD_US 200000     /* 200 ms between measurements    */
#define ECHO_TIMEOUT_US   60000       /* 60 ms max echo wait            */
#define MIN_PULSE_US      100         /* reject noise below this        */
#define MAX_PULSE_US      30000       /* reject timeout / no-object > 30 cm */
#define SPEED_OF_SOUND_CM_PER_US 0.0343  /* 343 m/s in cm/us */

#define LOG_FILE_NAME "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Echo alert callback (rising and falling edges)                      */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile int      g_echo_seen    = 0;

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_rising_tick  = tick;
        g_echo_seen    = 1;
    } else if (level == 0) {
        /* Falling edge: end of echo pulse */
        g_falling_tick = tick;
    }
    /* level == 2 indicates a watchdog timeout; ignore here */
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns distance in centimetres, or -1.0 on timeout / invalid data.
 * pigpio ticks are 32-bit microseconds and wrap every ~71.6 min.
 * The subtraction (falling - rising) handles the wraparound correctly
 * when the result is interpreted as a signed 32-bit difference.
 */
static double measure_distance(void)
{
    /* Reset state */
    g_echo_seen    = 0;
    g_rising_tick  = 0;
    g_falling_tick = 0;

    /* Generate 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo with timeout */
    uint32_t start_wait = gpioTick();
    while (!g_echo_seen) {
        if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
            return -1.0;  /* timeout: no echo received */
        }
        gpioDelay(100);  /* poll every 100 us */
    }

    /* Compute pulse width with 32-bit wraparound handling */
    int32_t pulse_us = (int32_t)(g_falling_tick - g_rising_tick);

    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        return -1.0;  /* noise / out of range */
    }

    /* distance = (pulse_us * speed_of_sound) / 2 (round trip) */
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("%s Distance: %.2f cm\n", timestamp, distance);

    if (g_log_file) {
        fprintf(g_log_file, "%s Distance: %.2f cm\n", timestamp, distance);
        fflush(g_log_file);
    }
}

static void log_error(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(stderr, "%s Error: %s\n", timestamp, message);

    if (g_log_file) {
        fprintf(g_log_file, "%s Error: %s\n", timestamp, message);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
