    }

    /* Enable pull-down on echo pin to avoid floating noise */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register echo alert callback */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx(ECHO) failed\n");
