#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24

#define DISTANCE_THRESHOLD_OPEN 50
#define DISTANCE_THRESHOLD_CLOSE 60
#define SERVO_OPEN 1500
#define SERVO_CLOSED 1000
#define SERVO_NEUTRAL 1250
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_FREQ 50
#define SERVO_RANGE 20000

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x000A
#define VL53L1X_REG_GPIO_HV_MUX_CTRL 0x0030
#define VL53L1X_REG_GPIO_TIO_HV_STATUS 0x0031
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x000A
#define VL53L1X_REG_GPIO_HV_MUX_CTRL 0x0030
#define VL53L1X_REG_GPIO_TIO_HV_STATUS 0x0031

#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_ERROR -1

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int init_vl53l1x(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return VL53L1X_ERROR;
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0x%02X).\n", model_id, VL53L1X_MODEL_ID);
        return VL53L1X_ERROR;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to stop sensor.\n");
        return VL53L1X_ERROR;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to clear interrupt.\n");
        return VL53L1X_ERROR;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) != 0) {
        fprintf(stderr, "Error: Failed to configure interrupt.\n");
        return VL53L1X_ERROR;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_GPIO_HV_MUX_CTRL, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to configure GPIO.\n");
        return VL53L1X_ERROR;
    }
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to start sensor.\n");
        return VL53L1X_ERROR;
    }
    return 0;
}

static int read_distance(int handle) {
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};
    int timeout = 100;
    while (timeout-- > 0) {
        if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) return VL53L1X_ERROR;
        if (status & 0x01) break;
        gpioDelay(1000);
    }
    if (timeout <= 0) {
        fprintf(stderr, "Error: Sensor timeout.\n");
        return VL53L1X_ERROR;
    }
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 2) return VL53L1X_ERROR;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) return VL53L1X_ERROR;
    return (dist_buf[0] << 8) | dist_buf[1];
}

static void log_event(int distance, int gate_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Distance: %d cm, Gate: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, distance, gate_state ? "OPEN" : "CLOSED");
    fflush(log_file);
}

static void control_servo(int distance) {
    static int gate_state = 0;
    if (distance < DISTANCE_THRESHOLD_OPEN && !gate_state) {
        gpioServo(SERVO_PIN, SERVO_OPEN);
        gpioDelay(500000);
        gate_state = 1;
        log_event(distance, gate_state);
    } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_state) {
        gpioServo(SERVO_PIN, SERVO_CLOSED);
        gpioDelay(500000);
        gate_state = 0;
        log_event(distance, gate_state);
    }
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, SERVO_NEUTRAL);
    gpioWrite(SHUTDOWN_PIN, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    log_file = fopen("parking_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ);
    gpioSetPWMrange(SERVO_PIN, SERVO_RANGE);
    gpioServo(SERVO_PIN, SERVO_NEUTRAL);
    printf("Smart Parking Gate System Started.\n");
    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance != VL53L1X_ERROR) {
            control_servo(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }
        gpioDelay(100000);
    }
    cleanup();
    return 0;
}

