        i2c_handle = -1;
    }
    gpioServo(SERVO_PIN, SERVO_NEUTRAL);
    gpioWrite(SHUTDOWN_PIN, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    log_file = fopen("parking_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (init_vl53l1x(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return 1;
    }
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(SHUTDOWN_PIN, 1);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQ);
    gpioSetPWMrange(SERVO_PIN, SERVO_RANGE);
    gpioServo(SERVO_PIN, SERVO_NEUTRAL);
    printf("Smart Parking Gate System Started.\n");
    while (running) {
        int distance = read_distance(i2c_handle);
        if (distance != VL53L1X_ERROR) {
            control_servo(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }
        gpioDelay(100000);
    }
    cleanup();
    return 0;
}

