    char buf[3] = { (char)reg_hi, (char)reg_lo, (char)value };
    return i2cWriteI2CBlockData(i2c_handle, reg_hi, buf, 3);
}

static int i2c_read_reg16(uint8_t reg_hi, uint8_t reg_lo, uint8_t *buf, uint32_t len) {
