#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD_PIN 17
#define MOTOR_BACKWARD_PIN 18
#define TRIGGER_PIN 24
#define DISTANCE_THRESHOLD_CLOSE 100
#define DISTANCE_THRESHOLD_FAR 300
#define POLL_INTERVAL_US 10000
#define MAX_RETRIES 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    if (i2c_write_reg16(handle, 0x0000, 0x00) < 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, 0x0000, 0x01) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_read_distance(int handle) {
    uint8_t status = 0;
    int retries = 0;
    int delay_us = 1000;

    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, 0x0089, &status, 1) < 0) {
            fprintf(stderr, "I2C read error (status reg), retry %d\n", retries + 1);
            gpioDelay(delay_us);
            delay_us *= 2;
            retries++;
            continue;
        }
        if (status & 0x01) break;
        gpioDelay(delay_us);
        delay_us *= 2;
        retries++;
    }
    if (retries >= MAX_RETRIES) return -1;

    uint8_t dist_buf[2];
    retries = 0;
    delay_us = 1000;
    while (retries < MAX_RETRIES) {
        if (i2c_read_reg16(handle, 0x0096, dist_buf, 2) < 0) {
            fprintf(stderr, "I2C read error (distance reg), retry %d\n", retries + 1);
            gpioDelay(delay_us);
            delay_us *= 2;
            retries++;
            continue;
        }
        return (dist_buf[0] << 8) | dist_buf[1];
    }
    return -1;
}

static void motor_forward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 1);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Forward\n");
}

static void motor_backward(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 1);
    printf("Motor: Backward\n");
}

static void motor_stop(void) {
    gpioWrite(MOTOR_FORWARD_PIN, 0);
    gpioWrite(MOTOR_BACKWARD_PIN, 0);
    printf("Motor: Stop\n");
}

static void trigger_callback(int gpio, int level, uint32_t tick) {
    (void)gpio; (void)tick;
    if (level != 1) return;

    int distance = vl53l1x_read_distance(i2c_handle);
    if (distance < 0) {
        fprintf(stderr, "Sensor read failed or bus error\n");
        motor_stop();
        return;
    }

    printf("Distance: %d mm\n", distance);

    if (distance < DISTANCE_THRESHOLD_CLOSE) {
        motor_forward();
    } else if (distance > DISTANCE_THRESHOLD_FAR) {
        motor_backward();
    } else {
        motor_stop();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X\n", VL53L1X_ADDR);
        gpioTerminate();
        return 1;
    }

    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_DOWN);

    if (gpioSetISRFunc(TRIGGER_PIN, RISING_EDGE, 0, trigger_callback) != 0) {
        fprintf(stderr, "Failed to set ISR for trigger pin\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    motor_stop();
    gpioSetISRFunc(TRIGGER_PIN, RISING_EDGE, 0, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

