#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define MPR121_ADDR 0x5A
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "proximity_log.txt"

#define GPIO_CHIP "gpiochip0"
#define LED1_PIN 17
#define LED2_PIN 18
#define LED3_PIN 27
#define LED4_PIN 22

#define NUM_ELECTRODES 12
#define POLL_DELAY_MS 50

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_lines[4] = {NULL, NULL, NULL, NULL};

static const int led_pins[4] = {LED1_PIN, LED2_PIN, LED3_PIN, LED4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_message(const char *msg) {
    if (!log_fp) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "[%s] %s\n", ts, msg);
    fflush(log_fp);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    if (i2c_write_reg8(fd, 0x80, 0x63) < 0) return -1; // Soft reset
    usleep(10000);

    // Verify sensor presence by reading MHDR
    uint8_t mhdr = 0;
    if (i2c_read_reg8(fd, 0x2B, &mhdr) < 0) return -1;
    if (mhdr != 0x01) {
        fprintf(stderr, "MPR121 not detected (MHDR=0x%02X)\n", mhdr);
        return -1;
    }

    // Stop mode
    if (i2c_write_reg8(fd, 0x5E, 0x00) < 0) return -1;

    // Baseline filtering
    if (i2c_write_reg8(fd, 0x2B, 0x01) < 0) return -1; // MHDR
    if (i2c_write_reg8(fd, 0x2C, 0x01) < 0) return -1; // NHDR
    if (i2c_write_reg8(fd, 0x2D, 0x0E) < 0) return -1; // NCLR
    if (i2c_write_reg8(fd, 0x2E, 0x00) < 0) return -1; // FDLR

    // Auto-configuration thresholds
    if (i2c_write_reg8(fd, 0x5A, 0x0B) < 0) return -1;
    if (i2c_write_reg8(fd, 0x5D, 0xC8) < 0) return -1;
    if (i2c_write_reg8(fd, 0x5E, 0x82) < 0) return -1;
    if (i2c_write_reg8(fd, 0x5F, 0xB4) < 0) return -1;

    // Enable all 12 electrodes, run mode
    if (i2c_write_reg8(fd, 0x5E, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo = 0, hi = 0;
    if (i2c_read_reg8(fd, 0x00, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, 0x01, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

static void set_led_pattern(struct gpiod_line *lines[4], uint8_t pattern) {
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(lines[i], (pattern >> i) & 1) < 0) {
            fprintf(stderr, "Failed to set LED %d: %s\n", i, strerror(errno));
        }
    }
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (led_lines[i]) {
            gpiod_line_set_value(led_lines[i], 0);
            gpiod_line_release(led_lines[i]);
            led_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_fp) {
        log_message("Program terminated.");
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(chip, led_pins[i]);
        if (!led_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(led_lines[i], "proximity-art", 0) < 0) {
            fprintf(stderr, "Failed to request output on GPIO %d: %s\n", led_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        cleanup();
        return 1;
    }

    log_message("Program started. MPR121 initialized.");

    uint8_t led_patterns[NUM_ELECTRODES] = {
        0x01, 0x02, 0x04, 0x08, 0x01, 0x02, 0x04, 0x08, 0x01, 0x02, 0x04, 0x08
    };

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(i2c_fd, &touch_status) < 0) {
            log_message("Error reading touch status.");
            usleep(POLL_DELAY_MS * 1000);
            continue;
        }

        int active_electrode = -1;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1 << i)) {
                active_electrode = i;
                break;
            }
        }

        if (active_electrode >= 0) {
            set_led_pattern(led_lines, led_patterns[active_electrode]);
            char msg[128];
            snprintf(msg, sizeof(msg), "Electrode %d touched. LED pattern: 0x%02X", active_electrode, led_patterns[active_electrode]);
            log_message(msg);
        } else {
            set_led_pattern(led_lines, 0x00);
            log_message("No electrodes touched. All LEDs off.");
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    cleanup();
    return 0;
}

