#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define LED_GPIO 27
#define LOG_FILE "proximity.log"

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_NHD_RISING_NHD_Falling 0x33
#define MPR121_NCL_RISING_NCL_Falling 0x34
#define MPR121_FDL_RISING_FDL_Falling 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E
#define MPR121_AUTO_CONFIG0 0x7B
#define MPR121_AUTO_CONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(i2c_handle, reg, value) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", value, reg);
        return -1;
    }
    return 0;
}

static int mpr121_read(uint8_t reg) {
    int val = i2cReadByteData(i2c_handle, reg);
    if (val < 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
    }
    return val;
}

static int mpr121_init(void) {
    int device_id = mpr121_read(0x00);
    if (device_id < 0) {
        fprintf(stderr, "Failed to read MPR121 device ID\n");
        return -1;
    }
    if ((device_id & 0x0F) != 0x05) {
        fprintf(stderr, "Unexpected MPR121 device ID: 0x%02X\n", device_id);
        return -1;
    }

    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISING_NHD_Falling, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISING_NCL_Falling, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISING_FDL_Falling, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write(MPR121_TL, 0xB4) < 0) return -1;
    if (mpr121_write(MPR121_E0TTH, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_E0RTH, 0x05) < 0) return -1;
    if (mpr121_write(MPR121_ECR, 0x01) < 0) return -1;
    return 0;
}

static int read_touch_status(void) {
    int low = mpr121_read(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_proximity_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Proximity detected on electrode 0\n", s);
    fclose(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
