#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_US 30000
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_US 0.0343

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static long long get_timestamp_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static long long get_timestamp_ms(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

static int wait_for_value(struct gpiod_line *line, int value, long long timeout_us) {
    long long start = get_timestamp_us();
    while (program_running) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_get_value failed: %s\n", strerror(errno));
            return -1;
        }
        if (v == value) {
            return 0;
        }
        if (get_timestamp_us() - start > timeout_us) {
            return 1;
        }
    }
    return 1;
}

static int measure_distance(struct gpiod_line *trigger, struct gpiod_line *echo, float *distance_out) {
    long long start, end, pulse_us;

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }
    usleep(5);

    if (gpiod_line_set_value(trigger, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);

    if (gpiod_line_set_value(trigger, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        return -1;
    }

    if (wait_for_value(echo, 1, TIMEOUT_US) != 0) {
        fprintf(stderr, "Timeout waiting for echo rising edge (sensor absent?)\n");
        return 1;
    }

    start = get_timestamp_us();
    if (wait_for_value(echo, 0, TIMEOUT_US) != 0) {
        fprintf(stderr, "Timeout waiting for echo falling edge\n");
        return 1;
    }
    end = get_timestamp_us();

    pulse_us = end - start;
    *distance_out = (float)pulse_us * SOUND_SPEED_CM_PER_US / 2.0f;

    if (*distance_out < MIN_DISTANCE_CM || *distance_out > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", *distance_out);
        return 2;
    }

    return 0;
}

static void log_distance(FILE *fp, float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "gmtime failed\n");
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%.2f\n", timestamp, distance) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    fflush(fp);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    FILE *fp = NULL;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (trigger == NULL) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (echo == NULL) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04-trigger", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance;
        int rc = measure_distance(trigger, echo, &distance);

        if (rc == 0) {
            log_distance(fp, distance);
            printf("Distance: %.2f cm\n", distance);
        } else if (rc == 1) {
            fprintf(stderr, "Measurement timeout or sensor absent.\n");
        } else if (rc == 2) {
            fprintf(stderr, "Distance out of valid range.\n");
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");
    ret = 0;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    if (fp) fclose(fp);
    return ret;
}

