#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 1000000
#define MIN_PULSE_US     58
#define MAX_PULSE_US     25000
#define SPEED_OF_SOUND   343.0
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_start_tick = 0;
static volatile uint32_t     g_pulse_us   = 0;
static volatile int          g_echo_seen  = 0;
static FILE                 *g_log_fp     = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0 && g_start_tick != 0) {
        uint32_t start = g_start_tick;
        uint32_t end   = tick;
        g_pulse_us    = end - start;
        g_echo_seen   = 1;
        g_start_tick  = 0;
    }
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        return -1;
    }

    /* 1 kOhm / 2 kOhm divider steps 5V echo down to ~3.3V for the Pi. */
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_OFF) < 0) {
        fprintf(stderr, "Warning: failed to set pull on ECHO_PIN %d.\n", ECHO_PIN);
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise TRIGGER_PIN low.\n");
        return -1;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        return -1;
    }

    return 0;
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance(uint32_t pulse_us)
{
    return (double)pulse_us * SPEED_OF_SOUND / 2.0e6;
}

static void log_distance(double distance)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s, Distance: %.2f m\n", timestamp, distance);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

static void cleanup(void)
{
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
