static volatile uint32_t     g_start_tick = 0;
static volatile uint32_t     g_pulse_us   = 0;
static volatile int          g_echo_seen  = 0;
static FILE                 *g_log_fp     = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0 && g_start_tick != 0) {
        uint32_t start = g_start_tick;
        uint32_t end   = tick;
        g_pulse_us    = end - start;
        g_echo_seen   = 1;
        g_start_tick  = 0;
    }
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        return -1;
