#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define TRIGGER_PIN 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_REG 0x0020

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int read_reg16(int handle, uint16_t reg, uint16_t *out) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int read_reg8(int handle, uint16_t reg, uint8_t *out) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 1) != 1) return -1;
    *out = (uint8_t)buf[0];
    return 0;
}

static int init_sensor(int handle) {
    if (write_reg8(handle, MODE_REG, 0x00) < 0) return -1;
    if (write_reg8(handle, TIMEOUT_REG, 0x00) < 0) return -1;
    if (write_reg8(handle, START_REG, 0x01) < 0) return -1;
    return 0;
}

static void log_data(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s, Distance: %u mm, Status: 0x%02X", ts, distance, status);
}

int main(void) {
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", TRIGGER_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 1);

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device at bus %d addr 0x%02X", I2C_BUS, VL53L1X_ADDR);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (init_sensor(i2c_handle) < 0) {
        syslog(LOG_ERR, "Sensor initialisation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "VL53L1X monitoring started");

    while (running) {
        uint16_t distance = 0;
        uint8_t status = 0;
        int dist_ok = (read_reg16(i2c_handle, DISTANCE_REG, &distance) == 0);
        int stat_ok = (read_reg8(i2c_handle, STATUS_REG, &status) == 0);

        if (dist_ok && stat_ok) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Read error: distance=%d status=%d", dist_ok, stat_ok);
        }

        gpioDelay(100000);
    }

    syslog(LOG_INFO, "Shutting down");
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

