#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29
#define GATE_GPIO      24
#define DIST_THRESHOLD 20          /* cm */
#define POLL_MS        100
#define LOG_FILE       "gate_log.txt"

/* VL53L1X register addresses */
#define REG_MODEL_ID          0x010F
#define REG_SYSRANGE_START    0x0015
#define REG_RESULT_RANGE_VAL  0x0089
#define REG_RANGING_MODE      0x0021

#define EXPECTED_MODEL_ID     0xEA

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_file) return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;

    fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                        */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 0)
        return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len)
        return -1;
    return 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return (i2cWriteDevice(handle, buf, 3) == 0) ? 0 : -1;
}

/* ------------------------------------------------------------------ */
/* VL53L1X                                                            */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t id = 0;
    if (i2c_read_reg16(handle, REG_MODEL_ID, &id, 1) != 0) {
        log_event("Error: failed to read model ID");
        return -1;
    }
    if (id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                id, EXPECTED_MODEL_ID);
        log_event("Error: unexpected model ID");
        return -1;
    }

    /* Ranging mode: short */
    if (i2c_write_reg16(handle, REG_RANGING_MODE, 0x00) != 0) {
        log_event("Error: failed to set ranging mode");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg16(handle, REG_SYSRANGE_START, 0x01) != 0) {
        log_event("Error: failed to start ranging");
        return -1;
    }

    log_event("VL53L1X initialised and ranging started");
    return 0;
}

static int vl53l1x_read_distance_cm(int handle, int *distance_cm)
{
    uint8_t buf[2];
    if (i2c_read_reg16(handle, REG_RESULT_RANGE_VAL, buf, 2) != 0) {
        log_event("Error: failed to read distance register");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *distance_cm = (int)(raw / 10);   /* mm -> cm */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Gate control                                                       */
/* ------------------------------------------------------------------ */
static void gate_set(int state)
{
    if (gpioWrite(GATE_GPIO, state) != 0)
        log_event("Error: failed to write gate GPIO");
    else
        log_event(state ? "Gate OPENED" : "Gate CLOSED");
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        log_event("Program terminated");
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log file first so init errors can be recorded */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }
    log_event("Program started");

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialisation failed");
        fclose(g_log_file);
        g_log_file = NULL;
        return EXIT_FAILURE;
    }

    /* Configure gate GPIO */
    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        log_event("Error: failed to set gate GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GATE_GPIO, 0);   /* start closed */

    /* Open I2C */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        log_event("Error: i2cOpen failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        log_event("Error: VL53L1X initialisation failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int gate_open = 0;

    while (g_running) {
        int dist_cm = 0;
        if (vl53l1x_read_distance_cm(g_i2c_handle, &dist_cm) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Distance: %d cm", dist_cm);
            log_event(msg);

            if (dist_cm < DIST_THRESHOLD) {
                if (!gate_open) {
                    gate_set(1);
                    gate_open = 1;
                }
            } else {
                if (gate_open) {
                    gate_set(0);
                    gate_open = 0;
                }
            }
        }
        /* else: error already logged */

        gpioDelay(POLL_MS * 1000);   /* microseconds */
    }

    cleanup();
    return EXIT_SUCCESS;
}

