#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE   2.0
#define MAX_DISTANCE   400.0
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define SAMPLES        5
#define TIMEOUT_US     30000
#define TRIGGER_US     10
#define LOOP_DELAY_US  100000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_start = 0;
static volatile uint32_t     g_pulse_end   = 0;
static volatile int          g_echo_state  = 0;
static volatile double       g_distance    = -1.0;
static volatile int          g_data_ready  = 0;

static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        g_pulse_start = tick;
        g_echo_state  = 1;
    } else if (level == 0 && g_echo_state) {
        g_pulse_end   = tick;
        g_echo_state  = 0;
        g_data_ready  = 1;
    }
}

static double measure_distance(void) {
    g_pulse_start = 0;
    g_pulse_end   = 0;
    g_echo_state  = 0;
    g_data_ready  = 0;

    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(TRIGGER_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = gpioTick();
    while (!g_data_ready && (gpioTick() - start_tick) < TIMEOUT_US) {
        gpioDelay(100);
    }

    if (!g_data_ready) return -1.0;

    uint32_t pulse_width = g_pulse_end - g_pulse_start;
    double distance = (double)pulse_width / 1000000.0 * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static double moving_average(double new_value) {
    static double buffer[SAMPLES] = {0.0};
    static int    idx = 0;
    static int    filled = 0;
    double sum = 0.0;
    buffer[idx] = new_value;
    idx = (idx + 1) % SAMPLES;
    if (filled < SAMPLES) filled++;
    for (int i = 0; i < filled; i++) sum += buffer[i];
    return sum / (double)filled;
}

static int distance_to_angle(double distance) {
    if (distance < 0.0) return 90;
    double norm = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    double angle = MIN_ANGLE + (MAX_ANGLE - MIN_ANGLE) * (1.0 - log10(norm + 1e-6));
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return (int)angle;
}

static int angle_to_pulse(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;
    return MIN_PULSE_US + (int)((double)(angle - MIN_ANGLE) * (MAX_PULSE_US - MIN_PULSE_US) / (MAX_ANGLE - MIN_ANGLE));
}

static int set_servo_angle(int angle) {
    int pulse = angle_to_pulse(angle);
    int rc = gpioServo(SERVO_PIN, pulse);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed: %d\n", rc);
        return -1;
    }
    return 0;
}

static void log_data(double distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(g_log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(g_log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise trigger pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Failed to set echo alert callback\n");
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("distance_log.csv", "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }
    fprintf(g_log_file, "Timestamp,Distance_cm,Servo_angle_deg\n");
    fflush(g_log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting distance measurement and servo tracking...\n");

    while (g_running) {
        double distance = measure_distance();
        double smoothed = moving_average(distance);
        int angle = distance_to_angle(smoothed);
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Servo command failed\n");
        }
        log_data(smoothed, angle);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return 0;
}

