#define BUFFER_SIZE 10
#define DISTANCE_THRESHOLD 200
#define POLL_DELAY_US 50000

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x0001
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x004D
#define VL53L1X_REG_RESULT_DISTANCE 0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x000A
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0001
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0002
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT 0x0004
#define VL53L1X_REG_SYSTEM_THRESH_HIGH 0x0005
#define VL53L1X_REG_SYSTEM_THRESH_LOW 0x0006
#define VL53L1X_REG_SYSTEM_CROSSTALK 0x0007
#define VL53L1X_REG_SYSTEM_SIGNAL_RATE 0x0008

static int i2c_handle = -1;
static int distance_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, int len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

static int vl53l1x_init(int handle) {
    uint8_t id_buf[2];
    if (i2c_read_reg16(handle, 0x0001, id_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read VL53L1X ID register.\n");
        return -1;
    }
    if ((id_buf[0] != 0xEA) || (id_buf[1] != 0xCC)) {
        fprintf(stderr, "Error: Invalid VL53L1X ID: 0x%02X%02X\n", id_buf[0], id_buf[1]);
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x01) != 0) return -1;
    gpioDelay(1000);

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_HIGH, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_THRESH_LOW, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_CROSSTALK, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_SIGNAL_RATE, 0x00) != 0) return -1;

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) != 0) return -1;
    gpioDelay(1000);
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x01) != 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int read_distance(int handle) {
    uint8_t status_buf[1];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, status_buf, 1) != 1) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }
    if ((status_buf[0] & 0x07) == 0) {
        return 0;
    }

    uint8_t dist_buf[2];
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Warning: Failed to clear interrupt.\n");
