    return (dist_buf[0] << 8) | dist_buf[1];
}

static void update_circular_buffer(int distance) {
    distance_buffer[buffer_index] = distance;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static int check_threshold(int distance) {
    return (distance < DISTANCE_THRESHOLD) ? 1 : 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
