#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROX_HIGH_REG 0x08
#define PROX_LOW_REG 0x09
#define INTERRUPT_GPIO 27
#define LOG_FILE "proximity.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static int threshold = DEFAULT_THRESHOLD;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_proximity(int handle, int *prox) {
    int high = i2cReadByteData(handle, PROX_HIGH_REG);
    if (high < 0) return -1;
    int low = i2cReadByteData(handle, PROX_LOW_REG);
    if (low < 0) return -1;
    *prox = (high << 8) | low;
    return 0;
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    int prox;
    if (read_proximity(i2c_handle, &prox) == 0) {
        fprintf(log_file, "%s, Proximity: %d, Status: %s\n",
                ctime(&(time_t){time(NULL)}), prox,
                (prox <= threshold) ? "SAFE" : "ALERT");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error reading proximity in interrupt handler\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = strtol(optarg, NULL, 0);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", i2c_address, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(INTERRUPT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", INTERRUPT_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting pull-down on GPIO %d\n", INTERRUPT_GPIO);
        cleanup();
        return 1;
    }

    if (gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR on GPIO %d\n", INTERRUPT_GPIO);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    printf("Proximity monitoring started. Threshold: %d\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

