#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SPEAKER_PIN 18

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 200.0
#define MIN_FREQUENCY_HZ 200.0
#define MAX_FREQUENCY_HZ 2000.0

#define ECHO_TIMEOUT_US 200000  /* 200 ms */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 50000     /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance using the HC-SR04.
 * Returns distance in cm, or -1.0 on timeout/error.
 */
static float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo start timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: Echo end timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (diff / 2.0f) * 0.0343f;  /* speed of sound ~343 m/s */
    return distance;
}

/*
 * Map distance to frequency using a logarithmic curve.
 * Returns 0 on success, -1 on invalid distance.
 */
static int map_distance_to_frequency(float distance, float *frequency) {
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1;
    }
    *frequency = MIN_FREQUENCY_HZ * expf((distance - MIN_DISTANCE_CM) / 50.0f);
    if (*frequency < MIN_FREQUENCY_HZ) *frequency = MIN_FREQUENCY_HZ;
    if (*frequency > MAX_FREQUENCY_HZ) *frequency = MAX_FREQUENCY_HZ;
    return 0;
}

/*
 * Generate a square wave of given frequency on the speaker pin using pigpio hardware PWM.
 * 50% duty cycle, 20 kHz carrier (to drive an 8-ohm speaker).
 */
static void generate_tone(float frequency) {
    if (frequency <= 0.0f) {
        gpioPWM(SPEAKER_PIN, 0);
        return;
    }

    /* pigpio hardware PWM: duty cycle in range 0-255 */
    unsigned duty = 128;  /* 50% */

    /* Set PWM frequency to the desired tone frequency */
    if (gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        return;
    }

    /* Set PWM range to 255 for finer duty control */
    if (gpioSetPWMrange(SPEAKER_PIN, 255) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        return;
    }

    /* Start PWM with 50% duty cycle */
    if (gpioPWM(SPEAKER_PIN, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM start failed\n");
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SPEAKER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(speaker) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float current_frequency = 0.0f;

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: Sensor read failed, keeping previous frequency.\n");
        } else {
            if (map_distance_to_frequency(distance, &current_frequency) < 0) {
                fprintf(stderr, "Warning: Distance out of range, keeping previous frequency.\n");
            } else {
                printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, current_frequency);
            }
        }

        generate_tone(current_frequency);
        gpioDelay(LOOP_DELAY_US);
    }

    /* Cleanup */
    gpioPWM(SPEAKER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

