#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000  // 50 ms timeout for echo
#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define THRESHOLD_CM 10.0

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

int trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);  // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
    return 0;
}

int measure_echo_pulse() {
    uint32_t start_tick, end_tick;
    int timeout;

    // Wait for echo to go high
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 0) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            return -1;  // Timeout waiting for echo start
        }
    }
    start_tick = gpioTick();

    // Wait for echo to go low
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        gpioDelay(1);
        timeout++;
        if (timeout > TIMEOUT_US) {
            return -1;  // Timeout waiting for echo end
        }
    }
    end_tick = gpioTick();

    return (int)(end_tick - start_tick);
}

float calculate_distance(int pulse_width_us) {
    return (float)pulse_width_us / 2.0 / 29.1;  // cm
}

int main() {
    signal(SIGINT, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    while (program_running) {
        if (trigger_sensor() != 0) {
            fprintf(stderr, "Trigger failed\n");
            gpioDelay(500000);
            continue;
        }

        int pulse_width = measure_echo_pulse();
        if (pulse_width < 0) {
            printf("Invalid reading\n");
        } else {
            float distance = calculate_distance(pulse_width);
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                printf("Invalid reading\n");
            } else {
                printf("Distance: %.2f cm\n", distance);
                if (distance < THRESHOLD_CM) {
                    printf("Too close!\n");
                }
            }
        }
        gpioDelay(500000);  // 500 ms between readings
    }

    gpioTerminate();
    return 0;
}

