#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1175_ADDR 0x60
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define I2C_DEVICE "/dev/i2c-1"
#define LOG_FILE "proximity_log.csv"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_ambient_light(int fd, uint16_t *als_visible) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA0, &lo) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, REG_ALS_VIS_DATA1, &hi) < 0) {
        return -1;
    }
    *als_visible = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int log_data(FILE *fp, uint16_t als_visible) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        return -1;
    }
    if (fprintf(fp, "%s,%u\n", timestamp, als_visible) < 0) {
        return -1;
    }
    if (fflush(fp) != 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_fp, 0, SEEK_END);
    long file_size = ftell(g_log_fp);
    if (file_size == 0) {
        fprintf(g_log_fp, "timestamp,als_visible\n");
        fflush(g_log_fp);
    }

    printf("Si1175 proximity sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t als_visible;
        if (read_ambient_light(g_i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error reading ambient light data: %s\n", strerror(errno));
        } else {
            if (log_data(g_log_fp, als_visible) < 0) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            } else {
                printf("ALS Visible: %u\n", als_visible);
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

