#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1120_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "si1120_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

#define REG_PART_ID 0x00
#define REG_ALS_DATA0 0x22
#define REG_ALS_DATA1 0x23
#define REG_PS1_DATA0 0x18
#define REG_PS1_DATA1 0x19
#define REG_COMMAND 0x30
#define CMD_RESET 0x01

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc >= 0) return 0;
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X, rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_reg(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg=0x%02X, rc=%d), attempt %d/%d\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int read_16bit_le(int handle, uint8_t low_reg, uint8_t high_reg, uint16_t *out) {
    uint8_t lo, hi;
    if (read_reg(handle, low_reg, &lo) != 0) return -1;
    if (read_reg(handle, high_reg, &hi) != 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1120(int handle) {
    uint8_t part_id;
    if (read_reg(handle, REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID register\n");
        return -1;
    }
    if (part_id != 0x41) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x41)\n", part_id);
        return -1;
    }
    if (write_reg(handle, REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static void log_data(FILE *fp, uint16_t als, uint16_t prox) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ALS: %u, Proximity: %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            (unsigned)als, (unsigned)prox);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (rc=%d)\n",
                I2C_BUS, SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1120(i2c_handle) != 0) {
        fprintf(stderr, "Si1120 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t als = 0, prox = 0;
        if (read_16bit_le(i2c_handle, REG_ALS_DATA0, REG_ALS_DATA1, &als) != 0) {
            fprintf(stderr, "Failed to read ALS data\n");
        } else if (read_16bit_le(i2c_handle, REG_PS1_DATA0, REG_PS1_DATA1, &prox) != 0) {
            fprintf(stderr, "Failed to read proximity data\n");
        } else {
            log_data(log_file, als, prox);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

