#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE 0x06
#define SI1145_REG_INT_CFG 0x1A
#define SI1145_REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define SI1145_REG_ALS_VIS_ADC_GAIN 0x24
#define SI1145_REG_PS_ADC_COUNTER 0x22
#define SI1145_REG_PS_LED21 0x0C
#define SI1145_REG_PS_LED3 0x0F
#define SI1145_REG_PS_ADC_MISC 0x11
#define SI1145_REG_PS_ADC_GAIN 0x0D
#define SI1145_REG_COMMAND 0x80
#define SI1145_CMD_PS_FORCE 0x03
#define SI1145_REG_PS1_DATA0 0x16
#define SI1145_REG_PS1_DATA1 0x17
#define SI1145_HW_KEY_VAL 0x03
#define SI1145_MEAS_RATE_2MS 0x02
#define MAX_RETRIES 3
#define LOG_FILE "proximity_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, result);
    }
    return result;
}

static int read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
    }
    return result;
}

static int initialize_sensor(int handle) {
    if (write_register(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_register(handle, SI1145_REG_MEAS_RATE, SI1145_MEAS_RATE_2MS) < 0) return -1;
    if (write_register(handle, SI1145_REG_INT_CFG, 0x00) < 0) return -1;
    if (write_register(handle, SI1145_REG_ALS_VIS_IR_ADC_COUNTER, 0x0B) < 0) return -1;
    if (write_register(handle, SI1145_REG_ALS_VIS_ADC_GAIN, 0x00) < 0) return -1;
    if (write_register(handle, SI1145_REG_PS_ADC_COUNTER, 0x49) < 0) return -1;
    if (write_register(handle, SI1145_REG_PS_LED21, 0x03) < 0) return -1;
    if (write_register(handle, SI1145_REG_PS_LED3, 0x0F) < 0) return -1;
    if (write_register(handle, SI1145_REG_PS_ADC_MISC, 0x03) < 0) return -1;
    if (write_register(handle, SI1145_REG_PS_ADC_GAIN, 0x07) < 0) return -1;
    if (write_register(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) < 0) return -1;
    return 0;
}

static int read_proximity(int handle) {
    int low = read_register(handle, SI1145_REG_PS1_DATA0);
    if (low < 0) return -1;
    int high = read_register(handle, SI1145_REG_PS1_DATA1);
    if (high < 0) return -1;
    return (high << 8) | low;
}

static void log_data(FILE *fp, int proximity_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Proximity: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, proximity_value);
    fflush(fp);
}

static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(fp);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        log_error(log_file, "Sensor initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int proximity_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && proximity_value < 0 && !terminate) {
            proximity_value = read_proximity(i2c_handle);
            if (proximity_value < 0) {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retries, MAX_RETRIES);
                    gpioDelay(100000);
                }
            }
        }

        if (proximity_value >= 0) {
            log_data(log_file, proximity_value);
        } else {
            fprintf(stderr, "Failed to read proximity after %d retries\n", MAX_RETRIES);
            log_error(log_file, "Failed to read proximity after retries");
        }

        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

