#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27
#define DISTANCE_THRESHOLD 20.0f
#define SPEED_OF_SOUND 0.0343f  /* cm/us */
#define TRIGGER_PULSE_US 10
#define POLL_DELAY_US 1000000   /* 1 second */

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick   = 0;
static volatile int      echo_state = 0;  /* 0=idle, 1=rising seen, 2=falling seen */

static void signal_handler(int sig) {
    (void)sig;
    gpioTerminate();
    exit(0);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        start_tick = tick;
        echo_state = 1;
    } else if (level == 0 && echo_state == 1) {
        /* Falling edge: echo pulse ends */
        end_tick = tick;
        echo_state = 2;
    }
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", ECHO_PIN);
        return -1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", BUZZER_PIN);
        return -1;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert function on GPIO%d\n", ECHO_PIN);
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        return -1;
    }
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin low\n");
        return -1;
    }
    return 0;
}

static void trigger_sensor(void) {
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
    }
}

static float calculate_distance(uint32_t pulse_width) {
    return (float)pulse_width * SPEED_OF_SOUND / 2.0f;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        echo_state = 0;
        start_tick = 0;
        end_tick   = 0;

        trigger_sensor();

        /* Wait for echo callback to complete (falling edge) */
        int waited = 0;
        while (echo_state != 2 && waited < 100) {
            gpioDelay(10000); /* 10 ms */
            waited++;
        }

        if (echo_state != 2) {
            fprintf(stderr, "Warning: echo timeout (no valid reading)\n");
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint32_t pulse_width = end_tick - start_tick;
        float distance = calculate_distance(pulse_width);

        printf("Distance: %.2f cm\n", distance);

        if (distance < DISTANCE_THRESHOLD) {
            if (gpioWrite(BUZZER_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to set buzzer high\n");
            }
        } else {
            if (gpioWrite(BUZZER_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to set buzzer low\n");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioTerminate();
    return 0;
}

