#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 20.0
#define MAX_DISTANCE 200.0
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_MID_PULSE 1500
#define ECHO_TIMEOUT_US 30000
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static double measure_distance(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) return -1.0;
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) return -1.0;

    uint32_t start_tick = 0, end_tick = 0;
    int timeout = 0;

    while (gpioRead(ECHO_PIN) == 0) {
        start_tick = gpioTick();
        if (start_tick == 0) {
            timeout = 1;
            break;
        }
    }
    if (timeout) return -1.0;

    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick == 0) {
            timeout = 1;
            break;
        }
    }
    if (timeout) return -1.0;

    uint32_t diff = end_tick - start_tick;
    if (diff == 0) return -1.0;

    double distance = (double)diff * SPEED_OF_SOUND / 2000000.0;
    return distance;
}

static int calculate_servo_angle(double distance) {
    if (distance < MIN_DISTANCE) return 180;
    if (distance > MAX_DISTANCE) return 0;
    return (int)((distance - MAX_DISTANCE) * 90.0 / (MIN_DISTANCE - MAX_DISTANCE));
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int pulse = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / 180);
    if (gpioServo(SERVO_PIN, pulse) < 0) return -1;
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(ECHO_PIN, PI_INPUT) < 0 ||
        gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (running) {
        double distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Sensor error or timeout, retrying...\n");
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        int angle = calculate_servo_angle(distance);
        if (set_servo_angle(angle) < 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

