#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 18
#define DISTANCE_THRESHOLD_OPEN 200
#define DISTANCE_THRESHOLD_CLOSE 250
#define SERVO_CLOSED_US 1000
#define SERVO_OPEN_US 2000
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 0) return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

static int vl53l1x_init(int handle) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Invalid model ID 0x%02X (expected 0xEA).\n", model_id);
        return -1;
    }
    if (i2c_write_reg16(handle, 0x0010, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0011, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0012, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0013, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0014, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0015, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0016, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0017, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0018, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x0019, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x001A, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x001B, 0x00) != 0) return -1;
    if (i2c_write_reg16(handle, 0x001C, 0x00) != 0) return -1;
