#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND 0.0343
#define MIN_DISTANCE   20.0
#define MAX_DISTANCE   200.0
#define MIN_ANGLE      0
#define MAX_ANGLE      180
#define MIN_PULSE_US   500
#define MAX_PULSE_US   2500
#define TIMEOUT_US     50000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US  100000

static volatile int keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

float measure_distance(void) {
    uint32_t start_tick, end_tick, timeout_tick;

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(2);
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() >= timeout_tick) return -1.0;
    }
    start_tick = gpioTick();

    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() >= timeout_tick) return -1.0;
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    return (float)pulse_us * SPEED_OF_SOUND / 2.0;
}

int distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) return MIN_ANGLE;
    if (distance > MAX_DISTANCE) return MAX_ANGLE;
    return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE));
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    signal(SIGINT, handle_sigint);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: sensor timeout or invalid reading\n");
        } else {
            int angle = distance_to_angle(distance);
            int pulse_us = MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
            gpioServo(SERVO_PIN, pulse_us);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

