    return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (MAX_ANGLE - MIN_ANGLE));
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(100000);

    signal(SIGINT, handle_sigint);

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        float distance = measure_distance();

        if (distance < 0) {
            fprintf(stderr, "Error: sensor timeout or invalid reading\n");
        } else {
            int angle = distance_to_angle(distance);
            int pulse_us = MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US) / MAX_ANGLE);
            gpioServo(SERVO_PIN, pulse_us);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

