#define SI7005_ADDR 0x40
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define CONFIG_REG 0x03
#define SI7005_CMD_TEMP 0x01
#define SI7005_CMD_HUMID 0x02
#define SI7005_CMD_READ 0x00
#define CONVERSION_DELAY_US 10000
#define SAMPLE_INTERVAL_US 2000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_config(uint8_t config) {
    char buf[2] = { (char)CONFIG_REG, (char)config };
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    char cmd = (char)reg;
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing register address\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading register\n");
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
