    if (write_config(SI7005_CMD_READ) != 0) {
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);

    if (read_register(TEMP_REG, &raw_temp) != 0) {
        return -1;
    }
    if (read_register(HUMID_REG, &raw_humid) != 0) {
        return -1;
    }

    *temperature = ((175.72f * (float)raw_temp) / 65536.0f) - 46.85f;
    *humidity = ((125.0f * (float)raw_humid) / 65536.0f) - 6.0f;

    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

