#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_CONFIG       0x1A
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_PWR_MGMT_2   0x6C
#define MPU6050_WHO_AM_I     0x75

/* Expected WHO_AM_I response */
#define MPU6050_WHO_AM_I_RESP 0x68

/* Global handle for signal handler cleanup */
static int g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; return 0 on success, -1 on error     */
/* ------------------------------------------------------------------ */
static int mpu_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; return 0 on success, -1 on error    */
/* ------------------------------------------------------------------ */
static int mpu_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at reg; return 0 on success, -1 err  */
/* ------------------------------------------------------------------ */
static int mpu_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error: i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MPU-6050; return 0 on success, -1 on error          */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int handle)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (mpu_read_byte(handle, MPU6050_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: cannot read WHO_AM_I — sensor absent or bus error\n");
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I_RESP) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who_am_i, MPU6050_WHO_AM_I_RESP);
        return -1;
    }
    printf("MPU-6050 detected (WHO_AM_I = 0x%02X)\n", who_am_i);

    /* Reset the device */
    if (mpu_write_byte(handle, MPU6050_PWR_MGMT_1, 0x80) != 0)
        return -1;
    gpioDelay(100000); /* 100 ms settle after reset */

    /* Wake up: clear SLEEP bit, use internal 8 MHz oscillator */
    if (mpu_write_byte(handle, MPU6050_PWR_MGMT_1, 0x00) != 0)
        return -1;
    gpioDelay(2000); /* 2 ms stabilization */

    /* Disable sleep mode, enable temperature sensor */
    if (mpu_write_byte(handle, MPU6050_PWR_MGMT_2, 0x00) != 0)
        return -1;

    /* Sample-rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_byte(handle, MPU6050_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 0 -> gyro bandwidth 8 kHz, accel bandwidth 1 kHz */
    if (mpu_write_byte(handle, MPU6050_CONFIG, 0x00) != 0)
        return -1;

    /* Gyro: ±250 deg/s (FS_SEL = 0) */
    if (mpu_write_byte(handle, MPU6050_GYRO_CONFIG, 0x00) != 0)
        return -1;

    /* Accel: ±2 g (AFS_SEL = 0) */
    if (mpu_write_byte(handle, MPU6050_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    printf("MPU-6050 initialised: 125 Hz, ±2 g accel, ±250 deg/s gyro\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and print one sample                                          */
/* ------------------------------------------------------------------ */
static void read_and_print(int handle)
{
    uint8_t buf[14];
    int16_t ax, ay, az, gx, gy, gz;

    if (mpu_read_block(handle, MPU6050_ACCEL_XOUT_H, buf, sizeof(buf)) != 0)
        return;

    ax = (int16_t)((buf[0]  << 8) | buf[1]);
    ay = (int16_t)((buf[2]  << 8) | buf[3]);
    az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* buf[6..7] = temperature (skipped) */
    gx = (int16_t)((buf[8]  << 8) | buf[9]);
    gy = (int16_t)((buf[10] << 8) | buf[11]);
    gz = (int16_t)((buf[12] << 8) | buf[13]);

    printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
           ax, ay, az, gx, gy, gz);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the MPU-6050 default address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (mpu6050_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting 125 Hz data logging (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (g_running) {
        read_and_print(g_i2c_handle);
        gpioDelay(100000); /* 100 ms -> ~125 Hz */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

