#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define SHT40_ADDR 0x44
#define SHT40_MEASURE_HIGH_REP 0xFD
#define I2C_BUS 1
#define MEASUREMENT_DELAY_US 10000
#define READ_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    uint8_t cmd = SHT40_MEASURE_HIGH_REP;
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x%02X)\n", cmd);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity = -6.0f + 125.0f * (float)h_raw / 65535.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X\n", I2C_BUS, SHT40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        float temperature, humidity;

        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            time_t now = time(NULL);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
            printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", ts, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Warning: Sensor read failed, re-opening I2C bus\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            sleep(1);
            if (running) {
                i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: Failed to re-open I2C bus\n");
                    break;
                }
            }
        }

        if (running) sleep(READ_INTERVAL_S);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

