#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5A
#define TA_REG 0x06
#define TO_REG 0x07
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, float *out) {
    uint8_t buf[3] = {0};
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 3) != 3) {
        return -1;
    }
    uint16_t raw = (uint16_t)((buf[1] << 8) | buf[0]);
    *out = (float)raw * 0.02 - 273.15;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    if (fprintf(log_fp, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MLX90614_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(log_fp, 0, SEEK_END);
    long file_size = ftell(log_fp);
    if (file_size == 0) {
        fprintf(log_fp, "Timestamp,Ambient (C),Object (C)\n");
        fflush(log_fp);
    }

    printf("MLX90614 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int rc = 0;

        if (i2c_read_reg16(i2c_fd, TA_REG, &ambient) != 0) {
            fprintf(stderr, "Error reading ambient temperature: %s\n", strerror(errno));
            rc = -1;
        }
        if (i2c_read_reg16(i2c_fd, TO_REG, &object) != 0) {
            fprintf(stderr, "Error reading object temperature: %s\n", strerror(errno));
            rc = -1;
        }

        if (rc == 0) {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            } else {
                printf("Ambient: %.2f C, Object: %.2f C\n", ambient, object);
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

