#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_fp = NULL;
static FILE *error_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (error_fp) {
        fprintf(error_fp, "%s: %s\n", ts, msg);
        fflush(error_fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (error_fp) {
        fclose(error_fp);
        error_fp = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus to STS30-DIS");
        return -1;
    }
    return 0;
}

static int read_temperature(float *temp_c) {
    unsigned char cmd[2] = {0x36, 0x15};
    unsigned char buf[6];
    int ret;

    ret = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (ret != 0) {
        log_error("I2C write failed (sensor may be absent or bus error)");
        return -1;
    }

    gpioDelay(10000); /* 10 ms conversion time */

    ret = i2cReadDevice(i2c_handle, (char *)buf, 6);
    if (ret != 6) {
        log_error("I2C read failed (sensor absent or bus error)");
        return -1;
    }

    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *temp_c = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static void log_data(float temp_c) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_fp, "%s, %.2f\n", ts, temp_c);
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    error_fp = fopen(ERROR_LOG_FILE, "a");
    if (!error_fp) {
        perror("fopen error_log.txt");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen enclosure_temp_log.txt");
        fclose(error_fp);
        error_fp = NULL;
        gpioTerminate();
        return 1;
    }

    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("STS30-DIS temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp_c;
        if (read_temperature(&temp_c) == 0) {
            log_data(temp_c);
            printf("Temperature: %.2f C\n", temp_c);
        } else {
            log_error("Failed to read temperature from STS30-DIS");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

