#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */
#define MAX_RETRIES    3
#define MEAS_DELAY_US  2000     /* 2 ms measurement wait */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus=%d addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sdp31(float *pressure_pa, float *temperature_c)
{
    uint8_t cmd[2] = { 0x21, 0x96 };   /* continuous measurement, mass flow */
    uint8_t buf[6];
    int rc;

    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
        if (rc < 0) {
            fprintf(stderr, "Warning: i2cWriteDevice attempt %d/%d failed: %d\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(1000 * attempt);   /* 1 ms, 2 ms, 3 ms backoff */
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        rc = i2cReadDevice(g_i2c_handle, (char *)buf, 6);
        if (rc < 0) {
            fprintf(stderr, "Warning: i2cReadDevice attempt %d/%d failed: %d\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(1000 * attempt);
            continue;
        }
        if (rc != 6) {
            fprintf(stderr, "Warning: short read attempt %d/%d: got %d bytes\n",
                    attempt, MAX_RETRIES, rc);
            gpioDelay(1000 * attempt);
            continue;
        }

        /* CRC check on pressure (bytes 0-1, CRC byte 2) and temperature (bytes 3-4, CRC byte 5) */
        if (sensirion_crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Warning: pressure CRC mismatch attempt %d/%d\n",
                    attempt, MAX_RETRIES);
            gpioDelay(1000 * attempt);
            continue;
        }
        if (sensirion_crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Warning: temperature CRC mismatch attempt %d/%d\n",
                    attempt, MAX_RETRIES);
            gpioDelay(1000 * attempt);
            continue;
        }

        int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

        *pressure_pa    = (float)raw_pressure    / 60.0f;
        *temperature_c  = (float)raw_temperature / 200.0f;
        return 0;
    }

    fprintf(stderr, "Error: SDP31 read failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

static int log_data(float pressure_pa, float temperature_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, pressure_pa, temperature_c) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error: fflush failed on log file.\n");
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Error opening log file");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# SDP31 airflow log started\n");
    fflush(g_log_file);

    while (g_running) {
        float pressure_pa, temperature_c;

        if (read_sdp31(&pressure_pa, &temperature_c) == 0) {
            if (log_data(pressure_pa, temperature_c) != 0) {
                fprintf(stderr, "Error: logging failed, continuing.\n");
            }
        } else {
            fprintf(stderr, "Error: sensor read failed, continuing.\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

