#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7015_ADDR    0x40
#define CMD_TEMP       0xF3
#define CMD_HUMID      0xF5
#define LOG_FILE       "sensor_data.txt"
#define SAMPLE_US      5000000  /* 5 seconds */
#define MAX_POLL_US    20000    /* 20 ms max per measurement */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read a 16-bit big-endian raw value from the Si7015 in No Hold Master mode.
 * Returns 0 on success, -1 on I2C error, -2 on timeout. */
static int read_raw(int handle, uint8_t cmd, uint16_t *raw_out)
{
    char buf[2];
    int  bytes;
    int  elapsed = 0;
    int  delay_us = 1000;   /* 1 ms poll interval */

    if (i2cWriteByte(handle, cmd) != 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n",
                cmd, pigpio_error(i2cWriteByte(handle, cmd)));
        return -1;
    }

    while (elapsed < MAX_POLL_US) {
        bytes = i2cReadDevice(handle, buf, 2);
        if (bytes == 2) {
            *raw_out = ((uint16_t)(buf[0] << 8)) | (uint8_t)buf[1];
            return 0;
        }
        if (bytes < 0) {
            fprintf(stderr, "I2C read failed (cmd 0x%02X): %s\n",
                    cmd, pigpio_error(bytes));
            return -1;
        }
        gpioDelay(delay_us);
        elapsed += delay_us;
    }

    fprintf(stderr, "Si7015 measurement timeout (cmd 0x%02X)\n", cmd);
    return -2;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

static void log_data(float temp, float hum)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    } else {
        fprintf(fp, "<timestamp-error>, Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
    }

    fclose(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;
        int rc_t = read_raw(g_i2c_handle, CMD_TEMP, &raw_t);
        int rc_h = read_raw(g_i2c_handle, CMD_HUMID, &raw_h);

        if (rc_t == 0 && rc_h == 0) {
            float temp = convert_temperature(raw_t);
            float hum  = convert_humidity(raw_h);
            log_data(temp, hum);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Sensor read error (T=%d, H=%d); retrying next cycle.\n",
                    rc_t, rc_h);
        }

        /* Sleep in 100 ms slices so SIGINT is caught promptly. */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

