        close(i2c_fd);
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen " LOG_FILE);
        close(i2c_fd);
        return 1;
    }

    printf("SHT40 greenhouse monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
