#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define BUFFER_SIZE      60
#define POLL_INTERVAL_US 2000000  /* 2 seconds */
#define MEASURE_DELAY_US 10000    /* 10 ms */
#define MAX_RETRIES      3

/* Si7021 commands */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUMID_HOLD  0xE5
#define CMD_RESET               0xFE

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    /* Reset the sensor to ensure a known state */
    if (i2cWriteByte(i2c_handle, CMD_RESET) < 0) {
        fprintf(stderr, "Warning: Si7021 reset failed (sensor may be absent)\n");
    }
    gpioDelay(15000); /* 15 ms reset recovery */
    return 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    char buf[2];
    int  result;
    int  retries;

    /* --- Temperature --- */
    retries = MAX_RETRIES;
    do {
        result = i2cWriteByte(i2c_handle, CMD_MEASURE_TEMP_HOLD);
        if (result == 0) break;
        fprintf(stderr, "Temp write failed (rc=%d), retries left=%d\n", result, retries - 1);
        gpioDelay(1000);
    } while (--retries > 0);
    if (result != 0) return -1;

    gpioDelay(MEASURE_DELAY_US);

    retries = MAX_RETRIES;
    do {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Temp read failed (rc=%d), retries left=%d\n", result, retries - 1);
        gpioDelay(1000);
    } while (--retries > 0);
    if (result != 2) return -1;

    uint16_t raw_temp = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *temperature = (175.72f * (float)raw_temp / 65536.0f) - 46.85f;

    /* --- Humidity --- */
    retries = MAX_RETRIES;
    do {
        result = i2cWriteByte(i2c_handle, CMD_MEASURE_HUMID_HOLD);
        if (result == 0) break;
        fprintf(stderr, "Humid write failed (rc=%d), retries left=%d\n", result, retries - 1);
        gpioDelay(1000);
    } while (--retries > 0);
    if (result != 0) return -1;

    gpioDelay(MEASURE_DELAY_US);

    retries = MAX_RETRIES;
    do {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "Humid read failed (rc=%d), retries left=%d\n", result, retries - 1);
        gpioDelay(1000);
    } while (--retries > 0);
    if (result != 2) return -1;

    uint16_t raw_hum = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *humidity = (125.0f * (float)raw_hum / 65536.0f) - 6.0f;

    return 0;
}

static void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (T=%.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

static void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    circular_buffer[buffer_index].timestamp   = now;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity    = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;

    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] Temp: %.2f C  Hum: %.2f %%RH\n", ts, temperature, humidity);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature, humidity;

        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            control_fan(temperature);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 20 && running; i++) {
            gpioDelay(POLL_INTERVAL_US / 20);
        }
    }

    /* Cleanup */
    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

