#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS 1

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT           0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT  0x3F86
#define CMD_GET_DATA_READY             0xE4B8

#define LOG_FILE "air_quality.log"
#define POLL_INTERVAL_US 1000000  /* 1 second */
#define MEASUREMENT_INTERVAL_US 5000000 /* 5 seconds */
#define MAX_RETRIES 3

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int send_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice failed for command 0x%04X (rc=%d)\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int read_data(uint8_t *data, size_t len) {
    int rc = i2cReadDevice(i2c_handle, (char *)data, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice returned %d, expected %zu\n", rc, len);
        return -1;
    }
    return 0;
}

static int is_data_ready(int *ready) {
    if (send_command(CMD_GET_DATA_READY) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms processing time */
    uint8_t buf[3];
    if (read_data(buf, 3) != 0)
        return -1;
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready word\n");
        return -1;
    }
    uint16_t word = (uint16_t)((buf[0] << 8) | buf[1]);
    *ready = (word & 0x07FF) != 0;
    return 0;
}

static int read_measurement(uint16_t *co2, float *temp, float *hum) {
    if (send_command(CMD_READ_MEASUREMENT) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms processing time */
    uint8_t buf[9];
    if (read_data(buf, 9) != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t t_raw   = (uint16_t)((buf[3] << 8) | buf[4]);
    uint16_t h_raw   = (uint16_t)((buf[6] << 8) | buf[7]);

    *co2  = co2_raw;
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum  = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static int log_data(uint16_t co2, float temp, float hum) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        send_command(CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(50000); /* 50 ms stop delay */
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (rc=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: failed to start periodic measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(1000000); /* 1 s startup delay */

    printf("SCD40 monitoring started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        int ready = 0;
        int retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (is_data_ready(&ready) == 0 && ready) {
                uint16_t co2;
                float temp, hum;
                if (read_measurement(&co2, &temp, &hum) == 0) {
                    if (log_data(co2, temp, hum) != 0) {
                        fprintf(stderr, "Warning: log write failed\n");
                    }
                    printf("CO2: %u ppm, Temp: %.2f C, Hum: %.2f %%\n", co2, temp, hum);
                    break;
                }
            }
            retries++;
            gpioDelay(100000); /* 100 ms backoff */
        }
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Error: measurement read failed after %d retries\n", MAX_RETRIES);
        }
        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

