#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SCD40_I2C_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define MEASUREMENT_INTERVAL_SEC 5

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_GET_DATA_READY_STATUS 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    int rc = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len) {
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "I2C read failed: expected %d bytes, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

static int scd40_start_periodic_measurement(void) {
    return i2c_write_cmd(CMD_START_PERIODIC_MEASUREMENT);
}

static int scd40_stop_periodic_measurement(void) {
    return i2c_write_cmd(CMD_STOP_PERIODIC_MEASUREMENT);
}

static int scd40_get_data_ready_status(uint16_t *ready) {
    if (i2c_write_cmd(CMD_GET_DATA_READY_STATUS) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms processing delay */
    uint8_t buf[3];
    if (i2c_read_bytes(buf, 3) < 0)
        return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on data ready status\n");
        return -1;
    }
    *ready = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int scd40_read_measurement(uint16_t *co2, float *temp, float *rh) {
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) < 0)
        return -1;
    gpioDelay(10000);
    uint8_t buf[9];
    if (i2c_read_bytes(buf, 9) < 0)
        return -1;
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }
    *co2 = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t t_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw = ((uint16_t)buf[6] << 8) | buf[7];
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void control_led(int co2) {
    gpioWrite(LED_GPIO, (co2 > CO2_THRESHOLD) ? 1 : 0);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", SCD40_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
