    *co2 = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t t_raw = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw = ((uint16_t)buf[6] << 8) | buf[7];
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d) {
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void control_led(int co2) {
    gpioWrite(LED_GPIO, (co2 > CO2_THRESHOLD) ? 1 : 0);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        scd40_stop_periodic_measurement();
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
