#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define EDGE_TIMEOUT_US 50000        /* 50 ms per edge wait */
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f C\n", timestamp, temperature);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

/*
 * Measure the high pulse width (TH) and total cycle width (TL) of the
 * TMP05 PWM-style output.  Returns 0 on success, -1 on timeout or error.
 */
static int measure_pulse_widths(int gpio_pin, int *th_us, int *tl_us) {
    uint32_t start_tick, end_tick;

    /* Wait for the line to go HIGH (start of a cycle). */
    start_tick = gpioTick();
    while (gpioRead(gpio_pin) == 0) {
        if ((gpioTick() - start_tick) > EDGE_TIMEOUT_US) {
            return -1;  /* Timeout waiting for HIGH */
        }
    }
    start_tick = gpioTick();

    /* Wait for the line to go LOW (end of high pulse). */
    while (gpioRead(gpio_pin) == 1) {
        if ((gpioTick() - start_tick) > EDGE_TIMEOUT_US) {
            return -1;  /* Timeout waiting for LOW */
        }
    }
    end_tick = gpioTick();
    *th_us = (int)(end_tick - start_tick);

    /* Wait for the line to go HIGH again (end of cycle). */
    while (gpioRead(gpio_pin) == 0) {
        if ((gpioTick() - end_tick) > EDGE_TIMEOUT_US) {
            return -1;  /* Timeout waiting for HIGH */
        }
    }
    end_tick = gpioTick();
    *tl_us = (int)(end_tick - start_tick);

    return 0;
}

static float calculate_temperature(int th_us, int tl_us) {
    if (tl_us == 0) {
        return -999.0f;  /* Guard against division by zero */
    }
    return 4215.0f - (2143.0f * (float)th_us / (float)tl_us);
}

int main(void) {
    int th_us, tl_us;
    float temperature;
    int consecutive_errors = 0;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Set GPIO pin as input */
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("TMP05 temperature monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (measure_pulse_widths(GPIO_PIN, &th_us, &tl_us) != 0) {
            log_error("Sensor read timeout or line stuck (no edges detected)");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION: 3 consecutive read failures");
                consecutive_errors = 0;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        temperature = calculate_temperature(th_us, tl_us);

        if (temperature < -40.0f || temperature > 150.0f) {
            log_error("Temperature reading out of valid range");
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION: 3 consecutive read failures");
                consecutive_errors = 0;
            }
        } else {
            log_temperature(temperature);
            consecutive_errors = 0;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("TMP05 temperature monitoring stopped.\n");
    return 0;
}

