#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEAS_CMD_HIGH_REP 0x2400
#define MEAS_DELAY_US 15000
#define MAX_RETRIES 3
#define RETRY_DELAY_S 1
#define LOG_INTERVAL_S 5
#define OFFSET_PERIOD_S 3600
#define TEMP_OFFSET_MAX 2.0f
#define HUM_OFFSET_MAX 5.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temp, float *hum) {
    uint8_t cmd[2] = { (MEAS_CMD_HIGH_REP >> 8) & 0xFF, MEAS_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t h_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *hum = 100.0f * (float)h_raw / 65535.0f;
    return 0;
}

static void apply_offset(float *temp, float *hum) {
    time_t now = time(NULL);
    float t = (float)(now % OFFSET_PERIOD_S) / OFFSET_PERIOD_S * 2.0f * M_PI;
    *temp += TEMP_OFFSET_MAX * sinf(t);
    *hum += HUM_OFFSET_MAX * sinf(t);
}

static void log_data(FILE *fp, float temp, float hum) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed (addr 0x%02X): %d\n", SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
