#define MEAS_DELAY_US 15000
#define MAX_RETRIES 3
#define RETRY_DELAY_S 1
#define LOG_INTERVAL_S 5
#define OFFSET_PERIOD_S 3600
#define TEMP_OFFSET_MAX 2.0f
#define HUM_OFFSET_MAX 5.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int read_sht35(int handle, float *temp, float *hum) {
    uint8_t cmd[2] = { (MEAS_CMD_HIGH_REP >> 8) & 0xFF, MEAS_CMD_HIGH_REP & 0xFF };
    uint8_t buf[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "I2C write error\n");
        return -1;
