#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44
#define MEASURE_CMD    0x2400   /* single-shot, high repeatability, clock stretching disabled */
#define MEASURE_DELAY_US 15000 /* 15 ms worst-case for high repeatability */
#define SAMPLE_INTERVAL_S 5
#define CSV_FILENAME   "environment.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler for clean shutdown ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Read one measurement from the SHT35 ----
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_sht35(int handle, float *temperature, float *humidity)
{
    uint8_t cmd[2] = {
        (uint8_t)((MEASURE_CMD >> 8) & 0xFF),
        (uint8_t)(MEASURE_CMD & 0xFF)
    };
    uint8_t data[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[SHT35] I2C write failed (cmd 0x%04X)\n", MEASURE_CMD);
        return -1;
    }

    /* Wait for conversion (high repeatability, clock stretching disabled) */
    gpioDelay(MEASURE_DELAY_US);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[SHT35] I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* CRC validation */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHT35] Temperature CRC mismatch\n");
        return -2;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHT35] Humidity CRC mismatch\n");
        return -2;
    }

    /* Convert raw values */
    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ---- Append a CSV row; writes header if file is new/empty ---- */
static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "a+");
    if (!fp) {
        fprintf(stderr, "[CSV] Cannot open '%s' for append\n", filename);
        return -1;
    }

    /* Determine whether file is empty so we can write a header */
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    int need_header = (file_size == 0);

    if (need_header)
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "[CSV] Error closing '%s'\n", filename);
        return -1;
    }
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] Initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C device at SHT35 address 0x44 */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[I2C] Failed to open bus %d addr 0x%02X (err %d)\n",
                I2C_BUS, SHT35_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT35 logging started (bus %d, addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, SHT35_ADDR);

    int consecutive_errors = 0;

    while (g_running) {
        float temperature, humidity;

        int rc = read_sht35(g_i2c_handle, &temperature, &humidity);
        if (rc == 0) {
            consecutive_errors = 0;
            printf("T=%.2f C  RH=%.2f %%\n", temperature, humidity);
            if (log_data(CSV_FILENAME, temperature, humidity) != 0)
                fprintf(stderr, "[CSV] Logging failed for this sample\n");
        } else {
            consecutive_errors++;
            fprintf(stderr, "[SHT35] Read failed (code %d), consecutive errors: %d\n",
                    rc, consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "[SHT35] Too many consecutive errors; aborting.\n");
                break;
            }
        }

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    /* Clean shutdown */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

