#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40
#define CMD_MEASURE_H  0xF5
#define CMD_MEASURE_T  0xF3
#define CMD_READ_PREV  0xE0
#define CMD_RESET      0xFE
#define LOG_FILE       "environment.log"
#define POLL_TIMEOUT_MS 100
#define POLL_DELAY_MS   5
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;
static int g_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(uint8_t cmd) {
    if (write(g_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len) {
    ssize_t n = read(g_fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_measurement(uint8_t cmd, uint16_t *raw) {
    if (i2c_write_cmd(cmd) < 0) return -1;

    uint8_t buf[3];
    for (int elapsed = 0; elapsed < POLL_TIMEOUT_MS; elapsed += POLL_DELAY_MS) {
        if (i2c_read_bytes(buf, 3) == 0) {
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                        crc8(buf, 2), buf[2]);
                return -1;
            }
            *raw = (uint16_t)((buf[0] << 8) | buf[1]);
            return 0;
        }
        usleep(POLL_DELAY_MS * 1000);
    }
    fprintf(stderr, "Timeout waiting for measurement 0x%02X\n", cmd);
    return -1;
}

static int read_temperature(uint16_t *raw_t) {
    if (read_measurement(CMD_MEASURE_T, raw_t) < 0) return -1;
    return 0;
}

static int read_humidity(uint16_t *raw_h) {
    if (read_measurement(CMD_MEASURE_H, raw_h) < 0) return -1;
    if (i2c_write_cmd(CMD_READ_PREV) < 0) return -1;
    return 0;
}

static void log_data(float temp, float hum) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, hum);
    } else {
        fprintf(fp, "ERROR,%.2f,%.2f\n", temp, hum);
    }
    fclose(fp);
}

static void log_error(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s,ERROR,ERROR,%s\n", ts, msg);
    } else {
        fprintf(fp, "ERROR,ERROR,%s\n", msg);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(g_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(g_fd);
        return 1;
    }

    if (i2c_write_cmd(CMD_RESET) < 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway.\n");
    }
    usleep(15000);

    while (g_running) {
        uint16_t raw_h = 0, raw_t = 0;
        float temp = -999.0f, hum = -999.0f;
        int ok = 0;

        if (read_humidity(&raw_h) == 0 && read_temperature(&raw_t) == 0) {
            ok = 1;
            temp = 175.72f * raw_t / 65536.0f - 46.85f;
            hum  = 125.0f  * raw_h / 65536.0f - 6.0f;
            if (temp < -40.0f || temp > 125.0f || hum < 0.0f || hum > 100.0f) {
                fprintf(stderr, "Out-of-range: T=%.2f H=%.2f\n", temp, hum);
                ok = 0;
            }
        }

        if (ok) {
            log_data(temp, hum);
        } else {
            log_error("I2C/CRC failure");
            if (i2c_write_cmd(CMD_RESET) < 0) {
                fprintf(stderr, "Reset write failed; continuing.\n");
            }
            usleep(15000);
        }

        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    if (g_fd >= 0) close(g_fd);
    return 0;
}

