    if (flow_slpm > FLOW_MAX_SLPM) flow_slpm = FLOW_MAX_SLPM;
    if (flow_slpm < FLOW_MIN_SLPM) flow_slpm = FLOW_MIN_SLPM;
    if (flow_slpm > FLOW_MIN_SLPM) {
        duty = (int)((flow_slpm / FLOW_MAX_SLPM) * PWM_RANGE);
    }
