    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Cannot open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
