#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B

#define WHO_AM_I_VAL 0xB1
#define CTRL_REG1_VAL 0xB0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_pressure(int handle, float *pressure) {
    uint8_t xl, l, h;
    if (read_register(handle, PRESS_OUT_XL, &xl) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 1, &l) < 0) return -1;
    if (read_register(handle, PRESS_OUT_XL + 2, &h) < 0) return -1;

    int32_t raw = ((int32_t)h << 16) | ((int32_t)l << 8) | (int32_t)xl;
    if (raw & 0x00800000) raw |= 0xFF000000;
    *pressure = (float)raw / 4096.0f;
    return 0;
}

static int read_temperature(int handle, float *temperature) {
    uint8_t l, h;
    if (read_register(handle, TEMP_OUT_L, &l) < 0) return -1;
    if (read_register(handle, TEMP_OUT_L + 1, &h) < 0) return -1;

    int16_t raw = (int16_t)((uint16_t)h << 8) | (uint16_t)l;
    *temperature = 42.5f + (float)raw / 480.0f;
    return 0;
}

static void log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", ts, pressure, temperature);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", LPS33HW_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t who_am_i = 0;
    if (read_register(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }

