#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define TEMP_REG       0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * STLM75: 16-bit two's-complement, 9-bit resolution.
 *   Byte 0 = sign bit (D15) + 8 data bits (D7..D0)
 *   Byte 1 = 8 data bits (D7..D0) + low 7 bits of temperature (D6..D0)
 *   Temperature = (raw >> 7) / 2.0  degrees Celsius
 */
static float read_temperature(int handle)
{
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", TEMP_REG, raw);
        return -1000.0f;
    }

    /* pigpio returns the word with the low byte in bits 0..7 and the
     * high byte in bits 8..15, which matches the STLM75 wire order. */
    int16_t swapped = (int16_t)(((raw & 0xFF) << 8) | ((raw >> 8) & 0xFF));

    int16_t temp_raw = swapped >> 7;          /* arithmetic shift keeps sign */
    float temp_c = (float)temp_raw / 2.0f;
    return temp_c;
}

static void update_circular_buffer(float temp, float *buf, int *idx, int size)
{
    buf[*idx] = temp;
    *idx = (*idx + 1) % size;
}

static float calculate_average(const float *buf, int size, int count)
{
    if (count <= 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < count; i++) sum += buf[i];
    return sum / (float)count;
}

int main(void)
{
    float temp_buffer[BUFFER_SIZE];
    int   buf_idx = 0;
    int   count   = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) temp_buffer[i] = 0.0f;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("STLM75 temperature monitor started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, I2C_ADDR);
    printf("LED on GPIO %d, threshold %.1f C, buffer size %d.\n",
           LED_GPIO, TEMP_THRESHOLD, BUFFER_SIZE);

    while (g_running) {
        float temp = read_temperature(handle);
        if (temp < -999.0f) {
            fprintf(stderr, "Temperature read failed; skipping cycle.\n");
        } else {
            update_circular_buffer(temp, temp_buffer, &buf_idx, BUFFER_SIZE);
            if (count < BUFFER_SIZE) count++;

            float avg = calculate_average(temp_buffer, BUFFER_SIZE, count);
            printf("Temp: %.2f C  |  Avg: %.2f C  |  LED: %s\n",
                   temp, avg, (avg > TEMP_THRESHOLD) ? "ON" : "OFF");

            if (avg > TEMP_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }

        time_sleep(POLL_INTERVAL);
    }

    /* Clean shutdown */
    gpioWrite(LED_GPIO, 0);
    i2cClose(handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

