#define CMD_GET_DATA_READY 0x0202
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_SET_MEASUREMENT_INTERVAL 0x4600
#define CMD_SET_FORCED_RESTART 0x4610

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc <<= 1;
        }
    }
    return crc;
}

static int scd30_write_command(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X\n", cmd);
        return -1;
    }
    return 0;
}

static int scd30_write_command_with_args(uint16_t cmd, uint16_t arg) {
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = crc8(&buf[2], 2);
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 5) != 0) {
        fprintf(stderr, "Error: I2C write failed for command 0x%04X with arg 0x%04X\n", cmd, arg);
        return -1;
    }
    return 0;
}

static int scd30_read_data(uint8_t *data, int len) {
    if (i2cReadDevice(g_i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error: I2C read failed (expected %d bytes)\n", len);
        return -1;
    }
    return 0;
}

static int scd30_data_ready(int *ready) {
    if (scd30_write_command(CMD_GET_DATA_READY) != 0) return -1;
    gpioDelay(2000);
    uint8_t buf[3];
    if (scd30_read_data(buf, 3) != 0) return -1;
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on data-ready word\n");
        return -1;
    }
    *ready = (buf[0] << 8) | buf[1];
    return 0;
}

static int scd30_read_measurement(float *co2, float *temp, float *rh) {
    if (scd30_write_command(CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(2000);
    uint8_t buf[18];
    if (scd30_read_data(buf, 18) != 0) return -1;
    for (int i = 0; i < 6; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }
    uint32_t co2_raw = ((uint32_t)buf[0] << 24) | ((uint32_t)buf[1] << 16) |
                       ((uint32_t)buf[3] << 8) | (uint32_t)buf[4];
    uint32_t temp_raw = ((uint32_t)buf[6] << 24) | ((uint32_t)buf[7] << 16) |
                        ((uint32_t)buf[9] << 8) | (uint32_t)buf[10];
    uint32_t rh_raw = ((uint32_t)buf[12] << 24) | ((uint32_t)buf[13] << 16) |
                      ((uint32_t)buf[15] << 8) | (uint32_t)buf[16];
    *co2 = (float)co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *rh = (float)rh_raw / 100.0f;
    return 0;
}

static void log_data(float co2, float temp, float rh) {
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
    fprintf(g_log_file, "%s,%.2f,%.2f,%.2f\n", ts, co2, temp, rh);
    fflush(g_log_file);
}

static void control_ventilation(float co2) {
    if (co2 >= CO2_THRESHOLD_HIGH) {
        printf("Ventilation: HIGH\n");
    } else if (co2 >= CO2_THRESHOLD_LOW) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: OFF\n");
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        scd30_write_command(CMD_STOP_PERIODIC_MEASUREMENT);
        gpioDelay(50000);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return 0;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 0;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 0;
    }

    if (scd30_write_command_with_args(CMD_SET_MEASUREMENT_INTERVAL, MEASUREMENT_INTERVAL_SEC) != 0) {
        fprintf(stderr, "Error: Failed to set measurement interval\n");
        cleanup();
        return 0;
    }
    gpioDelay(2000);

    if (scd30_write_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        cleanup();
        return 0;
    }
    gpioDelay(2000);

    printf("SCD30 initialized. Logging to %s every %d seconds.\n", LOG_FILE, MEASUREMENT_INTERVAL_SEC);

    while (g_running) {
        int ready = 0;
        if (scd30_data_ready(&ready) != 0) {
            fprintf(stderr, "Warning: data-ready check failed, retrying\n");
            gpioDelay(1000000);
            continue;
        }
        if (!ready) {
            gpioDelay(1000000);
            continue;
        }

        float co2, temp, rh;
        if (scd30_read_measurement(&co2, &temp, &rh) != 0) {
            fprintf(stderr, "Warning: measurement read failed, retrying\n");
            gpioDelay(1000000);
            continue;
        }

        log_data(co2, temp, rh);
        control_ventilation(co2);

        printf("CO2: %.2f ppm, Temp: %.2f C, RH: %.2f %%\n", co2, temp, rh);

        for (int i = 0; i < MEASUREMENT_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

