#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define SDP32_ADDR 0x21
#define I2C_BUS 1
#define MEASUREMENT_INTERVAL_MS 1000
#define MAX_RETRIES 3

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sdp32(int handle, float *pressure) {
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t buf[9];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "Error: I2C write failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(20000);

        if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        if (crc8(&buf[0], 2) != buf[2]) {
            fprintf(stderr, "Error: Pressure CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (crc8(&buf[3], 2) != buf[5]) {
            fprintf(stderr, "Error: Temperature CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (crc8(&buf[6], 2) != buf[8]) {
            fprintf(stderr, "Error: Scale-factor CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

        if (scale_factor == 0) {
            fprintf(stderr, "Error: Invalid scale factor (0) from sensor\n");
            return -1;
        }

        *pressure = (float)raw_pressure / (float)scale_factor;
        return 0;
    }

    fprintf(stderr, "Error: Failed to read SDP32 after %d retries\n", MAX_RETRIES);
    return -1;
}

static void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int interval = MEASUREMENT_INTERVAL_MS;
    int opt;

    while ((opt = getopt(argc, argv, "i:")) != -1) {
        switch (opt) {
            case 'i':
                interval = atoi(optarg);
                if (interval <= 0) {
                    fprintf(stderr, "Error: Invalid interval. Using default value.\n");
                    interval = MEASUREMENT_INTERVAL_MS;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-i interval_ms]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at address 0x%02X on bus %d\n", SDP32_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float pressure;
    while (!terminate) {
        if (read_sdp32(i2c_handle, &pressure) == 0) {
            log_data(pressure);
        } else {
            fprintf(stderr, "Error: Failed to read pressure. Exiting.\n");
            break;
        }
        gpioDelay(interval * 1000);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

