#define MEAS_DELAY_US  45000    /* 45 ms conversion time */
#define LOOP_DELAY_US  1000000  /* 1 s between readings */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one continuous-measurement frame from the SDP810              */
/* Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.          */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t cmd[2] = {
        (uint8_t)((CMD_CONTINUOUS >> 8) & 0xFF),
        (uint8_t)(CMD_CONTINUOUS & 0xFF)
    };
    uint8_t buf[9];

    /* Send continuous-measurement command */
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd 0x%04X)\n",
                CMD_CONTINUOUS);
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    int n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 9)\n", n);
        return -1;
    }

    /* CRC validation */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -2;
        }
    }

    /* Raw values are big-endian 16-bit signed */
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_pressure  = (int16_t)((buf[6] << 8) | buf[7]);

    /* Guard against a zero scale factor (sensor absent or not ready) */
    if (scale_pressure == 0) {
        fprintf(stderr, "[ERROR] Scale factor is zero — sensor not ready?\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_pressure;
    *temperature = (float)raw_temperature / 200.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SDP810 address */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SDP810_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP810-125Pa reader started (I2C bus %d, addr 0x%02X).\n",
           I2C_BUS, SDP810_ADDR);
    printf("Press Ctrl+C to stop.\n\n");

    int consecutive_errors = 0;

    while (g_running) {
        float pressure, temperature;

        int rc = read_sdp810(g_i2c_handle, &pressure, &temperature);

        if (rc == 0) {
            printf("Pressure:  %7.2f Pa\n", pressure);
            printf("Temperature: %6.2f °C\n\n", temperature);
            consecutive_errors = 0;
        } else if (rc == -2) {
            /* CRC mismatch — log and keep going */
            consecutive_errors++;
        } else {
            /* I/O error or sensor-absent path */
            consecutive_errors++;
            fprintf(stderr, "[WARN] Read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "[FATAL] Too many consecutive failures — aborting.\n");
                break;
            }
        }

        /* Sleep 1 s (interruptible by signals) */
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

