#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HDC1000_ADDR        0x40
#define HDC1000_TEMP_REG    0x00
#define HDC1000_CONFIG_REG  0x02
#define HDC1000_MANUF_REG   0xFE
#define HDC1000_DEV_ID_REG  0xFF

#define I2C_BUS             "/dev/i2c-1"
#define SAMPLE_INTERVAL_S   5
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int hdc1000_verify_id(int fd)
{
    uint16_t manuf_id = 0, dev_id = 0;
    if (i2c_read_reg16(fd, HDC1000_MANUF_REG, &manuf_id) < 0)
        return -1;
    if (i2c_read_reg16(fd, HDC1000_DEV_ID_REG, &dev_id) < 0)
        return -1;
    if (manuf_id != 0x5449 || dev_id != 0x1000) {
        fprintf(stderr, "HDC1000 ID mismatch: manuf=0x%04X dev=0x%04X (expected 0x5449 0x1000)\n",
                manuf_id, dev_id);
        return -1;
    }
    return 0;
}

static int hdc1000_init(int fd)
{
    /* Configuration: bit 12 = 1 -> 14-bit temp + 14-bit humidity, bit 13 = 0 -> no heater */
    uint16_t config = 0x1000;
    if (i2c_write_reg16(fd, HDC1000_CONFIG_REG, config) < 0)
        return -1;
    return 0;
}

static int hdc1000_read(int fd, float *temperature, float *humidity)
{
    /* Trigger a combined 14-bit temp + 14-bit humidity measurement */
    if (i2c_write_reg16(fd, HDC1000_TEMP_REG, 0x0000) < 0)
        return -1;

    usleep(CONVERSION_DELAY_MS * 1000);

    uint16_t raw_t, raw_h;
    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_t) < 0)
        return -1;
    if (i2c_read_reg16(fd, HDC1000_TEMP_REG, &raw_h) < 0)
        return -1;

    *temperature = ((float)raw_t / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)raw_h / 65536.0f) * 100.0f;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", HDC1000_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_verify_id(fd) < 0) {
        fprintf(stderr, "HDC1000 not detected at address 0x%02X\n", HDC1000_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    if (hdc1000_init(fd) < 0) {
        fprintf(stderr, "HDC1000 init failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X). Sampling every %d s.\n",
           I2C_BUS, HDC1000_ADDR, SAMPLE_INTERVAL_S);
    fflush(stdout);

    while (g_running) {
        float temperature, humidity;
        if (hdc1000_read(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

