#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define CMD_MEASURE_TEMP_HOLD 0xE3
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char cmd = CMD_MEASURE_TEMP_HOLD;
    char buf[2];
    int result;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteDevice(handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(100000);
            continue;
        }

        gpioDelay(20000);

        result = i2cReadDevice(handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", attempt + 1, result);
            gpioDelay(100000);
            continue;
        }

        uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        *temperature = (175.72f * raw / 65536.0f) - 46.85f;
        return 0;
    }

    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, SI7051_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature;
    while (running) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
        }
        sleep(READ_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

