#include <pigpio.h>

#define ICP10101_ADDR 0x63
#define ICP10101_CMD_READ_OTP 0x50
#define ICP10101_CMD_MEASURE_HP 0x40
#define ICP10101_MEASURE_DELAY_US 7000
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_calibration(int handle, uint16_t cal[4]) {
    char cmd = ICP10101_CMD_READ_OTP;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write OTP read command\n");
        return -1;
    }
    gpioDelay(2000);
    char buf[8];
    int n = i2cReadDevice(handle, buf, 8);
    if (n != 8) {
        fprintf(stderr, "Error: failed to read 8 bytes of OTP data (got %d)\n", n);
        return -1;
    }
    for (int i = 0; i < 4; i++) {
        cal[i] = ((uint16_t)(uint8_t)buf[2 * i] << 8) | (uint8_t)buf[2 * i + 1];
    }
    return 0;
}

static int read_sensor(int handle, const uint16_t cal[4],
                       float *temperature, float *pressure) {
    char cmd = ICP10101_CMD_MEASURE_HP;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(ICP10101_MEASURE_DELAY_US);
    char buf[6];
    int n = i2cReadDevice(handle, buf, 6);
    if (n != 6) {
        fprintf(stderr, "Error: failed to read 6 bytes of measurement data (got %d)\n", n);
        return -1;
    }
    if (buf[0] == 0xFF && buf[1] == 0xFF && buf[2] == 0xFF &&
        buf[3] == 0xFF && buf[4] == 0xFF && buf[5] == 0xFF) {
        fprintf(stderr, "Error: sensor returned all 0xFF — sensor absent or not responding\n");
        return -1;
    }
    uint16_t raw_t = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    uint32_t raw_p = ((uint32_t)(uint8_t)buf[2] << 24) |
                     ((uint32_t)(uint8_t)buf[3] << 16) |
                     ((uint32_t)(uint8_t)buf[4] << 8)  |
                     (uint8_t)buf[5];

    float t = (float)raw_t / 65535.0f;
    float p = (float)raw_p / 65535.0f;

    float scale_factor_lut = (float)cal[0] / 65535.0f;
    float scale_factor_h = (float)cal[1] / 65535.0f;
    float scale_factor_p = (float)cal[2] / 65535.0f;

    float t_comp = t * scale_factor_lut;
    float p_comp = p * scale_factor_p;
    float t_final = t_comp * 165.0f - 40.0f;
    float p_final = p_comp * scale_factor_h * 100.0f;

    *temperature = t_final;
    *pressure = p_final;
    return 0;
}

static void log_data(float temperature, float pressure) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", ts, temperature, pressure);
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, ICP10101_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t cal[4];
    if (read_calibration(g_i2c_handle, cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data\n");
        cleanup();
        return 1;
    }

    printf("ICP-10101 initialized. Sampling every %d seconds. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, pressure;
        if (read_sensor(g_i2c_handle, cal, &temperature, &pressure) == 0) {
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Warning: sensor read failed, will retry next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

