#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90819_ADDR  0x60
#define PRESSURE_MSB   0xAA
#define PRESSURE_LSB   0xAB
#define SCALE_FACTOR   0.1f
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_msb, uint8_t reg_lsb, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg_msb, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n", reg_msb, strerror(errno));
        return -1;
    }
    if (write(fd, &reg_lsb, 1) != 1) {
        fprintf(stderr, "I2C write (reg 0x%02X) failed: %s\n", reg_lsb, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (regs 0x%02X/0x%02X) failed: %s\n",
                reg_msb, reg_lsb, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static void log_pressure(float pressure_kpa)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    char ts[32];

    if (localtime_r(&now, &tm_buf) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_buf);
    } else {
        snprintf(ts, sizeof(ts), "unknown");
    }
    printf("[%s] Pressure: %.2f kPa\n", ts, pressure_kpa);
    fflush(stdout);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX90819_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MLX90819 pressure sensor reader started (I2C addr 0x%02X on %s).\n",
           MLX90819_ADDR, I2C_BUS);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t raw = 0;
        if (i2c_read_reg16(fd, PRESSURE_MSB, PRESSURE_LSB, &raw) == 0) {
            float pressure_kpa = (float)raw * SCALE_FACTOR;
            log_pressure(pressure_kpa);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

