#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAFE_MIN_KPA   200.0f
#define SAFE_MAX_KPA   250.0f
#define SCALE_FACTOR   0.01f
#define SAMPLE_PERIOD  1.0
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int open_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

static int read_pressure(float *pressure_kpa)
{
    char buf[2];
    int  rc;

    rc = i2cReadI2CBlockData(g_i2c_handle, PRESSURE_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed (rc=%d)\n", rc);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *pressure_kpa = (float)raw * SCALE_FACTOR;
    return 0;
}

static void log_pressure(float pressure_kpa)
{
    time_t     now;
    struct tm  tm_utc;
    char       ts[32];

    time(&now);
    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kpa);
    fflush(g_log_file);
}

static void check_pressure(float pressure_kpa)
{
    if (pressure_kpa < SAFE_MIN_KPA || pressure_kpa > SAFE_MAX_KPA) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa out of safe range [%.0f-%.0f] kPa\n",
                pressure_kpa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    int  file_exists = 0;
    int  file_size   = 0;
    int  first_read  = 1;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a+");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    file_size = (int)ftell(g_log_file);
    if (file_size > 0) {
        file_exists = 1;
    } else {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    while (g_running) {
        float pressure_kpa = 0.0f;
        int   ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_pressure(&pressure_kpa) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying I2C open after failure...\n");
                if (open_i2c() != 0) {
                    fprintf(stderr, "I2C reopen failed; will retry next cycle\n");
                }
            }
        }

        if (ok) {
            log_pressure(pressure_kpa);
            check_pressure(pressure_kpa);
            first_read = 0;
        } else {
            fprintf(stderr, "Failed to read pressure after %d attempts; skipping cycle\n",
                    MAX_RETRIES);
            if (first_read && !file_exists) {
                fprintf(stderr, "Log file is empty; cannot append; aborting\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

