    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.2f\n", ts, pressure_kpa);
    fflush(g_log_file);
}

static void check_pressure(float pressure_kpa)
{
    if (pressure_kpa < SAFE_MIN_KPA || pressure_kpa > SAFE_MAX_KPA) {
        fprintf(stderr, "WARNING: Pressure %.2f kPa out of safe range [%.0f-%.0f] kPa\n",
                pressure_kpa, SAFE_MIN_KPA, SAFE_MAX_KPA);
    }
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    int  file_exists = 0;
    int  file_size   = 0;
    int  first_read  = 1;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (open_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a+");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    file_size = (int)ftell(g_log_file);
    if (file_size > 0) {
        file_exists = 1;
    } else {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    while (g_running) {
        float pressure_kpa = 0.0f;
        int   ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_pressure(&pressure_kpa) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying I2C open after failure...\n");
                if (open_i2c() != 0) {
                    fprintf(stderr, "I2C reopen failed; will retry next cycle\n");
                }
            }
        }

        if (ok) {
            log_pressure(pressure_kpa);
            check_pressure(pressure_kpa);
            first_read = 0;
        } else {
            fprintf(stderr, "Failed to read pressure after %d attempts; skipping cycle\n",
                    MAX_RETRIES);
            if (first_read && !file_exists) {
                fprintf(stderr, "Log file is empty; cannot append; aborting\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    cleanup();
    return EXIT_SUCCESS;
}

