    if (size <= LOG_FILE_SIZE_LIMIT) {
        return 0;
    }
    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "%s.old", filename);
    if (rename(filename, new_filename) != 0) {
        fprintf(stderr, "Warning: failed to rotate log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(const char *timestamp, float temperature, float humidity) {
    if (rotate_log_file(LOG_FILE) != 0) {
        return -1;
    }
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
