#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 4
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 36
#define NIBBLE_MAX_TICKS 813
#define CHECKSUM_NIBBLES 4
#define LOG_FILE "pressure_log.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if (!running) return -1;
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int measure_pulse_width(int gpio, uint32_t timeout_us) {
    if (wait_for_level(gpio, 0, timeout_us) < 0) return -1;
    uint32_t start = gpioTick();
    if (wait_for_level(gpio, 1, timeout_us) < 0) return -1;
    uint32_t end = gpioTick();
    uint32_t width = end - start;
    return (int)width;
}

static int read_nibble(int gpio, uint32_t timeout_us) {
    int width = measure_pulse_width(gpio, timeout_us);
    if (width < 0) return -1;
    if (width < NIBBLE_MIN_TICKS || width > NIBBLE_MAX_TICKS) return -1;
    return (width - NIBBLE_MIN_TICKS) / TICK_US;
}

static int read_sent_nibble(int gpio, uint32_t timeout_us) {
    int nibble = read_nibble(gpio, timeout_us);
    if (nibble < 0) return -1;
    if (nibble < 0 || nibble > 15) return -1;
    return nibble;
}

static int read_sent_data(int gpio, uint32_t timeout_us, int *data) {
    if (read_sent_nibble(gpio, timeout_us) != 0) return -1;
    for (int i = 0; i < CHECKSUM_NIBBLES; i++) {
        int nibble = read_sent_nibble(gpio, timeout_us);
        if (nibble < 0) return -1;
        data[i] = nibble;
    }
    return 0;
}

static int calculate_checksum(const int *data) {
    int sum = 0;
    for (int i = 0; i < CHECKSUM_NIBBLES; i++) sum += data[i];
    return sum % 16;
}

static float convert_to_pressure(int raw) {
    const float scale = 0.01f;
    const float offset = 0.0f;
    return (float)raw * scale + offset;
}

static void log_pressure(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int data[CHECKSUM_NIBBLES];
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && running) {
            if (read_sent_data(GPIO_PIN, 1000000, data) == 0) {
                int checksum = calculate_checksum(data);
                if (checksum == data[3]) {
                    success = 1;
                    break;
                }
            }
            retries++;
            gpioDelay(10000);
        }

        if (success) {
            int raw = (data[0] << 8) | (data[1] << 4) | data[2];
            float pressure = convert_to_pressure(raw);
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Sensor read failed or invalid checksum\n");
        }

        gpioDelay(100000);
    }

    gpioTerminate();
    printf("Pressure monitoring stopped.\n");
    return 0;
}

