#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_REG_TEMP 0x00
#define TMP117_REG_DEVICE_ID 0x0B
#define TMP117_DEVICE_ID 0x0117
#define TEMP_SCALE 0.0078125f
#define LOG_FILE "greenhouse_temps.dat"
#define SAMPLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, TMP117_REG_TEMP, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature register: %d\n", result);
        return -1;
    }

    int16_t raw_temp = (int16_t)((buf[1] << 8) | buf[0]);
    *temperature = (float)raw_temp * TEMP_SCALE;
    return 0;
}

static int log_temperature(FILE *fp, float temperature) {
    uint8_t data[4];
    data[0] = (uint8_t)(temperature);
    data[1] = (uint8_t)(temperature >> 8);
    data[2] = (uint8_t)(temperature >> 16);
    data[3] = (uint8_t)(temperature >> 24);

    if (fwrite(data, 1, 4, fp) != 4) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

static int verify_device_id(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, TMP117_REG_DEVICE_ID, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading device ID: %d\n", result);
        return -1;
    }

