#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TMP117_ADDR    0x48
#define TEMP_REG       0x00
#define BUFFER_SIZE    100
#define LOG_FILE       "temperature_log.dat"
#define SAMPLE_PERIOD  5.0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

typedef struct {
    time_t timestamp;
    float  temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, time_t ts, float temp) {
    cb->buffer[cb->head].timestamp   = ts;
    cb->buffer[cb->head].temperature = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static int cb_save(const CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    size_t to_write = (size_t)(cb->count * sizeof(TemperatureReading));
    size_t written  = fwrite(cb->buffer, sizeof(TemperatureReading), cb->count, fp);
    if (written != (size_t)cb->count) {
        fprintf(stderr, "Short write: %zu of %zu\n", written, cb->count);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

static int read_temperature(int handle, float *out) {
    char reg = (char)TEMP_REG;
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "I2C write (reg select) failed\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "I2C read (temperature) failed\n");
        return -1;
    }
    int16_t raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    *out = (float)raw * 0.0078125f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    CircularBuffer cb;
    cb_init(&cb);

    while (g_running) {
        float temp;
        if (read_temperature(g_i2c_handle, &temp) == 0) {
            time_t now = time(NULL);
            cb_add(&cb, now, temp);
            if (cb_save(&cb, LOG_FILE) != 0) {
                fprintf(stderr, "Warning: failed to save buffer to %s\n", LOG_FILE);
            }
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Skipping sample due to read error\n");
        }
        time_sleep(SAMPLE_PERIOD);
    }

    if (cb_save(&cb, LOG_FILE) != 0) {
        fprintf(stderr, "Warning: failed to flush buffer on exit\n");
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

