    (void)sig;
    terminate = 1;
}

/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int read_shtc3(int handle, float *temperature, float *humidity) {
    uint8_t cmd[2] = { (uint8_t)(MEASURE_CMD >> 8), (uint8_t)(MEASURE_CMD & 0xFF) };
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: I2C write failed (cmd 0x7866)\n");
        return -1;
    }

    gpioDelay(MEASURE_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed (expected 6 bytes)\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 0-1, CRC byte 2) */
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity (bytes 3-4, CRC byte 5) */
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t hum_raw  = (uint16_t)((data[3] << 8) | data[4]);

    *temperature = 175.0f * (float)temp_raw / 65535.0f - 45.0f;
    *humidity    = 100.0f * (float)hum_raw  / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f %%\n", *humidity);
        return -1;
