#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error: %d\n", raw);
        return -1;
    }
    int16_t signed_raw = (int16_t)raw;
    *temperature = (float)signed_raw * 0.0078125f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int retry_count = 0;
    while (running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
            retry_count = 0;
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            retry_count++;
            if (retry_count > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            gpioDelay(1000000);
            i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %d\n", i2c_handle);
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

