                fprintf(stderr, "Error logging temperature\n");
            }
            retry_count = 0;
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            retry_count++;
            if (retry_count > MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
