#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define LOG_FILE "flow_log.txt"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3

/* Conversion constants from Honeywell HAFUHH0025PA3 datasheet */
#define FLOW_SCALE 16384.0f
#define FLOW_OFFSET 0.1f
#define FLOW_RANGE 0.8f
#define FLOW_MAX_SLPM 25.0f

#define TEMP_SCALE 4096.0f
#define TEMP_OFFSET 0.1f
#define TEMP_RANGE 0.8f
#define TEMP_MIN_C -40.0f
#define TEMP_MAX_C 80.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int initialize_i2c(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n", I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int read_sensor_data(uint16_t *flow_raw, uint16_t *temp_raw) {
    char buf[4];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C data: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    *flow_raw = ((uint16_t)(buf[0] & 0x3F) << 8) | (uint8_t)buf[1];
    *temp_raw = ((uint16_t)(buf[2] & 0x3F) << 8) | (uint8_t)buf[3];
    return 0;
}

static float convert_flow(uint16_t raw) {
    float flow = ((float)raw / FLOW_SCALE) - FLOW_OFFSET;
    flow = flow * FLOW_RANGE * FLOW_MAX_SLPM;
    if (flow < 0.0f) flow = 0.0f;
    if (flow > FLOW_MAX_SLPM) flow = FLOW_MAX_SLPM;
    return flow;
}

static float convert_temperature(uint16_t raw) {
    float temp = ((float)raw / TEMP_SCALE) - TEMP_OFFSET;
    temp = temp * TEMP_RANGE * (TEMP_MAX_C - TEMP_MIN_C) + TEMP_MIN_C;
    if (temp < TEMP_MIN_C) temp = TEMP_MIN_C;
    if (temp > TEMP_MAX_C) temp = TEMP_MAX_C;
    return temp;
}

static void log_data(float flow, float temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f C\n", timestamp, flow, temp);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* First two reads may return stale data; discard */
    for (int i = 0; i < 2; i++) {
        uint16_t f, t;
        if (read_sensor_data(&f, &t) == 0) break;
        gpioDelay(100000); /* 100 ms */
    }

    while (running) {
        uint16_t flow_raw, temp_raw;
        if (read_sensor_data(&flow_raw, &temp_raw) == 0) {
            float flow = convert_flow(flow_raw);
            float temp = convert_temperature(temp_raw);
            log_data(flow, temp);
        } else {
            fprintf(stderr, "Read failed, attempting re-initialization...\n");
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Re-initialization failed, retrying in %d s...\n", SAMPLE_INTERVAL_SEC);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

