#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_START_LOW_US 18000
#define DHT11_START_HIGH_US 40
#define DHT11_RESP_LOW_US 80
#define DHT11_RESP_HIGH_US 80
#define DHT11_BIT_LOW_US 50
#define DHT11_TIMEOUT_US 1000
#define SAMPLE_INTERVAL_S 2

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg, int code) {
    FILE *fp = fopen("dht11_errors.log", "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - ERROR: %s (code %d)\n", ts, msg, code);
    fclose(fp);
}

static void log_reading(float temp, float hum) {
    FILE *fp = fopen("dht11_readings.txt", "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s - Temperature: %.1f C, Humidity: %.1f %%\n", ts, temp, hum);
    fclose(fp);
}

/* Wait for line to reach target level or timeout (returns 0 on success, -1 on timeout) */
static int wait_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

/* Measure high pulse duration; returns duration in us, or -1 on timeout */
static int measure_high(int gpio, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == 1) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return (int)(gpioTick() - start);
}

static int read_dht11(float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i, j;

    /* --- Start signal: pull low for >=18 ms, then high briefly --- */
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(DHT11_START_LOW_US);
    gpioWrite(DHT11_GPIO, 1);
    gpioDelay(DHT11_START_HIGH_US);
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    /* --- Wait for sensor response: 80 us low then 80 us high --- */
    if (wait_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) != 0) {
        log_error("Sensor not responding (no initial low)", 1);
        return 1;
    }
    if (wait_level(DHT11_GPIO, 1, DHT11_TIMEOUT_US) != 0) {
        log_error("Sensor response high timeout", 2);
        return 2;
    }
    if (measure_high(DHT11_GPIO, DHT11_TIMEOUT_US) < 0) {
        log_error("Sensor response high pulse timeout", 3);
        return 3;
    }

    /* --- Read 40 data bits --- */
    for (i = 0; i < 5; i++) {
        for (j = 7; j >= 0; j--) {
            /* Each bit starts with 50 us low */
            if (wait_level(DHT11_GPIO, 0, DHT11_TIMEOUT_US) != 0) {
                log_error("Data bit low timeout", 4);
                return 4;
            }
            /* Measure high-pulse duration to determine bit value */
            int high_us = measure_high(DHT11_GPIO, DHT11_TIMEOUT_US);
            if (high_us < 0) {
                log_error("Data bit high timeout", 5);
                return 5;
            }
            if (high_us > 50) {
                data[i] |= (1 << j);
            }
        }
    }

    /* --- Checksum validation --- */
    uint8_t checksum = (uint8_t)((data[0] + data[1] + data[2] + data[3]) & 0xFF);
    if (checksum != data[4]) {
        log_error("Checksum mismatch", 6);
        return 6;
    }

    /* DHT11: humidity = byte0, temperature = byte2 (both integer-only) */
    *hum = (float)data[0];
    *temp = (float)data[2];
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temp, hum;
    int rc;

    while (running) {
        rc = read_dht11(&temp, &hum);
        if (rc == 0) {
            log_reading(temp, hum);
        } else {
            log_error("DHT11 read failed", rc);
        }
        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int s = 0; s < SAMPLE_INTERVAL_S * 10 && running; s++) {
            gpioDelay(100000);
        }
    }

    gpioTerminate();
    return 0;
}

