#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x64
#define ADPD105_ADDR_2 0x65
#define ADPD105_REG_DEVICE_ID 0x00
#define ADPD105_REG_RED_DATA 0x64
#define ADPD105_REG_GREEN_DATA 0x66
#define ADPD105_REG_BLUE_DATA 0x68
#define ADPD105_DEVICE_ID 0x2A
#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register16(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *value = (uint16_t)((uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

static int read_cct(int handle, float *cct) {
    uint16_t red, green, blue;
    if (read_register16(handle, ADPD105_REG_RED_DATA, &red) != 0) {
        return -1;
    }
    if (read_register16(handle, ADPD105_REG_GREEN_DATA, &green) != 0) {
        return -1;
    }
    if (read_register16(handle, ADPD105_REG_BLUE_DATA, &blue) != 0) {
        return -1;
    }
    float r = (float)red;
    float g = (float)green;
    float b = (float)blue;
    float n = (r + g + b) / 3.0f;
    if (n == 0.0f) {
        return -1;
    }
    float x = (r / n);
    float y = (g / n);
    float u = (x / (x + y + 0.000001f));
    float v = (y / (x + y + 0.000001f));
    float u_ref = 0.3127f;
    float v_ref = 0.3290f;
    float u_diff = u - u_ref;
    float v_diff = v - v_ref;
    float temp = (u_diff / v_diff) * 100.0f;
    if (temp < 1000.0f || temp > 40000.0f) {
        return -1;
    }
    *cct = temp;
    return 0;
}

static int log_data(float avg_cct) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f\n", timestamp, avg_cct) < 0) {
        return -1;
    }
    fflush(log_file);
    return 0;
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ADPD105_ADDR_1, i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n", ADPD105_ADDR_2, i2c_handle2);
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    int id1 = i2cReadByteData(i2c_handle1, ADPD105_REG_DEVICE_ID);
    if (id1 != ADPD105_DEVICE_ID) {
        fprintf(stderr, "Sensor 1 (0x%02X) not detected (ID=0x%02X, expected 0x%02X)\n",
                ADPD105_ADDR_1, id1, ADPD105_DEVICE_ID);
        cleanup();
        return 1;
    }

    int id2 = i2cReadByteData(i2c_handle2, ADPD105_REG_DEVICE_ID);
    if (id2 != ADPD105_DEVICE_ID) {
        fprintf(stderr, "Sensor 2 (0x%02X) not detected (ID=0x%02X, expected 0x%02X)\n",
                ADPD105_ADDR_2, id2, ADPD105_DEVICE_ID);
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
        fflush(log_file);
    }

    while (running) {
        float cct1 = 0.0f, cct2 = 0.0f;
        int ok1 = (read_cct(i2c_handle1, &cct1) == 0);
        int ok2 = (read_cct(i2c_handle2, &cct2) == 0);

        if (!ok1) {
            fprintf(stderr, "Error reading sensor 1 (0x%02X)\n", ADPD105_ADDR_1);
        }
        if (!ok2) {
            fprintf(stderr, "Error reading sensor 2 (0x%02X)\n", ADPD105_ADDR_2);
        }

        float avg_cct = (ok1 && ok2) ? (cct1 + cct2) / 2.0f : (ok1 ? cct1 : (ok2 ? cct2 : 0.0f));

        if (log_data(avg_cct) != 0) {
            fprintf(stderr, "Error writing to log file\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

