#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MLX90824_ADDR 0x60
#define PRESSURE_REG 0x0A2C
#define TEMPERATURE_REG 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define SAMPLE_INTERVAL_SEC 2
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0.0f
#define P_MAX_KPA 800.0f
#define T_MIN_C -40.0f
#define T_MAX_C 125.0f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void get_timestamp(char *buf, size_t len) {
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static int read_register16(int handle, uint16_t reg, uint16_t *out) {
    char cmd[2] = { (char)((reg >> 8) & 0xFF), (char)(reg & 0xFF) };
    char data[2] = {0, 0};
    int rc = i2cWriteDevice(handle, cmd, 2);
    if (rc < 0) return -1;
    rc = i2cReadDevice(handle, data, 2);
    if (rc < 0) return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static float convert_pressure(uint16_t raw) {
    return (float)(raw - OUTPUT_MIN) * (P_MAX_KPA - P_MIN_KPA) / (float)(OUTPUT_MAX - OUTPUT_MIN);
}

static float convert_temperature(uint16_t raw) {
    return (float)raw * 0.01f - 40.0f;
}

static void log_data(float pressure_kpa, float temperature_c) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.2f C\n", ts, pressure_kpa, temperature_c);
    fflush(log_file);
}

static void log_error(const char *msg) {
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(log_file, "%s, ERROR: %s\n", ts, msg);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90824_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n", I2C_BUS, MLX90824_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t raw_pressure = 0, raw_temperature = 0;
        int p_ok = read_register16(i2c_handle, PRESSURE_REG, &raw_pressure);
        int t_ok = read_register16(i2c_handle, TEMPERATURE_REG, &raw_temperature);

        if (p_ok == 0 && t_ok == 0) {
            float pressure_kpa = convert_pressure(raw_pressure);
            float temperature_c = convert_temperature(raw_temperature);
            log_data(pressure_kpa, temperature_c);
        } else {
            if (p_ok < 0) log_error("Failed to read pressure register");
            if (t_ok < 0) log_error("Failed to read temperature register");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return EXIT_SUCCESS;
}

