#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LM75B_ADDR     0x48
#define TEMP_REG       0x00
#define FAN_GPIO       18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   26.0f
#define SAMPLE_INTERVAL_US   1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Circular buffer ---- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ---- LM75B temperature read ---- */
static int read_temperature(int handle, float *temperature) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (reg 0x%02X): %d\n", TEMP_REG, raw);
        return -1;
    }

    /* pigpio returns the word as (msb << 8) | lsb; LM75B sends MSB first */
    uint16_t word = (uint16_t)((raw >> 8) & 0xFF) | ((uint16_t)(raw & 0xFF) << 8);

    /* 9-bit signed, 0.5 °C resolution: bits D9..D1 = temp, D0 = 0 */
    int16_t temp_raw = (int16_t)(word >> 7);          /* keep sign */
    temp_raw >>= 1;                                   /* D9..D1 -> D8..D0 */
    *temperature = (float)temp_raw * 0.5f;
    return 0;
}

/* ---- Fan control with hysteresis ---- */
static void control_fan(float avg_temp) {
    static int fan_on = 0;

    if (avg_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (avg %.2f °C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to set FAN_GPIO high\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (avg %.2f °C)\n", avg_temp);
        } else {
            fprintf(stderr, "Failed to set FAN_GPIO low\n");
        }
    }
}

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure fan GPIO */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set FAN_GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, LM75B_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    printf("LM75B fan controller started. Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            cb_add(&temp_buffer, temperature);
            float avg = cb_average(&temp_buffer);
            printf("Temp: %.2f °C | Avg: %.2f °C\n", temperature, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

