/*
 * STTS2004 temperature monitor with hysteresis LED control.
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - STTS2004 I2C temperature sensor (default slave address 0x4A)
 *   - LED on GPIO 17 (BCM), 330 ohm series resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o temp_monitor temp_monitor.c -lgpiod
 *
 * Run:
 *   ./temp_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define TEMP_REG       0x00
#define LED_GPIO       17
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define POLL_INTERVAL_SEC    1
#define MAX_CONSECUTIVE_ERRORS 10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit temperature register from the STTS2004.
 * Returns 0 on success and stores the temperature in *out_temp_c.
 * Returns -1 on I2C error.
 */
static int read_temperature(int fd, float *out_temp_c)
{
    uint8_t reg = TEMP_REG;
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Read 2 bytes of temperature data */
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed: expected 2 bytes, got %zd (%s)\n",
                n, n == -1 ? strerror(errno) : "short read");
        return -1;
    }

    /* Combine MSB and LSB, right-shift by 4 bits, convert to Celsius */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 4;
    *out_temp_c = (float)raw * 0.0625f;
    return 0;
}

int main(void)
{
    int fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) == -1) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Open the GPIO chip and get the LED line */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "stts2004-led", 0) == -1) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }

    printf("STTS2004 temperature monitor started. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (g_running) {
        float temperature;

        if (read_temperature(fd, &temperature) == 0) {
            consecutive_errors = 0;
            printf("Temperature: %.2f °C\n", temperature);

            int led_val = (temperature > TEMP_THRESHOLD_HIGH) ? 1 : 0;
            if (gpiod_line_set_value(led_line, led_val) == -1) {
                fprintf(stderr, "Failed to set LED GPIO %d: %s\n",
                        LED_GPIO, strerror(errno));
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Temperature read failed (%d consecutive)\n",
                    consecutive_errors);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive I2C errors. Exiting.\n");
                goto cleanup;
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure LED is off on exit */
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (fd != -1)
        close(fd);

    if (ret == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return ret;
}

