#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  60
#define MAX_RETRIES    3
#define MEASURE_DELAY_US 20000  /* 20 ms — Si7021 no-hold conversion time */

/* Si7021 commands (single-byte, no register address) */
#define CMD_MEASURE_RH_NO_HOLD   0xF5
#define CMD_MEASURE_TEMP_NO_HOLD 0xF3
#define CMD_READ_TEMP_PREV_RH    0xE0
#define CMD_READ_ID_1            0xFA
#define CMD_READ_ID_2            0x0F
#define CMD_RESET                0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers (single-byte command + 2-byte read)          */
/* ------------------------------------------------------------------ */
static int si7021_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    return i2cWriteDevice(handle, buf, 1);
}

static int si7021_read_bytes(int handle, char *buf, int len)
{
    return i2cReadDevice(handle, buf, len);
}

/*
 * Read a 16-bit raw value from the Si7021 after issuing a no-hold
 * measurement command.  Returns 0 on success, -1 on failure.
 */
static int si7021_read_raw(int handle, uint8_t cmd, uint16_t *raw)
{
    char buf[3];
    int rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = si7021_write_cmd(handle, cmd);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice(cmd 0x%02X) failed: %d\n",
                    attempt + 1, cmd, rc);
            gpioDelay(100000); /* 100 ms back-off */
            continue;
        }

        gpioDelay(MEASURE_DELAY_US);

        rc = si7021_read_bytes(handle, buf, 3);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cReadDevice after 0x%02X failed: %d\n",
                    attempt + 1, cmd, rc);
            gpioDelay(100000);
            continue;
        }
        if (rc != 3) {
            fprintf(stderr, "[attempt %d] short read after 0x%02X: got %d bytes\n",
                    attempt + 1, cmd, rc);
            gpioDelay(100000);
            continue;
        }

        /* buf[0..1] = data, buf[2] = CRC — discard CRC */
        *raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor presence check                                               */
/* ------------------------------------------------------------------ */
static int si7021_check_present(int handle)
{
    /*
     * Read the Si7021 firmware revision / ID register.
     * Command 0xFA 0x0F returns 8 bytes: [dev_id, 0, 0, 0, 0, 0, 0, 0].
     * A NACK or short read indicates the sensor is not present.
