    rc = i2cWriteDevice(handle, cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Sensor presence check: i2cWriteDevice failed: %d\n", rc);
        return -1;
    }

    gpioDelay(10000); /* 10 ms conversion time */

    rc = i2cReadDevice(handle, buf, 8);
    if (rc < 0) {
        fprintf(stderr, "Sensor presence check: i2cReadDevice failed: %d\n", rc);
        return -1;
    }
    if (rc != 8) {
        fprintf(stderr, "Sensor presence check: short read: %d bytes\n", rc);
        return -1;
    }

    /* buf[0] should be 0x15 for Si7021 (MSB of device ID). */
    if ((uint8_t)buf[0] != 0x15) {
        fprintf(stderr, "Sensor presence check: unexpected ID byte 0x%02X\n",
                (uint8_t)buf[0]);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversion formulas                                                 */
/* ------------------------------------------------------------------ */
static float raw_to_celsius(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temp_c, float rh)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    FILE *fp;

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp_c, rh);
    fflush(fp);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", ts, temp_c, rh);
}

static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    FILE *fp;

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed in log_error\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "%s,ERROR,%s\n", ts, msg);
        fflush(fp);
        fclose(fp);
    }

    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
