    while (g_running) {
        uint16_t raw_rh = 0, raw_temp = 0;
        int ok = 0;

        /* Read relative humidity (no-hold) */
        if (si7021_read_raw(g_i2c_handle, CMD_MEASURE_RH_NO_HOLD, &raw_rh) == 0) {
            /* Read temperature from the just-computed RH measurement */
            if (si7021_read_raw(g_i2c_handle, CMD_READ_TEMP_PREV_RH, &raw_temp) == 0) {
                ok = 1;
            } else {
                fprintf(stderr, "Failed to read temperature after RH measurement\n");
            }
        } else {
            fprintf(stderr, "Failed to read humidity\n");
        }

        if (ok) {
