#include <unistd.h>
#include <pigpio.h>

#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_CONFIG_REG 0x02
#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hdc1080(int handle, float *temperature, float *humidity) {
    unsigned char config[2];
    config[0] = 0x10; /* 14-bit temp, 14-bit humidity, no heater, single measurement */
    config[1] = 0x00;

    if (i2cWriteI2CBlockData(handle, HDC1080_CONFIG_REG, (char *)config, 2) < 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }

    gpioDelay(20000); /* 20 ms conversion time */

    unsigned char data[4];
    if (i2cReadI2CBlockData(handle, HDC1080_TEMP_REG, (char *)data, 4) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    unsigned int raw_temp = (data[0] << 8) | data[1];
    unsigned int raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_humidity / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (running) {
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

