#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define STS40_ADDR        0x44
#define I2C_BUS           "/dev/i2c-1"
#define LOG_FILE          "temperature_log.txt"
#define MEAS_CMD_MSB      0x2C
#define MEAS_CMD_LSB      0xE0
#define CONVERSION_MS     10
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC8: polynomial 0x31, init 0x00, no reflect */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                STS40_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_temperature(float *temperature)
{
    uint8_t cmd[2] = { MEAS_CMD_MSB, MEAS_CMD_LSB };
    ssize_t w = write(g_i2c_fd, cmd, sizeof(cmd));
    if (w != (ssize_t)sizeof(cmd)) {
        fprintf(stderr, "Error writing measurement command: %s\n",
                w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    usleep(CONVERSION_MS * 1000);

    uint8_t data[3];
    ssize_t r = read(g_i2c_fd, data, sizeof(data));
    if (r != (ssize_t)sizeof(data)) {
        fprintf(stderr, "Error reading temperature data: %s\n",
                r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temperature = -45.0f + (175.0f * (float)raw / 65535.0f);
    return 0;
}

static int log_temperature(float temperature)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("Greenhouse temperature monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Warning: failed to log temperature\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read temperature\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("Resources released. Goodbye.\n");
    return 0;
}

