        log_error("Failed to write command to I2C device");
        return -1;
    }
    return 0;
}

static int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t buf[9];
    if (i2cWriteDevice(i2c_handle, (char *)&CMD_READ_MEASUREMENT, 2) != 0) {
        log_error("Failed to write read measurement command");
