#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define WHO_AM_I_VAL 0x08
#define CALIB_START_REG 0x05
#define CALIB_BYTES 4
#define MEAS_CMD_REG 0x00
#define MEAS_CMD_VAL 0x00
#define DATA_REG 0x00
#define DATA_BYTES 6
#define SAMPLE_INTERVAL_US 5000000
#define MEAS_DELAY_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_calibration(int handle, uint16_t *c0, uint16_t *c1, uint16_t *c2, uint16_t *c3) {
    char buf[CALIB_BYTES];
    if (i2cReadI2CBlockData(handle, CALIB_START_REG, buf, CALIB_BYTES) != CALIB_BYTES) {
        fprintf(stderr, "Error: Failed to read calibration coefficients\n");
        return -1;
    }
    *c0 = (uint16_t)((buf[0] << 8) | buf[1]);
    *c1 = (uint16_t)((buf[2] << 8) | buf[3]);
    *c2 = (uint16_t)((buf[4] << 8) | buf[5]);
    *c3 = (uint16_t)((buf[6] << 8) | buf[7]);
    return 0;
}

static int read_sensor(int handle, uint16_t *c0, uint16_t *c1, uint16_t *c2, uint16_t *c3,
                       float *pressure, float *temperature) {
    char cmd = MEAS_CMD_VAL;
    if (i2cWriteI2CBlockData(handle, MEAS_CMD_REG, &cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(MEAS_DELAY_US);

    char data[DATA_BYTES];
    if (i2cReadI2CBlockData(handle, DATA_REG, data, DATA_BYTES) != DATA_BYTES) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        return -1;
    }

    uint32_t raw_p = ((uint32_t)(data[0] & 0x0F) << 16) | ((uint32_t)data[1] << 8) | (uint32_t)data[2];
    uint32_t raw_t = ((uint32_t)(data[3] & 0x0F) << 16) | ((uint32_t)data[4] << 8) | (uint32_t)data[5];

    float p_comp = (float)raw_p / 65536.0f;
    float t_comp = (float)raw_t / 65536.0f;

    *pressure = (*c0 + *c1 * p_comp + *c2 * t_comp + *c3 * p_comp * t_comp) / 100.0f;
    *temperature = t_comp * 100.0f;
    return 0;
}

static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ICP10110_ADDR);
        gpioTerminate();
        return 1;
    }

    int who = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n", who, WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t c0, c1, c2, c3;
    if (read_calibration(i2c_handle, &c0, &c1, &c2, &c3) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting data acquisition...\n");

    while (program_running) {
        float pressure, temperature;
        if (read_sensor(i2c_handle, &c0, &c1, &c2, &c3, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
            printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure, temperature);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting gracefully...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

