/*
 * Raspberry Pi 4 Model B — TDK ICP-10125 barometric pressure sensor reader
 * with libgpiod warning LED.
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO 2 (I2C1 SDA, pin 3)
 *   ICP-10125 SCL  -> GPIO 3 (I2C1 SCL, pin 5)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *   Warning LED    -> GPIO 17 (pin 11) through 330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10125 icp10125.c -lgpiod
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x63
#define LED_GPIO       17
#define POLL_MS        1000
#define WARN_ON_MS     100
#define WARN_OFF_MS    100
#define NORMAL_ON_MS   500
#define NORMAL_OFF_MS  500

/* ICP-10125 commands */
#define CMD_READ_OTP   0x66
#define CMD_MEASURE    0x4011  /* high-accuracy, 20 ms */

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- CRC-8 (polynomial 0x31, init 0x00) — InvenSense datasheet ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write16(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write16(0x%04X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_otp(int fd, uint16_t *c0, uint16_t *c1,
                    uint16_t *c2, uint16_t *c3)
{
    uint8_t cmd[2] = { (uint8_t)(CMD_READ_OTP >> 8), (uint8_t)(CMD_READ_OTP & 0xFF) };
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "OTP read: write command failed: %s\n", strerror(errno));
        return -1;
    }
    uint8_t data[18];
    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "OTP read: failed to read 18 bytes: %s\n", strerror(errno));
        return -1;
    }
    /* 9 words, 2 bytes each, CRC after each word */
    for (int i = 0; i < 9; i++) {
        uint8_t crc = crc8(&data[i * 3], 2);
        if (crc != data[i * 3 + 2]) {
            fprintf(stderr, "OTP CRC mismatch at word %d (calc 0x%02X got 0x%02X)\n",
                    i, crc, data[i * 3 + 2]);
            return -1;
        }
    }
    *c0 = (uint16_t)((data[0]  << 8) | data[1]);
    *c1 = (uint16_t)((data[3]  << 8) | data[4]);
    *c2 = (uint16_t)((data[6]  << 8) | data[7]);
    *c3 = (uint16_t)((data[9]  << 8) | data[10]);
    return 0;
}

static int read_measurement(int fd, uint16_t *raw_p, uint16_t *raw_t)
{
    if (i2c_write16(fd, CMD_MEASURE) < 0)
        return -1;

    struct timespec ts = { 0, 20 * 1000 * 1000 }; /* 20 ms */
    nanosleep(&ts, NULL);

    uint8_t buf[6];
    if (i2c_read_block(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* CRC over [pressure_hi, pressure_lo, crc], [temp_hi, temp_lo, crc] */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    *raw_p = (uint16_t)((buf[0] << 8) | buf[1]);
    *raw_t = (uint16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

static float convert_pressure(uint16_t raw_p, uint16_t c0, uint16_t c1,
                              uint16_t c2, uint16_t c3)
{
    /* 32-bit fixed-point arithmetic (Q16) */
    int32_t p = (int32_t)raw_p;
    int32_t c0s = (int32_t)c0;
    int32_t c1s = (int32_t)c1;
    int32_t c2s = (int32_t)c2;
    int32_t c3s = (int32_t)c3;

    int32_t p_sq = p * p;
    int32_t p_cb = p_sq * p;

    int32_t L = c0s * 65536;
    int32_t M = c1s * 256;
    int32_t N = c2s;
    int32_t D = c3s;

    int32_t p_comp = L + (M * p) + (N * p_sq) + (D * p_cb);
    if (p_comp < 0) p_comp = 0;
    return (float)p_comp / 65536.0f;
}

static float convert_temperature(uint16_t raw_t)
{
    return (float)raw_t / 65536.0f * 165.0f - 40.0f;
}

int main(void)
{
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length write to the OTP register */
    uint8_t probe[2] = { (uint8_t)(CMD_READ_OTP >> 8), (uint8_t)(CMD_READ_OTP & 0xFF) };
    if (write(fd, probe, 0) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X: %s\n",
                ICP10125_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    uint16_t c0, c1, c2, c3;
    if (read_otp(fd, &c0, &c1, &c2, &c3) < 0) {
        fprintf(stderr, "Failed to read OTP calibration data\n");
        close(fd);
        return EXIT_FAILURE;
    }
    printf("Calibration: c0=%u c1=%u c2=%u c3=%u\n", c0, c1, c2, c3);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Cannot open GPIO chip: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(led, "icp10125-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ICP-10125 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_p, raw_t;
        if (read_measurement(fd, &raw_p, &raw_t) < 0) {
            fprintf(stderr, "Read failed; retrying in %d ms\n", POLL_MS);
            struct timespec ts = { 0, POLL_MS * 1000 * 1000 };
            nanosleep(&ts, NULL);
            continue;
        }

        float pressure = convert_pressure(raw_p, c0, c1, c2, c3);
        float temperature = convert_temperature(raw_t);

        printf("Pressure: %.2f Pa  Temperature: %.2f C\n",
               pressure, temperature);

        if (pressure < 95000.0f) {
            /* Warning: high altitude */
            gpiod_line_set_value(led, 1);
            struct timespec on  = { 0, WARN_ON_MS  * 1000 * 1000 };
            struct timespec off = { 0, WARN_OFF_MS * 1000 * 1000 };
            nanosleep(&on, NULL);
            gpiod_line_set_value(led, 0);
            nanosleep(&off, NULL);
        } else {
            /* Normal: blink at 1 Hz */
            gpiod_line_set_value(led, 1);
            struct timespec on  = { 0, NORMAL_ON_MS  * 1000 * 1000 };
            struct timespec off = { 0, NORMAL_OFF_MS * 1000 * 1000 };
            nanosleep(&on, NULL);
            gpiod_line_set_value(led, 0);
            nanosleep(&off, NULL);
        }
    }

    /* Cleanup */
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

