#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS        1
#define MLX90614_ADDR  0x5A
#define FAN_GPIO       18
#define AMBIENT_REG    0x06
#define OBJECT_REG     0x07
#define TEMP_THRESHOLD_HIGH  30.0f
#define TEMP_THRESHOLD_LOW   28.0f
#define LOG_FILE       "temperature_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000
#define SAMPLE_INTERVAL_S 2

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, uint8_t reg, float *temp_c) {
    int raw = i2cReadWordData(handle, reg);
    if (raw < 0) {
        fprintf(stderr, "I2C read failed for reg 0x%02X: %d\n", reg, raw);
        return -1;
    }
    int16_t raw16 = (int16_t)raw;
    *temp_c = (float)raw16 * 0.02f - 273.15f;
    return 0;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, object);
    }
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    int fan_on = 0;

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_temperature(i2c_handle, AMBIENT_REG, &ambient) == 0 &&
                read_temperature(i2c_handle, OBJECT_REG, &object) == 0) {
                ok = 1;
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (!ok) {
            fprintf(stderr, "Failed to read temperatures after %d attempts\n", MAX_RETRIES);
        } else {
            log_temperature(ambient, object);

            if (object > TEMP_THRESHOLD_HIGH && !fan_on) {
                if (gpioWrite(FAN_GPIO, 1) == 0) {
                    fan_on = 1;
                    printf("Fan ON (Object: %.2f C)\n", object);
                } else {
                    fprintf(stderr, "gpioWrite ON failed\n");
                }
            } else if (object < TEMP_THRESHOLD_LOW && fan_on) {
                if (gpioWrite(FAN_GPIO, 0) == 0) {
                    fan_on = 0;
                    printf("Fan OFF (Object: %.2f C)\n", object);
                } else {
                    fprintf(stderr, "gpioWrite OFF failed\n");
                }
            }
        }

        if (running) {
            gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
        }
    }

    gpioWrite(FAN_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

