#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define SHT40_CMD_HIGH_REP 0xFD
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_sht40(int handle, float *temperature, float *humidity) {
    char cmd = SHT40_CMD_HIGH_REP;
    char buf[6];
    int result;

    for (int i = 0; i < MAX_RETRIES; i++) {
        result = i2cWriteDevice(handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        result = i2cReadDevice(handle, buf, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read error (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(100000);
            continue;
        }

        unsigned int raw_temp = ((unsigned char)buf[0] << 8) | (unsigned char)buf[1];
        unsigned int raw_hum = ((unsigned char)buf[3] << 8) | (unsigned char)buf[4];

        *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
        *humidity = -6.0f + 125.0f * (float)raw_hum / 65535.0f;

        if (*humidity < 0.0f) *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    return -1;
}

void handle_client(int client_socket) {
    float temperature, humidity;
    char response[512];

    if (read_sht40(i2c_handle, &temperature, &humidity) != 0) {
        const char *error_msg = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\nSensor read failed.";
        send(client_socket, error_msg, strlen(error_msg), 0);
        close(client_socket);
        return;
    }

    snprintf(response, sizeof(response),
             "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n"
             "<html><head><title>SHT40 Sensor Data</title></head>"
             "<body><h1>SHT40 Sensor Data</h1>"
             "<p>Temperature: %.2f &deg;C</p>"
             "<p>Humidity: %.2f %%</p>"
             "</body></html>",
             temperature, humidity);

    send(client_socket, response, strlen(response), 0);
    close(client_socket);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n", SHT40_ADDR, strerror(errno));
        gpioTerminate();
