int read_sht40(int handle, float *temperature, float *humidity) {
    char cmd = SHT40_CMD_HIGH_REP;
    char buf[6];
    int result;

    for (int i = 0; i < MAX_RETRIES; i++) {
        result = i2cWriteDevice(handle, &cmd, 1);
        if (result != 0) {
            fprintf(stderr, "I2C write error (attempt %d): %s\n", i + 1, strerror(errno));
            gpioDelay(100000);
