#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <pigpio.h>

#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(int handle, float *temperature) {
    int raw = i2cReadWordData(handle, TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %s\n", strerror(errno));
        return -1;
    }

    /* TMP102 returns data left-justified in two bytes; shift right by 4 */
    int16_t shifted = (int16_t)(raw >> 4);
    /* Sign-extend 12-bit value to 16-bit */
    if (shifted & 0x0800) {
        shifted |= 0xF000;
    }
    *temperature = shifted * 0.0625f;
    return 0;
}

static int log_temperature(const char *filename, float temperature) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n",
                TMP102_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n", strerror(errno));
    }

    printf("Smart Greenhouse Climate Monitoring System\n");
    printf("TMP102 at I2C bus %d, address 0x%02X. Logging to %s every %d s.\n",
           I2C_BUS, TMP102_ADDR, LOG_FILE, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(handle, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            if (log_temperature(LOG_FILE, temperature) != 0) {
                fprintf(stderr, "Failed to log temperature reading.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping log entry.\n");
        }

        /* Sleep in 1-second increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    printf("\nShutting down...\n");
    if (i2cClose(handle) != 0) {
        fprintf(stderr, "Warning: error closing I2C handle: %s\n", strerror(errno));
    }
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

