#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HDC2010_ADDR        0x40
#define REG_TEMP_LOW        0x00
#define REG_TEMP_HIGH       0x01
#define REG_HUMID_LOW       0x02
#define REG_HUMID_HIGH      0x03
#define REG_MEAS_CFG        0x0E
#define REG_CONFIG          0x0F

#define MEAS_CFG_TRIGGER    0x01
#define CONFIG_HEATER_OFF   0x00
#define MEAS_CFG_READY      0x00

#define POLL_TIMEOUT_MS     500
#define POLL_INTERVAL_US    1000
#define MAX_RETRIES         3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(g_i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *out) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_low + 1, &hi) < 0) return -1;
    *out = ((uint16_t)hi << 8) | lo;
    return 0;
}

static int wait_measurement_ready(void) {
    uint8_t cfg;
    int elapsed = 0;
    while (elapsed < POLL_TIMEOUT_MS) {
        if (read_reg(REG_MEAS_CFG, &cfg) < 0) return -1;
        if ((cfg & 0x01) == MEAS_CFG_READY) return 0;
        gpioDelay(POLL_INTERVAL_US);
        elapsed += POLL_INTERVAL_US / 1000;
    }
    fprintf(stderr, "Measurement timeout after %d ms\n", POLL_TIMEOUT_MS);
    return -1;
}

static int read_hdc2010(float *temperature, float *humidity) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write_reg(REG_MEAS_CFG, MEAS_CFG_TRIGGER) < 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }
        if (wait_measurement_ready() < 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }
        uint16_t raw_temp, raw_hum;
        if (read_word(REG_TEMP_LOW, &raw_temp) < 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }
        if (read_word(REG_HUMID_LOW, &raw_hum) < 0) {
            retries++;
            gpioDelay(100000);
            continue;
        }
        *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
        *humidity    = ((float)raw_hum  / 65536.0f) * 100.0f;
        return 0;
    }
    fprintf(stderr, "Failed to read HDC2010 after %d retries\n", MAX_RETRIES);
    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_reg(REG_CONFIG, CONFIG_HEATER_OFF) < 0) {
        fprintf(stderr, "Warning: could not set CONFIG register\n");
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        float temperature, humidity;
        if (read_hdc2010(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        for (int i = 0; i < 5 && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

