        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X (pigpio error %d).\n",
                I2C_BUS, SDP800_ADDR, handle);
        goto cleanup_gpio;
    }

    printf("SDP800-500Pa sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t pressure = 0, temperature = 0;

        if (read_sdp800(handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d Pa, Temperature: %d C\n", pressure, temperature);
