    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup_handle:
    if (handle >= 0) {
        i2cClose(handle);
    }
cleanup_gpio:
    gpioTerminate();
    return ret;
}

