#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SPI_SPEED_HZ 4000000
#define SPI_BITS 8
#define SPI_DELAY_US 0
#define SAMPLE_INTERVAL_US 1000000
#define MAX_PROFILE_POINTS 100

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_fp = NULL;

typedef struct {
    float temperature;
    time_t timestamp;
} TemperatureData;

typedef struct {
    float temperature;
    time_t timestamp;
    int valid;
} SensorData;

typedef struct {
    float kp, ki, kd;
    float integral, previous_error;
} PIDController;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open spidev");
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) { perror("SPI_IOC_WR_MODE"); close(spi_fd); spi_fd=-1; return -1; }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) { perror("SPI_IOC_WR_BITS_PER_WORD"); close(spi_fd); spi_fd=-1; return -1; }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) { perror("SPI_IOC_WR_MAX_SPEED_HZ"); close(spi_fd); spi_fd=-1; return -1; }
    return 0;
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) { perror("gpiod_chip_open_by_name"); return -1; }
    relay_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!relay_line) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); chip=NULL; return -1; }
    if (gpiod_line_request_output(relay_line, "reflow_oven", 0) < 0) { perror("gpiod_line_request_output"); gpiod_chip_close(chip); chip=NULL; relay_line=NULL; return -1; }
    return 0;
}

static int read_max6675(float *temperature) {
    uint8_t tx[2] = {0, 0};
    uint8_t rx[2] = {0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }
    uint16_t raw = ((uint16_t)rx[0] << 8) | rx[1];
    if (raw & 0x0004) {
        fprintf(stderr, "MAX6675 open-circuit fault\n");
        return -1;
    }
    if (raw & 0x0002) {
        fprintf(stderr, "MAX6675 short to GND fault\n");
        return -1;
    }
    uint16_t temp_raw = raw & 0x0FFF;
    *temperature = temp_raw * 0.25f;
    return 0;
}

static int read_profile(float *temperature, time_t *timestamp) {
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) { perror("fopen profile"); return -1; }
    static float temps[MAX_PROFILE_POINTS];
    static time_t times[MAX_PROFILE_POINTS];
    static int count = 0;
    if (count == 0) {
        char line[256];
        while (fgets(line, sizeof(line), fp) && count < MAX_PROFILE_POINTS) {
            if (sscanf(line, "%ld,%f", &times[count], &temps[count]) == 2) count++;
        }
        if (count == 0) { fprintf(stderr, "Profile file empty\n"); fclose(fp); return -1; }
    }
    fclose(fp);
    time_t now = time(NULL);
    for (int i = 0; i < count; i++) {
        if (now >= times[i]) {
            *temperature = temps[i];
            *timestamp = times[i];
            return 0;
        }
    }
    fprintf(stderr, "Profile ended at %ld\n", times[count-1]);
    return -1;
}

static float pid_calculate(PIDController *pid, float setpoint, float actual) {
    float error = setpoint - actual;
    pid->integral += error;
    if (pid->integral > 100.0f) pid->integral = 100.0f;
    if (pid->integral < -100.0f) pid->integral = -100.0f;
    float derivative = error - pid->previous_error;
    float output = pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
    pid->previous_error = error;
    if (output < 0.0f) output = 0.0f;
    if (output > 1.0f) output = 1.0f;
    return output;
}

static int log_data(float temperature, float duty_cycle) {
    if (!log_fp) {
        log_fp = fopen(LOG_FILE, "a");
        if (!log_fp) { perror("fopen log"); return -1; }
        fprintf(log_fp, "timestamp,temperature_celsius,duty_cycle\n");
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fp, "%s,%.2f,%.2f\n", ts, temperature, duty_cycle);
    fflush(log_fp);
    return 0;
}

static void cleanup(void) {
    if (relay_line) { gpiod_line_set_value(relay_line, 0); gpiod_line_release(relay_line); relay_line=NULL; }
    if (chip) { gpiod_chip_close(chip); chip=NULL; }
    if (spi_fd >= 0) { close(spi_fd); spi_fd=-1; }
    if (log_fp) { fclose(log_fp); log_fp=NULL; }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) { perror("sigaction"); return 1; }
    if (sigaction(SIGTERM, &sa, NULL) < 0) { perror("sigaction"); return 1; }
    if (spi_init() < 0) { cleanup(); return 1; }
    if (gpio_init() < 0) { cleanup(); return 1; }
    PIDController pid = {1.0f, 0.1f, 0.01f, 0.0f, 0.0f};
    float temperature = 0.0f;
    time_t timestamp = 0;
    float setpoint = 0.0f;
    while (running) {
        SensorData sensor = {0, 0, 0};
        if (read_max6675(&temperature) < 0) {
            fprintf(stderr, "SPI read error\n");
        } else {
            sensor.temperature = temperature;
            sensor.timestamp = time(NULL);
            sensor.valid = 1;
        }
        if (read_profile(&setpoint, &timestamp) < 0) {
            fprintf(stderr, "Profile read error\n");
        }
        float duty = pid_calculate(&pid, setpoint, sensor.valid ? sensor.temperature : 0.0f);
        if (gpiod_line_set_value(relay_line, duty > 0.5f ? 1 : 0) < 0) {
            perror("gpiod_line_set_value");
        }
        if (log_data(sensor.valid ? sensor.temperature : 0.0f, duty) < 0) {
            fprintf(stderr, "Log write error\n");
        }
        usleep(SAMPLE_INTERVAL_US);
    }
    cleanup();
    return 0;
}

