static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *pwm_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *sensor_id, float *temperature) {
    char path[256];
    snprintf(path, sizeof(path), "%s/%s/%s", W1_DEVICES_DIR, sensor_id, W1_TEMP_FILE);

    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char buf[256];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    close(fd);
    if (n < 0) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        return -1;
    }
    buf[n] = '\0';

    if (strstr(buf, "YES") == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1;
    }

    char *t_str = strstr(buf, "t=");
    if (t_str == NULL) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return -1;
    }

    long temp_raw = strtol(t_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0f;
    return 0;
}

static float calculate_pid(float setpoint, float actual, PIDGains *gains, float *integral, float *prev_error) {
    float error = setpoint - actual;
    *integral += error;
    float derivative = error - *prev_error;
    float output = gains->Kp * error + gains->Ki * (*integral) + gains->Kd * derivative;
    *prev_error = error;
    return output;
}

static int set_pwm_duty_cycle(int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    long long on_ns = (long long)duty_percent * PWM_PERIOD_NS / 100;
    long long off_ns = PWM_PERIOD_NS - on_ns;

    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        fprintf(stderr, "Failed to set PWM line high: %s\n", strerror(errno));
        return -1;
    }
    usleep(on_ns / 1000);
    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        fprintf(stderr, "Failed to set PWM line low: %s\n", strerror(errno));
        return -1;
    }
    usleep(off_ns / 1000);
    return 0;
}

static void log_data(float avg_temp, float setpoint, float pid_output, int pwm_duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, avg_temp, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (pwm_line) {
        gpiod_line_set_value(pwm_line, 0);
        gpiod_line_release(pwm_line);
        pwm_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    float setpoint = atof(argv[1]);
    float Kp = atof(argv[2]);
    float Ki = atof(argv[3]);
    float Kd = 0.0f;

    if (setpoint < 0.0f || Kp < 0.0f || Ki < 0.0f) {
