            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float avg_temp = temp_sum / valid_readings;
        float pid_output = calculate_pid(setpoint, avg_temp, &gains, &integral, &prev_error);
        int pwm_duty = (int)(pid_output * 100.0f);
        if (pwm_duty < 0) pwm_duty = 0;
        if (pwm_duty > 100) pwm_duty = 100;

