        printf("Avg: %.2f, Setpoint: %.2f, PID: %.2f, PWM: %d%%\n", avg_temp, setpoint, pid_output, pwm_duty);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    printf("Greenhouse controller stopped.\n");
    return 0;
