#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x38
#define GPIO_CHIP       "gpiochip4"
#define DEHUMIDIFIER_PIN 17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL   5
#define I2C_RETRIES     3
#define I2C_RETRY_DELAY 10000  /* microseconds */
#define MEASURE_DELAY   80000  /* microseconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (write(fd, buf, len) == (ssize_t)len)
            return 0;
        if (errno == EREMOTEIO || errno == EIO) {
            fprintf(stderr, "I2C write error (attempt %d/%d): %s\n",
                    attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY);
            continue;
        }
        return -1;
    }
    return -1;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        if (read(fd, buf, len) == (ssize_t)len)
            return 0;
        if (errno == EREMOTEIO || errno == EIO) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                    attempt + 1, I2C_RETRIES, strerror(errno));
            usleep(I2C_RETRY_DELAY);
            continue;
        }
        return -1;
    }
    return -1;
}

static int aht20_init(int fd) {
    uint8_t cmd[3] = {0xBE, 0x08, 0x00};
    if (i2c_write(fd, cmd, sizeof(cmd)) != 0) {
        fprintf(stderr, "AHT20 init write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);  /* 100 ms */
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t cmd[3] = {0xAC, 0x33, 0x00};
    uint8_t data[6];

    if (i2c_write(fd, cmd, sizeof(cmd)) != 0) {
        fprintf(stderr, "AHT20 trigger write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(MEASURE_DELAY);

    if (i2c_read(fd, data, sizeof(data)) != 0) {
        fprintf(stderr, "AHT20 data read failed: %s\n", strerror(errno));
        return -1;
    }

    if ((data[0] & 0x80) != 0) {
        fprintf(stderr, "AHT20 busy: status=0x%02X\n", data[0]);
        return -1;
    }
    if ((data[0] & 0x68) != 0x08) {
        fprintf(stderr, "AHT20 not calibrated: status=0x%02X\n", data[0]);
        return -1;
    }

    uint32_t raw = ((uint32_t)data[1] << 12) |
                   ((uint32_t)data[2] << 4)  |
                   ((uint32_t)data[3] >> 4);
    *humidity = ((float)raw / 1048576.0f) * 100.0f;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *relay_line = NULL;
    int i2c_fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    relay_line = gpiod_chip_get_line(chip, DEHUMIDIFIER_PIN);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        goto cleanup_chip;
    }

    if (gpiod_line_request_output(relay_line, "dehumidifier", 0) != 0) {
        perror("gpiod_line_request_output");
        goto cleanup_chip;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        goto cleanup_gpio;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup_i2c;
    }

    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "AHT20 initialization failed; sensor may be absent.\n");
        goto cleanup_i2c;
    }

    printf("AHT20 initialized. Monitoring humidity (high=%.1f%%, low=%.1f%%)...\n",
           HUMIDITY_HIGH, HUMIDITY_LOW);

    while (running) {
        float humidity = 0.0f;
        if (aht20_read_humidity(i2c_fd, &humidity) == 0) {
            time_t now = time(NULL);
            struct tm *tm_info = localtime(&now);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("[%s] Humidity: %.2f%%\n", ts, humidity);

            if (humidity > HUMIDITY_HIGH) {
                if (gpiod_line_set_value(relay_line, 1) != 0)
                    perror("gpiod_line_set_value (on)");
                else
                    printf("Dehumidifier ON\n");
            } else if (humidity < HUMIDITY_LOW) {
                if (gpiod_line_set_value(relay_line, 0) != 0)
                    perror("gpiod_line_set_value (off)");
                else
                    printf("Dehumidifier OFF\n");
            }
        } else {
            fprintf(stderr, "Failed to read humidity after retries.\n");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    gpiod_line_set_value(relay_line, 0);
    ret = EXIT_SUCCESS;

cleanup_i2c:
    if (i2c_fd >= 0)
        close(i2c_fd);
cleanup_gpio:
    if (relay_line)
        gpiod_line_release(relay_line);
cleanup_chip:
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

