#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_CMD_MEASURE_RH 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define API_HOST "api.example.com"
#define API_PORT 80
#define SLEEP_INTERVAL 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, int len) {
    int total = 0;
    while (total < len) {
        int n = read(fd, buf + total, len - total);
        if (n <= 0) {
            syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    if (i2c_write(fd, HTU21D_CMD_MEASURE_RH) < 0) {
        return -1;
    }
    usleep(10000);

    uint8_t buf[3];
    if (i2c_read(fd, buf, 3) < 0) {
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "CRC mismatch on humidity data");
        return -1;
    }

    uint16_t raw = (buf[0] << 8) | buf[1];
    raw &= 0xFFFC;
    *humidity = -6.0f + 125.0f * (float)raw / 65536.0f;
    return 0;
}

static int post_data(const char *url, float humidity) {
    struct addrinfo hints, *res, *p;
    int sockfd = -1;
    int ret = -1;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(API_HOST, "80", &hints, &res) != 0) {
        syslog(LOG_ERR, "getaddrinfo failed");
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        sockfd = socket(p->ai_family, p->ai_socktype, p->ai_protocol);
        if (sockfd < 0) continue;
        if (connect(sockfd, p->ai_addr, p->ai_addrlen) == 0) break;
        close(sockfd);
        sockfd = -1;
    }

    freeaddrinfo(res);

    if (sockfd < 0) {
        syslog(LOG_ERR, "Failed to connect to API: %s", strerror(errno));
        return -1;
    }

    char json[128];
    snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);

    char request[512];
    snprintf(request, sizeof(request),
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %zu\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             url, API_HOST, strlen(json), json);

    if (write(sockfd, request, strlen(request)) < 0) {
        syslog(LOG_ERR, "Failed to send HTTP request: %s", strerror(errno));
        goto cleanup;
    }

    char response[1024];
    ssize_t n = read(sockfd, response, sizeof(response) - 1);
    if (n > 0) {
        response[n] = '\0';
        syslog(LOG_INFO, "HTTP response: %s", response);
    } else {
        syslog(LOG_ERR, "Failed to read HTTP response: %s", strerror(errno));
        goto cleanup;
    }

    ret = 0;

cleanup:
    close(sockfd);
    return ret;
}

int main(void) {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", I2C_DEVICE, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address 0x%02X: %s", HTU21D_ADDR, strerror(errno));
        close(fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Humidity monitor started");

    while (running) {
        float humidity;
        if (read_humidity(fd, &humidity) == 0) {
            syslog(LOG_INFO, "Humidity: %.2f%%", humidity);
            if (post_data("/humidity", humidity) != 0) {
                syslog(LOG_ERR, "Failed to post data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        for (int i = 0; i < SLEEP_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    close(fd);
    closelog();
    return 0;
}

