    msleep(20);
    cmd[0] = AHT20_INIT_CMD; cmd[1] = 0x08; cmd[2] = 0x00;
    if (i2c_write(fd, cmd, 3) < 0) return -1;
    msleep(10);
    return 0;
}

static int aht20_read(int fd, float *temp, float *hum) {
    uint8_t cmd[3] = { AHT20_MEAS_CMD, 0x33, 0x00 };
    if (i2c_write(fd, cmd, 3) < 0) return -1;

    uint8_t data[7];
    for (int attempt = 0; attempt < 10; attempt++) {
        if (i2c_read(fd, data, 7) == 0) break;
        msleep(10);
        if (attempt == 9) return -1;
    }

    if (data[0] & 0x80) {
        fprintf(stderr, "AHT20 busy, retrying...\n");
        return -1;
    }

    uint32_t raw_h = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    uint32_t raw_t = ((uint32_t)(data[3] & 0x0F) << 16) | ((uint32_t)data[4] << 8) | data[5];

    *hum = ((float)raw_h / 1048576.0f) * 100.0f;
    *temp = ((float)raw_t / 1048576.0f) * 200.0f - 50.0f;
    return 0;
}

static int tmp117_read(int fd, float *temp) {
    uint8_t reg = TMP117_TEMP_REG;
    if (i2c_write(fd, &reg, 1) < 0) return -1;
    uint8_t data[2];
    if (i2c_read(fd, data, 2) < 0) return -1;
    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp = raw * 0.0078125f;
    return 0;
}

static int log_data(const char *filename, float temp, float hum, int motion) {
    FILE *fp = fopen(filename, "a");
    if (!fp) { perror("fopen"); return -1; }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) { perror("gpiod_chip_open"); return 1; }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) { perror("gpiod_chip_get_line"); gpiod_chip_close(chip); return 1; }
    if (gpiod_line_request_input(pir, "pir_logger") < 0) {
        perror("gpiod_line_request_input"); gpiod_chip_close(chip); return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("open i2c"); gpiod_chip_close(chip); return 1; }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("ioctl TMP117"); close(i2c_fd); gpiod_chip_close(chip); return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("ioctl AHT20"); close(i2c_fd); gpiod_chip_close(chip); return 1;
    }

    if (aht20_init(i2c_fd) < 0) {
        fprintf(stderr, "Warning: AHT20 init failed, logging without humidity.\n");
    }

    time_t last_midnight = time(NULL);
    struct tm tm;
    localtime_r(&last_midnight, &tm);
    char filename[64];
    strftime(filename, sizeof(filename), "log_%Y-%m-%d.csv", &tm);

    while (running) {
        time_t now = time(NULL);
        localtime_r(&now, &tm);
        if (now - last_midnight >= 86400) {
            strftime(filename, sizeof(filename), "log_%Y-%m-%d.csv", &tm);
            last_midnight = now;
        }

        float temp = 0.0f, hum = 0.0f;
        int motion = gpiod_line_get_value(pir);
        int tmp_ok = (tmp117_read(i2c_fd, &temp) == 0);
        int hum_ok = (aht20_read(i2c_fd, &temp, &hum) == 0);

        if (tmp_ok && hum_ok) {
            log_data(filename, temp, hum, motion);
        } else if (tmp_ok) {
            log_data(filename, temp, -1.0f, motion);
        } else {
            fprintf(stderr, "Sensor read error, skipping log.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    gpiod_line_release(pir);
    gpiod_chip_close(chip);
    close(i2c_fd);
    return 0;
}

