#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENABLE_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_TIME_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int set_motor_direction(struct gpiod_line *in1, struct gpiod_line *in2, int forward) {
    int ret;
    ret = gpiod_line_set_value(in1, forward ? 1 : 0);
    if (ret < 0) {
        log_event("Error setting IN1 direction");
        return -1;
    }
    ret = gpiod_line_set_value(in2, forward ? 0 : 1);
    if (ret < 0) {
        log_event("Error setting IN2 direction");
        return -1;
    }
    return 0;
}

static int close_window(struct gpiod_line *ena, struct gpiod_line *in1, struct gpiod_line *in2) {
    log_event("Closing window...");

    if (set_motor_direction(in1, in2, 1) < 0) {
        return -1;
    }

    if (gpiod_line_set_value(ena, 1) < 0) {
        log_event("Error enabling motor");
        return -1;
    }

    for (int i = 0; i < MOTOR_RUN_TIME_SEC && program_running; i++) {
        sleep(1);
    }

    if (gpiod_line_set_value(ena, 0) < 0) {
        log_event("Error disabling motor");
        return -1;
    }

    log_event("Window closed.");
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line = gpiod_chip_get_line(chip, MOTOR_ENABLE_PIN);
    in1_line = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        perror("gpiod_line_request_input(rain)");
        goto cleanup;
    }

    if (gpiod_line_request_output(ena_line, "motor_enable", 0) < 0) {
        perror("gpiod_line_request_output(ena)");
        goto cleanup;
    }

    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        perror("gpiod_line_request_output(in1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        perror("gpiod_line_request_output(in2)");
        goto cleanup;
    }

    log_event("Program started.");

    while (program_running) {
        int rain_value = gpiod_line_get_value(rain_line);
        if (rain_value < 0) {
            perror("gpiod_line_get_value(rain)");
            break;
        }

        if (rain_value == 0) {
            log_event("Rain detected!");
            if (close_window(ena_line, in1_line, in2_line) < 0) {
                log_event("Error closing window.");
            }
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && program_running; i++) {
            sleep(1);
        }
    }

    log_event("Program exiting.");
    ret = EXIT_SUCCESS;

cleanup:
    if (ena_line) gpiod_line_set_value(ena_line, 0);
    if (in1_line) gpiod_line_set_value(in1_line, 0);
    if (in2_line) gpiod_line_set_value(in2_line, 0);
    if (rain_line) gpiod_line_release(rain_line);
    if (ena_line) gpiod_line_release(ena_line);
    if (in1_line) gpiod_line_release(in1_line);
    if (in2_line) gpiod_line_release(in2_line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

