#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define SAMPLE_INTERVAL_US 500000  /* 500 ms */
#define MAX_CPU_LOAD 100.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read /proc/stat and return the total jiffies across all CPUs. */
static unsigned long long read_cpu_jiffies(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return 0ULL;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    int n = fscanf(fp,
                   "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice);
    fclose(fp);

    if (n != 10)
        return 0ULL;

    return user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
}

static double calculate_cpu_load(unsigned long long *prev_jiffies, unsigned long long *prev_idle)
{
    unsigned long long cur_jiffies = read_cpu_jiffies();
    unsigned long long cur_idle   = 0ULL;

    FILE *fp = fopen("/proc/stat", "r");
    if (fp) {
        int n = fscanf(fp, "cpu  %*u %*u %*u %llu %*u %*u %*u %*u %*u %*u", &cur_idle);
        fclose(fp);
        if (n != 1)
            cur_idle = 0ULL;
    }

    if (*prev_jiffies == 0ULL && *prev_idle == 0ULL) {
        *prev_jiffies = cur_jiffies;
        *prev_idle    = cur_idle;
        return 0.0;
    }

    unsigned long long delta_jiffies = cur_jiffies - *prev_jiffies;
    unsigned long long delta_idle    = cur_idle    - *prev_idle;

    *prev_jiffies = cur_jiffies;
    *prev_idle    = cur_idle;

    if (delta_jiffies == 0ULL)
        return 0.0;

    double idle_fraction = (double)delta_idle / (double)delta_jiffies;
    double load = 100.0 * (1.0 - idle_fraction);

    if (load < 0.0)   load = 0.0;
    if (load > 100.0) load = 100.0;

    return load;
}

static void set_led_color(int r, int g, int b)
{
    /* Common-anode LED: 0 = full brightness, 255 = off. */
    gpioPWM(RED_PIN,   255 - r);
    gpioPWM(GREEN_PIN, 255 - g);
    gpioPWM(BLUE_PIN,  255 - b);
}

static void map_load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0)   load = 0.0;
    if (load > 100.0) load = 100.0;

    if (load < 50.0) {
        /* 0-50%: green to yellow */
        *r = (int)(load / 50.0 * 255.0);
        *g = 255;
        *b = 0;
    } else {
        /* 50-100%: yellow to red */
        *r = 255;
        *g = (int)((100.0 - load) / 50.0 * 255.0);
        *b = 0;
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Configure PWM on all three pins at 1 MHz, 50% duty cycle. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN, 1000000) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, 1000000) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, 1000000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(RED_PIN, 128) != 0 || gpioPWM(GREEN_PIN, 128) != 0 || gpioPWM(BLUE_PIN, 128) != 0) {
        fprintf(stderr, "Failed to initialise PWM duty cycles\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    unsigned long long prev_jiffies = 0ULL;
    unsigned long long prev_idle    = 0ULL;

    while (g_running) {
        double load = calculate_cpu_load(&prev_jiffies, &prev_idle);

        int r, g, b;
        map_load_to_color(load, &r, &g, &b);

        set_led_color(r, g, b);

        printf("CPU Load: %.2f%%  Color: R=%3d G=%3d B=%3d\n", load, r, g, b);
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Turn LED off (common-anode: full off = 255). */
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    gpioTerminate();
    return 0;
}

