    gpioPWM(BLUE_PIN,  255 - b);
}

static void map_load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0)   load = 0.0;
    if (load > 100.0) load = 100.0;

    if (load < 50.0) {
        /* 0-50%: green to yellow */
        *r = (int)(load / 50.0 * 255.0);
        *g = 255;
        *b = 0;
    } else {
        /* 50-100%: yellow to red */
        *r = 255;
        *g = (int)((100.0 - load) / 50.0 * 255.0);
        *b = 0;
    }
}

