{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Configure PWM on all three pins at 1 MHz, 50% duty cycle. */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_PIN, 1000000) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, 1000000) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, 1000000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(RED_PIN, 128) != 0 || gpioPWM(GREEN_PIN, 128) != 0 || gpioPWM(BLUE_PIN, 128) != 0) {
