    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    unsigned long long prev_jiffies = 0ULL;
    unsigned long long prev_idle    = 0ULL;

    while (g_running) {
        double load = calculate_cpu_load(&prev_jiffies, &prev_idle);

        int r, g, b;
        map_load_to_color(load, &r, &g, &b);

        set_led_color(r, g, b);

        printf("CPU Load: %.2f%%  Color: R=%3d G=%3d B=%3d\n", load, r, g, b);
        fflush(stdout);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Turn LED off (common-anode: full off = 255). */
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    gpioTerminate();
    return 0;
}

