#include <string.h>

#define FAN_GPIO        18
#define SPI_CHANNEL     0
#define SPI_SPEED       500000
#define SPI_FLAGS       0
#define BUFFER_SIZE     20
#define PWM_FREQ        1000
#define PWM_RANGE       255
#define SAMPLE_PERIOD   1.0

#define TEMP_THRESHOLD_LOW   25.0
#define TEMP_THRESHOLD_MED   40.0
#define TEMP_THRESHOLD_HIGH  60.0

#define FAULT_OPEN_CIRCUIT  0x01
#define FAULT_SHORT_GND     0x02
#define FAULT_SHORT_VCC     0x04
#define FAULT_DATA          0x08

typedef struct {
    time_t timestamp;
    float  temperature;
    int    pwm_duty;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int      buffer_index = 0;
static int      buffer_count = 0;
static int      spi_handle   = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(float temp, int duty) {
    LogEntry *e = &log_buffer[buffer_index];
    e->timestamp = time(NULL);
    e->temperature = temp;
    e->pwm_duty = duty;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("\n--- Log Buffer (%d entries) ---\n", buffer_count);
    int start = (buffer_count < BUFFER_SIZE) ? 0 : buffer_index;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm = localtime(&log_buffer[idx].timestamp);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
        printf("[%s] Temp: %.2f C, PWM: %d/%d\n",
               ts, log_buffer[idx].temperature, log_buffer[idx].pwm_duty, PWM_RANGE);
    }
    printf("--- End of Log Buffer ---\n\n");
}

static int read_max31855(float *temp_out) {
