#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define BMP180_CAL_DATA_LEN 22

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration_data(void) {
    uint8_t data[BMP180_CAL_DATA_LEN];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)data, BMP180_CAL_DATA_LEN) != BMP180_CAL_DATA_LEN) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }
    cal.ac1 = (int16_t)((data[0] << 8) | data[1]);
    cal.ac2 = (int16_t)((data[2] << 8) | data[3]);
    cal.ac3 = (int16_t)((data[4] << 8) | data[5]);
    cal.ac4 = (uint16_t)((data[6] << 8) | data[7]);
    cal.ac5 = (uint16_t)((data[8] << 8) | data[9]);
    cal.ac6 = (uint16_t)((data[10] << 8) | data[11]);
    cal.b1 = (int16_t)((data[12] << 8) | data[13]);
    cal.b2 = (int16_t)((data[14] << 8) | data[15]);
    cal.mb = (int16_t)((data[16] << 8) | data[17]);
    cal.mc = (int16_t)((data[18] << 8) | data[19]);
    cal.md = (int16_t)((data[20] << 8) | data[21]);
    if (cal.ac1 == 0 || cal.ac1 == 0xFFFF || cal.ac6 == 0 || cal.ac6 == 0xFFFF) {
        fprintf(stderr, "Invalid calibration data (sensor not present?)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    uint8_t cmd = 0x2E;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((data[0] << 8) | data[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    uint8_t cmd = 0x34 + (BMP180_OSS << 6);
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << BMP180_OSS));
    uint8_t data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }
    *up = ((int32_t)(data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    return x1 + x2;
}

static double calculate_temperature(int32_t ut) {
    int32_t b5 = compute_b5(ut);
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(int32_t up, int32_t ut) {
    int32_t b5 = compute_b5(ut);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

static void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(2, PI_INPUT);
    gpioSetPullUpDown(2, PI_PUD_UP);
    if (gpioSetISRFuncEx(2, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting ISR\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    printf("Press Ctrl+C to exit\n");
    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                double temperature = calculate_temperature(ut);
                double pressure = calculate_pressure(up, ut);
                log_data(temperature, pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }
        sleep(1);
    }
    printf("\nExiting...\n");
    gpioSetISRFuncEx(2, FALLING_EDGE, 0, NULL, NULL);
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

