        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, BME280_RESET_CMD) < 0) {
        fprintf(stderr, "Error resetting BME280: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    usleep(2000);

    uint8_t status;
    int retries = 10;
    do {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status, 1) < 0) {
            fprintf(stderr, "Error reading status: %s\n", strerror(errno));
            close(fd);
            return 1;
        }
        if (status & 0x01) usleep(2000);
    } while ((status & 0x01) && retries-- > 0);

    if (status & 0x01) {
        fprintf(stderr, "BME280 reset timeout\n");
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error writing CTRL_HUM: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) {
        fprintf(stderr, "Error writing CONFIG: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error writing CTRL_MEAS: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    bme280_calib_data cal;
    if (read_calibration_data(fd, &cal) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return 1;
    }

    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    }

    while (running) {
        float temp, hum, press;
        if (read_bme280_data(fd, &cal, &temp, &hum, &press) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temp, hum, press);
            fflush(fp);
            printf("%s,%.2f,%.2f,%.2f\n", timestamp, temp, hum, press);
        } else {
            fprintf(stderr, "Error reading BME280 data: %s\n", strerror(errno));
        }
        sleep(5);
    }

    fclose(fp);
    close(fd);
    return 0;
}

