#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <math.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_CAL_START 0xAA
#define BMP180_OSS 0
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 50

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static double pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_calibration_data(void) {
    int v;
    v = i2cReadWordData(i2c_handle, 0xAA); if (v < 0) return -1; ac1 = (int16_t)v;
    v = i2cReadWordData(i2c_handle, 0xAC); if (v < 0) return -1; ac2 = (int16_t)v;
    v = i2cReadWordData(i2c_handle, 0xAE); if (v < 0) return -1; ac3 = (int16_t)v;
    v = i2cReadWordData(i2c_handle, 0xB0); if (v < 0) return -1; ac4 = (uint16_t)v;
    v = i2cReadWordData(i2c_handle, 0xB2); if (v < 0) return -1; ac5 = (uint16_t)v;
    v = i2cReadWordData(i2c_handle, 0xB4); if (v < 0) return -1; ac6 = (uint16_t)v;
    v = i2cReadWordData(i2c_handle, 0xB6); if (v < 0) return -1; b1 = (int16_t)v;
    v = i2cReadWordData(i2c_handle, 0xB8); if (v < 0) return -1; b2 = (int16_t)v;
    v = i2cReadWordData(i2c_handle, 0xBA); if (v < 0) return -1; mb = (int16_t)v;
    v = i2cReadWordData(i2c_handle, 0xBC); if (v < 0) return -1; mc = (int16_t)v;
    v = i2cReadWordData(i2c_handle, 0xBE); if (v < 0) return -1; md = (int16_t)v;
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int v = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (v < 0) return -1;
    int v2 = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (v2 < 0) return -1;
    *ut = (v << 8) | v2;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(5000);
    int v = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    if (v < 0) return -1;
    int v2 = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 1);
    if (v2 < 0) return -1;
    int v3 = i2cReadByteData(i2c_handle, BMP180_REG_MSB + 2);
    if (v3 < 0) return -1;
    *up = ((v << 16) | (v2 << 8) | v3) >> (8 - BMP180_OSS);
    return 0;
}

static double calculate_pressure(int32_t ut, int32_t up) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p / 100.0;
}

static void timer_callback(void *userdata) {
    (void)userdata;
    int32_t ut, up;
    if (read_raw_temperature(&ut) < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    double pressure = calculate_pressure(ut, up);
    pressure_buffer[buffer_index] = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;

    double sum = 0.0;
    for (int i = 0; i < buffer_count; i++) sum += pressure_buffer[i];
    double avg = sum / buffer_count;

    if (buffer_count >= 2) {
        double diff = fabs(pressure - avg);
        if (diff > 5.0) {
            gpioWrite(ALERT_GPIO, 1);
            fprintf(stderr, "Alert: Pressure deviation %.2f hPa\n", diff);
        } else {
            gpioWrite(ALERT_GPIO, 0);
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data() < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        gpioDelay(100000);
    }

    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

