#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define PWM_FREQ 25000
#define PWM_RANGE 255
#define SLEEP_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("fopen temperature file");
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Failed to parse temperature\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli / 1000;
}

static int calculate_duty(int temp) {
    if (temp < 40) return 0;
    if (temp >= 70) return PWM_RANGE;
    return (int)(((float)(temp - 40) / 30.0f) * PWM_RANGE);
}

static int set_fan_speed(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(FAN_GPIO, duty) < 0) {
        fprintf(stderr, "gpioPWM failed\n");
        return -1;
    }
    return duty;
}

static void log_data(int temp, int duty) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    if (fprintf(log_fp, "%s, Temp: %d C, Duty: %d\n", ts, temp, duty) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
    }
    fflush(log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        gpioTerminate();
        return 1;
    }

    while (running) {
        int temp = read_cpu_temp();
        if (temp < 0) {
            fprintf(stderr, "Temperature read error, skipping cycle\n");
        } else {
            int duty = calculate_duty(temp);
            if (set_fan_speed(duty) < 0) {
                fprintf(stderr, "Fan speed set error\n");
            }
            log_data(temp, duty);
        }
        sleep(SLEEP_SEC);
    }

    gpioPWM(FAN_GPIO, 0);
    if (log_fp) fclose(log_fp);
    gpioTerminate();
    return 0;
}

