#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BMP280_ADDR_1  0x76
#define BMP280_ADDR_2  0x77
#define BMP280_CHIP_ID 0x58

#define BMP280_REG_CHIP_ID    0xD0
#define BMP280_REG_RESET      0xE0
#define BMP280_REG_STATUS     0xF3
#define BMP280_REG_CTRL_MEAS  0xF4
#define BMP280_REG_CONFIG     0xF5
#define BMP280_REG_PRESS_MSB  0xF7
#define BMP280_REG_TEMP_MSB   0xFA
#define BMP280_REG_CALIB      0x88

#define OVERSAMPLING_TEMP  1
#define OVERSAMPLING_PRESS 1
#define MODE_FORCED        0x01

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2c_read_reg(fd, BMP280_REG_CALIB, buf, sizeof(buf)) != 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    cal->dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    cal->dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    cal->dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    cal->dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int bmp280_init(int fd, bmp280_calib_t *cal) {
    uint8_t chip_id;
    if (i2c_read_reg(fd, BMP280_REG_CHIP_ID, &chip_id, 1) != 0) {
        fprintf(stderr, "Error: failed to read chip_id: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: chip_id mismatch (0x%02X, expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (bmp280_read_calibration(fd, cal) != 0) {
        fprintf(stderr, "Error: failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    /* config: t_sb=0.5ms(000), filter=off(000), spi3w_en=0 -> 0x00 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Error: failed to write config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t status;
    uint8_t data[6];
    uint8_t ctrl = (OVERSAMPLING_TEMP << 5) | (OVERSAMPLING_PRESS << 2) | MODE_FORCED;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, ctrl) != 0) return -1;
    for (int i = 0; i < 50; i++) {
        if (i2c_read_reg(fd, BMP280_REG_STATUS, &status, 1) != 0) return -1;
        if ((status & 0x08) == 0) break;
        usleep(2000);
        if (i == 49) {
            fprintf(stderr, "Error: measurement timeout\n");
            return -1;
        }
    }
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) != 0) return -1;
    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static double compensate_pressure(int32_t raw_p, int32_t t_fine, const bmp280_calib_t *cal) {
