#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define TEMP_REG       0x00
#define GPIO_CHIP      "gpiochip4"
#define LED_PIN        18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t running = 1;

static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer temp_buffer = {{0.0f}, 0, 0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_init(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LM75_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int i2c_read_temp(float *temp) {
    uint8_t reg = TEMP_REG;
    uint8_t data[2];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("I2C write reg");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("I2C read temp");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    raw >>= 5;
    *temp = (float)raw / 256.0f;
    return 0;
}

static int gpio_init(void) {
    if (chip) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
    }
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "lm75_monitor", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(led_line);
        led_line = NULL;
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    return 0;
}

static void buffer_add(float temp) {
    pthread_mutex_lock(&buffer_mutex);
    temp_buffer.buffer[temp_buffer.head] = temp;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) temp_buffer.count++;
    pthread_mutex_unlock(&buffer_mutex);
}

static float buffer_average(void) {
    pthread_mutex_lock(&buffer_mutex);
    float sum = 0.0f;
    for (int i = 0; i < temp_buffer.count; i++) sum += temp_buffer.buffer[i];
    float avg = (temp_buffer.count > 0) ? (sum / temp_buffer.count) : 0.0f;
    pthread_mutex_unlock(&buffer_mutex);
    return avg;
}

static void *data_acquisition_thread(void *arg) {
    (void)arg;
    while (running) {
        float temp;
        if (i2c_read_temp(&temp) == 0) {
            buffer_add(temp);
            float avg = buffer_average();
            printf("Temperature: %.2f C, Average: %.2f C\n", temp, avg);
            if (temp > TEMP_THRESHOLD) {
                gpiod_line_set_value(led_line, 1);
            } else {
                gpiod_line_set_value(led_line, 0);
            }
        } else {
            fprintf(stderr, "Error reading temperature. Re-initializing I2C.\n");
            if (i2c_init() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C.\n");
            }
        }
        sleep(POLL_INTERVAL);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (i2c_init() != 0) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        return 1;
    }

    if (gpio_init() != 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        close(i2c_fd);
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, data_acquisition_thread, NULL) != 0) {
        perror("pthread_create");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        sleep(1);
    }

    pthread_join(thread, NULL);
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer_mutex);
    printf("Program terminated gracefully.\n");
    return 0;
}

