        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, data_acquisition_thread, NULL) != 0) {
        perror("pthread_create");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        sleep(1);
    }

    pthread_join(thread, NULL);
    gpiod_line_set_value(led_line, 0);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer_mutex);
    printf("Program terminated gracefully.\n");
    return 0;
}

