#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define MAX_TEMP 80.0
#define SAMPLE_INTERVAL_US 100000
#define R_REF 430.0
#define R0 100.0
#define A 0.0039083
#define B 0.0000005775
#define MAX31865_CONFIG_REG 0x80
#define MAX31865_RTD_MSB 0x01
#define MAX31865_RTD_LSB 0x02
#define MAX31865_FAULT_REG 0x07

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static double target_temperature = 25.0;
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;
static double integral = 0.0;
static double previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    char tx[2] = {(char)(reg & 0x7F), (char)value};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    return 0;
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    char tx[2] = {(char)(reg | 0x80), 0x00};
    char rx[2] = {0, 0};
    if (spiXfer(spi_handle, tx, rx, 2) != 2) return -1;
    *value = (uint8_t)rx[1];
    return 0;
}

static int max31865_init(void) {
    if (spi_write_reg(MAX31865_CONFIG_REG, 0xC1) != 0) {
        fprintf(stderr, "Error: Failed to initialize MAX31865 (config write failed)\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_rtd_code(uint16_t *code) {
    uint8_t msb, lsb;
    if (spi_read_reg(MAX31865_RTD_MSB, &msb) != 0) return -1;
    if (spi_read_reg(MAX31865_RTD_LSB, &lsb) != 0) return -1;
    *code = ((uint16_t)(msb & 0x7F) << 8) | lsb;
    return 0;
}

static double rtd_to_resistance(uint16_t code) {
    double rtd_code = (double)code;
    double rtd_resistance = (rtd_code / 32768.0) * R_REF;
    return rtd_resistance;
}

static double resistance_to_temperature(double rtd_resistance) {
    double r = rtd_resistance;
    double a = A;
    double b = B;
    double discriminant = a * a - 4.0 * b * (1.0 - r / R0);
    if (discriminant < 0.0) return -999.0;
    double sqrt_disc = sqrt(discriminant);
    double t1 = (-a + sqrt_disc) / (2.0 * b);
    double t2 = (-a - sqrt_disc) / (2.0 * b);
    if (t1 >= 0.0) return t1;
    if (t2 >= 0.0) return t2;
    return -999.0;
}

static double pid_control(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 100.0) output = 100.0;
    return output;
}

static void set_heater_pwm(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0));
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    gpioPWM(HEATER_GPIO, pwm_value);
}

static void cleanup(void) {
    gpioPWM(HEATER_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

static int load_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s'. Using defaults.\n", filename);
        return -1;
    }
    char buffer[4096];
    size_t n = fread(buffer, 1, sizeof(buffer) - 1, fp);
    fclose(fp);
    if (n == 0) {
        fprintf(stderr, "Warning: Config file empty. Using defaults.\n");
        return -1;
    }
    buffer[n] = '\0';
    cJSON *root = cJSON_Parse(buffer);
    if (!root) {
        fprintf(stderr, "Warning: Could not parse JSON. Using defaults.\n");
        return -1;
    }
    cJSON *t = cJSON_GetObjectItemCaseSensitive(root, "target_temperature");
    if (cJSON_IsNumber(t)) target_temperature = t->valuedouble;
    cJSON *kp = cJSON_GetObjectItemCaseSensitive(root, "Kp");
    if (cJSON_IsNumber(kp)) Kp = kp->valuedouble;
    cJSON *ki = cJSON_GetObjectItemCaseSensitive(root, "Ki");
    if (cJSON_IsNumber(ki)) Ki = ki->valuedouble;
    cJSON *kd = cJSON_GetObjectItemCaseSensitive(root, "Kd");
    if (cJSON_IsNumber(kd)) Kd = kd->valuedouble;
    cJSON_Delete(root);
    printf("Config loaded: target=%.2f Kp=%.4f Ki=%.4f Kd=%.4f\n", target_temperature, Kp, Ki, Kd);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }
    if (max31865_init() != 0) {
        fprintf(stderr, "Error: MAX31865 initialisation failed\n");
        cleanup();
        return 1;
    }
    load_config("config.json");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting PID control loop. Target: %.2f C\n", target_temperature);

    while (running) {
        uint16_t rtd_code;
        if (read_rtd_code(&rtd_code) != 0) {
            fprintf(stderr, "Error: SPI read failed\n");
            set_heater_pwm(0.0);
            cleanup();
            return 1;
        }
        double rtd_resistance = rtd_to_resistance(rtd_code);
        double temperature = resistance_to_temperature(rtd_resistance);
        if (temperature < -100.0) {
            fprintf(stderr, "Error: Invalid temperature reading (fault?)\n");
            set_heater_pwm(0.0);
            cleanup();
            return 1;
        }
        uint8_t fault;
        if (spi_read_reg(MAX31865_FAULT_REG, &fault) != 0) {
            fprintf(stderr, "Error: Failed to read MAX31865 fault register\n");
            set_heater_pwm(0.0);
            cleanup();
            return 1;
        }
        if (fault & 0x01) {
            fprintf(stderr, "Error: MAX31865 fault detected (0x%02X)\n", fault);
            set_heater_pwm(0.0);
            cleanup();
            return 1;
        }
        if (temperature > MAX_TEMP) {
            fprintf(stderr, "Error: Temperature %.2f C exceeds max %.1f C\n", temperature, MAX_TEMP);
            set_heater_pwm(0.0);
            cleanup();
            return 1;
        }
        double duty_cycle = pid_control(temperature);
        set_heater_pwm(duty_cycle);
        printf("Temp: %.2f C  Duty: %.1f%%\n", temperature, duty_cycle);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_heater_pwm(0.0);
    cleanup();
    return 0;
}

