#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "breach_log.txt"

#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA

#define BMP180_OSS 3
#define TEMP_CMD 0x2E
#define PRESSURE_CMD 0x34

#define TEMP_THRESHOLD 30.0f
#define PRESSURE_THRESHOLD 950.0f

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < 3; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        if (errno != EINTR) { fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno)); return -1; }
    }
    return -1;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int i = 0; i < 3; i++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buf, len) == len) return 0;
        }
        if (errno != EINTR) { fprintf(stderr, "I2C read reg 0x%02X failed: %s\n", reg, strerror(errno)); return -1; }
    }
    return -1;
}

static int read_calibration(int fd, bmp180_cal_t *cal) {
    uint8_t buf[22];
    if (i2c_read(fd, BMP180_REG_CAL_AC1, buf, 22) != 0) return -1;
    cal->ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal->ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal->ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal->ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal->ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal->ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal->b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal->b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal->mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal->mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal->md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temp(int fd, int32_t *ut) {
    if (i2c_write(fd, BMP180_REG_CONTROL, TEMP_CMD) != 0) return -1;
    usleep(5000);
    uint8_t buf[2];
    if (i2c_read(fd, BMP180_REG_MSB, buf, 2) != 0) return -1;
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    if (i2c_write(fd, BMP180_REG_CONTROL, PRESSURE_CMD | (BMP180_OSS << 6)) != 0) return -1;
    usleep(2000 + (3000 << BMP180_OSS));
    uint8_t buf[3];
    if (i2c_read(fd, BMP180_REG_MSB, buf, 3) != 0) return -1;
    *up = ((int32_t)buf[0] << 16 | (int32_t)buf[1] << 8 | (int32_t)buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut, const bmp180_cal_t *cal) {
    int32_t x1 = ((ut - (int32_t)cal->ac6) * (int32_t)cal->ac5) >> 15;
    int32_t x2 = ((int32_t)cal->mc << 11) / (x1 + (int32_t)cal->md);
    return x1 + x2;
}

static float calc_temp(int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calc_pressure(int32_t up, int32_t ut, const bmp180_cal_t *cal) {
    int32_t b5 = compute_b5(ut, cal);
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal->b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal->ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    uint32_t b4 = ((uint32_t)cal->ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (uint32_t)(50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
