#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define GPIO_PIN 27
#define DEBOUNCE_MS 200
#define LOG_INTERVAL_S 2

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_toggle_tick = 0;
static int i2c_handle = -1;
static int pigpio_initialized = 0;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    uint8_t buf[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buf, 22) != 22) {
        fprintf(stderr, "Error: failed to read calibration data\n");
        return -1;
    }
    cal.ac1 = (int16_t)((buf[0] << 8) | buf[1]);
    cal.ac2 = (int16_t)((buf[2] << 8) | buf[3]);
    cal.ac3 = (int16_t)((buf[4] << 8) | buf[5]);
    cal.ac4 = (uint16_t)((buf[6] << 8) | buf[7]);
    cal.ac5 = (uint16_t)((buf[8] << 8) | buf[9]);
    cal.ac6 = (uint16_t)((buf[10] << 8) | buf[11]);
    cal.b1 = (int16_t)((buf[12] << 8) | buf[13]);
    cal.b2 = (int16_t)((buf[14] << 8) | buf[15]);
    cal.mb = (int16_t)((buf[16] << 8) | buf[17]);
    cal.mc = (int16_t)((buf[18] << 8) | buf[19]);
    cal.md = (int16_t)((buf[20] << 8) | buf[21]);
    return 0;
}

static int read_raw_temperature(int32_t *ut) {
    uint8_t cmd = 0x2E;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write temperature command\n");
        return -1;
    }
    gpioDelay(5000);
    uint8_t buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: failed to read raw temperature\n");
        return -1;
    }
    *ut = (int32_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    uint8_t cmd = 0x34 + (BMP180_OSS << 6);
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: failed to write pressure command\n");
        return -1;
    }
    gpioDelay(2000 + (3000 << BMP180_OSS));
    uint8_t buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buf, 3) != 3) {
        fprintf(stderr, "Error: failed to read raw pressure\n");
        return -1;
    }
    *up = ((int32_t)(buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: failed to open pressure_log.txt\n");
        return;
    }
    fprintf(fp, "%s, %d Pa\n", timestamp, pressure);
    fclose(fp);
}

static void toggle_logging(void) {
    logging_enabled = !logging_enabled;
    printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
}

static void gpio_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 0) {
        uint32_t elapsed = tick - last_toggle_tick;
        if (elapsed > DEBOUNCE_MS * 1000) {
            last_toggle_tick = tick;
            toggle_logging();
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }

    if (read_calibration() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (gpioSetAlertFunc(GPIO_PIN, gpio_callback) != 0) {
        fprintf(stderr, "Error: failed to set GPIO alert function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 pressure logger started. Press the button on GPIO27 to toggle logging.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up;
            if (read_raw_temperature(&ut) == 0 && read_raw_pressure(&up) == 0) {
                int32_t b5 = compute_b5(ut);
                int32_t pressure = compute_pressure(up, b5);
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Warning: sensor read error, skipping log entry\n");
            }
        }
        sleep(LOG_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFunc(GPIO_PIN, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (pigpio_initialized) gpioTerminate();
    return 0;
}

