#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000
#define PWM_RANGE 100
#define MAX_DUTY_CYCLE 80
#define DEFAULT_TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"

#define MAX31855_FAULT_OPEN 0x01
#define MAX31855_FAULT_GND 0x02
#define MAX31855_FAULT_VCC 0x04

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file);
}

static int read_max31855(float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(spi_handle, tx, rx, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault: ");
        if (raw & MAX31855_FAULT_OPEN) fprintf(stderr, "open circuit ");
        if (raw & MAX31855_FAULT_GND) fprintf(stderr, "short to GND ");
        if (raw & MAX31855_FAULT_VCC) fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return -1;
    }

    int16_t thermocouple_temp = (int16_t)(raw >> 18);
    *temperature = thermocouple_temp * 0.25f;
    return 0;
}

static int calculate_pwm(float current_temp, float target_temp, float *integral) {
    float error = target_temp - current_temp;
    float kp = 10.0f;
    float ki = 0.1f;

    *integral += error;
    if (*integral > 100.0f) *integral = 100.0f;
    if (*integral < -100.0f) *integral = -100.0f;

    float output = kp * error + ki * (*integral);
    if (output < 0.0f) output = 0.0f;
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;

    return (int)output;
}

static void set_heater_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

static void cleanup(void) {
    gpioWrite(HEATER_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float target_temp = DEFAULT_TARGET_TEMP;

    if (argc > 1) {
        target_temp = atof(argv[1]);
        if (target_temp < -50.0f || target_temp > 150.0f) {
            fprintf(stderr, "Invalid target temperature: %.2f\n", target_temp);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
        fflush(log_file);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float integral = 0.0f;
    int last_duty = 0;

    while (running) {
        float temperature;
        if (read_max31855(&temperature) == 0) {
            int duty = calculate_pwm(temperature, target_temp, &integral);
            if (duty != last_duty) {
                set_heater_pwm(duty);
                last_duty = duty;
            }
            log_data(temperature, last_duty);
        } else {
            set_heater_pwm(0);
            log_data(-999.0f, 0);
        }
        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

