#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255
#define POLL_US   500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read CPU temperature in millidegrees Celsius from the sysfs thermal zone.
 * Returns 0 on success and stores the value in *out_temp; returns -1 on error.
 */
static int read_temperature(int *out_temp)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("fopen(" TEMP_FILE ")");
        return -1;
    }

    if (fscanf(fp, "%d", out_temp) != 1) {
        fprintf(stderr, "Error: failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error: read error on %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose(" TEMP_FILE ")");
        return -1;
    }

    return 0;
}

/*
 * Map temperature (m°C) to RGB values for a common-anode LED.
 * Common anode: duty = 255 - brightness (0 = fully on, 255 = fully off).
 */
static void set_led_color(int red, int green, int blue)
{
    int r_duty = PWM_RANGE - red;
    int g_duty = PWM_RANGE - green;
    int b_duty = PWM_RANGE - blue;

    if (gpioPWM(RED_PIN,   r_duty) < 0)
        fprintf(stderr, "Warning: gpioPWM(RED) failed\n");
    if (gpioPWM(GREEN_PIN, g_duty) < 0)
        fprintf(stderr, "Warning: gpioPWM(GREEN) failed\n");
    if (gpioPWM(BLUE_PIN,  b_duty) < 0)
        fprintf(stderr, "Warning: gpioPWM(BLUE) failed\n");
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on all three pins --- */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(RED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(GREEN_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BLUE_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(RED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(GREEN_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(BLUE_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure LED is off (common anode: duty 255 = off) --- */
    set_led_color(0, 0, 0);

    /* --- Main loop --- */
    while (g_running) {
        int temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Error: failed to read temperature, skipping update\n");
        } else {
            int red, green, blue;

            if (temperature < 40000) {
                red   = 0;
                green = 0;
                blue  = PWM_RANGE;   /* solid blue */
            } else if (temperature < 60000) {
                red   = 0;
                green = PWM_RANGE;   /* solid green */
                blue  = 0;
            } else {
                red   = PWM_RANGE;   /* solid red */
                green = 0;
                blue  = 0;
            }

            set_led_color(red, green, blue);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n",
                   temperature, red, green, blue);
            fflush(stdout);
        }

        /* Sleep 0.5 s, but wake early if a signal arrives */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(POLL_US / 10);
    }

    /* --- Clean shutdown: turn off LED and release pigpio --- */
    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

