#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float humidity;
    float temperature;
} DHT22Data;

typedef struct {
    char *data;
    size_t size;
} MemoryStruct;

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    MemoryStruct *mem = (MemoryStruct *)userp;
    char *ptr = realloc(mem->data, mem->size + realsize + 1);
    if (!ptr) return 0;
    mem->data = ptr;
    memcpy(&(mem->data[mem->size]), contents, realsize);
    mem->size += realsize;
    mem->data[mem->size] = 0;
    return realsize;
}

int read_dht22(int gpio, DHT22Data *data) {
    int i, j, k;
    int bit_count = 0;
    int byte_index = 0;
    unsigned char data_bytes[5] = {0};
    int timeout = 0;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(2000);
    gpioWrite(gpio, 1);
    gpioDelay(30);
    gpioSetMode(gpio, PI_INPUT);

    for (i = 0; i < 85; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 1 && timeout < 100) { gpioDelay(1); timeout++; }
        if (timeout >= 100) break;
        timeout = 0;
        while (gpioRead(gpio) == 0 && timeout < 100) { gpioDelay(1); timeout++; }
        if (timeout >= 100) break;
        timeout = 0;
        while (gpioRead(gpio) == 1 && timeout < 100) { gpioDelay(1); timeout++; }
        if (timeout >= 100) break;

        if (timeout > 40) {
            data_bytes[byte_index] |= (1 << (7 - bit_count));
        }
        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    if (i < 85 || byte_index != 5) {
        fprintf(stderr, "DHT22: Sensor absent or communication error\n");
        return -1;
    }

    if (data_bytes[4] != ((data_bytes[0] + data_bytes[1] + data_bytes[2] + data_bytes[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum error\n");
        return -2;
    }

    data->humidity = (float)(((unsigned int)data_bytes[0] << 8) | data_bytes[1]) / 10.0;
    data->temperature = (float)(((unsigned int)data_bytes[2] << 8) | data_bytes[3]) / 10.0;
    if (data_bytes[2] & 0x80) {
        data->temperature = -data->temperature;
    }

    return 0;
}

int send_data(float humidity, float temperature) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    char json_string[256];
    snprintf(json_string, sizeof(json_string),
             "{\"humidity\": %.2f, \"temperature\": %.2f}",
             humidity, temperature);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "curl_slist_append() failed\n");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        fprintf(stderr, "HTTP request failed with code: %ld\n", http_code);
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    curl_global_init(CURL_GLOBAL_ALL);

    DHT22Data dht22_data;
    int retries = 0;

    while (running) {
        if (read_dht22(DHT22_GPIO, &dht22_data) == 0) {
            if (send_data(dht22_data.humidity, dht22_data.temperature) == 0) {
                printf("Data sent successfully: Humidity = %.2f, Temperature = %.2f\n",
                       dht22_data.humidity, dht22_data.temperature);
                retries = 0;
            } else {
                fprintf(stderr, "Failed to send data. Retrying...\n");
                retries++;
                if (retries >= MAX_RETRIES) {
                    fprintf(stderr, "Max retries reached. Exiting.\n");
                    break;
                }
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor. Retrying...\n");
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
        }
        sleep(5);
    }

    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

