#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_PIN 4
#define MAX_RETRIES 3
#define DEFAULT_SERVER_URL "http://your-server.com/api/humidity"
#define READ_INTERVAL_SEC 10
#define DHT22_TIMEOUT_US 200

static volatile sig_atomic_t running = 1;
static char *server_url = DEFAULT_SERVER_URL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int pin, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(pin) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *humidity) {
    uint8_t data[5] = {0};
    int i, j;

    for (i = 0; i < 5; i++) data[i] = 0;

    gpioSetMode(DHT22_PIN, PI_OUTPUT);
    gpioWrite(DHT22_PIN, 1);
    gpioDelay(500000);
    gpioWrite(DHT22_PIN, 0);
    gpioDelay(2000);
    gpioWrite(DHT22_PIN, 1);
    gpioDelay(30);
    gpioSetMode(DHT22_PIN, PI_INPUT);

    if (wait_for_level(DHT22_PIN, 0, DHT22_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_PIN, 1, DHT22_TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_PIN, 0, DHT22_TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_PIN, 1, DHT22_TIMEOUT_US) < 0) return -1;
        uint32_t start = gpioTick();
        if (wait_for_level(DHT22_PIN, 0, DHT22_TIMEOUT_US) < 0) return -1;
        uint32_t duration = gpioTick() - start;
        data[i / 8] <<= 1;
        if (duration > 50) data[i / 8] |= 1;
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) return -1;

    uint16_t raw_humidity = (data[0] << 8) | data[1];
    *humidity = (float)raw_humidity / 10.0f;
    return 0;
}

static int post_humidity(float humidity) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        return -1;
    }

    char json[64];
    snprintf(json, sizeof(json), "{\"humidity\": %.1f}", humidity);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        syslog(LOG_ERR, "curl_slist_append() failed");
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, 5L);
    curl_easy_setopt(curl, CURLOPT_NOSIGNAL, 1L);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
        return -1;
    }

    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    if (http_code < 200 || http_code >= 300) {
        syslog(LOG_ERR, "HTTP POST returned non-2xx status: %ld", http_code);
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s server_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_humidity", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    curl_global_init(CURL_GLOBAL_DEFAULT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

