#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int read_cpu_temp(void) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading CPU temperature from %s\n", CPU_TEMP_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

static int read_fan_max_state(void) {
    FILE *fp = fopen(FAN_MAX_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_MAX_STATE_PATH, strerror(errno));
        return -1;
    }
    int max_state;
    if (fscanf(fp, "%d", &max_state) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_MAX_STATE_PATH);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return max_state;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing fan state to %s\n", FAN_STATE_PATH);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_fan_speed(int fan_speed) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }
    if (fprintf(fp, "%s Fan speed: %d\n", timestamp, fan_speed) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int calculate_fan_speed(int cpu_temp) {
    if (cpu_temp < 45000) return 0;
    if (cpu_temp < 55000) return 1;
    if (cpu_temp < 65000) return 2;
    return 3;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int last_fan_speed = -1;

    while (program_running) {
        int cpu_temp = read_cpu_temp();
        if (cpu_temp < 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int max_state = read_fan_max_state();
        if (max_state < 0) {
            fprintf(stderr, "Failed to read max_state. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }
        if (max_state == 0) {
            fprintf(stderr, "Max fan state is 0. Cannot control fan.\n");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int fan_speed = calculate_fan_speed(cpu_temp);

        if (fan_speed > max_state) {
            fprintf(stderr, "Requested fan speed %d exceeds max_state %d. Clamping.\n", fan_speed, max_state);
            fan_speed = max_state;
        }

        if (fan_speed != last_fan_speed) {
            if (write_fan_state(fan_speed) == 0) {
                last_fan_speed = fan_speed;
                if (log_fan_speed(fan_speed) != 0) {
                    fprintf(stderr, "Failed to log fan speed.\n");
                }
            } else {
                fprintf(stderr, "Failed to write fan state.\n");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    fprintf(stderr, "Shutting down...\n");
    if (write_fan_state(0) != 0) {
        fprintf(stderr, "Failed to stop fan on shutdown.\n");
    }
    if (log_fan_speed(0) != 0) {
        fprintf(stderr, "Failed to log shutdown.\n");
    }
    return 0;
}

