#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"
#define MAX_RETRIES 3
#define TEMP_ERROR -1000.0f

#define MAX31855_FAULT_OPEN_CIRCUIT 0x01
#define MAX31855_FAULT_SHORT_GND 0x02
#define MAX31855_FAULT_SHORT_VCC 0x04

typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float target_temperature;
    float integral;
    float previous_error;
} PIDController;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float read_temperature(void) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};
    int ret;

    for (int i = 0; i < MAX_RETRIES; i++) {
        ret = spiXfer(spi_handle, tx, rx, 4);
        if (ret == 4) break;
        gpioDelay(10000);
    }

    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed after %d retries\n", MAX_RETRIES);
        return TEMP_ERROR;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "MAX31855 fault detected: ");
        if (raw & MAX31855_FAULT_OPEN_CIRCUIT) fprintf(stderr, "open circuit ");
        if (raw & MAX31855_FAULT_SHORT_GND)    fprintf(stderr, "short to GND ");
        if (raw & MAX31855_FAULT_SHORT_VCC)    fprintf(stderr, "short to VCC ");
        fprintf(stderr, "\n");
        return TEMP_ERROR;
    }

    int16_t thermocouple_temp = (int16_t)((raw >> 18) & 0x3FFF);
    if (raw & 0x8000) {
        thermocouple_temp |= 0xC000;
    }
    return thermocouple_temp * 0.25f;
}

static float pid_calculate(PIDController *pid, float current_temperature) {
    float error = pid->target_temperature - current_temperature;
    pid->integral += error;
    if (pid->integral > 100.0f) pid->integral = 100.0f;
    if (pid->integral < -100.0f) pid->integral = -100.0f;
    float derivative = error - pid->previous_error;
    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    return output;
}

static void set_heater_pwm(float duty_cycle) {
    if (duty_cycle < 0.0f) duty_cycle = 0.0f;
    if (duty_cycle > 100.0f) duty_cycle = 100.0f;
    gpioPWM(HEATER_GPIO, (int)(duty_cycle * (PWM_RANGE / 100.0f)));
}

static void log_data(float temperature, float duty_cycle, float pid_output, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (message) {
        fprintf(log_file, "%s, Temperature: ERROR, PWM: %.2f, PID: %.2f, Message: %s\n",
                timestamp, duty_cycle, pid_output, message);
    } else {
        fprintf(log_file, "%s, Temperature: %.2f, PWM: %.2f, PID: %.2f\n",
                timestamp, temperature, duty_cycle, pid_output);
    }
    fflush(log_file);
}

static void cleanup(void) {
    gpioWrite(HEATER_GPIO, 0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    gpioPWM(HEATER_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    PIDController pid = {1.0f, 0.1f, 0.01f, 50.0f, 0.0f, 0.0f};

    while (running) {
        float temperature = read_temperature();

        if (temperature > 100.0f || temperature < 0.0f) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
            log_data(temperature, 0.0f, 0.0f, "Temperature out of range");
            set_heater_pwm(0.0f);
            pid.integral = 0.0f;
            pid.previous_error = 0.0f;
            gpioDelay(1000000);
            continue;
        }

        if (temperature == TEMP_ERROR) {
            log_data(temperature, 0.0f, 0.0f, "SPI read error");
            set_heater_pwm(0.0f);
            pid.integral = 0.0f;
            pid.previous_error = 0.0f;
            gpioDelay(1000000);
            continue;
        }

        float pid_output = pid_calculate(&pid, temperature);
        float duty_cycle = pid_output;

        if (duty_cycle < 0.0f) duty_cycle = 0.0f;
        if (duty_cycle > 100.0f) duty_cycle = 100.0f;

        set_heater_pwm(duty_cycle);
        log_data(temperature, duty_cycle, pid_output, NULL);

        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

