    if (!fp) {
        perror("fopen log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    float temp_c = temp_milli / 1000.0f;
    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temp_c, duty_cycle) < 0) {
