        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", FAN_GPIO);
        gpioTerminate();
        return 1;
    }

    if (set_fan_speed(0) < 0) {
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "r");
    if (!fp) {
        fp = fopen(LOG_FILE, "w");
        if (!fp) {
            perror("fopen create log file");
            gpioTerminate();
            return 1;
        }
        fprintf(fp, "Timestamp,Temperature(C),DutyCycle(%%)\n");
        fclose(fp);
    } else {
        fclose(fp);
    }

    while (running) {
        int temp_milli = read_cpu_temp();
        if (temp_milli < 0) {
            fprintf(stderr, "Error reading CPU temperature, skipping cycle\n");
        } else {
            int duty_cycle = calculate_duty_cycle(temp_milli);
            if (set_fan_speed(duty_cycle) < 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }
            if (log_data(temp_milli, duty_cycle) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        sleep(POLL_INTERVAL_SEC);
    }

    set_fan_speed(0);
    gpioTerminate();
    return 0;
}

