#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define MEASUREMENT_CMD 0x3608
#define FLOW_SCALE_FACTOR 0.01f
#define LOG_FILE "flow_log.txt"
#define POLL_INTERVAL_SEC 1
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    char cmd[2] = { (MEASUREMENT_CMD >> 8) & 0xFF, MEASUREMENT_CMD & 0xFF };
    char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (handle %d, retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(2000);

        if (i2cReadDevice(handle, buf, 3) != 3) {
            fprintf(stderr, "I2C read failed (handle %d, retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        if (crc8((uint8_t *)buf, 2) != (uint8_t)buf[2]) {
            fprintf(stderr, "CRC mismatch (handle %d, retry %d)\n", handle, retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        int16_t raw = (buf[0] << 8) | buf[1];
        *flow_rate = (float)raw * FLOW_SCALE_FACTOR;
        return 0;
    }

    fprintf(stderr, "Failed to read flow rate after %d retries (handle %d)\n", MAX_RETRIES, handle);
    return -1;
}

static int log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1 (addr 0x%02X): %d\n", SENSOR1_ADDR, i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2 (addr 0x%02X): %d\n", SENSOR2_ADDR, i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting flow sensor monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int rc1 = read_flow_rate(i2c_handle1, &flow1);
        int rc2 = read_flow_rate(i2c_handle2, &flow2);

        if (rc1 == 0 && rc2 == 0) {
            if (log_flow_rates(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log flow rates\n");
            }
        } else {
            fprintf(stderr, "Sensor read error: sensor1=%d, sensor2=%d\n", rc1, rc2);
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

