#include <string.h>
#include <errno.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_encoder_data(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, angle);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

static void encoder_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;

    if (gpio != SENSOR_A_GPIO && gpio != SENSOR_B_GPIO) {
        return;
    }

    static int last_state = 0;
    static int a_state = 0;
    static int b_state = 0;

    if (gpio == SENSOR_A_GPIO) {
        a_state = level;
    } else {
        b_state = level;
    }

    int current_state = (a_state << 1) | b_state;

    if (current_state != last_state) {
        int delta = current_state - last_state;
        if (delta == 1 || delta == -3) {
            // Clockwise
            log_encoder_data((float)((int)(log_file ? ftell(log_file) : 0) % (int)PULSES_PER_REVOLUTION) / PULSES_PER_REVOLUTION * 360.0);
        } else if (delta == -1 || delta == 3) {
            // Counter-clockwise
            log_encoder_data((float)((int)(log_file ? ftell(log_file) : 0) % (int)PULSES_PER_REVOLUTION) / PULSES_PER_REVOLUTION * 360.0);
        }
        last_state = current_state;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, encoder_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, encoder_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B_GPIO);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000); // 100ms delay to reduce CPU usage
    }

    printf("\nExiting gracefully...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

