/*
 * ADPD144RI Red/IR Photometric Sensor Reader with I2C and GPIO LED
 * Board:  Raspberry Pi 3 Model B+
 * Library: libgpiod (GPIO), Linux I2C character-device interface
 *
 * Wiring:
 *   ADPD144RI SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   ADPD144RI SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   ADPD144RI VDD  -> 3.3 V
 *   ADPD144RI GND  -> GND
 *   LED anode     -> GPIO 17 (1 kΩ series resistor to GND)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adpd144ri adpd144ri.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- ADPD144RI constants (verified against datasheet) ---- */
#define I2C_BUS          "/dev/i2c-1"
#define ADPD144RI_ADDR   0x39          /* 7-bit default address */

#define REG_FIFO_DATA    0x60          /* 16-bit red + IR, little-endian */
#define REG_MODE         0x01          /* Mode register */
#define REG_INT_EN       0x02          /* Interrupt enable register */
#define REG_INT_STATUS   0x03          /* Interrupt status register */

#define MODE_STANDBY     0x00
#define MODE_OPERATE     0x01

#define IR_THRESHOLD     2000
#define LED_GPIO         17
#define SAMPLE_MS        100
#define LOG_FILE         "adpd144ri_log.txt"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_fp   = NULL;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);   /* LED off */
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* ADPD144RI FIFO data is little-endian: low byte first */
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    /* Standby first so the device is in a known state */
    if (i2c_write_reg8(fd, REG_MODE, MODE_STANDBY) < 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Enable data-ready interrupt (optional, but good practice) */
    if (i2c_write_reg8(fd, REG_INT_EN, 0x01) < 0)
        return -1;

    /* Start continuous operation */
    if (i2c_write_reg8(fd, REG_MODE, MODE_OPERATE) < 0)
        return -1;

    usleep(10000);  /* 10 ms for first conversion */
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor_data(int fd, uint16_t *red, uint16_t *ir)
{
    return i2c_read_reg16(fd, REG_FIFO_DATA, red) ||
           i2c_read_reg16(fd, REG_FIFO_DATA, ir);
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL)
        return;
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0)
        return;

    fprintf(fp, "%s,%u,%u\n", ts, red, ir);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Probe sensor presence ---- */
    uint8_t probe;
    if (write(g_i2c_fd, &probe, 0) < 0) {
        fprintf(stderr, "Sensor at 0x%02X not responding: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (init_sensor(g_i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_led = gpiod_chip_get_line(g_chip, LED_GPIO);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_led, "adpd144ri-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADPD144RI monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t red = 0, ir = 0;

        if (read_sensor_data(g_i2c_fd, &red, &ir) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        log_data(g_log_fp, red, ir);

        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(g_led, 1);
        } else {
            gpiod_line_set_value(g_led, 0);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

