#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define LOG_FILE "air_quality_log.csv"
#define READ_INTERVAL_SEC 5
#define TVOC_SCALE 10.0f
#define ECO2_OFFSET 400.0f
#define ECO2_SCALE 50.0f
#define IAQ_MAX 100.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_sensor_data(uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 7);
    if (result != 7) {
        fprintf(stderr, "Error reading sensor data: expected 7 bytes, got %d\n", result);
        return -1;
    }
    return 0;
}

static float calculate_iaq(uint16_t tvoc, uint16_t eco2) {
    float tvoc_f = (float)tvoc;
    float eco2_f = (float)eco2;
    float iaq = IAQ_MAX - (tvoc_f / TVOC_SCALE) - ((eco2_f - ECO2_OFFSET) / ECO2_SCALE);
    if (iaq < 0.0f) iaq = 0.0f;
    if (iaq > IAQ_MAX) iaq = IAQ_MAX;
    return iaq;
}

static void log_data(float iaq, uint16_t tvoc, uint16_t eco2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
