#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_MS 100
#define TAMPER_DURATION_S 5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec start_time, current_time;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip by name */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for the touch sensor */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as input with the consumer label */
    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO %d (chip %s)...\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);
    printf("Alert triggered when touched for > %d seconds. Press Ctrl+C to exit.\n",
           TAMPER_DURATION_S);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (value == 1) {
            /* Sensor is touched */
            if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                goto cleanup;
            }

            /* Wait for the sensor to be released */
            while (program_running) {
                value = gpiod_line_get_value(line);
                if (value < 0) {
                    fprintf(stderr, "Failed to read GPIO line %d: %s\n",
                            GPIO_LINE_OFFSET, strerror(errno));
                    goto cleanup;
                }
                if (value == 0) {
                    break; /* Released */
                }
                usleep(POLL_INTERVAL_MS * 1000);
            }

            /* Check if the touch lasted longer than the tamper duration */
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
                fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
                goto cleanup;
            }

            double elapsed = (current_time.tv_sec - start_time.tv_sec)
                           + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

            if (elapsed > TAMPER_DURATION_S) {
                printf("ALERT: Tamper detected! Touch held for %.2f seconds.\n", elapsed);
                fflush(stdout);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

