/*
 * INMP441 I2S MEMS Microphone Audio Capture for Raspberry Pi 4 Model B
 *
 * Hardware Connections:
 *   INMP441 VDD  -> 3.3V (Pin 1)
 *   INMP441 GND  -> GND  (Pin 9)
 *   INMP441 SCK  -> GPIO 11 (Pin 23, I2S BCLK)
 *   INMP441 WS   -> GPIO 17 (Pin 11, I2S LRCLK)
 *   INMP441 SD   -> GPIO 18 (Pin 12, I2S DIN)
 *
 * The INMP441 outputs 24-bit data left-justified in a 32-bit frame.
 * We extract the 24-bit sample and right-shift it to produce 16-bit PCM.
 *
 * Build: gcc -O2 -Wall -o audio_capture audio_capture.c -lgpiod -lasound
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/soundcard.h>
#include <gpiod.h>

#define I2S_DEVICE      "/dev/snd/pcmC0D0c"  /* ALSA capture device */
#define AUDIO_FILE      "audio_capture.pcm"
#define SAMPLE_RATE     48000
#define BITS_PER_SAMPLE 16
#define CHANNELS        2
#define BUFFER_BYTES    4096

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * Open the ALSA PCM device for capture.
 * Returns a file descriptor or -1 on failure.
 */
static int open_alsa_capture(void) {
    int fd = open(I2S_DEVICE, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening ALSA device %s: %s\n",
                I2S_DEVICE, strerror(errno));
        return -1;
    }

    /* Set hardware parameters: 24-bit, 2 channels, 48 kHz */
    int format = AFMT_S24_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting audio format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int channels = CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting channel count: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    /* Verify the kernel accepted our settings */
    if (channels != CHANNELS || rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: ALSA did not accept requested settings "
                        "(channels=%d, rate=%d)\n", channels, rate);
    }

    return fd;
}

/*
 * Read audio data from the ALSA device.
 * Returns the number of bytes read, or -1 on error.
 */
static ssize_t read_audio_data(int fd, uint8_t *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading audio data: %s\n", strerror(errno));
        return -1;
    }
    return bytes_read;
}

/*
 * Process 24-bit left-justified I2S data into 16-bit PCM.
 * Each 32-bit frame contains two 24-bit samples (left and right).
 * We extract the left channel and right-shift to produce 16-bit samples.
 */
static void process_audio_data(const uint8_t *raw_data, int16_t *pcm_data,
                               size_t raw_data_len) {
    size_t num_32bit_frames = raw_data_len / 4;
    size_t num_samples = num_32bit_frames * 2; /* 2 samples per 32-bit frame */

    if (num_samples > BUFFER_BYTES / sizeof(int16_t)) {
        num_samples = BUFFER_BYTES / sizeof(int16_t);
    }

    for (size_t i = 0; i < num_samples; i++) {
        /* Each 32-bit frame: [unused][24-bit left][24-bit right] */
        size_t frame_idx = i / 2;
        size_t byte_offset = frame_idx * 4;
        uint32_t sample32 = ((uint32_t)raw_data[byte_offset + 1] << 16) |
                            ((uint32_t)raw_data[byte_offset + 2] << 8) |
                            ((uint32_t)raw_data[byte_offset + 3]);

        /* Extract 24-bit left channel and right-shift to 16-bit */
        pcm_data[i] = (int16_t)(sample32 >> 8);
    }
}

/*
 * Write PCM data to a raw file.
 * Returns 0 on success, -1 on error.
 */
static int write_audio_data(const int16_t *pcm_data, size_t num_samples,
                            const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    size_t items_written = fwrite(pcm_data, sizeof(int16_t), num_samples, fp);
    if (items_written != num_samples) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the ALSA PCM device for capture */
    int audio_fd = open_alsa_capture();
    if (audio_fd < 0) {
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip and line for the L/R select pin (GPIO 17) */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(audio_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *lr_line = gpiod_chip_get_line(chip, 17);
    if (lr_line == NULL) {
        fprintf(stderr, "Error getting GPIO line 17: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(audio_fd);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initially low (select left channel) */
    if (gpiod_line_request_output(lr_line, "inmp441-lr-select", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line 17 as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(audio_fd);
        return EXIT_FAILURE;
    }

    /* Main acquisition loop */
    uint8_t raw_data[BUFFER_BYTES];
    int16_t pcm_data[BUFFER_BYTES / sizeof(int16_t)];

    while (g_running) {
        ssize_t bytes_read = read_audio_data(audio_fd, raw_data, sizeof(raw_data));
        if (bytes_read < 0) {
            /* Error already printed; continue or break */
            break;
        }

        if (bytes_read == 0) {
            /* No data available (should not happen with blocking read) */
            continue;
        }

        process_audio_data(raw_data, pcm_data, (size_t)bytes_read);

        if (write_audio_data(pcm_data, bytes_read / sizeof(int16_t), AUDIO_FILE) < 0) {
            break;
        }
    }

    /* Clean up resources */
    gpiod_line_release(lr_line);
    gpiod_chip_close(chip);
    close(audio_fd);

    printf("\nAudio capture stopped. Data saved to %s\n", AUDIO_FILE);
    return EXIT_SUCCESS;
}

