#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_US 50000
#define LOG_FILE "flame_log.txt"
#define SENSOR_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    } else {
        fprintf(fp, "(unknown time): %s\n", msg);
    }
    fclose(fp);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "setMode flame failed\n");
        return -1;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "setMode fan failed\n");
        return -1;
    }
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "setPWMfrequency failed\n");
        return -1;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "setPWMrange failed\n");
        return -1;
    }
    if (gpioPWM(FAN_PIN, 0) < 0) {
        fprintf(stderr, "gpioPWM init failed\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioPWM(FAN_PIN, 0);
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
}

static int read_flame(void) {
    int v = gpioRead(FLAME_SENSOR_PIN);
    if (v < 0) {
        fprintf(stderr, "gpioRead flame failed\n");
        return -1;
    }
    return v;
}

static int set_fan_speed(int pct) {
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    int duty = (pct * PWM_RANGE) / 100;
    if (gpioPWM(FAN_PIN, duty) < 0) {
        fprintf(stderr, "gpioPWM fan failed\n");
        return -1;
    }
    return 0;
}

static double flame_duration_ms(int duration_ms) {
    return 100.0 * (1.0 - exp(-0.001 * duration_ms));
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("GPIO init failed");
        return 1;
    }
    log_event("System started");

    int last_stable = -1;
    int last_raw = -1;
    int flame_active = 0;
    int flame_start_ms = 0;
    int debounce_count = 0;

    while (running) {
        int raw = read_flame();
        if (raw < 0) {
            log_event("Sensor read error");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (raw != last_raw) {
            debounce_count = 0;
            last_raw = raw;
        } else {
            debounce_count++;
            if (debounce_count >= (DEBOUNCE_MS / POLL_INTERVAL_US)) {
                if (raw != last_stable) {
                    last_stable = raw;
                    if (raw == 0) {
                        flame_start_ms = 0;
                        flame_active = 1;
                        log_event("Flame detected");
                    } else {
                        flame_active = 0;
                        log_event("Flame ended");
                    }
                }
            }
        }

        if (flame_active) {
            flame_start_ms += (POLL_INTERVAL_US / 1000);
            double dur = flame_duration_ms(flame_start_ms);
            int speed = (int)dur;
            if (speed > 80) speed = 80;
            if (set_fan_speed(speed) < 0) {
                log_event("Fan speed set failed");
            }
        } else {
            if (set_fan_speed(0) < 0) {
                log_event("Fan off failed");
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Shutting down");
    cleanup();
    return 0;
}

