#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define TRIGGER_PIN 23
#define INT_PIN     24
#define DATA_SIZE   32768
#define LOG_FILE    "radar_data.log"

#define START_FREQ_GHZ 77.0f
#define END_FREQ_GHZ   79.0f
#define NUM_CHIRPS     64
#define NUM_SAMPLES    256
#define FRAME_PERIOD_MS 100

#define MAGIC_NUMBER 0x52444144u

typedef struct {
    uint32_t magic;
    uint8_t  timestamp[8];
    float    start_freq;
    float    end_freq;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period_ms;
} __attribute__((packed)) RadarConfig;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        return -1;
    }
    if (gpioSetMode(INT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set interrupt pin mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(INT_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on interrupt pin\n");
        return -1;
    }
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize trigger pin low\n");
        return -1;
    }
    return 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

static int log_header(const RadarConfig *cfg) {
    log_file = fopen(LOG_FILE, "wb");
    if (!log_file) {
        perror("Failed to open log file");
        return -1;
    }
    if (fwrite(&cfg->magic, sizeof(cfg->magic), 1, log_file) != 1) {
        perror("Failed to write magic number");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    if (fwrite(cfg->timestamp, sizeof(cfg->timestamp), 1, log_file) != 1) {
        perror("Failed to write timestamp");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    if (fwrite(&cfg->start_freq, sizeof(cfg->start_freq), 1, log_file) != 1) {
        perror("Failed to write start frequency");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    if (fwrite(&cfg->end_freq, sizeof(cfg->end_freq), 1, log_file) != 1) {
        perror("Failed to write end frequency");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    if (fwrite(&cfg->num_chirps, sizeof(cfg->num_chirps), 1, log_file) != 1) {
        perror("Failed to write num chirps");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    if (fwrite(&cfg->num_samples, sizeof(cfg->num_samples), 1, log_file) != 1) {
        perror("Failed to write num samples");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    if (fwrite(&cfg->frame_period_ms, sizeof(cfg->frame_period_ms), 1, log_file) != 1) {
        perror("Failed to write frame period");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Failed to flush header");
        fclose(log_file);
        log_file = NULL;
        return -1;
    }
    return 0;
}

static int log_frame(uint32_t frame_num, const uint8_t *data, size_t len) {
    if (!log_file) {
        fprintf(stderr, "Log file not open\n");
        return -1;
    }
    uint8_t ts[8];
    struct timespec spec;
    if (clock_gettime(CLOCK_REALTIME, &spec) != 0) {
        perror("clock_gettime failed");
        return -1;
    }
    ts[0] = (spec.tv_sec >> 0) & 0xFF;
    ts[1] = (spec.tv_sec >> 8) & 0xFF;
    ts[2] = (spec.tv_sec >> 16) & 0xFF;
    ts[3] = (spec.tv_sec >> 24) & 0xFF;
    ts[4] = (spec.tv_nsec >> 0) & 0xFF;
    ts[5] = (spec.tv_nsec >> 8) & 0xFF;
    ts[6] = (spec.tv_nsec >> 16) & 0xFF;
    ts[7] = (spec.tv_nsec >> 24) & 0xFF;

    if (fwrite(&frame_num, sizeof(frame_num), 1, log_file) != 1) {
        perror("Failed to write frame number");
        return -1;
    }
    if (fwrite(ts, sizeof(ts), 1, log_file) != 1) {
        perror("Failed to write frame timestamp");
        return -1;
    }
    if (fwrite(data, 1, len, log_file) != len) {
        perror("Failed to write frame data");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Failed to flush frame");
        return -1;
    }
    return 0;
}

static int request_frame(void) {
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set trigger high\n");
        return -1;
    }
    gpioDelay(1000);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low\n");
        return -1;
    }
    return 0;
}

static int wait_for_interrupt(void) {
    int timeout_ms = 1000;
    while (timeout_ms > 0) {
        if (gpioRead(INT_PIN) == 1) {
            return 0;
        }
        gpioDelay(1000);
        timeout_ms -= 1;
    }
    fprintf(stderr, "Timeout waiting for data-ready interrupt\n");
    return -1;
}

static int read_spi_data(uint8_t *data, size_t len) {
    char tx[DATA_SIZE];
    char rx[DATA_SIZE];
    memset(tx, 0, DATA_SIZE);
    int bytes = spiXfer(spi_handle, tx, rx, len);
    if (bytes != (int)len) {
        fprintf(stderr, "SPI transfer failed: expected %zu, got %d\n", len, bytes);
        return -1;
    }
    memcpy(data, rx, len);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (init_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    RadarConfig config;
    config.magic = MAGIC_NUMBER;
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    config.timestamp[0] = (ts.tv_sec >> 0) & 0xFF;
    config.timestamp[1] = (ts.tv_sec >> 8) & 0xFF;
    config.timestamp[2] = (ts.tv_sec >> 16) & 0xFF;
    config.timestamp[3] = (ts.tv_sec >> 24) & 0xFF;
    config.timestamp[4] = (ts.tv_nsec >> 0) & 0xFF;
    config.timestamp[5] = (ts.tv_nsec >> 8) & 0xFF;
    config.timestamp[6] = (ts.tv_nsec >> 16) & 0xFF;
    config.timestamp[7] = (ts.tv_nsec >> 24) & 0xFF;
    config.start_freq = START_FREQ_GHZ;
    config.end_freq = END_FREQ_GHZ;
    config.num_chirps = NUM_CHIRPS;
    config.num_samples = NUM_SAMPLES;
    config.frame_period_ms = FRAME_PERIOD_MS;

    if (log_header(&config) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t *frame_data = malloc(DATA_SIZE);
    if (!frame_data) {
        fprintf(stderr, "Failed to allocate frame buffer\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    uint32_t frame_num = 0;
    while (running) {
        if (request_frame() != 0) {
            fprintf(stderr, "Failed to request frame\n");
            break;
        }
        if (wait_for_interrupt() != 0) {
            fprintf(stderr, "Interrupt timeout, continuing\n");
            continue;
        }
        if (read_spi_data(frame_data, DATA_SIZE) != 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            break;
        }
        if (log_frame(frame_num, frame_data, DATA_SIZE) != 0) {
            fprintf(stderr, "Failed to log frame\n");
            break;
        }
        frame_num++;
        gpioDelay(FRAME_PERIOD_MS * 1000);
    }

    free(frame_data);
    if (log_file) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    return 0;
}

