#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define REG_RESULT 0x00
#define REG_CONFIG 0x01
#define CONFIG_CONTINUOUS 0xC000
#define CONFIG_RANGE_AUTO 0x0000
#define CONFIG_CONV_TIME_100MS 0x0000
#define CONFIG_POLARITY_ACTIVE_LOW 0x0000
#define CONFIG_INT_MODE_DISABLE 0x0000
#define CONFIG_QUE_EMPTY 0x0000
#define LUX_SCALE 0.01f

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_opt3001(void) {
    uint16_t config = CONFIG_CONTINUOUS | CONFIG_RANGE_AUTO |
                      CONFIG_CONV_TIME_100MS | CONFIG_POLARITY_ACTIVE_LOW |
                      CONFIG_INT_MODE_DISABLE | CONFIG_QUE_EMPTY;
    char buf[3];
    buf[0] = REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing config register\n");
        return -1;
    }
    return 0;
}

static int read_lux(float *lux) {
    char reg = REG_RESULT;
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing result register address\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading result register\n");
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    int exponent = (raw >> 12) & 0x0F;
    int mantissa = raw & 0x0FFF;
    *lux = LUX_SCALE * (float)(1 << exponent) * (float)mantissa;
    return 0;
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_opt3001() != 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float lux;
        if (read_lux(&lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        gpioDelay(100000);
    }

    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

