/*
 * Flame Detection Sensor Reader using libgpiod v2.x API
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: SainSmart IR Flame Detection Module (digital output)
 * Wiring: DOUT -> GPIO17 (physical pin 11), VCC -> 3.3V, GND -> GND
 * Logic:  Active-low digital output (0 = flame detected, 1 = no flame)
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(buf, len, "UNKNOWN");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request *line_req = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for SIGINT (Ctrl+C) */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure the line settings: input, bias pull-up */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Error: failed to allocate line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);

    /* Configure the line offset */
    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate line config: %s\n",
                strerror(errno));
        goto cleanup;
    }

    unsigned int offset = GPIO_LINE_OFFSET;
    if (gpiod_line_config_add_line_settings(line_cfg, &offset, 1, settings) != 0) {
        fprintf(stderr, "Error: failed to add line settings: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Configure the request (consumer label) */
    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Error: failed to allocate request config: %s\n",
                strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    /* Request the line */
    line_req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (line_req == NULL) {
        fprintf(stderr, "Error: failed to request GPIO line %u: %s\n",
                offset, strerror(errno));
        goto cleanup;
    }

    printf("Flame detection program started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (program_running) {
        int value = gpiod_line_request_get_value(line_req, GPIO_LINE_OFFSET);
        if (value < 0) {
            fprintf(stderr, "Error: failed to read GPIO line %u: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        char timestamp[32];
        get_timestamp(timestamp, sizeof(timestamp));

        if (value == 0) {
            printf("[%s] Flame Detected: YES\n", timestamp);
        } else {
            printf("[%s] Flame Detected: NO\n", timestamp);
        }
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line_req != NULL) {
        gpiod_line_request_release(line_req);
    }
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

