#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x36
#define SENSOR2_ADDR   0x37
#define FLOW_SCALE     0.036f
#define ALARM_GPIO     17
#define ALARM_THRESHOLD 0.5f
#define LOG_FILE       "flow_log.txt"
#define MEAS_DELAY_MS  100
#define LOOP_DELAY_MS  1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t reg, uint16_t cmd) {
    uint8_t buf[3] = { reg, (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read %zu bytes from reg 0x%02X failed: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(int fd, uint8_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    if (i2c_write_cmd(fd, 0x08, 0x3608) < 0) return -1;
    usleep(MEAS_DELAY_MS * 1000);
    return 0;
}

static int read_flow(int fd, uint8_t addr, float *flow_out) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    uint8_t buf[9];
    if (i2c_read_block(fd, 0x00, buf, sizeof(buf)) < 0)
        return -1;

    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data from 0x%02X\n", addr);
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on temperature data from 0x%02X\n", addr);
        return -1;
    }
    if (sensirion_crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "CRC mismatch on scale factor data from 0x%02X\n", addr);
        return -1;
    }

    int16_t raw_flow = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw_flow * FLOW_SCALE;
    return 0;
}

static void log_flow(FILE *log, float avg_flow) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log, "%s, %.3f\n", ts, avg_flow);
    fflush(log);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *alarm_line = gpiod_chip_get_line(chip, ALARM_GPIO);
    if (!alarm_line) {
        fprintf(stderr, "Failed to get GPIO %d: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, "flow_alarm", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", ALARM_GPIO, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (init_sensor(i2c_fd, SENSOR1_ADDR) < 0 || init_sensor(i2c_fd, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_flow(i2c_fd, SENSOR1_ADDR, &f1);
        int r2 = read_flow(i2c_fd, SENSOR2_ADDR, &f2);

        if (r1 < 0 || r2 < 0) {
            fprintf(stderr, "Sensor read error, skipping cycle.\n");
        } else {
            float avg = (f1 + f2) / 2.0f;
            log_flow(log, avg);
            gpiod_line_set_value(alarm_line, (avg < ALARM_THRESHOLD) ? 1 : 0);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    fclose(log);
    close(i2c_fd);
    return 0;
}

