            gpiod_line_set_value(alarm_line, (avg < ALARM_THRESHOLD) ? 1 : 0);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    gpiod_line_set_value(alarm_line, 0);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);
    fclose(log);
    close(i2c_fd);
    return 0;
}

