    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("Obstacle avoidance sensor monitoring started on GPIO %d.\n", SENSOR_PIN);
    printf("Press Ctrl+C to exit and view the log.\n");

    while (program_running) {
        int reading = gpioRead(SENSOR_PIN);
        if (reading < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d.\n", SENSOR_PIN);
            break;
        }

        if (reading == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Error: time() failed.\n");
                break;
            }
            add_to_buffer(now, reading);
            printf("ALERT: Obstacle detected! Reading: %d\n", reading);
        }

        gpioDelay(POLL_DELAY_US);
    }

    print_buffer();
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

