/*
 * D7S vibration sensor monitor for Raspberry Pi 5 (Bookworm 64-bit).
 *
 * Wiring:
 *   D7S SDA  -> GPIO 2 (I2C1 SDA, pin 3)
 *   D7S SCL  -> GPIO 3 (I2C1 SCL, pin 5)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * I2C bus: /dev/i2c-1  (GPIO 2 = SDA, GPIO 3 = SCL)
 * D7S default 7-bit address: 0x55
 *
 * Build:  gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x55

/* D7S register addresses */
#define REG_MODE_CONTROL  0x1D
#define REG_STATUS        0x1B
#define REG_X_LSB         0x2A
#define REG_X_MSB         0x2B
#define REG_Y_LSB         0x2C
#define REG_Y_MSB         0x2D
#define REG_Z_LSB         0x2E
#define REG_Z_MSB         0x2F

#define MODE_ACTIVE       0x10
#define STATUS_ACTIVE_BIT 0x01

#define SAMPLE_PERIOD_MS  500
#define ACTIVE_TIMEOUT_S  1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT,  &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg_lsb, int16_t *out)
{
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) != 0)
        return -1;
    *out = (int16_t)((uint16_t)lsb | ((uint16_t)msb << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(int fd)
{
    if (i2c_write_reg8(fd, REG_MODE_CONTROL, MODE_ACTIVE) != 0)
        return -1;

    for (int i = 0; i < ACTIVE_TIMEOUT_S * 10; i++) {
        uint8_t status;
        if (i2c_read_reg8(fd, REG_STATUS, &status) != 0)
            return -1;
        if (status & STATUS_ACTIVE_BIT)
            return 0;
        usleep(100 * 1000); /* 100 ms */
    }

    fprintf(stderr, "D7S did not become active within %d s\n", ACTIVE_TIMEOUT_S);
    return -1;
}

/* ------------------------------------------------------------------ */
static int read_acceleration(int fd, float *x_g, float *y_g, float *z_g)
{
    int16_t x, y, z;
    if (i2c_read_reg16_le(fd, REG_X_LSB, &x) != 0) return -1;
    if (i2c_read_reg16_le(fd, REG_Y_LSB, &y) != 0) return -1;
    if (i2c_read_reg16_le(fd, REG_Z_LSB, &z) != 0) return -1;

    /* D7S scaling: 0.0009765625 g per LSB (1/1024) */
    *x_g = (float)x * 0.0009765625f;
    *y_g = (float)y * 0.0009765625f;
    *z_g = (float)z * 0.0009765625f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *csv, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(csv, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(csv);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file (append); write header if empty */
    g_csv = fopen("fan_health.csv", "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(fan_health.csv) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_csv, 0, SEEK_END);
    if (ftell(g_csv) == 0)
        fprintf(g_csv, "timestamp,x_g,y_g,z_g\n");

    printf("D7S vibration monitor started. Logging to fan_health.csv.\n");
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_csv, x, y, z);
        } else {
            fprintf(stderr, "Read error; will retry next cycle.\n");
        }
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

