#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x0E
#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_US      100000  /* 100 ms */

/* TMAG5170-Q1 register addresses */
#define REG_DEVICE_ID  0x00
#define REG_X_CH_RESULT 0x01
#define REG_Y_CH_RESULT 0x03
#define REG_Z_CH_RESULT 0x05
#define REG_CONFIG_1   0x06
#define REG_CONFIG_2   0x07

/* Expected device ID for TMAG5170-Q1 */
#define EXPECTED_DEVICE_ID 0x8D

/* Config_1: continuous mode, all axes enabled, 50 mT range */
#define CONFIG_1_VAL   0x00

/* Config_2: 100 Hz update rate, 16-bit resolution */
#define CONFIG_2_VAL   0x00

/* LSB scale factor for 50 mT range (1 LSB = 0.004 mT) */
#define LSB_MT_50MT    0.004f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_axis(uint8_t reg, float *mt)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X): %d\n", reg, rc);
        return -1;
    }
    int16_t raw = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    *mt = (float)raw * LSB_MT_50MT;
    return 0;
}

static int log_data(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (!t || !strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t)) {
        fprintf(stderr, "Failed to format timestamp\n");
        return -1;
    }
    if (fprintf(g_log_file, "%s,%.4f,%.4f,%.4f\n", ts, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t device_id = 0;
    if (read_reg(REG_DEVICE_ID, &device_id) != 0) {
        fprintf(stderr, "Cannot read device ID - sensor may be absent\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (device_id != EXPECTED_DEVICE_ID) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n",
                device_id, EXPECTED_DEVICE_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_reg(REG_CONFIG_1, CONFIG_1_VAL) != 0 ||
        write_reg(REG_CONFIG_2, CONFIG_2_VAL) != 0) {
        fprintf(stderr, "Failed to configure TMAG5170\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,X_mT,Y_mT,Z_mT\n");
        fflush(g_log_file);
    }

    printf("TMAG5170 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_axis(REG_X_CH_RESULT, &x) != 0 ||
            read_axis(REG_Y_CH_RESULT, &y) != 0 ||
            read_axis(REG_Z_CH_RESULT, &z) != 0) {
            fprintf(stderr, "Sensor read error - continuing\n");
        } else {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Logging error - continuing\n");
            }
        }
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

