#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define SENSOR_GPIO 23
#define POLL_INTERVAL_SEC 2
#define REINIT_INTERVAL_SEC 60
#define LOG_FILE "flood_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(void) {
    int value = gpioRead(SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d.\n", SENSOR_GPIO);
        return -1;
    }
    return value;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }
    fclose(fp);
}

static void log_error(const char *message) {
    char buf[256];
    snprintf(buf, sizeof(buf), "ERROR: %s", message);
    log_event(buf);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started on GPIO %d. Press Ctrl+C to exit.\n", SENSOR_GPIO);

    time_t last_reinit_attempt = 0;
    time_t last_poll = 0;

    while (running) {
        time_t now = time(NULL);

        if (difftime(now, last_poll) >= POLL_INTERVAL_SEC) {
            int sensor_value = read_sensor();
            if (sensor_value == 1) {
                printf("ALERT: Water detected!\n");
                log_event("ALERT: Water detected");
            } else if (sensor_value == 0) {
                log_event("INFO: No water detected");
            } else {
                log_error("Sensor read failure");
            }
            last_poll = now;
        }

        if (difftime(now, last_reinit_attempt) >= REINIT_INTERVAL_SEC) {
            if (gpioInitialise() < 0) {
                log_error("pigpio re-initialization failed");
            } else {
                if (gpioSetMode(SENSOR_GPIO, PI_INPUT) != 0 ||
                    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) != 0) {
                    log_error("Failed to restore GPIO configuration after re-init");
                }
            }
            last_reinit_attempt = now;
        }

        sleep(1);
    }

    gpioTerminate();
    printf("Water level monitoring stopped.\n");
    return EXIT_SUCCESS;
}

