#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>

#define SENSOR_PIN 4          /* BCM GPIO 4, physical pin 7 */
#define SAMPLE_INTERVAL_US 1000000  /* 1 second in microseconds */
#define LOG_FILE "rpm_log.txt"

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — called on every rising edge of SENSOR_PIN  */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;
    (void)tick;
    if (level == 1) {
        __sync_fetch_and_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses counted over the sample interval           */
/* ------------------------------------------------------------------ */
static double calculate_rpm(int pulses)
{
    /* pulses per second * 60 = revolutions per minute */
    return (double)pulses * 60.0;
}

/* ------------------------------------------------------------------ */
/* Append one RPM record to the log file and stdout                   */
/* ------------------------------------------------------------------ */
static void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm);
        fflush(g_log_fp);
    }
    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable alert callback first so no more pulses arrive */
    gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);

    /* Disable timer (id 0) if it was ever active */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler.\n");
    }

    /* ---- configure sensor pin ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- register rising-edge alert callback ---- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx failed for pin %d.\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- start 1-second timer to sample and log ---- */
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_US, NULL, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetTimerFuncEx failed for timer 0.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO %d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);

    /* ---- main loop ---- */
    while (g_running) {
        gpioDelay(SAMPLE_INTERVAL_US);
        int pulses = __sync_fetch_and_and(&g_pulse_count, 0);
        double rpm = calculate_rpm(pulses);
        log_rpm(rpm);
    }

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

