#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27
#define LOG_FILE "rotation_log.txt"
#define DEBOUNCE_US 50000  /* 50 ms debounce */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Quadrature state machine: previous (A, B) -> current (A, B) -> direction */
typedef struct {
    int a, b;
} quad_state_t;

static quad_state_t prev_state = {0, 0};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* pigpio alert callback: runs in pigpio thread, keep it minimal */
static void sensor_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (level < 0) return;  /* timeout / error */

    int a = gpioRead(SENSOR_A_PIN);
    int b = gpioRead(SENSOR_B_PIN);

    if (a < 0 || b < 0) return;

    quad_state_t cur = {a, b};

    /* Only act on state change */
    if (cur.a == prev_state.a && cur.b == prev_state.b) return;

    /* Quadrature direction lookup: (prev, cur) -> direction */
    static const char *dir[4][4] = {
        {"", ""}, {"CW", "CCW"}, {"CCW", "CW"}, {"", ""}
    };

    int idx = (prev_state.a << 1) | prev_state.b;
    int cur_idx = (cur.a << 1) | cur.b;
    int delta = (cur_idx - idx + 4) % 4;

    if (delta == 1) {
        pthread_mutex_lock(&log_mutex);
        if (log_file) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            struct tm tm_info;
            localtime_r(&ts.tv_sec, &tm_info);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
            fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, dir[idx][cur_idx]);
            fflush(log_file);
        }
        pthread_mutex_unlock(&log_mutex);
    }

    prev_state = cur;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-ups\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(SENSOR_A_PIN, sensor_callback) != 0 ||
        gpioSetAlertFunc(SENSOR_B_PIN, sensor_callback) != 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring rotation on GPIO %d and %d. Press Ctrl+C to exit.\n",
           SENSOR_A_PIN, SENSOR_B_PIN);

    while (running) {
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    pthread_mutex_lock(&log_mutex);
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_unlock(&log_mutex);
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
    return EXIT_SUCCESS;
}

