#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int led_state = 0;
    int ret;

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (!touch_line) {
        perror("gpiod_chip_get_line (touch)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request LED line as output, initial value LOW */
    ret = gpiod_line_request_output(led_line, "ttp223b-led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (led)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request touch line for rising-edge events */
    ret = gpiod_line_request_rising_edge_events(touch_line, "ttp223b-touch");
    if (ret < 0) {
        perror("gpiod_line_request_rising_edge_events");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        goto cleanup;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        struct timespec ts = { 1, 0 }; /* 1-second timeout per iteration */
        ret = gpiod_line_event_wait(touch_line, &ts);
        if (ret < 0) {
            perror("gpiod_line_event_wait");
            break;
        }
        if (ret == 0) {
            /* Timeout, no event — loop back to check running flag */
            continue;
        }

        /* Event detected — read it to confirm and clear */
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            perror("gpiod_line_event_read");
            break;
        }

        /* Debounce: wait briefly and re-read the line */
        usleep(DEBOUNCE_MS * 1000);
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        if (val != 1) {
            /* False trigger — line went HIGH but is now LOW */
            continue;
        }

        /* Toggle LED */
        led_state = !led_state;
        ret = gpiod_line_set_value(led_line, led_state);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("Touch detected! LED toggled to %s\n",
               led_state ? "ON" : "OFF");
    }

cleanup:
    if (led_line) {
        gpiod_line_set_value(led_line, 0); /* ensure LED off */
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

