#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN    27
#define LED_2_PIN    22

#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000  /* 50 ms */

typedef struct {
    int      sensor_pin;
    time_t   timestamp;
    bool     touched;
} TouchEvent;

typedef struct {
    TouchEvent events[BUFFER_SIZE];
    int        head;
    int        count;
    int        overflow;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static CircularBuffer        g_buffer;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_1_PIN);
        return -1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_2_PIN);
        return -1;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED %d to OFF.\n", LED_1_PIN);
        return -1;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED %d to OFF.\n", LED_2_PIN);
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n", pin);
        return -1;
    }
    return v;
}

static int write_led(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed on GPIO %d (state=%d).\n", pin, state);
        return -1;
    }
    return 0;
}

static void add_to_buffer(CircularBuffer *buf, int sensor_pin, time_t ts, bool touched)
{
    buf->events[buf->head].sensor_pin = sensor_pin;
    buf->events[buf->head].timestamp  = ts;
    buf->events[buf->head].touched    = touched;

    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    } else {
        buf->overflow++;
    }
}

static void print_buffer(const CircularBuffer *buf)
{
    printf("\n--- Log Buffer (count=%d, overflow=%d) ---\n",
           buf->count, buf->overflow);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("[%2d] Sensor %d @ %ld  %s\n",
               i, buf->events[idx].sensor_pin,
               (long)buf->events[idx].timestamp,
               buf->events[idx].touched ? "touched" : "released");
    }
    printf("--- End of Log Buffer ---\n\n");
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_buffer.head  = 0;
    g_buffer.count = 0;
    g_buffer.overflow = 0;

    int prev1 = -1, prev2 = -1;

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        bool t1 = (s1 == 1);
        bool t2 = (s2 == 1);

        if (t1 != (prev1 == 1)) {
            if (write_led(LED_1_PIN, t1) == 0) {
                time_t now = time(NULL);
                if (now != (time_t)-1) {
                    add_to_buffer(&g_buffer, SENSOR_1_PIN, now, t1);
                }
            }
            prev1 = s1;
        }

        if (t2 != (prev2 == 1)) {
            if (write_led(LED_2_PIN, t2) == 0) {
                time_t now = time(NULL);
                if (now != (time_t)-1) {
                    add_to_buffer(&g_buffer, SENSOR_2_PIN, now, t2);
                }
            }
            prev2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup_gpio();
    print_buffer(&g_buffer);
    return EXIT_SUCCESS;
}

