#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define LOG_FILE "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Log a rain event with a timestamp */
static void log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
}

/* Read the rain sensor; returns 1 (rain), 0 (dry), or -1 on error */
static int read_rain_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        return -1;
    }
    /* Active-low: LOW (0) => rain detected, HIGH (1) => dry */
    return (value == 0) ? 1 : 0;
}

int main(void) {
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO 17 as input with internal pull-up */
    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(RAIN_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", RAIN_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rain sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           RAIN_SENSOR_GPIO);

    int previous_rain_state = -1;  /* Unknown initial state */

    while (program_running) {
        int rain_detected = read_rain_sensor(RAIN_SENSOR_GPIO);

        if (rain_detected < 0) {
            fprintf(stderr, "Error reading rain sensor on GPIO %d\n",
                    RAIN_SENSOR_GPIO);
            log_event("Error reading rain sensor");
        } else {
            if (rain_detected != previous_rain_state) {
                if (rain_detected == 1) {
                    log_event("Rain Detected");
                    printf("Rain Detected\n");
                } else {
                    log_event("No Rain");
                    printf("No Rain\n");
                }
                previous_rain_state = rain_detected;
            }
        }

        /* Sleep for 500 ms using pigpio's microsecond delay */
        gpioDelay(POLL_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

