#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define DEBOUNCE_US 5000  // 5 ms debounce
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(int s1, int s2) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%d,%d\n", timestamp, s1, s2);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_s1 = gpioRead(SENSOR1_GPIO);
    int last_s2 = gpioRead(SENSOR2_GPIO);
    if (last_s1 < 0 || last_s2 < 0) {
        fprintf(stderr, "Failed to read initial sensor states\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint32_t last_tick = gpioTick();
    int pulse_count = 0;

    while (running) {
        int s1 = gpioRead(SENSOR1_GPIO);
        int s2 = gpioRead(SENSOR2_GPIO);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "GPIO read error\n");
            break;
        }

        uint32_t now = gpioTick();
        if (now - last_tick > DEBOUNCE_US) {
            if (s1 != last_s1 || s2 != last_s2) {
                last_s1 = s1;
                last_s2 = s2;
                last_tick = now;

                if (s1 == 1 && s2 == 0) {
                    pulse_count++;
                } else if (s1 == 0 && s2 == 1) {
                    pulse_count++;
                }

                if (pulse_count >= PULSES_PER_REV) {
                    double elapsed_s = (double)(now - last_tick) / 1000000.0;
                    double rpm = 60.0 / elapsed_s;
                    printf("RPM: %.2f\n", rpm);
                    fflush(stdout);
                    pulse_count = 0;
                }
            }
        }

        log_data(s1, s2);
        gpioDelay(1000);  // 1 ms loop delay
    }

    printf("\nShutting down...\n");
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

