#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27
#define LOG_FILE     "bridge_integrity.log"
#define POLL_DELAY_US 100000  /* 100 ms */
#define ALARM_THRESHOLD_SEC 2

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not open.\n");
        return;
    }
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }
    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", ALARM_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d\n", SENSOR_1_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: Failed to set pull-down on GPIO %d\n", SENSOR_2_PIN);
        return -1;
    }
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to initialize alarm pin LOW\n");
        return -1;
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d\n", pin);
        return -1;
    }
    return value;
}

static void activate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate alarm\n");
    }
}

static void deactivate_alarm(void) {
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate alarm\n");
    }
}

static void cleanup(void) {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");
    log_event("Monitoring started");

    int sensor1_active = 0;
    int sensor2_active = 0;
    time_t sensor1_start_time = 0;
    time_t sensor2_start_time = 0;
    int alarm_active = 0;

    while (program_running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            log_event("Error reading sensor data");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        time_t now = time(NULL);
        if (now == (time_t)-1) {
            fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (s1 == 1) {
            if (!sensor1_active) {
                sensor1_active = 1;
                sensor1_start_time = now;
                log_event("Sensor 1: Tilt threshold exceeded");
            } else if (sensor1_start_time != 0 && (now - sensor1_start_time) >= ALARM_THRESHOLD_SEC) {
                if (!alarm_active) {
                    activate_alarm();
                    alarm_active = 1;
                    log_event("Alarm activated: Sensor 1 exceeded threshold for 2 seconds");
                }
            }
        } else {
            if (sensor1_active) {
                sensor1_active = 0;
                sensor1_start_time = 0;
                log_event("Sensor 1: Tilt restored");
            }
        }

        if (s2 == 1) {
            if (!sensor2_active) {
                sensor2_active = 1;
                sensor2_start_time = now;
                log_event("Sensor 2: Tilt threshold exceeded");
            } else if (sensor2_start_time != 0 && (now - sensor2_start_time) >= ALARM_THRESHOLD_SEC) {
                if (!alarm_active) {
                    activate_alarm();
                    alarm_active = 1;
                    log_event("Alarm activated: Sensor 2 exceeded threshold for 2 seconds");
                }
            }
        } else {
            if (sensor2_active) {
                sensor2_active = 0;
                sensor2_start_time = 0;
                log_event("Sensor 2: Tilt restored");
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    log_event("Monitoring stopped");
    cleanup();
    return 0;
}

