 *
 * Wiring:
 *   D7S-A0011 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   D7S-A0011 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   D7S-A0011 VDD -> 3.3 V
 *   D7S-A0011 GND -> GND
 *   LED anode -> GPIO17 (pin 11) through 330 ohm resistor -> GND
 *
 * Build: gcc -O2 -Wall -o seismic seismic.c -lpigpio -lm -lrt
 * Run:   sudo ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define D7S_I2C_ADDR         0x1D          /* D7S-A0011 default 7-bit address */
#define LED_GPIO             17
#define VIBRATION_THRESHOLD  500.0f        /* arbitrary units */
#define SAMPLE_PERIOD_US     100000        /* 100 ms */
#define MAX_RETRIES          3
#define LOG_FILE             "seismic_events.log"

/* D7S-A0011 register addresses */
#define REG_CTRL1            0x1F          /* Control register 1 */
#define REG_CTRL2            0x20          /* Control register 2 */
#define REG_OUT_X_L          0x28          /* X-axis acceleration (6 bytes) */

/* CTRL1 bits */
#define CTRL1_PD_BIT         0x02          /* Power-down bit (0 = normal) */

/* ------------------------------- Globals --------------------------------- */
static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes -------------------------- */
static int  init_pigpio(void);
static int  init_i2c(void);
static int  init_sensor(void);
static int  read_acceleration(float *x, float *y, float *z);
static float calc_magnitude(float x, float y, float z);
static void control_led(int on);
static void log_event(float magnitude);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    if (init_pigpio() != 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        fprintf(stderr, "Error: I2C initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed (sensor may be absent at 0x%02X).\n",
                D7S_I2C_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            float magnitude = calc_magnitude(x, y, z);

            if (magnitude > VIBRATION_THRESHOLD) {
                log_event(magnitude);
                control_led(1);
                gpioDelay(1000000);          /* 1 s on */
                control_led(0);
            }
        } else {
            fprintf(stderr, "Warning: Failed to read acceleration data.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- pigpio initialization ------------------------- */
static int init_pigpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

/* ----------------------------- I2C initialization -------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, D7S_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, D7S_I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

