/*
 * flame_monitor.c — KY-026 flame sensor monitor for Raspberry Pi 3 B+
 *
 * Sensors: 5x Keyes KY-026 digital flame sensors
 *   BCM GPIO 2, 3, 4, 17, 27  (physical pins 3, 5, 7, 11, 13)
 *   KY-026 DO -> GPIO (LOW = flame detected, HIGH = no flame)
 *   KY-026 VCC -> 3.3 V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor   (needs write access to /var/log)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

#define NUM_SENSORS   5
#define LOG_FILE      "/var/log/flame_events.log"
#define DEBOUNCE_MS   50
#define POLL_MS       1000
#define TIMESTAMP_LEN 32

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* Per-sensor state — line pointers are freed in reverse order of acquisition */
static struct gpiod_line *g_lines[NUM_SENSORS];
static int g_lines_acquired[NUM_SENSORS];   /* 1 = acquired, 0 = not */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        syslog(LOG_WARNING, "sigaction(SIGINT) failed: %s", strerror(errno));
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        syslog(LOG_WARNING, "sigaction(SIGTERM) failed: %s", strerror(errno));
}

/* Return 1 if a flame is currently detected (DO == LOW), 0 otherwise. */
static int is_flame_detected(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        syslog(LOG_ERR, "gpiod_line_get_value failed: %s", strerror(errno));
        return 0;  /* treat read failure as no-flame for safety */
    }
    return (val == 0) ? 1 : 0;
}

/* Debounced flame detection: re-read after DEBOUNCE_MS and confirm. */
static int flame_rising_edge(struct gpiod_line *line, int *prev_state)
{
    int cur = is_flame_detected(line);
    if (cur != *prev_state) {
        struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
        nanosleep(&ts, NULL);
        int confirmed = is_flame_detected(line);
        if (confirmed == cur) {
            *prev_state = cur;
            return 1;
        }
    }
    return 0;
}

static void log_flame_event(int sensor_id, unsigned int pin)
{
    FILE *fp = NULL;
    int fd = -1;
    int ret = -1;
    char ts[TIMESTAMP_LEN];

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r failed");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime failed");
        return;
    }

    fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd == -1) {
        syslog(LOG_ERR, "open(%s) failed: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fd, LOCK_EX) == -1) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        close(fd);
        return;
    }

    fp = fdopen(fd, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "fdopen failed: %s", strerror(errno));
        flock(fd, LOCK_UN);
        close(fd);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - Flame Detected\n",
                ts, sensor_id, pin) < 0) {
        syslog(LOG_ERR, "fprintf failed: %s", strerror(errno));
        ret = -1;
    } else {
        if (fflush(fp) == EOF)
            syslog(LOG_ERR, "fflush failed: %s", strerror(errno));
        else
            ret = 0;
    }

    if (fclose(fp) == EOF && ret == 0)
        syslog(LOG_ERR, "fclose failed: %s", strerror(errno));

    if (ret == 0)
        syslog(LOG_INFO, "Flame event logged for sensor %d (GPIO %u)", sensor_id, pin);
}

static void cleanup(void)
{
    for (int i = NUM_SENSORS - 1; i >= 0; i--) {
        if (g_lines_acquired[i] && g_lines[i]) {
            gpiod_line_release(g_lines[i]);
            g_lines[i] = NULL;
            g_lines_acquired[i] = 0;
        }
    }
}

int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame monitor starting");

    install_signal_handlers();

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
