#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 50

static const unsigned int gpio_pins[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_touch_event(int channel, int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Channel %d (BCM GPIO %u) %s\n",
           timestamp, channel, gpio_pins[channel],
           state ? "Touched" : "Released");
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(prev_states, 0, sizeof(prev_states));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(lines[i], "ttp226-touch") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read initial state of GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
        prev_states[i] = val;
    }

    printf("TTP226 8-Channel Touch Sensor Reader\n");
    printf("Polling every %d ms. Press Ctrl+C to exit.\n", POLL_INTERVAL_MS);
    fflush(stdout);

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
                goto cleanup;
            }

            if (val != prev_states[i]) {
                log_touch_event(i, val);
                prev_states[i] = val;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

