#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n",
            timestamp, lux, brightness, error_code);
    fflush(log_file);
}

static int veml7700_init(void) {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, VEML7700_ADDR, i2c_handle);
        return -1;
    }

    /* Config: ALS gain 1/8 (0x00), ALS integration time 100 ms (0x00) */
    uint16_t config = 0x0000;
    char buf[3];
    buf[0] = VEML7700_CONFIG_REG;
    buf[1] = (char)(config & 0xFF);       /* low byte first */
    buf[2] = (char)((config >> 8) & 0xFF); /* high byte second */

    if (i2cWriteDevice(i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error writing VEML7700 config register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    /* Allow integration time to elapse before first reading */
    gpioDelay(150000); /* 150 ms */
    return 0;
}

static int veml7700_read_lux(float *lux_out) {
    char reg = VEML7700_ALS_REG;
    if (i2cWriteDevice(i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error writing ALS register address\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(unsigned char)data[1] << 8) | (unsigned char)data[0];
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int calculate_brightness(float lux) {
    if (lux < 100.0f) return 100;
    if (lux < 500.0f) return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(LED_GPIO, brightness);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    if (veml7700_init() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float lux = 0.0f;
    int brightness = 0;
    int error_code = 0;

    while (!terminate) {
        error_code = veml7700_read_lux(&lux);
        if (error_code == 0) {
            brightness = calculate_brightness(lux);
            set_led_brightness(brightness);
            log_data(lux, brightness, 0);
        } else {
            fprintf(stderr, "Sensor read error, setting brightness to 0\n");
            set_led_brightness(0);
            log_data(0.0f, 0, error_code);
        }
        gpioDelay(1000000); /* 1 second */
    }

    set_led_brightness(0);
    cleanup();
    return EXIT_SUCCESS;
}

