        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)(unsigned char)data[1] << 8) | (unsigned char)data[0];
    *lux_out = (float)raw * 0.0576f;
    return 0;
}

static int calculate_brightness(float lux) {
    if (lux < 100.0f) return 100;
    if (lux < 500.0f) return 75;
    if (lux < 1000.0f) return 50;
    return 25;
}

static void set_led_brightness(int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(LED_GPIO, brightness);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);

    if (veml7700_init() != 0) {
        fprintf(stderr, "VEML7700 initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float lux = 0.0f;
    int brightness = 0;
    int error_code = 0;

    while (!terminate) {
        error_code = veml7700_read_lux(&lux);
        if (error_code == 0) {
            brightness = calculate_brightness(lux);
            set_led_brightness(brightness);
            log_data(lux, brightness, 0);
        } else {
            fprintf(stderr, "Sensor read error, setting brightness to 0\n");
            set_led_brightness(0);
            log_data(0.0f, 0, error_code);
        }
        gpioDelay(1000000); /* 1 second */
    }

    set_led_brightness(0);
    cleanup();
    return EXIT_SUCCESS;
}

