#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define OPT3001_ADDR        0x44
#define REG_RESULT          0x00
#define REG_CONFIG          0x01
#define CONFIG_CONTINUOUS   0xC810  /* RN=11 (auto-range), CT=100ms, M=11 (continuous) */
#define LOG_FILE            "light_data.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define CONV_WAIT_US        100000   /* 100 ms for first conversion */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Swap bytes: pigpio i2cReadWordData/i2cWriteWordData use little-endian
 * while the OPT3001 expects big-endian (MSB first). */
static uint16_t swap16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static int init_opt3001(int handle)
{
    uint16_t cfg = swap16(CONFIG_CONTINUOUS);
    int rc = i2cWriteWordData(handle, REG_CONFIG, cfg);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteWordData(config=0x%04X) failed: %d\n",
                cfg, rc);
        return -1;
    }
    gpioDelay(CONV_WAIT_US);
    return 0;
}

static int read_lux(int handle, float *lux_out)
{
    int raw = i2cReadWordData(handle, REG_RESULT);
    if (raw < 0) {
        fprintf(stderr, "Error: i2cReadWordData(result) failed: %d\n", raw);
        return -1;
    }
    uint16_t raw_be = swap16((uint16_t)raw);
    uint16_t exponent = (raw_be >> 12) & 0x0F;
    uint16_t mantissa = raw_be & 0x0FFF;
    *lux_out = (float)mantissa * 0.01f * (float)(1u << exponent);
    return 0;
}

static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f\n", ts, lux);
    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, OPT3001_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                OPT3001_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_opt3001(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: OPT3001 initialisation failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("OPT3001 initialised. Logging to '%s' every 1 s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        float lux;
        if (read_lux(g_i2c_handle, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(LOG_FILE, lux) != 0) {
                fprintf(stderr, "Warning: failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: failed to read lux value\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

