#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define GPIO_LEFT   17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT  22
#define LOG_FILE    "path_log.csv"
#define POLL_MS     50

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_data(FILE *fp, int left, int middle, int right)
{
    time_t rawtime;
    struct tm tm_info;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, left, middle, right) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    const unsigned int offsets[3] = { GPIO_LEFT, GPIO_MIDDLE, GPIO_RIGHT };
    int values[3];
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, offsets[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "ky033-path") < 0) {
            fprintf(stderr, "Failed to request GPIO %u as input: %s\n",
                    offsets[i], strerror(errno));
            goto cleanup;
        }
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int v = gpiod_line_get_value(lines[i]);
            if (v < 0) {
                fprintf(stderr, "Failed to read GPIO %u: %s\n",
                        offsets[i], strerror(errno));
                goto cleanup;
            }
            values[i] = v;
        }

        if (log_data(fp, values[0], values[1], values[2]) < 0) {
            goto cleanup;
        }

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
    }
    for (int i = 0; i < 3; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

