#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "touch_log.txt"
#define POLL_DELAY_US 10000   /* 10 ms */
#define DEBOUNCE_DELAY_US 200000 /* 200 ms */

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Best-effort LED off; ignore return on shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

static int log_touch_event(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: gmtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Touch detected\n", timestamp) < 0) {
        fprintf(stderr, "Warning: failed to write to log file\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file\n");
        return -1;
    }

    return 0;
}

int main(void)
{
    int last_state = 0;
    int led_state = 0;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler\n");
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_state < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        /* Rising-edge detection: LOW -> HIGH transition */
        if (current_state == 1 && last_state == 0) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            int debounced = gpioRead(TOUCH_SENSOR_PIN);
            if (debounced < 0) {
                fprintf(stderr, "Error: gpioRead failed during debounce on GPIO%d\n", TOUCH_SENSOR_PIN);
                break;
            }
            if (debounced == 1) {
                /* Valid touch event */
                led_state = !led_state;
                if (gpioWrite(LED_PIN, led_state) != 0) {
                    fprintf(stderr, "Error: gpioWrite failed on GPIO%d\n", LED_PIN);
                    break;
                }

                if (log_touch_event() != 0) {
                    fprintf(stderr, "Warning: failed to log touch event\n");
                }

                printf("Touch detected! LED toggled to %s\n",
                       led_state ? "ON" : "OFF");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    cleanup();
    printf("Exiting gracefully.\n");
    return EXIT_SUCCESS;
}

