#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/*
 * TMAG5110A1 Hall-effect latch magnetic sensor interface for Raspberry Pi 4.
 *
 * Wiring (BCM numbering):
 *   Sensor 1 OUT -> GPIO4  (physical pin 7)
 *   Sensor 2 OUT -> GPIO17 (physical pin 11)
 *   Sensor 3 OUT -> GPIO27 (physical pin 13)
 *
 * The TMAG5110A1 has an open-drain output.  The internal pull-up on each
 * GPIO keeps the line high when no magnet is present.  When a south pole
 * is detected the output goes low (active-low).  Therefore:
 *   GPIO low  -> magnet present
 *   GPIO high -> magnet removed
 *
 * Build:  gcc -Wall -Wextra -O2 -o magnet_monitor magnet_monitor.c -lpigpio -lrt
 * Run:    sudo ./magnet_monitor
 */

#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17
#define SENSOR_3_GPIO 27

#define LOG_FILE_NAME "magnet_log.txt"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, int sensor_id, int state)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    const char *state_str = (state == 0) ? "MAGNET_PRESENT" : "MAGNET_REMOVED";
    fprintf(fp, "%s - Sensor %d: %s\n", ts, sensor_id, state_str);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(int gpio_pin)
{
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", gpio_pin);
        return -1;
    }
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", gpio_pin);
        return -1;
    }
    return 0;
}

static int read_sensor(int gpio_pin)
{
    int level = gpioRead(gpio_pin);
    if (level < 0) {
        fprintf(stderr, "gpioRead(%d) failed\n", gpio_pin);
        return -1;
    }
    return level;  /* 0 = magnet present, 1 = magnet removed */
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor GPIOs --- */
    int pins[3] = {SENSOR_1_GPIO, SENSOR_2_GPIO, SENSOR_3_GPIO};
    for (int i = 0; i < 3; i++) {
        if (init_gpio(pins[i]) != 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        fclose(g_log_fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO4, GPIO17, GPIO27.\n");
    printf("Press Ctrl+C to exit.\n");

    /* --- Read initial states (do not log spurious transitions) --- */
    int prev[3] = {-1, -1, -1};  /* -1 => uninitialized */
    for (int i = 0; i < 3; i++) {
        int s = read_sensor(pins[i]);
        if (s >= 0) {
            prev[i] = s;
        } else {
            fprintf(stderr, "Warning: initial read of sensor %d failed; "
                            "will not log spurious transitions.\n", i + 1);
        }
    }

    /* --- Main polling loop --- */
    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int s = read_sensor(pins[i]);
            if (s < 0) {
                continue;  /* read error already reported */
            }

            if (s != prev[i]) {
                log_event(g_log_fp, i + 1, s);
                prev[i] = s;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

