#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI1182_ADDR 0x4A

#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_LED_CURRENT 0x3F
#define REG_AVG 0x04
#define REG_ENABLE 0x01
#define REG_HR 0x2A

#define EXPECTED_PART_ID 0x02
#define EXPECTED_HW_REV 0x01

#define MIN_BPM 30.0
#define MAX_BPM 220.0
#define MOVING_AVG_SIZE 5
#define SAMPLE_INTERVAL_US 1000000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static float moving_avg_buffer[MOVING_AVG_SIZE];
static int buffer_index = 0;
static int buffer_filled = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int init_sensor(void) {
    uint8_t part_id, hw_rev;

    if (read_reg(REG_PART_ID, &part_id) != 0) return -1;
    if (part_id != EXPECTED_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n", part_id, EXPECTED_PART_ID);
        return -1;
    }

    if (read_reg(REG_HW_REV, &hw_rev) != 0) return -1;
    if (hw_rev != EXPECTED_HW_REV) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X)\n", hw_rev, EXPECTED_HW_REV);
        return -1;
    }

    if (write_reg(REG_LED_CURRENT, 0x3F) != 0) return -1;
    if (write_reg(REG_AVG, 0x04) != 0) return -1;
    if (write_reg(REG_ENABLE, 0x01) != 0) return -1;

    return 0;
}

static int read_heart_rate(float *bpm) {
    int raw = i2cReadWordData(i2c_handle, REG_HR);
    if (raw < 0) {
        fprintf(stderr, "Error reading heart rate: %d\n", raw);
        return -1;
    }
    *bpm = (float)raw * 0.5f;
    return 0;
}

static float moving_average(float new_value) {
    moving_avg_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
    if (buffer_index == 0) buffer_filled = 1;

    float sum = 0.0f;
    int count = buffer_filled ? MOVING_AVG_SIZE : buffer_index;
    for (int i = 0; i < count; i++) sum += moving_avg_buffer[i];
    return sum / (float)count;
}

static int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, bpm) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float bpm;
        if (read_heart_rate(&bpm) == 0) {
            float filtered = moving_average(bpm);
            if (filtered >= MIN_BPM && filtered <= MAX_BPM) {
                if (log_data(filtered) != 0) {
                    fprintf(stderr, "Logging failed, continuing...\n");
                }
            } else {
                fprintf(stderr, "Invalid BPM reading: %.2f\n", filtered);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate, retrying...\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    printf("Exiting.\n");
    return 0;
}

