/*
 * touch_counter.c — Raspberry Pi Zero W
 *
 * Reads 8-channel TTP226 capacitive touch sensors (active-high, 3.3 V touched)
 * on GPIO 5..12 (BCM) and drives an 8-bit binary counter on GPIO 17..24.
 * Logs touch events to touch_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 * Run:    sudo ./touch_counter   (root needed for /dev/gpiochip0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define CHIP_NAME    "gpiochip0"
#define POLL_MS      10
#define STAB_MS      200

/* TTP226 OUT1..OUT8 -> BCM GPIO 5..12 */
static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
/* Binary counter display on BCM GPIO 17..24 */
static const unsigned int display_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(FILE *log, int channel, int counter)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];

    if (localtime_r(&now, &tmv) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tmv) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (log) {
        fprintf(log, "%s, Channel: %d, Counter: %d\n", ts, channel, counter);
        fflush(log);
    }
    printf("%s, Channel: %d, Counter: %d\n", ts, channel, counter);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_request *sensor_req = NULL;
    struct gpiod_line_request *display_req = NULL;
    FILE *log = NULL;
    int counter = 0;
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    memset(prev_states, 0, sizeof(prev_states));

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    log = fopen("touch_log.txt", "a");
    if (!log) {
        fprintf(stderr, "Warning: cannot open touch_log.txt: %s — logging to stdout only\n",
                strerror(errno));
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* --- Configure sensor lines as inputs --- */
    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new (sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "gpiod_line_settings_set_direction: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(line_cfg, &sensor_pins[i], 1, settings) < 0) {
            fprintf(stderr, "gpiod_line_config_add_line_settings (sensor %d): %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    sensor_req = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (!sensor_req) {
        fprintf(stderr, "gpiod_chip_request_lines (sensor): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Configure display lines as outputs, initial value 0 --- */
    line_cfg = gpiod_line_config_new();
    if (!line_cfg) {
        fprintf(stderr, "gpiod_line_config_new (display): %s\n", strerror(errno));
        goto cleanup;
    }

    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "gpiod_line_settings_new (display): %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "gpiod_line_settings_set_direction (display): %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_settings_set_output_value(settings, GPIOD_LINE_VALUE_INACTIVE) < 0) {
        fprintf(stderr, "gpiod_line_settings_set_output_value: %s\n", strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_config_add_line_settings(line_cfg, &display_pins[i], 1, settings) < 0) {
            fprintf(stderr, "gpiod_line_config_add_line_settings (display %d): %s\n",
                    i, strerror(errno));
            goto cleanup;
        }
    }

    display_req = gpiod_chip_request_lines(chip, NULL, line_cfg);
    if (!display_req) {
        fprintf(stderr, "gpiod_chip_request_lines (display): %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Stabilization delay --- */
    usleep(STAB_MS * 1000);

    /* --- Main loop --- */
    while (g_running) {
        int changed = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            enum gpiod_line_value val = gpiod_line_request_get_value(sensor_req, sensor_pins[i]);
            if (val == GPIOD_LINE_VALUE_ERROR) {
                fprintf(stderr, "gpiod_line_request_get_value (sensor %d): %s\n",
                        i, strerror(errno));
                continue;
            }

            if (val == GPIOD_LINE_VALUE_ACTIVE && prev_states[i] == 0) {
                /* Rising edge: new touch */
                counter = (counter + 1) & 0xFF;
                changed = 1;
            }
            prev_states[i] = (val == GPIOD_LINE_VALUE_ACTIVE) ? 1 : 0;
        }

        if (changed) {
            for (int i = 0; i < NUM_CHANNELS; i++) {
                enum gpiod_line_value v = (counter >> i) & 1
                    ? GPIOD_LINE_VALUE_ACTIVE : GPIOD_LINE_VALUE_INACTIVE;
                if (gpiod_line_request_set_value(display_req, display_pins[i], v) < 0) {
                    fprintf(stderr, "gpiod_line_request_set_value (display %d): %s\n",
                            i, strerror(errno));
                }
            }
            log_event(log, 0, counter); /* log with dummy channel 0 for counter state */
        }

        usleep(POLL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* --- Reset outputs to 0 --- */
    if (display_req) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            (void)gpiod_line_request_set_value(display_req, display_pins[i],
                                               GPIOD_LINE_VALUE_INACTIVE);
        }
    }

    /* --- Release requests --- */
    if (sensor_req)  gpiod_line_request_release(sensor_req);
    if (display_req) gpiod_line_request_release(display_req);
    if (line_cfg)    gpiod_line_config_free(line_cfg);
    if (settings)    gpiod_line_settings_free(settings);
    if (chip)        gpiod_chip_close(chip);

    /* --- Close log --- */
    if (log) {
        fclose(log);
    }

    return ret;
}

