#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_SENSORS 4
#define LOG_FILE "tracking_log.csv"
#define POLL_INTERVAL_MS 100

/* BCM GPIO numbers for the four KY-033 OUT pins (active-low: 0 = detected) */
static const unsigned int sensor_pins[NUM_SENSORS] = {17, 18, 27, 22};

