#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_US 100000
#define DEBOUNCE_WINDOW_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *log_file, int sensor_number) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (line1 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line1, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n", GPIO_LINE_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line2, "tilt-monitor", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n", GPIO_LINE_2, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring tilt sensors on GPIO %d and %d. Press Ctrl+C to exit.\n", GPIO_LINE_1, GPIO_LINE_2);

    int prev1 = gpiod_line_get_value(line1);
    int prev2 = gpiod_line_get_value(line2);
    if (prev1 < 0 || prev2 < 0) {
        fprintf(stderr, "Initial GPIO read failed: %s\n", strerror(errno));
        goto cleanup;
    }

    struct timespec last_event_time = {0, 0};

    while (program_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "GPIO read error: %s\n", strerror(errno));
            break;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        if (val1 == 0 && prev1 == 1) {
            if (now.tv_sec - last_event_time.tv_sec > 0 ||
                (now.tv_sec == last_event_time.tv_sec && now.tv_nsec - last_event_time.tv_nsec > DEBOUNCE_WINDOW_US)) {
                if (log_event(log_file, 1) == 0) {
                    last_event_time = now;
                }
            }
        }

        if (val2 == 0 && prev2 == 1) {
            if (now.tv_sec - last_event_time.tv_sec > 0 ||
                (now.tv_sec == last_event_time.tv_sec && now.tv_nsec - last_event_time.tv_nsec > DEBOUNCE_WINDOW_US)) {
                if (log_event(log_file, 2) == 0) {
                    last_event_time = now;
                }
            }
        }

        prev1 = val1;
        prev2 = val2;

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1 != NULL) {
        gpiod_line_release(line1);
    }
    if (line2 != NULL) {
        gpiod_line_release(line2);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return ret;
}

