#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN   17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define POLL_INTERVAL_MS  100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the lines for the sensor pins */
    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (left_line == NULL) {
        perror("gpiod_chip_get_line(LEFT)");
        goto cleanup;
    }
    center_line = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    if (center_line == NULL) {
        perror("gpiod_chip_get_line(CENTER)");
        goto cleanup;
    }
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (right_line == NULL) {
        perror("gpiod_chip_get_line(RIGHT)");
        goto cleanup;
    }

    /* Request the lines as inputs with pull-up enabled (active-low sensors) */
    if (gpiod_line_request_input_flags(left_line, "tracing-left",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(LEFT)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(center_line, "tracing-center",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(CENTER)");
        goto cleanup;
    }
    if (gpiod_line_request_input_flags(right_line, "tracing-right",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(RIGHT)");
        goto cleanup;
    }

    printf("Tracing sensor program started. Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (running) {
        int left_val = gpiod_line_get_value(left_line);
        int center_val = gpiod_line_get_value(center_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || center_val < 0 || right_val < 0) {
            fprintf(stderr, "Error reading sensor values.\n");
            goto cleanup;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left_val, center_val, right_val);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (left_line)   gpiod_line_release(left_line);
    if (center_line) gpiod_line_release(center_line);
    if (right_line)  gpiod_line_release(right_line);
    if (chip)        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

