#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49

#define SI1175_REG_ALS_VIS_DATA0 0x24
#define SI1175_REG_ALS_VIS_DATA1 0x25

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int read_als_data(int fd, uint16_t *als_data) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA0, &lsb) < 0) {
        return -1;
    }
    if (i2c_read_reg8(fd, SI1175_REG_ALS_VIS_DATA1, &msb) < 0) {
        return -1;
    }
    *als_data = ((uint16_t)msb << 8) | lsb;
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1175_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI1175_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Si1175 Heart Rate Sensor Reader\n");
    printf("Bus: %s, Address: 0x%02X\n", I2C_BUS, SI1175_ADDR);
    printf("Press Ctrl+C to exit.\n\n");

    while (running) {
        uint16_t als_data = 0;
        if (read_als_data(fd, &als_data) < 0) {
            fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("ALS Visible Data: %u\n", als_data);
        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

