    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the three GPIO lines */
    left_line = gpiod_chip_get_line(chip, LEFT_PIN);
    if (!left_line) {
