        goto cleanup;
    }
    mid_line = gpiod_chip_get_line(chip, MIDDLE_PIN);
    if (!mid_line) {
        perror("gpiod_chip_get_line (middle)");
        goto cleanup;
    }
    right_line = gpiod_chip_get_line(chip, RIGHT_PIN);
    if (!right_line) {
        perror("gpiod_chip_get_line (right)");
        goto cleanup;
    }

