    if (gpiod_line_request_input(mid_line, "tracking-sensor") < 0) {
        perror("gpiod_line_request_input (middle)");
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "tracking-sensor") < 0) {
        perror("gpiod_line_request_input (right)");
        goto cleanup;
    }

