    while (running) {
        int lv = gpiod_line_get_value(left_line);
        int mv = gpiod_line_get_value(mid_line);
        int rv = gpiod_line_get_value(right_line);

        if (lv < 0 || mv < 0 || rv < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

