    float t  = v * (1.0f - s * (1.0f - ff));
    float rf, gf, bf;
    switch (i) {
        case 0: rf = v; gf = t; bf = p; break;
        case 1: rf = q; gf = v; bf = p; break;
        case 2: rf = p; gf = v; bf = t; break;
        case 3: rf = p; gf = q; bf = v; break;
        case 4: rf = t; gf = p; bf = v; break;
        default: rf = v; gf = p; bf = q; break;
    }
    *r = (int)(rf * 255.0f);
    *g = (int)(gf * 255.0f);
    *b = (int)(bf * 255.0f);
}

static int set_led_color(int r, int g, int b) {
    int rr = (r < 0) ? 0 : (r > 255) ? 255 : r;
    int gg = (g < 0) ? 0 : (g > 255) ? 255 : g;
    int bb = (b < 0) ? 0 : (b > 255) ? 255 : b;
    int inv_r = PWM_RANGE - rr;
    int inv_g = PWM_RANGE - gg;
    int inv_b = PWM_RANGE - bb;
    if (gpioPWM(RED_PIN, inv_r) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on RED_PIN: %s", pigpio_error(0));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, inv_g) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on GREEN_PIN: %s", pigpio_error(0));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, inv_b) < 0) {
        syslog(LOG_ERR, "gpioPWM failed on BLUE_PIN: %s", pigpio_error(0));
        return -1;
    }
    return 0;
}

static int fade_to_color(int tr, int tg, int tb) {
    int cr, cg, cb;
    if (set_led_color(tr, tg, tb) < 0) return -1;
    for (int i = 1; i <= FADE_STEPS && g_running; i++) {
        float t = (float)i / (float)FADE_STEPS;
        cr = tr * t;
        cg = tg * t;
        cb = tb * t;
        if (set_led_color(cr, cg, cb) < 0) return -1;
        gpioDelay(FADE_SEC * 1000000 / FADE_STEPS);
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed on RED_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed on GREEN_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode failed on BLUE_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed on RED_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed on GREEN_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        syslog(LOG_ERR, "gpioSetPWMfrequency failed on BLUE_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on RED_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on GREEN_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "gpioSetPWMrange failed on BLUE_PIN: %s", pigpio_error(0));
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return 1;
    }
    srand((unsigned int)time(NULL));
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "Mood lamp started");
    while (g_running) {
        float hue = (float)(rand() % 360);
        int tr, tg, tb;
        hsv_to_rgb(hue, 1.0f, 1.0f, &tr, &tg, &tb);
        if (fade_to_color(tr, tg, tb) < 0) {
            syslog(LOG_ERR, "Fade failed, continuing");
        }
    }
    syslog(LOG_INFO, "Mood lamp shutting down");
    cleanup();
    return 0;
}

