/*
 * TCS34725 color sensor reader with LED threshold indicator.
 * Board:  Raspberry Pi 4 Model B
 * Library: libgpiod (GPIO), Linux i2c-dev (I2C)
 * Sensor:  TCS34725 at I2C address 0x29 on /dev/i2c-1
 * LED:     GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -Wextra -o tcs34725 tcs34725.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- TCS34725 constants (from datasheet) ---- */
#define TCS34725_I2C_ADDR        0x29
#define TCS34725_CMD_BIT         0x80
#define TCS34725_REG_ENABLE      0x00
#define TCS34725_REG_ATIME       0x01
#define TCS34725_REG_CONTROL     0x0F
#define TCS34725_REG_ID          0x12
#define TCS34725_REG_CDATA       0x14
#define TCS34725_REG_RDATA       0x16
#define TCS34725_REG_GDATA       0x18
#define TCS34725_REG_BDATA       0x1A

#define TCS34725_ENABLE_PON      0x01
#define TCS34725_ENABLE_AEN      0x02
#define TCS34725_ID_VALUE        0x44

#define I2C_BUS                 "/dev/i2c-1"
#define GPIO_CHIP               "gpiochip4"
#define GPIO_LED                17
#define RED_THRESHOLD           200
#define POLL_MS                 200

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_chip  *g_chip = NULL;
static struct gpiod_line  *g_led  = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void sleep_ms(unsigned int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Write one byte to an 8-bit TCS34725 register.                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tcs_write8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(TCS34725_CMD_BIT | reg), value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "tcs_write8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an 8-bit TCS34725 register.                       */
/* Returns the byte value (0-255) on success, -1 on error.              */
/* ------------------------------------------------------------------ */
static int tcs_read8(int fd, uint8_t reg)
{
    uint8_t cmd = (uint8_t)(TCS34725_CMD_BIT | reg);
    ssize_t n = write(fd, &cmd, 1);
    if (n != 1) {
        fprintf(stderr, "tcs_read8(0x%02X) write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    n = read(fd, &val, 1);
    if (n != 1) {
        fprintf(stderr, "tcs_read8(0x%02X) read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return (int)val;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian channel register.                        */
/* Returns the value (0-65535) on success, -1 on error.                */
/* ------------------------------------------------------------------ */
static int tcs_read16(int fd, uint8_t reg)
{
    int lo = tcs_read8(fd, reg);
    if (lo < 0) return -1;
    int hi = tcs_read8(fd, (uint8_t)(reg + 1));
    if (hi < 0) return -1;
    return (hi << 8) | lo;
}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725: power on, set ATIME=0x00 (154 ms),         */
/* CONTROL=0x00 (1x gain), enable RGBC.                                 */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tcs_init(int fd)
{
    if (tcs_write8(fd, TCS34725_REG_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    sleep_ms(3);  /* power-on delay */

    if (tcs_write8(fd, TCS34725_REG_ATIME, 0x00) < 0)
        return -1;
    if (tcs_write8(fd, TCS34725_REG_CONTROL, 0x00) < 0)
        return -1;
    if (tcs_write8(fd, TCS34725_REG_ENABLE,
                   TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    sleep_ms(3);  /* integration time */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Power down the TCS34725.                                            */
/* ------------------------------------------------------------------ */
static void tcs_power_down(int fd)
{
    (void)tcs_write8(fd, TCS34725_REG_ENABLE, 0x00);
}

/* ------------------------------------------------------------------ */
/* Verify sensor identity and re-init on failure.                      */
/* Returns 0 on success, -1 on persistent failure.                     */
/* ------------------------------------------------------------------ */
static int tcs_verify_and_reinit(int fd)
{
    int id = tcs_read8(fd, TCS34725_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Failed to read ID register.\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x%02X).\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    if (tcs_init(fd) < 0) {
        fprintf(stderr, "TCS34725 re-initialization failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channel values.                                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tcs_read_all(int fd, uint16_t *c, uint16_t *r,
                        uint16_t *g, uint16_t *b)
{
    int v;
    v = tcs_read16(fd, TCS34725_REG_CDATA); if (v < 0) return -1; *c = (uint16_t)v;
    v = tcs_read16(fd, TCS34725_REG_RDATA); if (v < 0) return -1; *r = (uint16_t)v;
    v = tcs_read16(fd, TCS34725_REG_GDATA); if (v < 0) return -1; *g = (uint16_t)v;
    v = tcs_read16(fd, TCS34725_REG_BDATA); if (v < 0) return -1; *b = (uint16_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Per-channel calibration (example values — calibrate for your part). */
/* ------------------------------------------------------------------ */
static uint16_t calibrate_channel(uint16_t raw)
{
    const float offset = 0.0f;
    const float scale  = 1.0f;
    return (uint16_t)(offset + raw * scale);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_led) {
        gpiod_line_set_value(g_led, 0);
        gpiod_line_release(g_led);
        g_led = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        tcs_power_down(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Verify sensor identity ---- */
    int id = tcs_read8(g_i2c_fd, TCS34725_REG_ID);
    if (id < 0) {
        fprintf(stderr, "Cannot read TCS34725 ID — sensor absent or bus error.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected sensor ID 0x%02X (expected 0x%02X).\n",
                id, TCS34725_ID_VALUE);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (tcs_init(g_i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and request LED line ---- */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        tcs_power_down(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    g_led = gpiod_chip_get_line(g_chip, GPIO_LED);
    if (!g_led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LED, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        tcs_power_down(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_led, "tcs34725-led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO line %d as output: %s\n",
                GPIO_LED, strerror(errno));
        gpiod_line_release(g_led);
        g_led = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        tcs_power_down(g_i2c_fd);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("TCS34725 ready. Polling every %d ms. Press Ctrl-C to exit.\n",
           POLL_MS);

    /* ---- Main loop ---- */
    while (g_running) {
        uint16_t c, r, g, b;

        if (tcs_read_all(g_i2c_fd, &c, &r, &g, &b) < 0) {
            fprintf(stderr, "Read error — attempting re-initialization.\n");
            if (tcs_verify_and_reinit(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed; exiting.\n");
                break;
            }
            sleep_ms(POLL_MS);
            continue;
        }

        r = calibrate_channel(r);
        g = calibrate_channel(g);
        b = calibrate_channel(b);
        c = calibrate_channel(c);

        printf("C=%5u  R=%5u  G=%5u  B=%5u  ->  LED %s\n",
               c, r, g, b, (r > RED_THRESHOLD) ? "ON" : "OFF");

        if (gpiod_line_set_value(g_led, (r > RED_THRESHOLD) ? 1 : 0) < 0) {
            fprintf(stderr, "Warning: failed to set LED: %s\n",
                    strerror(errno));
        }

        sleep_ms(POLL_MS);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

