#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define LED_PIN 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS 1
#define MAX_LUX 1000.0f
#define MIN_LUX 0.0f
#define MAX_BRIGHTNESS 255
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define BH1750_MEASUREMENT_DELAY_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void set_led_brightness(int led_index, int brightness) {
    if (led_index < 0 || led_index >= NUM_LEDS) return;
    if (brightness < 0) brightness = 0;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;

    /* WS2812B expects GRB order; each color is 8 bits, 3 colors = 24 bits.
     * pigpio hardware PWM on GPIO18 supports 8-bit per-channel PWM.
     * We send the 24-bit color value as a single PWM pulse via gpioPWM.
     * For WS2812B timing, a 1 us high pulse = 1 bit, 0 us high pulse = 0 bit.
     * pigpio's gpioPWM uses a 1 us tick, so a 24-bit value directly maps to
     * 24 us of PWM duty cycle (0-255 out of 255 for 100% duty).
     * We use gpioPWM with a 1 us tick and a 24-bit range (0-255).
     */
    gpioPWM(LED_PIN, brightness);
}

static float read_bh1750(int handle) {
    char cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cWriteDevice(handle, &cmd, 1);
        if (result == 0) break;
        fprintf(stderr, "I2C write error (attempt %d/%d): %d\n", i + 1, RETRY_COUNT, result);
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (result != 0) {
        fprintf(stderr, "Failed to write to BH1750 after %d retries.\n", RETRY_COUNT);
        return -1.0f;
    }

    gpioDelay(BH1750_MEASUREMENT_DELAY_MS * 1000);

    for (int i = 0; i < RETRY_COUNT; i++) {
        result = i2cReadDevice(handle, buf, 2);
        if (result == 2) break;
        fprintf(stderr, "I2C read error (attempt %d/%d): %d\n", i + 1, RETRY_COUNT, result);
        gpioDelay(RETRY_DELAY_MS * 1000);
    }
    if (result != 2) {
        fprintf(stderr, "Failed to read from BH1750 after %d retries.\n", RETRY_COUNT);
        return -1.0f;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return (float)raw / 1.2f;
}

static int calculate_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;

    /* Logarithmic mapping: light -> brightness.
     * Logarithmic scaling prevents the LEDs from being overwhelmed by very
     * bright ambient light and provides a more natural visual response.
     */
    float normalized = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    float log_scaled = log10f(normalized + 1.0f) / log10f(2.0f);
    float brightness_f = (log_scaled + 1.0f) * 0.5f * (float)MAX_BRIGHTNESS;
    if (brightness_f < 0.0f) brightness_f = 0.0f;
    if (brightness_f > (float)MAX_BRIGHTNESS) brightness_f = (float)MAX_BRIGHTNESS;
    return (int)brightness_f;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d.\n", BH1750_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    /* Set GPIO18 to output mode for PWM control of the LED strip. */
    gpioSetMode(LED_PIN, PI_OUTPUT);

    while (running) {
        float lux = read_bh1750(i2c_handle);
        if (lux < 0.0f) {
            fprintf(stderr, "Error reading light level. Using default brightness.\n");
            lux = MAX_LUX / 2.0f;
        }

        int brightness = calculate_brightness(lux);
        set_led_brightness(0, brightness);

        gpioDelay(100000); /* 100 ms */
    }

    /* Turn off all LEDs before exiting. */
    set_led_brightness(0, 0);
    cleanup();
    return 0;
}

