#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define BH1750_ONE_TIME_HIGH_RES 0x20
#define BH1750_CONV_TIME_MS 120

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define NUM_LEDS 10
#define START_FRAME_SIZE 4
#define LED_FRAME_SIZE 4
#define END_FRAME_SIZE 4
#define TOTAL_FRAME_SIZE (START_FRAME_SIZE + (NUM_LEDS * LED_FRAME_SIZE) + END_FRAME_SIZE)

#define MIN_LUX 10.0f
#define MAX_LUX 300.0f
#define MIN_BRIGHTNESS 0
#define MAX_BRIGHTNESS 31

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_init(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    uint8_t cmd = BH1750_ONE_TIME_HIGH_RES;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing BH1750 command: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    usleep(BH1750_CONV_TIME_MS * 1000);
    return 0;
}

static int bh1750_read_lux(float *lux) {
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C device not initialized\n");
        return -1;
    }

    uint8_t buf[2];
    ssize_t bytes = read(i2c_fd, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading BH1750 data: %s\n", bytes < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int map_lux_to_brightness(float lux) {
    if (lux < MIN_LUX) lux = MIN_LUX;
    if (lux > MAX_LUX) lux = MAX_LUX;

    float normalized = (lux - MIN_LUX) / (MAX_LUX - MIN_LUX);
    int brightness = (int)(normalized * (MAX_BRIGHTNESS - MIN_BRIGHTNESS) + MIN_BRIGHTNESS);
    if (brightness < MIN_BRIGHTNESS) brightness = MIN_BRIGHTNESS;
    if (brightness > MAX_BRIGHTNESS) brightness = MAX_BRIGHTNESS;
    return brightness;
}

static int apa102_send_frame(const uint8_t *frame, size_t len) {
    uint8_t tx[len];
    uint8_t rx[len];
    memcpy(tx, frame, len);

    if (spi_transfer(tx, rx, len) < 0) {
        return -1;
    }
    return 0;
}

static int apa102_set_brightness(int brightness) {
    if (brightness < MIN_BRIGHTNESS || brightness > MAX_BRIGHTNESS) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    uint8_t frame[TOTAL_FRAME_SIZE];
    size_t idx = 0;

    memset(frame + idx, 0x00, START_FRAME_SIZE);
    idx += START_FRAME_SIZE;

    for (int i = 0; i < NUM_LEDS; i++) {
        frame[idx++] = 0xE0 | (uint8_t)brightness;
        frame[idx++] = 0x00; // Blue
        frame[idx++] = 0x00; // Green
        frame[idx++] = 0x00; // Red
    }

    memset(frame + idx, 0xFF, END_FRAME_SIZE);
    idx += END_FRAME_SIZE;

    if (apa102_send_frame(frame, TOTAL_FRAME_SIZE) < 0) {
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        uint8_t off_frame[TOTAL_FRAME_SIZE];
        memset(off_frame, 0x00, TOTAL_FRAME_SIZE);
        apa102_send_frame(off_frame, TOTAL_FRAME_SIZE);
        close(spi_fd);
        spi_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    if (bh1750_init() < 0) {
        cleanup();
        return 1;
    }

    if (apa102_set_brightness(0) < 0) {
        cleanup();
        return 1;
    }

    while (running) {
        float lux;
        if (bh1750_read_lux(&lux) < 0) {
            fprintf(stderr, "Sensor read failed, retrying...\n");
            usleep(500000);
            continue;
        }

        int brightness = map_lux_to_brightness(lux);
        if (apa102_set_brightness(brightness) < 0) {
            fprintf(stderr, "APA102 update failed\n");
        }

        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        usleep(100000);
    }

    cleanup();
    return 0;
}

