#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_SENSORS 3
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define BH1750_CMD_OT_HRES2 0x21
#define BH1750_CONV_MS 180
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_FLAGS 0
#define NUM_LEDS 16
#define FADE_STEPS 50
#define FADE_DELAY_US 10000
#define LOOP_DELAY_US 100000

static int i2c_handles[NUM_SENSORS];
static int num_sensors = 0;
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_bh1750(int handle, float *lux_out) {
    char cmd = BH1750_CMD_OT_HRES2;
    if (i2cWriteDevice(handle, &cmd, 1) != 0) {
        return -1;
    }
    gpioDelay(BH1750_CONV_MS * 1000);
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        return -1;
    }
    uint16_t raw = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int calculate_brightness(float avg_lux) {
    if (avg_lux < 0.0f) return 0;
    if (avg_lux > 1000.0f) return 31;
    return (int)((1000.0f - avg_lux) / 31.25f);
}

static int set_apa102_brightness(int brightness) {
    if (brightness < 0 || brightness > 31) return -1;
    char data[4 + NUM_LEDS * 4];
    for (int i = 0; i < 4; i++) {
        data[i] = 0x00;
    }
    for (int i = 0; i < NUM_LEDS; i++) {
        data[4 + i * 4] = 0xE0 | (brightness & 0x1F);
        data[4 + i * 4 + 1] = 0x00;
        data[4 + i * 4 + 2] = 0x00;
        data[4 + i * 4 + 3] = 0x00;
    }
    if (spiWrite(spi_handle, data, sizeof(data)) != 0) {
        return -1;
    }
    return 0;
}

static int fade_brightness(int current, int target) {
    if (current == target) return 0;
    int step = (target > current) ? 1 : -1;
    int diff = abs(target - current);
    for (int i = 0; i < diff && running; i++) {
        current += step;
        if (set_apa102_brightness(current) != 0) {
            return -1;
        }
        gpioDelay(FADE_DELAY_US);
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        set_apa102_brightness(0);
        spiClose(spi_handle);
        spi_handle = -1;
    }
    for (int i = 0; i < num_sensors; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = -1;
    }

    int addr_list[NUM_SENSORS] = {BH1750_ADDR_LOW, BH1750_ADDR_HIGH};
    for (int i = 0; i < NUM_SENSORS; i++) {
        int h = i2cOpen(I2C_BUS, addr_list[i], 0);
        if (h >= 0) {
            i2c_handles[i] = h;
            num_sensors++;
        } else {
            fprintf(stderr, "Warning: BH1750 at 0x%02X not found (err=%d)\n", addr_list[i], h);
        }
    }

    if (num_sensors == 0) {
        fprintf(stderr, "No BH1750 sensors detected. Exiting.\n");
        cleanup();
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (err=%d)\n", spi_handle);
        cleanup();
        return 1;
    }

    int current_brightness = 0;
    float lux_sum = 0.0f;
    int valid_sensors = 0;

    while (running) {
        lux_sum = 0.0f;
        valid_sensors = 0;
        for (int i = 0; i < num_sensors; i++) {
            float lux;
            if (read_bh1750(i2c_handles[i], &lux) == 0) {
                lux_sum += lux;
                valid_sensors++;
            } else {
                fprintf(stderr, "Warning: BH1750 read error on handle %d\n", i2c_handles[i]);
            }
        }

        if (valid_sensors > 0) {
            float avg_lux = lux_sum / (float)valid_sensors;
            int target = calculate_brightness(avg_lux);
            if (fade_brightness(current_brightness, target) != 0) {
                fprintf(stderr, "SPI write error during fade\n");
                break;
            }
            current_brightness = target;
        } else {
            fprintf(stderr, "No valid BH1750 readings. Keeping current brightness.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

