#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define VEML7700_CONFIG_REG 0x00
#define VEML7700_ALS_DATA_REG 0x04
#define I2C_BUS "/dev/i2c-1"
#define GPIO_CHIP "gpiochip4"
#define GPIO_PIN 18
#define MAX_LUX 120000.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

static volatile sig_atomic_t running = 1;
static struct gpiod_line *led_line = NULL;
static int i2c_fd = -1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3] = {reg, (uint8_t)(value & 0xFF), (uint8_t)((value >> 8) & 0xFF)};
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int veml7700_init(int fd) {
    if (i2c_write_reg16(fd, VEML7700_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Failed to initialize VEML7700\n");
        return -1;
    }
    usleep(10000);
    return 0;
}

int veml7700_read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_reg16(fd, VEML7700_ALS_DATA_REG, &raw) < 0) {
        return -1;
    }
    *lux = (float)raw * 0.0288f;
    return 0;
}

void set_led_brightness(struct gpiod_line *line, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > 255) brightness = 255;
    int on_time = brightness * 10;
    int off_time = (255 - brightness) * 10;
    gpiod_line_set_value(line, 1);
    usleep(on_time);
    gpiod_line_set_value(line, 0);
    usleep(off_time);
}

void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        cleanup();
        return 1;
    }
    if (veml7700_init(i2c_fd) < 0) {
        cleanup();
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(led_line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }

    while (running) {
        float lux = 0.0f;
        int retries = 0;
        int success = 0;
        while (retries < RETRY_COUNT && !success) {
            if (veml7700_read_lux(i2c_fd, &lux) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < RETRY_COUNT) {
                    usleep(RETRY_DELAY_MS * 1000);
                }
            }
        }
        if (!success) {
            fprintf(stderr, "Failed to read lux after %d retries\n", RETRY_COUNT);
            lux = 0.0f;
        }

        float brightness = 255.0f * powf(lux / MAX_LUX, 1.0f / 2.2f);
        if (brightness < 0.0f) brightness = 0.0f;
        if (brightness > 255.0f) brightness = 255.0f;

        set_led_brightness(led_line, (int)brightness);

        printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);
        usleep(LOOP_DELAY_MS * 1000);
    }

    cleanup();
    gpiod_chip_close(chip);
    return 0;
}

