#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define POLL_INTERVAL_US 50000
#define SELF_TEST_READINGS 5
#define SELF_TEST_DELAY_US 100000
#define SELF_TEST_BLINK_ON_MS 500
#define SELF_TEST_BLINK_OFF_MS 500
#define SELF_TEST_RAPID_ON_MS 100
#define SELF_TEST_RAPID_OFF_MS 100
#define BUZZER_SHORT_MS 200
#define BUZZER_LONG_MS 600
#define BUZZER_REPEATS 3
#define LED_BLINK_MS 500
#define LED_RAPID_MS 100

static volatile sig_atomic_t program_running = 1;

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
    fflush(stdout);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("Failed to open gpiochip4");
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!flame_line || !buzzer_line || !led_line) {
        perror("Failed to get GPIO lines");
        return -1;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        perror("Failed to request flame sensor line as input");
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Failed to request buzzer line as output");
        return -1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        perror("Failed to request LED line as output");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    if (flame_line) {
        gpiod_line_release(flame_line);
        flame_line = NULL;
    }
    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
        buzzer_line = NULL;
    }
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int self_test(void) {
    log_event("Starting self-test...");

    /* Blink LED twice: 500 ms on, 500 ms off */
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Failed to set LED on during self-test");
        return -1;
    }
    usleep(SELF_TEST_BLINK_ON_MS * 1000);
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Failed to set LED off during self-test");
        return -1;
    }
    usleep(SELF_TEST_BLINK_OFF_MS * 1000);

    /* Read flame sensor 5 times at 100 ms intervals */
    int flame_detected = 0;
    for (int i = 0; i < SELF_TEST_READINGS; i++) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            perror("Failed to read flame sensor during self-test");
            return -1;
        }
        if (val == 0) {
            flame_detected = 1;
        }
        usleep(SELF_TEST_DELAY_US);
    }

    if (!flame_detected) {
        log_event("Self-test failed: flame sensor not detected during self-test.");
        return -1;
    }

    log_event("Self-test passed.");
    return 0;
}

static void activate_alarm(void) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Failed to activate buzzer");
    }
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Failed to activate LED");
    }
}

static void deactivate_alarm(void) {
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Failed to deactivate buzzer");
    }
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Failed to deactivate LED");
    }
}

static void error_sequence(void) {
    log_event("Error sequence triggered.");

    /* Rapid LED blinking: 100 ms on/off for 5 cycles */
    for (int i = 0; i < 5 && program_running; i++) {
        if (gpiod_line_set_value(led_line, 1) < 0) {
            perror("Failed to set LED on during error sequence");
            return;
        }
        usleep(LED_RAPID_MS * 1000);
        if (gpiod_line_set_value(led_line, 0) < 0) {
            perror("Failed to set LED off during error sequence");
            return;
        }
        usleep(LED_RAPID_MS * 1000);
    }

    /* Buzzer pattern: short-short-long-short repeated 3 times */
    for (int i = 0; i < BUZZER_REPEATS && program_running; i++) {
        if (gpiod_line_set_value(buzzer_line, 1) < 0) {
            perror("Failed to activate buzzer during error sequence");
            return;
        }
        usleep(BUZZER_SHORT_MS * 1000);
        if (gpiod_line_set_value(buzzer_line, 0) < 0) {
            perror("Failed to deactivate buzzer during error sequence");
            return;
        }
        usleep(BUZZER_SHORT_MS * 1000);
        if (gpiod_line_set_value(buzzer_line, 1) < 0) {
            perror("Failed to activate buzzer during error sequence");
            return;
        }
        usleep(BUZZER_LONG_MS * 1000);
        if (gpiod_line_set_value(buzzer_line, 0) < 0) {
            perror("Failed to deactivate buzzer during error sequence");
            return;
        }
        if (i < BUZZER_REPEATS - 1) {
            usleep(BUZZER_SHORT_MS * 1000);
        }
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (init_gpio() < 0) {
        log_event("GPIO initialization failed. Exiting.");
        cleanup_gpio();
        return 1;
    }

    if (self_test() < 0) {
        log_event("Self-test failed. Exiting.");
        cleanup_gpio();
        return 1;
    }

    log_event("Flame sensor monitoring started.");

    int flame_active = 0;

    while (program_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            perror("Failed to read flame sensor");
            log_event("Error reading flame sensor.");
            error_sequence();
            cleanup_gpio();
            return 1;
        }

        if (val == 0 && !flame_active) {
            log_event("Flame detected!");
            activate_alarm();
            flame_active = 1;
        } else if (val == 1 && flame_active) {
            log_event("Flame gone.");
            deactivate_alarm();
            flame_active = 0;
        }

        usleep(POLL_INTERVAL_US);
    }

    log_event("Shutting down...");
    deactivate_alarm();
    cleanup_gpio();
    return 0;
}

