#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define LED_GPIO 17
#define BUFFER_SIZE 60
#define MIN_BLINK_RATE 0.5
#define MAX_BLINK_RATE 5.0
#define MIN_LUX 0.0
#define MAX_LUX 1000.0

static int i2c_fd = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *value) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    *value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_byte(fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        return -1;
    }
    usleep(180000); // Wait for first measurement (max 180ms)
    return 0;
}

static float read_lux(int fd) {
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0) {
        return -1.0f;
    }
    return (float)raw / 1.2f;
}

static void init_led_gpio(void) {
    FILE *fp = fopen("/sys/class/gpio/export", "w");
    if (fp) {
        fprintf(fp, "%d", LED_GPIO);
        fclose(fp);
    }
    usleep(100000);
    fp = fopen("/sys/class/gpio/gpio17/direction", "w");
