#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

static volatile int keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

/* Display digit '5' on a common-cathode 7-segment display via 74HC595.
 * Segments a,b,c,d,e,f,g,dp (in that order) are encoded as bits 0-6,7.
 * Common-cathode: 1 = segment ON. */
static const unsigned char digit5[8] = {1,1,1,0,1,1,1,0};

void shift_out(struct gpiod_line *data, struct gpiod_line *clock, struct gpiod_line *latch, const unsigned char *data_bits) {
    gpiod_line_set_value(latch, 0);
    for (int i = 7; i >= 0; i--) {
        gpiod_line_set_value(data, data_bits[i]);
        gpiod_line_set_value(clock, 1);
        gpiod_line_set_value(clock, 0);
    }
    gpiod_line_set_value(latch, 1);
    gpiod_line_set_value(latch, 0);
}

int main(void) {
    struct gpiod_chip *chip;
    struct gpiod_line *data_line, *clock_line, *latch_line;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!data_line || !clock_line || !latch_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(data_line, "seven-seg", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output data");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(clock_line, "seven-seg", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output clock");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    ret = gpiod_line_request_output(latch_line, "seven-seg", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output latch");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        shift_out(data_line, clock_line, latch_line, digit5);
        usleep(500000);
        if (!keep_running) break;
        shift_out(data_line, clock_line, latch_line, digit5);
        usleep(500000);
    }

    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

