#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define BLINK_INTERVAL_US 1000000  /* 1 second */

static volatile sig_atomic_t keep_running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get LED line */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line (LED)");
        goto cleanup;
    }

    /* Request LED line as output, initially low */
    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        perror("gpiod_line_request_output (LED)");
        goto cleanup;
    }

    /* Get button line */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line (button)");
        goto cleanup;
    }

    /* Request button line as input with pull-up and falling-edge events */
    if (gpiod_line_request_falling_edge_events_flags(button_line, "blink_button",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_falling_edge_events_flags (button)");
        goto cleanup;
    }

    printf("Blinking LED on BCM GPIO%d, button on BCM GPIO%d. Press Ctrl+C or button to exit.\n",
           LED_PIN, BUTTON_PIN);

    int led_state = 0;
    int blink_active = 1;

    while (keep_running) {
        if (blink_active) {
            led_state = !led_state;
            if (gpiod_line_set_value(led_line, led_state) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("LED %s\n", led_state ? "ON" : "OFF");
            usleep(BLINK_INTERVAL_US);
        }

        /* Check for button event with 1-second timeout */
        struct timespec ts = {1, 0};
        int ev = gpiod_line_event_wait(button_line, &ts);
        if (ev < 0) {
            perror("gpiod_line_event_wait");
            goto cleanup;
        }
        if (ev > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(button_line, &event) < 0) {
                perror("gpiod_line_event_read");
                goto cleanup;
            }
            printf("Button pressed! Stopping blink.\n");
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value (off)");
                goto cleanup;
            }
            blink_active = 0;
            ret = EXIT_SUCCESS;
            break;
        }
    }

cleanup:
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

