#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5
#define BLINK_DELAY_MS 750

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(LED_GPIO, 1) != 0) {
            fprintf(stderr, "Failed to write GPIO%d high\n", LED_GPIO);
            break;
        }
        printf("LED ON\n");
        fflush(stdout);
        gpioDelay(BLINK_DELAY_MS * 1000);

        if (!running) break;

        if (gpioWrite(LED_GPIO, 0) != 0) {
            fprintf(stderr, "Failed to write GPIO%d low\n", LED_GPIO);
            break;
        }
        printf("LED OFF\n");
        fflush(stdout);
        gpioDelay(BLINK_DELAY_MS * 1000);
    }

    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

