#include <signal.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define CHIP_NAME "gpiochip0"
#define CONSUMER "led_button"

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line (GPIO24) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    /* Get the button line (GPIO22) */
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("gpiod_chip_get_line(button)");
        goto cleanup;
    }

    /* Request LED line as output, initially low */
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    /* Request button line as input with pull-down */
    if (gpiod_line_request_input_flags(button_line, CONSUMER,
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(button)");
        goto cleanup;
    }

    printf("LED control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        int val = gpiod_line_get_value(button_line);
        if (val < 0) {
            perror("gpiod_line_get_value(button)");
            break;
        }

        if (val == 0) {
            /* Button pressed: blink LED */
            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led on)");
                break;
            }
            usleep(500000); /* 500 ms */

            if (!keep_running) break;

            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led off)");
                break;
            }
            usleep(500000); /* 500 ms */
        } else {
            /* Button released: ensure LED is off */
            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led off)");
                break;
            }
            usleep(10000); /* 10 ms poll interval */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nResources released. Exiting.\n");
    }
    return ret;
}

