#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS 10000000  // 10 ms = 100 Hz
#define PWM_STEP_NS   100000    // 100 us per step
#define STEP_COUNT    100       // 100 steps = 10 ms total

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static volatile sig_atomic_t keep_running = 1;

void cleanup_and_exit(int signum) {
    (void)signum;
    keep_running = 0;
}

void release_resources(void) {
    if (red_line) {
        gpiod_line_release(red_line);
        red_line = NULL;
    }
    if (green_line) {
        gpiod_line_release(green_line);
        green_line = NULL;
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
        blue_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = cleanup_and_exit;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("gpiod_chip_open_by_number");
        return 1;
    }

    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        release_resources();
        return 1;
    }

    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(green_line, "rgb_led", 0) < 0 ||
        gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as outputs\n");
        release_resources();
        return 1;
    }

    srand(time(NULL));

    while (keep_running) {
        int red_val = rand() % 101;
        int green_val = rand() % 101;
        int blue_val = rand() % 101;

        // Set target values
        gpiod_line_set_value(red_line, red_val > 50 ? 1 : 0);
        gpiod_line_set_value(green_line, green_val > 50 ? 1 : 0);
        gpiod_line_set_value(blue_line, blue_val > 50 ? 1 : 0);

        // Wait 100 ms
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100000000 };
        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }

    release_resources();
    return 0;
}

