#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SAMPLE_INTERVAL_US 500000
#define RETRY_DELAY_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adpd188bi_init(void) {
    if (i2cWriteByteData(i2c_handle, MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write MODE register (0x%02X)\n", MODE_REG);
        return -1;
    }
    return 0;
}

static int adpd188bi_read_16bit(uint8_t reg_lsb, uint8_t reg_msb, uint16_t *value) {
    int lsb = i2cReadByteData(i2c_handle, reg_lsb);
    if (lsb < 0) {
        fprintf(stderr, "Error: Failed to read LSB register 0x%02X\n", reg_lsb);
