#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* FXOS8700CQ I2C address (SA0 tied high on Adafruit breakout) */
#define FXOS8700_ADDR 0x1F

/* FXOS8700CQ register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_XYZ_DATA_CFG 0x0E
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_OUT_X_MSB  0x01

/* Expected chip ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* ±2g range: 4096 counts/g, 9.81 m/s² */
#define FXOS8700_SENSITIVITY 4096.0f
#define GRAVITY 9.81f

/* Impact threshold: 2 g in m/s² */
#define IMPACT_THRESHOLD 19.62f

/* Sampling interval: 50 ms */
#define SAMPLE_INTERVAL_US 50000

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int fxos8700_init(int handle)
{
    int who;

    /* Verify device identity */
    who = i2cReadByteData(handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who);
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X). "
                        "Sensor not present or wrong device.\n",
                who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit in CTRL_REG1 */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1 (standby)\n");
        return -1;
    }

    /* Configure ±2g range (0x00) */
    if (i2cWriteByteData(handle, FXOS8700_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write XYZ_DATA_CFG\n");
        return -1;
    }

    /* Activate: set ACTIVE bit (bit 0) in CTRL_REG1 */
    if (i2cWriteByteData(handle, FXOS8700_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1 (active)\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z)
{
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at OUT_X_MSB (0x01) */
    if (i2cReadI2CBlockData(handle, FXOS8700_OUT_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte acceleration block\n");
        return -1;
    }

    /* 14-bit left-justified data: shift right by 2 */
    raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 2;
    raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 2;
    raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 2;

    /* Convert to m/s² */
    *x = (float)raw_x / FXOS8700_SENSITIVITY * GRAVITY;
    *y = (float)raw_y / FXOS8700_SENSITIVITY * GRAVITY;
    *z = (float)raw_z / FXOS8700_SENSITIVITY * GRAVITY;

    return 0;
}

static int detect_impact(float magnitude)
{
    return (magnitude > IMPACT_THRESHOLD) ? 1 : 0;
}

static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp;
    time_t t;
    struct tm tm_info;
    char timestamp[64];

    t = time(NULL);
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open impact_log.txt for appending\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fclose(fp);
}

int main(void)
{
    float x, y, z, magnitude;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x1F */
    g_i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (fxos8700_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: FXOS8700 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (read_acceleration(g_i2c_handle, &x, &y, &z) == 0) {
            magnitude = sqrtf(x * x + y * y + z * z);
            if (detect_impact(magnitude)) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s²\n", magnitude);
            }
        }
        /* On read error, continue loop rather than crashing */

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("Impact detection stopped.\n");
    return EXIT_SUCCESS;
}

