#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GYRO_ADDR      0x69
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0xD3
#define CTRL_REG1      0x20
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define SAMPLE_PERIOD  50000  /* microseconds (20 Hz) */
#define CAL_SAMPLES    100
#define ALERT_THRESH   50.0f  /* dps */
#define SENSITIVITY    0.00875f  /* dps/LSB */

static volatile sig_atomic_t g_running = 1;
static int  g_fd  = -1;
static FILE *g_log = NULL;

static void sighandler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, dst, len);
    if (n < 0 || (size_t)n != len) {
