#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 registers */
#define ADXL345_DEVID       0x00
#define ADXL345_POWER_CTL   0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0      0x32

/* Expected device ID */
#define ADXL345_DEVID_VALUE 0xE5

/* LED GPIO */
#define LED_GPIO 17

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* Acceleration threshold in g */
#define ACCEL_THRESHOLD 2.0f

/* Full-resolution, ±2g range: 4 mg/LSB = 0.004 g/LSB */
#define SCALE_FACTOR 0.004f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(int handle) {
    int devid = i2cReadByteData(handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: failed to read DEVID register (pigpio error %d)\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Error: DEVID mismatch (got 0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby -> clear measure bit, then set measure bit */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL (standby)\n");
        return -1;
    }
    gpioDelay(1000);

    /* DATA_FORMAT: 0x0B = full resolution, ±2g, right-justified, 4 mg/LSB */
    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: failed to write DATA_FORMAT\n");
        return -1;
    }

    /* POWER_CTL: 0x08 = measure mode */
    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: failed to write POWER_CTL (measure)\n");
        return -1;
    }

    gpioDelay(1000);
    return 0;
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char raw[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte acceleration block\n");
        return -1;
    }

    x_raw = (int16_t)((raw[1] << 8) | (uint8_t)raw[0]);
    y_raw = (int16_t)((raw[3] << 8) | (uint8_t)raw[2]);
    z_raw = (int16_t)((raw[5] << 8) | (uint8_t)raw[4]);

    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

static void check_threshold(float x, float y, float z) {
    int exceed = (fabsf(x) > ACCEL_THRESHOLD) ||
                 (fabsf(y) > ACCEL_THRESHOLD) ||
                 (fabsf(z) > ACCEL_THRESHOLD);

    if (gpioWrite(LED_GPIO, exceed ? 1 : 0) < 0) {
        fprintf(stderr, "Warning: failed to write LED GPIO\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    float x, y, z;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (pigpio error %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open accel_log.txt\n");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    while (!terminate) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
            check_threshold(x, y, z);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

