#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define ACCEL_ADDR 0x19
#define MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define OUT_X_L_A   0x28
#define MR_REG_M    0x02
#define OUT_X_H_M   0x03

/* Scaling factors */
#define ACCEL_SCALE 0.000244f   /* +/- 2g  -> 1 mg/LSB  -> 0.000244 g/LSB */
#define MAG_SCALE   0.00014f    /* +/- 4 gauss -> 0.14 mGauss/LSB -> 0.00014 G/LSB */

#define LOG_FILE "compass_log.txt"
#define SAMPLE_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;
static int i2c_accel = -1;
static int i2c_mag   = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_accelerometer(void) {
    if (i2cWriteByteData(i2c_accel, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1_A (0x27)\n");
        return -1;
    }
    return 0;
}

static int init_magnetometer(void) {
    if (i2cWriteByteData(i2c_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write MR_REG_M (0x00)\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_accel, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);
    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;
    return 0;
}

static int read_magnetometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_mag, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error: failed to read magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[0] << 8) | (uint8_t)buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | (uint8_t)buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | (uint8_t)buffer[5]);
    *x = (float)raw_x * MAG_SCALE;
    *y = (float)raw_y * MAG_SCALE;
    *z = (float)raw_z * MAG_SCALE;
    return 0;
}

static float calculate_heading(float mx, float my, float mz) {
    float pitch = atan2f(-mx, sqrtf(my * my + mz * mz));
    float roll  = atan2f(my, mz);
    float heading = atan2f(sin(roll) * sin(pitch) + cos(roll) * cos(pitch) * mz,
                           cos(roll) * sin(pitch) - sin(roll) * cos(pitch) * mz);
    if (heading < 0) heading += 2.0f * M_PI;
    return heading * 180.0f / M_PI;
}

static void log_data(float heading, float ax, float ay, float az,
                     float mx, float my, float mz) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        return;
    }
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Heading,AccelX,AccelY,AccelZ,MagX,MagY,MagZ\n");
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            ts, heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_accel = i2cOpen(1, ACCEL_ADDR, 0);
    if (i2c_accel < 0) {
        fprintf(stderr, "Error: failed to open I2C for accelerometer (0x%02X)\n", ACCEL_ADDR);
        gpioTerminate();
        return 1;
    }

    i2c_mag = i2cOpen(1, MAG_ADDR, 0);
    if (i2c_mag < 0) {
        fprintf(stderr, "Error: failed to open I2C for magnetometer (0x%02X)\n", MAG_ADDR);
        i2cClose(i2c_accel);
        gpioTerminate();
        return 1;
    }

    if (init_accelerometer() != 0 || init_magnetometer() != 0) {
        fprintf(stderr, "Error: sensor initialization failed\n");
        i2cClose(i2c_accel);
        i2cClose(i2c_mag);
        gpioTerminate();
        return 1;
    }

    printf("LSM303DLHC compass logging started. Press Ctrl+C to stop.\n");

    while (running) {
        float ax, ay, az, mx, my, mz;
        int a_ok = read_accelerometer(&ax, &ay, &az);
        int m_ok = read_magnetometer(&mx, &my, &mz);

        if (a_ok == 0 && m_ok == 0) {
            float heading = calculate_heading(mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
            printf("Heading: %.2f deg | Accel: (%.2f, %.2f, %.2f) g | Mag: (%.2f, %.2f, %.2f) G\n",
                   heading, ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Warning: sensor read error, skipping sample\n");
        }

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    if (i2c_accel >= 0) i2cClose(i2c_accel);
    if (i2c_mag   >= 0) i2cClose(i2c_mag);
    gpioTerminate();
    printf("Done.\n");
    return 0;
}

