    buf[2] = (val >> 8) & 0xFF;
    buf[3] = val & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int vl6180x_read16(int handle, uint16_t reg, uint16_t *val) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, buf, 2) != 2) return -1;
    *val = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint8_t)buf[1];
    return 0;
}

static int vl6180x_init(int handle) {
    uint16_t model_id = 0;
    if (vl6180x_read16(handle, REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }
    if (model_id != 0xB4) {
        fprintf(stderr, "Error: Invalid model ID 0x%04X (expected 0xB4).\n", model_id);
        return -1;
    }

    if (vl6180x_write16(handle, 0x0207, 0x01) < 0) return -1;
    if (vl6180x_write16(handle, 0x0208, 0x01) < 0) return -1;
    if (vl6180x_write16(handle, 0x0096, 0x00) < 0) return -1;
    if (vl6180x_write16(handle, 0x0097, 0xfd) < 0) return -1;
    if (vl6180x_write16(handle, 0x00e3, 0x00) < 0) return -1;
    if (vl6180x_write16(handle, 0x00e4, 0x04) < 0) return -1;
    if (vl6180x_write16(handle, 0x00e5, 0x02) < 0) return -1;
    if (vl6180x_write16(handle, 0x00e6, 0x01) < 0) return -1;
    if (vl6180x_write16(handle, 0x00e7, 0x03) < 0) return -1;
    if (vl6180x_write16(handle, 0x00f5, 0x02) < 0) return -1;
    if (vl6180x_write16(handle, 0x00d9, 0x05) < 0) return -1;
    if (vl6180x_write16(handle, 0x00db, 0xce) < 0) return -1;
    if (vl6180x_write16(handle, 0x00dc, 0x03) < 0) return -1;
    if (vl6180x_write16(handle, 0x00dd, 0xf8) < 0) return -1;
    if (vl6180x_write16(handle, 0x009f, 0x00) < 0) return -1;
    if (vl6180x_write16(handle, 0x00a3, 0x3c) < 0) return -1;
    if (vl6180x_write16(handle, 0x00b7, 0x00) < 0) return -1;
    if (vl6180x_write16(handle, 0x00bb, 0x3c) < 0) return -1;
    if (vl6180x_write16(handle, 0x00b2, 0x09) < 0) return -1;
    if (vl6180x_write16(handle, 0x00ca, 0x09) < 0) return -1;
    if (vl6180x_write16(handle, 0x0198, 0x01) < 0) return -1;
    if (vl6180x_write16(handle, 0x01b0, 0x17) < 0) return -1;
    if (vl6180x_write16(handle, 0x01ad, 0x00) < 0) return -1;
    if (vl6180x_write16(handle, 0x00ff, 0x05) < 0) return -1;
    if (vl6180x_write16(handle, 0x0100, 0x05) < 0) return -1;
    if (vl6180x_write16(handle, 0x0199, 0x05) < 0) return -1;
    if (vl6180x_write16(handle, 0x01a6, 0x1b) < 0) return -1;
    if (vl6180x_write16(handle, 0x01ac, 0x3e) < 0) return -1;
    if (vl6180x_write16(handle, 0x01a7, 0x1f) < 0) return -1;
    if (vl6180x_write16(handle, 0x0030, 0x00) < 0) return -1;

    return 0;
}

static int read_distance(int handle, int *distance_mm) {
    uint16_t status = 0;
    uint16_t range = 0;

    if (vl6180x_write16(handle, REG_SYSRANGE_START, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (vl6180x_read16(handle, REG_RESULT_RANGE_STATUS, &status) < 0) return -1;
    if (status & 0x01) {
        fprintf(stderr, "Error: Range error (0x%04X).\n", status);
        return -1;
    }
    if (status & 0x10) {
        fprintf(stderr, "Error: Signal fail (0x%04X).\n", status);
        return -1;
    }
    if (status & 0x40) {
        fprintf(stderr, "Error: Overrange (0x%04X).\n", status);
        return -1;
    }

    if (vl6180x_read16(handle, REG_RESULT_RANGE_VAL, &range) < 0) return -1;
    *distance_mm = (int)range;
    return 0;
}

static void log_data(FILE *fp, int distance_mm, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm, Status: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm, status);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (vl6180x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL6180X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int distance = 0;
        if (read_distance(i2c_handle, &distance) == 0) {
            const char *status = (distance < THRESHOLD_MM) ? "DOOR_OPEN" : "DOOR_CLOSED";
            log_data(log_file, distance, status);
            printf("Distance: %d mm, Status: %s\n", distance, status);
        } else {
            fprintf(stderr, "Error: Failed to read distance. Re-initializing sensor.\n");
            i2cClose(i2c_handle);
            gpioDelay(100000);
            i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-open failed.\n");
                break;
            }
            if (vl6180x_init(i2c_handle) < 0) {
                fprintf(stderr, "Error: VL6180X re-initialization failed.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

