#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CTRL_REG 0x00
#define CTRL_ENABLE 0x80
#define SAMPLE_INTERVAL_US 10000
#define LOG_FILE "audio_log.dat"

static volatile sig_atomic_t running = 1;
static int i2c_handle1 = -1;
static int i2c_handle2 = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_sensor(int handle) {
    if (i2cWriteByteData(handle, CTRL_REG, CTRL_ENABLE) < 0) {
        fprintf(stderr, "Error writing control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_audio_sample(int handle, int16_t *sample) {
    char buf[2];
    int bytes = i2cReadI2CBlockData(handle, DATA_REG, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading audio data: %s\n", strerror(errno));
        return -1;
    }
    *sample = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static double calculate_tdoa(int16_t s1, int16_t s2) {
    return (double)(s1 - s2);
}

static void log_data(struct timespec ts, int16_t s1, int16_t s2, double tdoa) {
    if (log_file) {
        fprintf(log_file, "%ld,%ld,%d,%d,%.6f\n", ts.tv_sec, ts.tv_nsec, s1, s2, tdoa);
        fflush(log_file);
    }
}

static void cleanup(void) {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
        i2c_handle2 = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 1: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C for sensor 2: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2c_handle1 = -1;
        gpioTerminate();
        return 1;
    }

    if (init_sensor(i2c_handle1) < 0 || init_sensor(i2c_handle2) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    fprintf(log_file, "timestamp_sec,timestamp_nsec,sensor1_sample,sensor2_sample,tdoa\n");

    while (running) {
        int16_t s1 = 0, s2 = 0;
        int rc1 = read_audio_sample(i2c_handle1, &s1);
        int rc2 = read_audio_sample(i2c_handle2, &s2);

        if (rc1 == 0 && rc2 == 0) {
            struct timespec ts;
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                double tdoa = calculate_tdoa(s1, s2);
                log_data(ts, s1, s2, tdoa);
            } else {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            }
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

