    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

static int spi_read_register(uint8_t reg, int16_t *value)
{
    char tx[2], rx[2];
    int  status;

    /* ADIS16488A read: send 16-bit word with MSB=0, bits 6:0 = register address */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = 0x00;

    status = spiXfer(spi_handle, tx, rx, 2);
    if (status < 0) {
        fprintf(stderr, "SPI write (request) failed for reg 0x%02X: %d\n", reg, status);
        return -1;
    }

    /* Stall to let the sensor prepare the response */
    gpioDelay(STALL_US);

    /* Read the 16-bit data word */
    status = spiXfer(spi_handle, tx, rx, 2);
    if (status < 0) {
        fprintf(stderr, "SPI read failed for reg 0x%02X: %d\n", reg, status);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int read_imu_data(float *gyro_x, float *gyro_y, float *gyro_z,
                         float *accel_x, float *accel_y, float *accel_z)
{
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(X_GYRO_REG, &raw_gyro_x) < 0) return -1;
    if (spi_read_register(Y_GYRO_REG, &raw_gyro_y) < 0) return -1;
    if (spi_read_register(Z_GYRO_REG, &raw_gyro_z) < 0) return -1;
    if (spi_read_register(X_ACCEL_REG, &raw_accel_x) < 0) return -1;
    if (spi_read_register(Y_ACCEL_REG, &raw_accel_y) < 0) return -1;
    if (spi_read_register(Z_ACCEL_REG, &raw_accel_z) < 0) return -1;

    *gyro_x   = (float)raw_gyro_x   * GYRO_SENSITIVITY;
    *gyro_y   = (float)raw_gyro_y   * GYRO_SENSITIVITY;
    *gyro_z   = (float)raw_gyro_z   * GYRO_SENSITIVITY;
    *accel_x  = (float)raw_accel_x  * ACCEL_SENSITIVITY;
    *accel_y  = (float)raw_accel_y  * ACCEL_SENSITIVITY;
    *accel_z  = (float)raw_accel_z  * ACCEL_SENSITIVITY;

    return 0;
}

static void log_data(float gyro_x, float gyro_y, float gyro_z,
                     float accel_x, float accel_y, float accel_z)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec / 1000000L,
            gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
    fflush(fp);
}

int main(void)
{
    float gyro_x, gyro_y, gyro_z;
    float accel_x, accel_y, accel_z;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    atexit(cleanup);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return EXIT_FAILURE;
    }

    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        perror("Error opening CSV file");
        return EXIT_FAILURE;
    }

    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(fp);

    while (running) {
        if (read_imu_data(&gyro_x, &gyro_y, &gyro_z,
                          &accel_x, &accel_y, &accel_z) == 0) {
            log_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read IMU data\n");
        }

        /* Non-blocking 100 ms delay that responds to signals promptly */
        for (int i = 0; i < 10 && running; i++)
            gpioDelay(10000);  /* 10 ms chunks */
    }

    return EXIT_SUCCESS;
}

