/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 *
 * Uses libgpiod for the chip-select GPIO line and spidev for SPI
 * communication.  The ADIS16448 single-register read protocol is
 * implemented via two 16-bit SPI cycles: the first cycle sends the
 * 8-bit register address with bit 7 set (0x80) to select the
 * register, the second cycle clocks out the 16-bit data.
 *
 * Wiring:
 *   ADIS16448 CS  -> GPIO8  (physical pin 24, SPI0 CE0)
 *   ADIS16448 SDO -> GPIO9  (physical pin 21, SPI0 MISO)
 *   ADIS16448 SDA -> GPIO10 (physical pin 19, SPI0 MOSI)
 *   ADIS16448 SCL -> GPIO11 (physical pin 23, SPI0 SCLK)
 *   ADIS16448 VDD -> 3.3 V
 *   ADIS16448 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o adis16448 adis16448.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

/* ---- ADIS16448 register addresses ---- */
#define ADIS16448_XGYRO_OUT  0x04
#define ADIS16448_YGYRO_OUT  0x06
#define ADIS16448_ZGYRO_OUT  0x08
#define ADIS16448_XACCL_OUT  0x0A
#define ADIS16448_YACCL_OUT  0x0C
#define ADIS16448_ZACCL_OUT  0x0E

/* ---- Scale factors (from ADIS16448 datasheet) ---- */
#define GYRO_SCALE  0.02f   /* degrees/sec per LSB */
#define ACCL_SCALE  0.00025f /* g per LSB */

/* ---- SPI configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8

/* ---- CS GPIO line (GPIO8 = physical pin 24) ---- */
#define CS_CHIP_NAME    "gpiochip4"
#define CS_LINE_OFFSET  8

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * ADIS16448 single-register read:
 *   tx[0] = (reg_addr << 1) | 0x01  -> address with bit 7 set (read)
 *   tx[1] = 0x00                    -> dummy for clocking data out
 *   After the second transfer, rx[1] contains the high byte,
 *   rx[0] contains the low byte.
 */
static int adis16448_read_reg16(int spi_fd, uint8_t reg_addr, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)((reg_addr << 1) | 0x01), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 2,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI read address 0x%02X: %s\n",
                reg_addr, strerror(errno));
        return -1;
    }

    /* Small delay between cycles (datasheet: t_RCYC ~ 10 us) */
    usleep(10);

    tx[0] = 0x00;
    tx[1] = 0x00;
    rx[0] = 0;
    rx[1] = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI read data for 0x%02X: %s\n",
                reg_addr, strerror(errno));
        return -1;
    }

    *out = (int16_t)(((uint16_t)rx[1] << 8) | (uint16_t)rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open spidev ---- */
    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0)
        return EXIT_FAILURE;

    /* ---- Open GPIO chip and request CS line ---- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name(CS_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s): %s\n",
                CS_CHIP_NAME, strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    struct gpiod_line *cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(cs_line, "adis16448-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t raw_gx, raw_gy, raw_gz;
        int16_t raw_ax, raw_ay, raw_az;

        if (adis16448_read_reg16(spi_fd, ADIS16448_XGYRO_OUT, &raw_gx) < 0 ||
            adis16448_read_reg16(spi_fd, ADIS16448_YGYRO_OUT, &raw_gy) < 0 ||
            adis16448_read_reg16(spi_fd, ADIS16448_ZGYRO_OUT, &raw_gz) < 0 ||
            adis16448_read_reg16(spi_fd, ADIS16448_XACCL_OUT, &raw_ax) < 0 ||
            adis16448_read_reg16(spi_fd, ADIS16448_YACCL_OUT, &raw_ay) < 0 ||
            adis16448_read_reg16(spi_fd, ADIS16448_ZACCL_OUT, &raw_az) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            float gx = (float)raw_gx * GYRO_SCALE;
            float gy = (float)raw_gy * GYRO_SCALE;
            float gz = (float)raw_gz * GYRO_SCALE;
            float ax = (float)raw_ax * ACCL_SCALE;
            float ay = (float)raw_ay * ACCL_SCALE;
            float az = (float)raw_az * ACCL_SCALE;

            printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s  "
                   "Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
                   gx, gy, gz, ax, ay, az);
            fflush(stdout);
        }

        /* 100 ms delay */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 100 * 1000 * 1000 };
        nanosleep(&ts, NULL);
    }

    /* ---- Cleanup ---- */
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

