#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16448 Register Addresses */
#define X_GYRO_OUT  0x04
#define Y_GYRO_OUT  0x06
#define Z_GYRO_OUT  0x08
#define X_ACCL_OUT  0x0A
#define Y_ACCL_OUT  0x0C
#define Z_ACCL_OUT  0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0

/* Stall time between read command and data transfer (microseconds) */
#define ADIS16448_STALL_US 40

/* Scaling factors */
#define GYRO_SCALE  0.05f   /* deg/sec/LSB */
#define ACCL_SCALE  0.00025f /* g/LSB */

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit register from the ADIS16448.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int adis16448_read_register(uint8_t reg, int16_t *value) {
    char tx_cmd[2] = { (char)((reg | 0x80) >> 8), (char)(reg | 0x80) };
    char rx_cmd[2] = { 0, 0 };
    char tx_dummy[2] = { 0x00, 0x00 };
    char rx_data[2] = { 0, 0 };

    /* First transfer: send read command */
    if (spiXfer(spi_handle, tx_cmd, rx_cmd, 2) != 2) {
        fprintf(stderr, "SPI write (command) failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Stall time per ADIS16448 datasheet */
    gpioDelay(ADIS16448_STALL_US);

    /* Second transfer: send dummy to clock out data */
    if (spiXfer(spi_handle, tx_dummy, rx_data, 2) != 2) {
        fprintf(stderr, "SPI read (data) failed for register 0x%02X\n", reg);
        return -1;
    }

