#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_DEVID   0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_SCALE_FACTOR 256.0f
#define IMPACT_THRESHOLD 2.5f
#define LED_GPIO 17
#define LOG_FILE "impact_log.txt"
#define POLL_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_register(int handle, uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t val) {
    return i2cWriteByteData(handle, reg, val);
}

static int read_acceleration(int handle, float *x, float *y, float *z) {
    char raw[6];
    int rc = i2cReadI2CBlockData(handle, ADXL345_DATAX0, raw, 6);
    if (rc != 6) return -1;
    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);
    *x = (float)rx / ADXL345_SCALE_FACTOR;
    *y = (float)ry / ADXL345_SCALE_FACTOR;
    *z = (float)rz / ADXL345_SCALE_FACTOR;
    return 0;
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void log_impact(FILE *f, float mag, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(f, "%04d-%02d-%02d %02d:%02d:%02d, Magnitude: %.2f, X: %.2f, Y: %.2f, Z: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, mag, x, y, z);
    fflush(f);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", ADXL345_ADDRESS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t devid = 0;
    if (read_register(i2c_handle, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Failed to read ADXL345 DEVID register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0xE5)\n", devid);
        cleanup();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Failed to write DATA_FORMAT register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (write_register(i2c_handle, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to write POWER_CTL register\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Threshold: %.1fg. Press Ctrl+C to exit.\n", IMPACT_THRESHOLD);

    while (running) {
        float x, y, z;
        if (read_acceleration(i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "I2C read error\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float mag = calculate_magnitude(x, y, z);
        if (mag > IMPACT_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
            log_impact(log_file, mag, x, y, z);
            gpioDelay(500000);
            gpioWrite(LED_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

