#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* ICM-20602 I2C address (AD0 tied to GND) */
#define ICM20602_ADDR 0x68

/* ICM-20602 register addresses */
#define WHO_AM_I      0x75
#define WHO_AM_I_VAL  0x12
#define PWR_MGMT_1    0x6B
#define ACCEL_CONFIG  0x1C
#define GYRO_CONFIG   0x1B
#define ACCEL_XOUT_H  0x3B
#define GYRO_XOUT_H   0x43

/* Scaling factors for default ranges (+/- 2g, +/- 250 dps) */
#define ACCEL_SCALE 16384.0f
#define GYRO_SCALE  131.0f

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_imu(void) {
    /* Wake up the device: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms stabilization */

    /* Verify device identity */
    int who = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Set accelerometer range to +/- 2g */
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write ACCEL_CONFIG\n");
        return -1;
    }

    /* Set gyroscope range to +/- 250 dps */
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

static int read_imu_data(int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz) {
    char buf[12];

    /* Burst read 6 bytes from ACCEL_XOUT_H (0x3B) */
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read accelerometer data\n");
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *ay = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *az = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    /* Burst read 6 bytes from GYRO_XOUT_H (0x43) */
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyroscope data\n");
        return -1;
    }
    *gx = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *gy = (int16_t)((buf[2] << 8) | (uint8_t)buf[3]);
    *gz = (int16_t)((buf[4] << 8) | (uint8_t)buf[5]);

    return 0;
}

static void log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%d,%d,%d,%d,%d,%d\n",
            timestamp, ts.tv_nsec / 1000000,
            ax, ay, az, gx, gy, gz);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus 1 at address 0x%02X\n",
                ICM20602_ADDR);
        gpioTerminate();
        return 1;
    }

    if (init_imu() != 0) {
        fprintf(stderr, "Error: IMU initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        perror("Error: failed to open imu_log.csv");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,ax,ay,az,gx,gy,gz\n");

    int16_t ax, ay, az, gx, gy, gz;
    while (running) {
        if (read_imu_data(&ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(log_file, ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Warning: I2C read error, continuing...\n");
        }
        gpioDelay(100000); /* 100 ms -> 10 Hz */
    }

    fprintf(stderr, "\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

