#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8451Q_ADDR  0x1D
#define LED_GPIO_LINE  17
#define LOG_FILE       "impact_log.txt"
#define POLL_MS        100
#define LED_ON_MS      500
#define ACCEL_THRESHOLD 2.0f

#define REG_STATUS      0x00
#define REG_OUT_X_MSB   0x01
#define REG_WHO_AM_I    0x0D
#define REG_CTRL_REG1   0x2A
#define REG_CTRL_REG4   0x2D
#define REG_SYSMOD      0x0B

#define EXPECTED_WHO_AM_I 0x1A

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int16_t combine(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

static bool detect_impact(float x, float y, float z) {
    return (fabsf(x) > ACCEL_THRESHOLD ||
            fabsf(y) > ACCEL_THRESHOLD ||
            fabsf(z) > ACCEL_THRESHOLD);
}

static void log_impact(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s - Impact: X=%.2fg, Y=%.2fg, Z=%.2fg\n", ts, x, y, z);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return 1;
    }
    struct gpiod_line *led = gpiod_chip_get_line(chip, LED_GPIO_LINE);
    if (!led) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(led, "mma8451q-led", 0) < 0) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", MMA8451Q_ADDR, strerror(errno));
        close(i2c_fd);
        gpiod_line_release(led);
        gpiod_chip_close(chip);
        return 1;
    }

    uint8_t who = 0;
    if (i2c_read_reg(i2c_fd, REG_WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I: %s\n", strerror(errno));
        goto cleanup;
    }
    if (who != EXPECTED_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, EXPECTED_WHO_AM_I);
        goto cleanup;
    }

    if (i2c_write_reg(i2c_fd, REG_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to reset CTRL_REG1: %s\n", strerror(errno));
        goto cleanup;
    }
    if (i2c_write_reg(i2c_fd, REG_CTRL_REG4, 0x08) < 0) {
        fprintf(stderr, "Failed to set F_READ mode: %s\n", strerror(errno));
        goto cleanup;
    }
    if (i2c_write_reg(i2c_fd, REG_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to enable auto-sleep: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("MMA8451Q initialized. Monitoring for impacts...\n");

    while (g_running) {
        uint8_t status = 0;
        if (i2c_read_reg(i2c_fd, REG_STATUS, &status) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            usleep(POLL_MS * 1000);
            continue;
        }
        if (!(status & 0x08)) {
            usleep(POLL_MS * 1000);
            continue;
        }

        uint8_t buf[6];
        if (i2c_read_block(i2c_fd, REG_OUT_X_MSB, buf, 6) < 0) {
            fprintf(stderr, "I2C read block error: %s\n", strerror(errno));
            usleep(POLL_MS * 1000);
            continue;
        }

        int16_t x_raw = combine(buf[0], buf[1]);
        int16_t y_raw = combine(buf[2], buf[3]);
        int16_t z_raw = combine(buf[4], buf[5]);

        float x = (float)x_raw / 1024.0f;
        float y = (float)y_raw / 1024.0f;
        float z = (float)z_raw / 1024.0f;

        if (detect_impact(x, y, z)) {
            printf("Impact detected! X=%.2fg, Y=%.2fg, Z=%.2fg\n", x, y, z);
            log_impact(x, y, z);
            gpiod_line_set_value(led, 1);
            usleep(LED_ON_MS * 1000);
            gpiod_line_set_value(led, 0);
        }
        usleep(POLL_MS * 1000);
    }

cleanup:
    gpiod_line_set_value(led, 0);
    gpiod_line_release(led);
    gpiod_chip_close(chip);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

