/*
 * ADXL345 Freefall Detector for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - ADXL345 on /dev/i2c-1, address 0x53
 *   - INT1 pin (GPIO17, physical pin 11) connected to ADXL345 INT1
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -li2c -lgpiod -lm
 *
 * Run:
 *   sudo ./freefall
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDR          0x53
#define ADXL345_REG_DEVID     0x00
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF   0x20
#define ADXL345_REG_INT_MAP   0x2F
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0    0x32
#define ADXL345_REG_INT_SOURCE 0x30

#define ADXL345_DEVID         0xE5
#define ADXL345_INT_FREEFALL  0x04

/* ---- GPIO / interrupt constants ---- */
#define GPIO_CHIP_NAME        "gpiochip4"
#define GPIO_LINE_OFFSET      17
#define GPIO_CONSUMER         "adxl345-freefall"

/* ---- Freefall parameters ---- */
#define FREEFALL_THRESHOLD_MG 300.0f
#define FREEFALL_TIME_MS      100.0f

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C block write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 init ---- */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) < 0)
        return -1;
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n", devid, ADXL345_DEVID);
        return -1;
    }

    /* Standby before configuration */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) < 0)
        return -1;

    /* Set freefall threshold: 300 mg -> 0x1E (2.44 mg/LSB) */
    if (i2c_write_reg8(fd, ADXL345_REG_THRESH_FF, (uint8_t)(FREEFALL_THRESHOLD_MG / 2.44f)) < 0)
        return -1;

    /* Set freefall time: 100 ms -> 0x0A (100 * 10 ms) */
    if (i2c_write_reg8(fd, ADXL345_REG_TIME_FF, (uint8_t)(FREEFALL_TIME_MS / 10.0f)) < 0)
        return -1;

    /* Map freefall interrupt to INT1 (INT_MAP = 0x00) */
    if (i2c_write_reg8(fd, ADXL345_REG_INT_MAP, 0x00) < 0)
        return -1;

    /* Enable freefall interrupt (bit 2) */
    if (i2c_write_reg8(fd, ADXL345_REG_INT_ENABLE, ADXL345_INT_FREEFALL) < 0)
        return -1;

    /* Enter measurement mode (bit 3 = measure) */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

/* ---- Read acceleration ---- */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, ADXL345_REG_DATAX0, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* +/- 2 g full scale, 4 mg/LSB */
    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;
    return 0;
}

/* ---- Log data ---- */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char time_buf[32];
    strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld,%.3f,%.3f,%.3f\n", time_buf, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable interrupts and put sensor in standby */
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_INT_ENABLE, 0x00);
        (void)i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request line for interrupt */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
