#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LSM6DSR_ADDR 0x6A
#define WHO_AM_I 0x0F
#define WHO_AM_I_VAL 0x6C
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

#define ACCEL_THRESHOLD 0.2f
#define IMPACT_THRESHOLD 2.5f
#define WINDOW_SEC 1.0
#define SAMPLE_PERIOD_US 10000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) return -1;
    *val = (uint8_t)rc;
    return 0;
}

static int write_reg(uint8_t reg, uint8_t val) {
    return i2cWriteByteData(i2c_handle, reg, val);
}

static int init_lsm6dsr(void) {
    uint8_t who;
    if (read_reg(WHO_AM_I, &who) < 0) {
        fprintf(stderr, "Error: I2C read failed for WHO_AM_I.\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (0x%02X, expected 0x%02X). Sensor absent?\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (write_reg(CTRL1_XL, 0x40) < 0) return -1;
    if (write_reg(CTRL2_G, 0x40) < 0) return -1;
    return 0;
}

static int read_accel(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, (char *)buf, 6) != 6) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx / 16384.0f;
    *y = (float)ry / 16384.0f;
    *z = (float)rz / 16384.0f;
    return 0;
}

static int read_gyro(float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, (char *)buf, 6) != 6) return -1;
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx / 131.0f;
    *y = (float)ry / 131.0f;
    *z = (float)rz / 131.0f;
    return 0;
}

static void log_data(float ax, float ay, float az, float gx, float gy, float gz) {
    time_t rawtime;
    struct tm *timeinfo;
    char ts[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n", ts, ax, ay, az, gx, gy, gz);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed.\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed.\n");
        gpioTerminate();
        return 1;
    }
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR init failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    enum { IDLE, FREEFALL, IMPACT } state = IDLE;
    struct timespec ts_start, ts_now;
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    while (!terminate) {
        float ax, ay, az, gx, gy, gz;
        if (read_accel(&ax, &ay, &az) < 0 || read_gyro(&gx, &gy, &gz) < 0) {
            fprintf(stderr, "Sensor read error.\n");
            break;
        }
        log_data(ax, ay, az, gx, gy, gz);
        float mag = sqrtf(ax * ax + ay * ay + az * az);
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        double elapsed = (ts_now.tv_sec - ts_start.tv_sec) + (ts_now.tv_nsec - ts_start.tv_nsec) / 1e9;
        if (state == IDLE) {
            if (mag < ACCEL_THRESHOLD) {
                state = FREEFALL;
                ts_start = ts_now;
            }
        } else if (state == FREEFALL) {
            if (mag > IMPACT_THRESHOLD) {
                state = IMPACT;
                printf("Fall detected!\n");
            } else if (elapsed > WINDOW_SEC) {
                state = IDLE;
            }
        } else {
            state = IDLE;
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

