        if (state == IDLE) {
            if (mag < ACCEL_THRESHOLD) {
                state = FREEFALL;
                ts_start = ts_now;
            }
        } else if (state == FREEFALL) {
            if (mag > IMPACT_THRESHOLD) {
                state = IMPACT;
                printf("Fall detected!\n");
            } else if (elapsed > WINDOW_SEC) {
                state = IDLE;
            }
        } else {
            state = IDLE;
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }
    if (log_file) fclose(log_file);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

