#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16266 Register Addresses */
#define ADIS16266_XGYRO_OUT 0x14
#define ADIS16266_WHO_AM_I  0x02
#define ADIS16266_SMPL_PRD 0x36
#define ADIS16266_GLOB_CMD 0x68

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    3        /* CPOL=1, CPHA=1 */

/* Scaling factor for X_GYRO_OUT (degrees/sec per LSB) */
#define GYRO_SCALE 0.0305f

/* Expected WHO_AM_I value for ADIS16266 */
#define ADIS16266_WHO_AM_I_VAL 0x3F5A

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16266.
 * pigpio's spiRead returns the number of bytes read; we need exactly 2.
 * The ADIS16266 returns the response in the next transaction, so we
 * send the address, then read back, then send a dummy to clock out the data.
 */
static int read_register(uint8_t address, uint16_t *value) {
    char tx[2], rx[2];
    int ret;

    /* Send read command: address ORed with 0x80 */
    tx[0] = (char)(address | 0x80);
    tx[1] = 0x00;
    ret = spiWrite(spi_handle, tx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write (addr 0x%02X) failed: %d\n", address, ret);
        return -1;
    }

    /* Read response: pigpio returns the bytes received */
    ret = spiRead(spi_handle, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read (addr 0x%02X) failed: %d\n", address, ret);
        return -1;
    }

    /* Send dummy byte to clock out the data */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiWrite(spi_handle, tx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI dummy write (addr 0x%02X) failed: %d\n", address, ret);
        return -1;
    }

    /* ADIS16266 is big-endian: MSB first */
    *value = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/* Write a 16-bit register to the ADIS16266.
 * pigpio's spiWrite returns the number of bytes written.
 */
static int write_register(uint8_t address, uint16_t value) {
    char tx[2];
    int ret;

    /* ADIS16266 write: address ANDed with 0x7F, then 16-bit data */
    tx[0] = (char)(address & 0x7F);
    tx[1] = (char)(value & 0xFF);
    ret = spiWrite(spi_handle, tx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI write (addr 0x%02X) failed: %d\n", address, ret);
        return -1;
    }

    /* Send dummy byte to complete the transaction */
    tx[0] = 0x00;
    tx[1] = 0x00;
    ret = spiWrite(spi_handle, tx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI dummy write (addr 0x%02X) failed: %d\n", address, ret);
        return -1;
    }

    return 0;
}

/* Initialize the ADIS16266: verify WHO_AM_I and configure sample period */
static int initialize_adis16266(void) {
    uint16_t who_am_i = 0;

    /* Read WHO_AM_I to verify device identity */
    if (read_register(ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    printf("ADIS16266 detected (WHO_AM_I = 0x%04X)\n", who_am_i);

    /* Set sample period to 10 ms (0x000A) */
    if (write_register(ADIS16266_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data and convert to degrees/sec */
static int read_gyro_data(float *gyro_rate) {
    uint16_t raw_data = 0;

    if (read_register(ADIS16266_XGYRO_OUT, &raw_data) != 0) {
        fprintf(stderr, "Failed to read X_GYRO_OUT register\n");
        return -1;
    }

    /* Convert to signed 16-bit and apply scale factor */
    *gyro_rate = (float)((int16_t)raw_data) * GYRO_SCALE;
    return 0;
}

/* Log data to CSV file */
static int log_data(float gyro_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.4f\n", timestamp, gyro_rate) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

int main(void) {
    float gyro_rate;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI channel: mode 3 = (CPOL=1, CPHA=1) */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 2) | SPI_MODE);
    if (spi_handle < 0) {
