    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open gyro_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Gyro_Rate_dps\n");
        fflush(log_file);
    }

    /* Set up signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    printf("Logging gyroscope data to gyro_log.csv. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&gyro_rate) == 0) {
            if (log_data(gyro_rate) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed, continuing...\n");
        }
        gpioDelay(10000); /* 10 ms delay (microseconds) */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return 0;
}

