#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to VDD) */
#define GYRO_ADDR 0x69

/* L3G4200D register addresses */
#define WHO_AM_I    0x0F
#define CTRL_REG1   0x20
#define CTRL_REG4   0x23
#define OUT_X_L     0x28

/* Expected chip ID */
#define WHO_AM_I_VAL 0xD3

/* Sensitivity for +/- 250 dps: 8.75 mdps/LSB = 0.00875 dps/LSB */
#define SENSITIVITY 0.00875f

/* Globals for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_gyro(void) {
    int retries = 3;
    int status;

    /* Verify device identity */
    status = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (status < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", pigpio_error(status));
        return -1;
    }
    if (status != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                status, WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: normal mode, all axes enabled (0x0F) */
    status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL_REG1: %s\n", pigpio_error(status));
        return -1;
    }

    /* CTRL_REG4: full-scale = +-250 dps, continuous update (0x00) */
    status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error writing CTRL_REG4: %s\n", pigpio_error(status));
        return -1;
    }

    /* Allow sensor to settle after power-up */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n",
                status < 0 ? pigpio_error(status) : "short read");
        return -1;
    }

    /* Combine little-endian bytes: LSB first, then MSB */
    int16_t x = (int16_t)((buffer[1] << 8) | (uint8_t)buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | (uint8_t)buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | (uint8_t)buffer[4]);

    data->x = (float)x * SENSITIVITY;
    data->y = (float)y * SENSITIVITY;
    data->z = (float)z * SENSITIVITY;

    return 0;
}

static void log_data(const gyro_data_t *data) {
    struct timespec ts;
    char timestamp[64];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%09ld,%.6f,%.6f,%.6f\n",
            timestamp, ts.tv_nsec, data->x, data->y, data->z);
    fflush(log_file);
}

int main(void) {
    gyro_data_t gyro_data;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at GYRO_ADDR */
    i2c_handle = i2cOpen(1, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize gyroscope with retries */
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful termination */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    /* Main loop */
    while (!terminate) {
        if (read_gyro_data(&gyro_data) == 0) {
            log_data(&gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyro data, retrying...\n");
        }
        gpioDelay(10000); /* 10 ms */
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

