#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Read the flame sensor digital output.
 * Returns 0 (flame detected), 1 (no flame), or -1 on error. */
static int read_flame_sensor(void) {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", FLAME_SENSOR_GPIO);
        return -1;
    }
    return value;
}

/* Log a timestamped event to the log file and flush immediately. */
static void log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return;
    }

    if (fprintf(log_file, "%s - %s\n", buf, message) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed: %s\n", strerror(errno));
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO17 as input with internal pull-up so the line is
     * deterministic when the sensor's open-collector output is off. */
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for GPIO %d\n", FLAME_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    printf("Flame sensor monitoring started on GPIO %d. Press Ctrl+C to exit.\n",
           FLAME_SENSOR_GPIO);

    /* Main loop */
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            /* Flame detected (active-LOW) */
            log_event("Flame detected: YES");
            printf("FLAME DETECTED!\n");
        } else if (flame_detected == 1) {
            /* No flame */
            log_event("Flame detected: NO");
        } else {
            /* Error reading sensor */
            log_event("Error: Failed to read flame sensor");
        }

        gpioDelay(POLL_DELAY_US);  /* 500 ms */
    }

    /* Clean up */
    printf("\nExiting gracefully...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

