#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x53
#define REG_X_LSB      0x28
#define REG_X_MSB      0x29
#define REG_Y_LSB      0x2A
#define REG_Y_MSB      0x2B
#define REG_Z_LSB      0x2C
#define REG_Z_MSB      0x2D
#define LOG_FILE       "vibration_log.csv"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1)
        return -1;
    if (read(fd, val, 1) != 1)
        return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg8(fd, REG_X_LSB, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_X_MSB, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_LSB, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Y_MSB, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_LSB, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, REG_Z_MSB, &zh) < 0) return -1;

    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void get_iso8601_utc(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static int log_data(FILE *fp, const char *ts, int16_t x, int16_t y, int16_t z)
{
    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) return -1;
    fflush(fp);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "Timestamp,X,Y,Z\n");

    printf("Monitoring vibration (D7S-0001 @ 0x%02X). Press Ctrl+C to stop.\n", D7S_ADDR);

    while (g_running) {
        int16_t x, y, z;
        char ts[32];

        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        get_iso8601_utc(ts, sizeof(ts));
        if (log_data(g_log_fp, ts, x, y, z) < 0) {
            fprintf(stderr, "Log write error: %s\n", strerror(errno));
            break;
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_log_fp)  fclose(g_log_fp);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

