#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MMA8452Q_ADDR        0x1D
#define MMA8452Q_WHO_AM_I    0x0D
#define MMA8452Q_WHO_AM_I_VAL 0x2A
#define MMA8452Q_CTRL_REG1   0x2A
#define MMA8452Q_OUT_X_MSB   0x01
#define FALL_THRESHOLD_DEG  45.0
#define I2C_BUS             "/dev/i2c-1"
#define LOG_FILE            "fall_log.txt"
#define LOOP_DELAY_US       10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int16_t combine_msb_lsb(uint8_t msb, uint8_t lsb) {
    return (int16_t)((msb << 8) | lsb);
}

static int16_t raw_to_12bit(int16_t raw) {
    int16_t v = raw >> 4;
    if (v & 0x0800) v |= 0xF000;
    return v;
}

static double calculate_tilt_x(int16_t x, int16_t y, int16_t z) {
    return atan2((double)x, sqrt((double)y * y + (double)z * z)) * 180.0 / M_PI;
}

static void log_fall_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp,
            raw_to_12bit(x), raw_to_12bit(y), raw_to_12bit(z));
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    uint8_t who_am_i = 0;
    if (i2c_read_reg8(g_i2c_fd, MMA8452Q_WHO_AM_I, &who_am_i) < 0) {
        perror("read WHO_AM_I");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }
    if (who_am_i != MMA8452Q_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, MMA8452Q_WHO_AM_I_VAL);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_fd, MMA8452Q_CTRL_REG1, 0x00) < 0) {
        perror("write CTRL_REG1 standby");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(g_i2c_fd, MMA8452Q_CTRL_REG1, 0x20) < 0) {
        perror("write CTRL_REG1 active");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint8_t data[6];
        if (i2c_read_block(g_i2c_fd, MMA8452Q_OUT_X_MSB, data, 6) < 0) {
            perror("read accelerometer data");
            usleep(LOOP_DELAY_US);
            continue;
        }

        int16_t x_raw = combine_msb_lsb(data[0], data[1]);
        int16_t y_raw = combine_msb_lsb(data[2], data[3]);
        int16_t z_raw = combine_msb_lsb(data[4], data[5]);

        int16_t x = raw_to_12bit(x_raw);
        int16_t y = raw_to_12bit(y_raw);
        int16_t z = raw_to_12bit(z_raw);

        double tilt = calculate_tilt_x(x, y, z);
        if (fabs(tilt) > FALL_THRESHOLD_DEG) {
            log_fall_event(x_raw, y_raw, z_raw);
        }

        usleep(LOOP_DELAY_US);
    }

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

