#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define WHO_AM_I       0x0F
#define WHO_AM_I_VAL   0x3D
#define CTRL_REG1      0x20
#define CTRL_REG2      0x21
#define CTRL_REG3      0x22
#define CTRL_REG4      0x23
#define OUT_X_L        0x28
#define MAX_RETRIES    3
#define SAMPLE_HZ      10
#define SAMPLE_MS      (1000 / SAMPLE_HZ)
#define METAL_THRESH   800.0f
#define MG_PER_LSB     0.146f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sigh(int sig) { (void)sig; g_running = 0; }

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int init_magnetometer(int fd) {
    uint8_t id;
    if (i2c_read(fd, WHO_AM_I, &id) < 0) {
        fprintf(stderr, "init: WHO_AM_I read failed: %s\n", strerror(errno));
        return -1;
    }
    if (id != WHO_AM_I_VAL) {
        fprintf(stderr, "init: WHO_AM_I mismatch: 0x%02X (expected 0x%02X)\n", id, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write(fd, CTRL_REG1, 0x70) < 0) {
        fprintf(stderr, "init: CTRL_REG1 write failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write(fd, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "init: CTRL_REG2 write failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write(fd, CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "init: CTRL_REG3 write failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write(fd, CTRL_REG4, 0x0C) < 0) {
        fprintf(stderr, "init: CTRL_REG4 write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, OUT_X_L, buf, 6) < 0) {
        fprintf(stderr, "read: burst failed: %s\n", strerror(errno));
        return -1;
    }
    int16_t rx = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t ry = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t rz = (int16_t)((buf[5] << 8) | buf[4]);
    *x = (float)rx * MG_PER_LSB;
    *y = (float)ry * MG_PER_LSB;
    *z = (float)rz * MG_PER_LSB;
    return 0;
}

static void log_data(FILE *f, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(f, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(f);
}

int main(void) {
    struct sigaction sa = { .sa_handler = sigh };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_log = fopen("magnetic_log.txt", "a");
    if (!g_log) {
        fprintf(stderr, "fopen failed: %s\n", strerror(errno));
        return 1;
    }

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        g_i2c_fd = open(I2C_BUS, O_RDWR);
        if (g_i2c_fd < 0) {
            fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
            usleep(1000000);
            continue;
        }
        if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
            fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n", LIS3MDL_ADDR, strerror(errno));
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(1000000);
            continue;
        }
        if (init_magnetometer(g_i2c_fd) == 0) break;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        usleep(1000000);
    }
    if (g_i2c_fd < 0) {
        fprintf(stderr, "init failed after %d attempts\n", MAX_RETRIES);
        fclose(g_log);
        return 1;
    }

    fprintf(stderr, "LIS3MDL initialized on %s @ 0x%02X\n", I2C_BUS, LIS3MDL_ADDR);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) == 0) {
            log_data(g_log, x, y, z);
            float mag = sqrtf(x*x + y*y + z*z);
            if (mag > METAL_THRESH) {
                fprintf(stderr, "METAL DETECTED! magnitude=%.2f mG\n", mag);
            }
        } else {
            fprintf(stderr, "read error, reinit...\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            for (int r = 0; r < MAX_RETRIES && g_running; r++) {
                usleep(1000000);
                g_i2c_fd = open(I2C_BUS, O_RDWR);
                if (g_i2c_fd >= 0 && ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) >= 0) {
                    if (init_magnetometer(g_i2c_fd) == 0) break;
                    close(g_i2c_fd);
                    g_i2c_fd = -1;
                }
            }
            if (g_i2c_fd < 0) {
                fprintf(stderr, "reinit failed, exiting\n");
                break;
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

