#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_PARTID      0x01
#define ADXL354B_REG_XDATA       0x08
#define ADXL354B_REG_YDATA       0x0B
#define ADXL354B_REG_ZDATA       0x0E
#define ADXL354B_REG_STATUS      0x04
#define ADXL354B_REG_POWER_CTL   0x2D
#define ADXL354B_REG_RESET       0x1F

// Expected Part ID for ADXL354B
#define ADXL354B_PARTID_EXPECTED 0x1D

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    0

// Sensitivity for +-2g range (3.9 microg/LSB)
#define SENSITIVITY 0.0000039

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_init(int handle);
int read_acceleration_data(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// SPI read function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    char tx_buf[1 + len];
    char rx_buf[1 + len];
    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    if (spiXfer(handle, tx_buf, rx_buf, 1 + len) != (1 + len)) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }
    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI write function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;
    if (spiWrite(handle, tx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// ADXL354B initialization function
int adxl354b_init(int handle) {
    uint8_t part_id;
    int retries = 3;

    // Check sensor presence by reading PARTID
    while (retries > 0) {
        if (spi_read_register(handle, ADXL354B_REG_PARTID, &part_id, 1) == 0) {
            if (part_id == ADXL354B_PARTID_EXPECTED) {
                break;
            } else {
                fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", part_id, ADXL354B_PARTID_EXPECTED);
            }
        } else {
            fprintf(stderr, "Failed to read PARTID, retrying...\n");
        }
        retries--;
        gpioDelay(1000); // 1 ms delay
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to initialize ADXL354B: sensor not detected\n");
        return -1;
    }

    // Reset the device
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay for reset

    // Set measurement mode (clear RUN bit in POWER_CTL to enter standby)
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Failed to set standby mode\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    // Wait for STABLE bit in STATUS register
    uint8_t status;
    int stable_wait = 100; // 100 * 10ms = 1 second max
    while (stable_wait > 0) {
        if (spi_read_register(handle, ADXL354B_REG_STATUS, &status, 1) == 0) {
            if (status & 0x04) { // STABLE bit
                break;
            }
        }
        gpioDelay(10000); // 10 ms
        stable_wait--;
    }
    if (stable_wait == 0) {
        fprintf(stderr, "Timeout waiting for STABLE bit\n");
        return -1;
    }

    // Set measurement mode (set RUN bit in POWER_CTL)
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x01) != 0) {
        fprintf(stderr, "Failed to set measurement mode\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay

    return 0;
}

// Function to read acceleration data from ADXL354B
int read_acceleration_data(int handle, float *x, float *y, float *z) {
    uint8_t x_data[3], y_data[3], z_data[3];
    int16_t x_raw, y_raw, z_raw;

    // Read X axis data (3 bytes)
    if (spi_read_register(handle, ADXL354B_REG_XDATA, x_data, 3) != 0) {
        fprintf(stderr, "Failed to read X axis data\n");
        return -1;
    }

    // Read Y axis data (3 bytes)
    if (spi_read_register(handle, ADXL354B_REG_YDATA, y_data, 3) != 0) {
        fprintf(stderr, "Failed to read Y axis data\n");
        return -1;
    }

    // Read Z axis data (3 bytes)
    if (spi_read_register(handle, ADXL354B_REG_ZDATA, z_data, 3) != 0) {
        fprintf(stderr, "Failed to read Z axis data\n");
        return -1;
    }

    // Combine 3 bytes into 20-bit signed integer (left-justified)
    x_raw = (int16_t)((x_data[0] << 12) | (x_data[1] << 4) | (x_data[2] >> 4));
    y_raw = (int16_t)((y_data[0] << 12) | (y_data[1] << 4) | (y_data[2] >> 4));
    z_raw = (int16_t)((z_data[0] << 12) | (z_data[1] << 4) | (z_data[2] >> 4));

    // Convert to g-force units
    *x = x_raw * SENSITIVITY;
    *y = y_raw * SENSITIVITY;
    *z = z_raw * SENSITIVITY;

    return 0;
}

// Function to log data to file
void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, X: %.6f g, Y: %.6f g, Z: %.6f g\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (program_running) {
        if (read_acceleration_data(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    cleanup();

    return 0;
}

