#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ADIS16362 Register Addresses */
#define X_GYRO_REG 0x04
#define Y_GYRO_REG 0x06
#define Z_GYRO_REG 0x08
#define X_ACCL_REG 0x0A
#define Y_ACCL_REG 0x0C
#define Z_ACCL_REG 0x0E

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 /* 1 MHz */
#define SPI_FLAGS 0x03    /* Mode 3: CPOL=1, CPHA=1 */

/* Scaling Factors */
#define GYRO_SCALE 0.05f   /* deg/sec/LSB */
#define ACCL_SCALE 0.0025f /* g/LSB */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read a 16-bit register from the ADIS16362 via SPI.
 * ADIS16362 read protocol: send address with MSB set, then dummy byte.
 * The requested data is returned on the next 16-bit transfer.
 * Returns 0 on success, -1 on SPI error. */
static int read_register(uint8_t reg_addr, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];
    int ret;

    /* Send read command: address with MSB set (read bit) */
    tx_buf[0] = (char)(reg_addr | 0x80);
    tx_buf[1] = 0x00; /* dummy byte */

    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read command failed for reg 0x%02X (ret=%d)\n", reg_addr, ret);
        return -1;
    }

    /* Wait for conversion (stall) */
    gpioDelay(100); /* 100 us */

    /* Read the actual data */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;
    ret = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data read failed for reg 0x%02X (ret=%d)\n", reg_addr, ret);
        return -1;
    }

    *value = (int16_t)(((uint16_t)(uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Log IMU data to CSV file with high-precision timestamp */
static void log_data(float x_gyro, float y_gyro, float z_gyro,
                     float x_accl, float y_accl, float z_accl) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel=%d, baud=%d, flags=0x%02X)\n",
                SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("ADIS16362 IMU logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
        int16_t raw_accl_x, raw_accl_y, raw_accl_z;

        /* Read gyroscope data */
        if (read_register(X_GYRO_REG, &raw_gyro_x) != 0 ||
            read_register(Y_GYRO_REG, &raw_gyro_y) != 0 ||
            read_register(Z_GYRO_REG, &raw_gyro_z) != 0) {
            fprintf(stderr, "Gyroscope read error, skipping sample\n");
            gpioDelay(10000); /* 10 ms */
            continue;
        }

        /* Read accelerometer data */
        if (read_register(X_ACCL_REG, &raw_accl_x) != 0 ||
            read_register(Y_ACCL_REG, &raw_accl_y) != 0 ||
            read_register(Z_ACCL_REG, &raw_accl_z) != 0) {
            fprintf(stderr, "Accelerometer read error, skipping sample\n");
            gpioDelay(10000);
            continue;
        }

        /* Convert raw data to physical units */
        float x_gyro = (float)raw_gyro_x * GYRO_SCALE;
        float y_gyro = (float)raw_gyro_y * GYRO_SCALE;
        float z_gyro = (float)raw_gyro_z * GYRO_SCALE;
        float x_accl = (float)raw_accl_x * ACCL_SCALE;
        float y_accl = (float)raw_accl_y * ACCL_SCALE;
        float z_accl = (float)raw_accl_z * ACCL_SCALE;

        /* Log the data */
        log_data(x_gyro, y_gyro, z_gyro, x_accl, y_accl, z_accl);

        /* Delay to achieve approximately 100 Hz sampling */
        gpioDelay(10000); /* 10 ms */
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

