#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_status(int pin17_val, int pin27_val) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Sensor 17 (GPIO%d): %s | Sensor 27 (GPIO%d): %s\n",
           timestamp,
           GPIO_PIN_17,
           (pin17_val == 0) ? "OBSTACLE DETECTED" : "clear",
           GPIO_PIN_27,
           (pin27_val == 0) ? "OBSTACLE DETECTED" : "clear");
    fflush(stdout);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_bulk lines;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure both lines as inputs */
    gpiod_line_bulk_init(&lines);
    gpiod_line_bulk_add(&lines, GPIO_PIN_17);
    gpiod_line_bulk_add(&lines, GPIO_PIN_27);

    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "Failed to allocate line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "Failed to allocate line config: %s\n", strerror(errno));
        goto cleanup;
    }

    ret = gpiod_line_config_add_line_settings(line_cfg, &lines, settings);
    if (ret != 0) {
        fprintf(stderr, "Failed to add line settings: %s\n", strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "Failed to allocate request config: %s\n", strerror(errno));
        goto cleanup;
    }
    gpiod_request_config_set_consumer(req_cfg, "ky032-avoidance");

    request = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (request == NULL) {
        fprintf(stderr, "Failed to request GPIO lines %d and %d: %s\n",
                GPIO_PIN_17, GPIO_PIN_27, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 obstacle avoidance system started.\n");
    printf("Sensor 17 on GPIO%d, Sensor 27 on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_PIN_17, GPIO_PIN_27);
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        struct gpiod_line_values *values = gpiod_line_request_get_values(request);
        if (values == NULL) {
            fprintf(stderr, "Failed to read line values: %s\n", strerror(errno));
            break;
        }

        int val17 = gpiod_line_values_get_value(values, GPIO_PIN_17);
        int val27 = gpiod_line_values_get_value(values, GPIO_PIN_27);

        if (val17 < 0 || val27 < 0) {
            fprintf(stderr, "Failed to read line values: %s\n", strerror(errno));
            gpiod_line_values_free(values);
            break;
        }

        log_status(val17, val27);

        gpiod_line_values_free(values);

        /* Sleep 100 ms; usleep is interruptible by signals */
