/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Uses libgpiod for CS line control and spidev for SPI communication.
 * SPI0, CE0 (GPIO8), Mode 3, 1 MHz, MSB first.
 *
 * Build: gcc -O2 -Wall -o adis16266 adis16266.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define GPIO_CHIP       "gpiochip4"
#define CS_LINE_OFFSET  8          /* GPIO8 = SPI0 CE0 */

#define ADIS16266_XGYRO_OUT  0x04
#define ADIS16266_YGYRO_OUT  0x06
#define ADIS16266_ZGYRO_OUT  0x08
#define ADIS16266_MSC_CTRL   0x24

#define SCALE_FACTOR  0.02f   /* deg/sec per LSB */
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ADIS16266 two-transfer read: send address with MSB set, then read 2 bytes. */
static int adis16266_read_reg16(int spi_fd, struct gpiod_line *cs_line,
                                 uint8_t reg, int16_t *out)
{
    uint8_t tx[2], rx[2];
    struct spi_ioc_transfer tr;
    int ret;

    /* Phase 1: send read address (MSB = 1) */
    memset(&tr, 0, sizeof(tr));
    tx[0] = reg | 0x80;
    tx[1] = 0x00;
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)tx;
    tr.len = 2;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI write phase failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    /* Phase 2: dummy byte to clock out data */
    memset(&tr, 0, sizeof(tr));
    tx[0] = 0x00;
    tx[1] = 0x00;
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 2;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI read phase failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static int adis16266_write_reg8(int spi_fd, struct gpiod_line *cs_line,
                                 uint8_t reg, uint8_t value)
{
    uint8_t tx[2], rx[2];
    struct spi_ioc_transfer tr;
    int ret;

    memset(&tr, 0, sizeof(tr));
    tx[0] = reg & 0x7F;
    tx[1] = value;
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 2;
    tr.speed_hz = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        fprintf(stderr, "CS low failed: %s\n", strerror(errno));
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 1) {
        fprintf(stderr, "SPI write failed: %s\n", strerror(errno));
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        fprintf(stderr, "CS high failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int spi_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_3;
    uint8_t bits = 8;
    uint32_t speed = 1000000;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open GPIO chip and request CS line */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP, strerror(errno));
        goto cleanup;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                CS_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(cs_line, "adis16266-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Enable data-ready mode via MSC_CTRL */
    if (adis16266_write_reg8(spi_fd, cs_line, ADIS16266_MSC_CTRL, 0x01) < 0) {
        fprintf(stderr, "Failed to configure ADIS16266\n");
        goto cleanup;
    }

    printf("ADIS16266 Gyroscope Reader (SPI0 CE0, Mode 3, 1 MHz)\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x_raw, y_raw, z_raw;
        float x_rate, y_rate, z_rate;

        if (adis16266_read_reg16(spi_fd, cs_line, ADIS16266_XGYRO_OUT, &x_raw) < 0 ||
            adis16266_read_reg16(spi_fd, cs_line, ADIS16266_YGYRO_OUT, &y_raw) < 0 ||
            adis16266_read_reg16(spi_fd, cs_line, ADIS16266_ZGYRO_OUT, &z_raw) < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        x_rate = (float)x_raw * SCALE_FACTOR;
        y_rate = (float)y_raw * SCALE_FACTOR;
        z_rate = (float)z_raw * SCALE_FACTOR;

        printf("X: %7.2f deg/s  Y: %7.2f deg/s  Z: %7.2f deg/s\n",
               x_rate, y_rate, z_rate);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line)
        gpiod_line_release(cs_line);
    if (chip)
        gpiod_chip_close(chip);
    if (spi_fd >= 0)
        close(spi_fd);

    return ret;
}

