/* LSM6DSR I2C 7-bit address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I    0x0F
#define CTRL1_XL    0x10
#define CTRL2_G     0x11
#define OUTX_L_G    0x22
#define OUTX_L_XL   0x28

/* Expected chip ID */
#define LSM6DSR_WHO_AM_I 0x6B

/* Sensitivities for +-2g accel and +-250 dps gyro */
#define ACCEL_SENSITIVITY 0.000061f   /* g/LSB */
#define GYRO_SENSITIVITY  0.00875f    /* dps/LSB */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, val, rc);
        return -1;
    }
