/* FXOS8700 I2C address (SA0 tied to GND on Adafruit breakout) */
#define FXOS8700_ADDR 0x1D

/* FXOS8700 register addresses */
#define FXOS8700_WHO_AM_I   0x0D
#define FXOS8700_CTRL_REG1  0x2A
#define FXOS8700_CTRL_REG2  0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB  0x01

/* Expected chip ID */
#define FXOS8700_WHO_AM_I_VAL 0xC7

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed: reg=0x%02X, val=0x%02X, rc=%d\n", reg, val, rc);
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed: reg=0x%02X, rc=%d\n", reg, rc);
    }
    return rc;
}

static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed: reg=0x%02X, expected=%u, got=%d\n", reg, len, rc);
        return -1;
    }
    return 0;
}

static int init_fxos8700(int handle) {
    int who = read_reg(handle, FXOS8700_WHO_AM_I);
    if (who < 0) {
        return -1;
    }
    if (who != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (write_reg(handle, FXOS8700_CTRL_REG1, 0x00) < 0) return -1;
    if (write_reg(handle, FXOS8700_CTRL_REG2, 0x00) < 0) return -1;

    /* Hybrid mode: enable accelerometer (auto-increment) and magnetometer */
    if (write_reg(handle, FXOS8700_M_CTRL_REG1, 0x1F) < 0) return -1;
    if (write_reg(handle, FXOS8700_M_CTRL_REG2, 0x20) < 0) return -1;

    /* Active mode, 100 Hz ODR (0x01 = 0b00000001) */
    if (write_reg(handle, FXOS8700_CTRL_REG1, 0x01) < 0) return -1;

    return 0;
}

static int read_sensor_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *mx, int16_t *my, int16_t *mz) {
    uint8_t buf[12];
    if (read_block(handle, FXOS8700_OUT_X_MSB, buf, sizeof(buf)) < 0) {
        return -1;
    }

    /* Accelerometer: 14-bit left-aligned, shift right 2 to get 16-bit signed */
    *ax = (int16_t)((buf[0] << 8) | buf[1]) >> 2;
    *ay = (int16_t)((buf[2] << 8) | buf[3]) >> 2;
    *az = (int16_t)((buf[4] << 8) | buf[5]) >> 2;

    /* Magnetometer: 16-bit signed */
    *mx = (int16_t)((buf[6] << 8) | buf[7]);
    *my = (int16_t)((buf[8] << 8) | buf[9]);
    *mz = (int16_t)((buf[10] << 8) | buf[11]);

    return 0;
}

