#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define SOUND_SENSOR_GPIO 17
#define SAMPLE_INTERVAL_US 1000   /* 1 ms */
#define WINDOW_DURATION_S 5
#define LOOP_PAUSE_S 1

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int validate_threshold(int threshold) {
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer (got %d)\n", threshold);
        return 0;
    }
    return 1;
}

static int read_sound_sensor(void) {
    int level = gpioRead(SOUND_SENSOR_GPIO);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO %d\n", SOUND_SENSOR_GPIO);
        return -1;
    }
    return level;
}

static void print_timestamp(void) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);
    printf("[%s] ", buf);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long val = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || endptr == argv[1]) {
        fprintf(stderr, "Error: threshold must be an integer\n");
        return EXIT_FAILURE;
    }
    int threshold = (int)val;

    if (!validate_threshold(threshold)) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", SOUND_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Noise monitoring started. Threshold: %d high readings in %d seconds.\n", threshold, WINDOW_DURATION_S);
    printf("Press Ctrl+C to exit.\n");

    while (program_running) {
        int high_count = 0;
        int error = 0;

        for (int i = 0; i < WINDOW_DURATION_S * 1000 && program_running; i++) {
            int level = read_sound_sensor();
            if (level < 0) {
                error = 1;
                break;
            }
            if (level == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
        }

        if (error) {
            break;
        }

        if (high_count > threshold) {
            print_timestamp();
            printf("ALERT: %d high readings in %d seconds (threshold: %d)\n",
                   high_count, WINDOW_DURATION_S, threshold);
        } else {
            print_timestamp();
            printf("Status: %d high readings in %d seconds (threshold: %d)\n",
                   high_count, WINDOW_DURATION_S, threshold);
        }

        if (program_running) {
            sleep(LOOP_PAUSE_S);
        }
    }

    gpioTerminate();
    printf("\nNoise monitoring stopped.\n");
    return EXIT_SUCCESS;
}

