/*
 * Door Access Control System (Raspberry Pi 4 Model B)
 * Uses libgpiod (modern GPIO API) instead of wiringPi.
 *
 * GPIO17 -> TIP120 -> 5V relay module -> 12V door lock
 *   LOW  = energized (locked)
 *   HIGH = de-energized (unlocked)
 *
 * Build: gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define CODE_LENGTH 6
#define LOG_FILE    "access_log.txt"
#define UNLOCK_SEC  5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int generate_code(void)
{
    return (rand() % 900000) + 100000; /* 100000..999999 */
}

static int unlock_door(struct gpiod_line *line, int duration_sec)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to set line HIGH (unlock): %s\n",
                strerror(errno));
        return -1;
    }
    sleep(duration_sec);
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to set line LOW (lock): %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static int log_access(int code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error: writing to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Error: cannot open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Get lines --- */
    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        fprintf(stderr, "Error: cannot get GPIO%d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        fprintf(stderr, "Error: cannot get GPIO%d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Request lines as outputs, default LOW (energized/locked) --- */
    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Error: request_output GPIO%d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Error: request_output GPIO%d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door Access Control System\n");
    printf("Door A: GPIO%d (active-HIGH relay via TIP120)\n", DOOR_A_PIN);
    printf("Door B: GPIO%d\n", DOOR_B_PIN);
    printf("Unlock duration: %d seconds\n", UNLOCK_SEC);
    printf("Press Ctrl+C to exit.\n\n");

    int code = generate_code();
    printf("Generated 6-digit code: %06d\n", code);
    fflush(stdout);

    while (g_running) {
        printf("Enter 6-digit code: ");
        fflush(stdout);

        char input[16];
        if (!fgets(input, sizeof(input), stdin)) {
            if (feof(stdin)) {
                printf("\nEOF received, exiting.\n");
                break;
            }
            fprintf(stderr, "Error: fgets failed: %s\n", strerror(errno));
            break;
        }

        /* Strip trailing newline */
        input[strcspn(input, "\n")] = '\0';

        /* Validate: all digits, length == CODE_LENGTH */
        int valid = 1;
        for (int i = 0; i < CODE_LENGTH; i++) {
            if (!isdigit((unsigned char)input[i])) {
                valid = 0;
                break;
            }
        }
        if (!valid || (int)strlen(input) != CODE_LENGTH) {
            fprintf(stderr, "Invalid input. Please enter exactly %d digits.\n",
                    CODE_LENGTH);
            continue;
        }

        int entered = atoi(input);
        if (entered < 100000 || entered > 999999) {
            fprintf(stderr, "Invalid range. Code must be between 100000 and 999999.\n");
            continue;
        }

        if (entered == code) {
            printf("Access granted! Unlocking Door A for %d seconds...\n",
                   UNLOCK_SEC);
            fflush(stdout);

            if (unlock_door(line_a, UNLOCK_SEC) < 0) {
                fprintf(stderr, "Error: unlock_door failed.\n");
            } else {
                printf("Door A locked.\n");
                fflush(stdout);
                if (log_access(code) < 0) {
                    fprintf(stderr, "Warning: log_access failed.\n");
                }
                code = generate_code();
                printf("New 6-digit code: %06d\n", code);
                fflush(stdout);
            }
        } else {
            printf("Access denied.\n");
            fflush(stdout);
        }
    }

    /* --- Ensure both doors are locked (LOW) --- */
    if (line_a) gpiod_line_set_value(line_a, 0);
    if (line_b) gpiod_line_set_value(line_b, 0);

    ret = EXIT_SUCCESS;

cleanup:
    if (line_a) gpiod_line_release(line_a);
    if (line_b) gpiod_line_release(line_b);
    if (chip)   gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return ret;
}

