#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BH1750_ADDR 0x23
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "light_log.txt"
#define BH1750_ONE_TIME_HIGH_RES_2 0x21
#define BH1750_CONV_TIME_MS 180

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_write_cmd(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error writing command 0x%02X to BH1750: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read_data(int fd, uint16_t *raw_value) {
    uint8_t buf[2];
    ssize_t bytes = read(fd, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading from BH1750 (read %zd bytes): %s\n", bytes, strerror(errno));
        return -1;
    }
    *raw_value = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2f;
}

static int log_data(const char *timestamp, float lux_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    char timestamp[32];
    struct timespec ts;
    struct tm *tm_info;
    float lux_value;
    uint16_t raw_value;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("BH1750 light sensor logging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (bh1750_write_cmd(fd, BH1750_ONE_TIME_HIGH_RES_2) == -1) {
            fprintf(stderr, "Failed to write command to BH1750. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        usleep(BH1750_CONV_TIME_MS * 1000);

        if (bh1750_read_data(fd, &raw_value) == -1) {
            fprintf(stderr, "Failed to read data from BH1750. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        lux_value = calculate_lux(raw_value);

        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            sleep(5);
            continue;
        }
        tm_info = localtime(&ts.tv_sec);
        if (tm_info == NULL) {
            fprintf(stderr, "Error converting time.\n");
            sleep(5);
            continue;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        if (log_data(timestamp, lux_value) == -1) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);

        sleep(5);
    }

    printf("\nExiting gracefully...\n");
    if (fd >= 0) {
        close(fd);
    }
    return 0;
}

