#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define PORT 12345
#define SHARED_SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define SAMPLE_INTERVAL_US 20000
#define PLAYBACK_DURATION_S 5

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

static int i2c_handle = -1;
static int server_fd = -1;
static int client_fd = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_init(void) {
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(10000);

    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: MPR121 electrode config failed\n");
        return -1;
    }
    return 0;
}

static int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }
    *touch_data = (buf[1] << 8) | buf[0];
    return 0;
}

static void set_pwm_frequency(int frequency) {
    if (frequency <= 0) frequency = 1;
    gpioSetPWMfrequency(PWM_GPIO, frequency);
    gpioPWM(PWM_GPIO, PWM_RANGE / 2);
}

static void log_frequency(int frequency) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%d\n", frequency);
        fclose(fp);
    } else {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        cleanup();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioPWM(PWM_GPIO, 0);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Error: setsockopt failed\n");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: Bind failed\n");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: Listen failed\n");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (!terminate) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error: Accept failed\n");
            continue;
        }

        char buffer[1024];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received: %s\n", buffer);

            if (strstr(buffer, SHARED_SECRET) != NULL) {
                printf("Motion detected! Playing theremin...\n");
                time_t start_time = time(NULL);
                int touch_data;

                while (!terminate && (time(NULL) - start_time) < PLAYBACK_DURATION_S) {
                    if (read_touch_data(&touch_data) == 0) {
                        int max_touch = 0;
                        for (int i = 0; i < 12; i++) {
                            if (touch_data & (1 << i)) {
                                max_touch = i + 1;
                            }
                        }
                        if (max_touch > 0) {
                            int frequency = 220 + (int)(log10(max_touch + 1) * 660);
                            if (frequency > 880) frequency = 880;
                            set_pwm_frequency(frequency);
                            log_frequency(frequency);
                        }
                    }
                    gpioDelay(SAMPLE_INTERVAL_US);
                }
                gpioPWM(PWM_GPIO, 0);
            }
        } else if (bytes_received < 0) {
            fprintf(stderr, "Error: Receive failed\n");
        }
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

