        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        cleanup();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    gpioPWM(PWM_GPIO, 0);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        cleanup();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        fprintf(stderr, "Error: setsockopt failed\n");
        cleanup();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        fprintf(stderr, "Error: Bind failed\n");
        cleanup();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        fprintf(stderr, "Error: Listen failed\n");
        cleanup();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    while (!terminate) {
        client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error: Accept failed\n");
            continue;
        }

        char buffer[1024];
        ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received: %s\n", buffer);

            if (strstr(buffer, SHARED_SECRET) != NULL) {
                printf("Motion detected! Playing theremin...\n");
                time_t start_time = time(NULL);
                int touch_data;

                while (!terminate && (time(NULL) - start_time) < PLAYBACK_DURATION_S) {
                    if (read_touch_data(&touch_data) == 0) {
                        int max_touch = 0;
                        for (int i = 0; i < 12; i++) {
                            if (touch_data & (1 << i)) {
                                max_touch = i + 1;
                            }
                        }
                        if (max_touch > 0) {
                            int frequency = 220 + (int)(log10(max_touch + 1) * 660);
                            if (frequency > 880) frequency = 880;
                            set_pwm_frequency(frequency);
                            log_frequency(frequency);
                        }
                    }
                    gpioDelay(SAMPLE_INTERVAL_US);
                }
                gpioPWM(PWM_GPIO, 0);
            }
        } else if (bytes_received < 0) {
            fprintf(stderr, "Error: Receive failed\n");
        }
        close(client_fd);
        client_fd = -1;
    }

    cleanup();
    return 0;
}

