#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDRESS 0x1E

// LSM303DLHC Magnetometer Registers
#define LSM303_CTRL_REG1_M 0x20
#define LSM303_OUT_X_L_M 0x08

// GPIO pin for LED
#define LED_PIN 17

// I2C device path
#define I2C_DEVICE "/dev/i2c-1"

// Global variables for cleanup
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c(void);
int init_magnetometer(void);
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_z_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(double z_magnitude);
void cleanup(void);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Initialize I2C communication
int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LSM303_ADDRESS, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Initialize the LSM303DLHC magnetometer
int init_magnetometer(void) {
    uint8_t reg = LSM303_CTRL_REG1_M;
    uint8_t value = 0x18; // 10 Hz continuous conversion

    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write CTRL_REG1_M: %s\n", strerror(errno));
        return -1;
    }

    if (write(i2c_fd, &value, 1) != 1) {
        fprintf(stderr, "Failed to set CTRL_REG1_M value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read magnetometer data (X, Y, Z) in a single I2C block read
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = LSM303_OUT_X_L_M;
    uint8_t buffer[6];

    // Write the starting register address
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Failed to write register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data
    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes (little-endian)
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate the magnitude of the Z-axis field
double calculate_z_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt((double)x * x + (double)y * y + (double)z * z);
}

// Set LED brightness using hardware PWM via libgpiod
int set_led_brightness(double z_magnitude) {
    // Map the magnitude to a PWM duty cycle (0-100%)
    int duty_cycle = (int)(z_magnitude / 1000.0 * 100.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    // libgpiod does not support hardware PWM directly; we use software PWM via gpiod_line_set_value
    // For simplicity, we set the line high if duty_cycle > 50, otherwise low
    // This is a basic approximation; for true PWM, use a timer-based approach or external hardware
    int value = (duty_cycle > 50) ? 1 : 0;
    if (gpiod_line_set_value(led_line, value) < 0) {
        fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn off LED
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Set up signal handlers
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO using libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", LED_PIN, strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(led_line, "lsm303_led", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("lsm303_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int16_t x, y, z;
    double z_magnitude;

    // Main loop
    while (running) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate Z-axis magnitude
            z_magnitude = calculate_z_magnitude(x, y, z);

            // Set LED brightness
            if (set_led_brightness(z_magnitude) != 0) {
                fprintf(stderr, "Failed to set LED brightness\n");
            }

            // Log data
            fprintf(log_file, "X: %d, Y: %d, Z: %d, Z Magnitude: %.2f\n", x, y, z, z_magnitude);
            fflush(log_file);
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        usleep(100000); // 100 ms delay
    }

    // Cleanup
    cleanup();

    return 0;
}

