        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

static int read_magnetometer(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_msb, x_lsb, z_msb, z_lsb, y_msb, y_lsb;

    if (read_register(handle, HMC5883L_DATA_X_MSB, &x_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_X_MSB + 1, &x_lsb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Z_MSB, &z_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Z_MSB + 1, &z_lsb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Y_MSB, &y_msb) < 0) return -1;
    if (read_register(handle, HMC5883L_DATA_Y_MSB + 1, &y_lsb) < 0) return -1;

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);

    return 0;
}

static void calculate_hard_iron(int16_t x, int16_t y, int16_t z,
                                int *offset_x, int *offset_y, int *offset_z,
                                int *sample_count, int16_t *buffer_x,
                                int16_t *buffer_y, int16_t *buffer_z) {
    static int idx = 0;
    buffer_x[idx] = x;
    buffer_y[idx] = y;
    buffer_z[idx] = z;
    idx = (idx + 1) % NUM_SAMPLES;

    int count = (*sample_count < NUM_SAMPLES) ? *sample_count : NUM_SAMPLES;
    *offset_x = 0;
    *offset_y = 0;
    *offset_z = 0;

    for (int i = 0; i < count; i++) {
        *offset_x += buffer_x[i];
        *offset_y += buffer_y[i];
        *offset_z += buffer_z[i];
    }

    *offset_x /= count;
    *offset_y /= count;
    *offset_z /= count;

    *sample_count = (*sample_count < NUM_SAMPLES) ? (*sample_count + 1) : NUM_SAMPLES;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int16_t buffer_x[NUM_SAMPLES], buffer_y[NUM_SAMPLES], buffer_z[NUM_SAMPLES];
    int offset_x = 0, offset_y = 0, offset_z = 0;
    int sample_count = 0;

    while (running) {
        int16_t x, y, z;

        if (read_magnetometer(i2c_handle, &x, &y, &z) == 0) {
            calculate_hard_iron(x, y, z, &offset_x, &offset_y, &offset_z,
                                &sample_count, buffer_x, buffer_y, buffer_z);

            int corrected_x = x - offset_x;
            int corrected_y = y - offset_y;
            int corrected_z = z - offset_z;

            printf("X: %d, Y: %d, Z: %d\n", corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Error reading magnetometer data\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

