/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 * Uses Linux i2c-dev + libgpiod (no wiringPi).
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2  (physical pin 3, I2C bus 1)
 *   LSM303D SCL  -> Pi GPIO3  (physical pin 5, I2C bus 1)
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *   LSM303D SA0  -> HIGH  (I2C address 0x1D)
 *
 * Build: gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- LSM303D constants ---- */
#define LSM303D_ADDR        0x1D
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49

#define LSM303D_CTRL_REG1_A 0x20
#define LSM303D_CTRL_REG4_A 0x23
#define LSM303D_INT1_CFG    0x30
#define LSM303D_INT1_THS    0x31
#define LSM303D_INT1_DURATION 0x32
#define LSM303D_OUT_X_L_A   0x28

#define LSM303D_CTRL1_A_VAL 0x57   /* 50 Hz, XYZ axes enabled */
#define LSM303D_CTRL4_A_VAL 0x00   /* +-2 g full-scale */
#define LSM303D_INT_CFG_VAL 0x2A   /* Any-motion, high threshold */
#define LSM303D_INT_THS_VAL 0x7D   /* 2000 mg threshold (16 LSB/g) */
#define LSM303D_INT_DURATION_VAL 0x00 /* immediate */

#define I2C_BUS        "/dev/i2c-1"
#define GPIO_CHIP       "gpiochip4"   /* BCM GPIO on Pi Zero W */
#define INT1_BCM_PIN    23
#define BUFFER_SIZE     64
#define SAMPLE_PERIOD_US 10000       /* 10 ms */

/* ---- Data structures ---- */
typedef struct {
    int16_t x, y, z;
} accel_t;

typedef struct {
    struct timespec ts;
    accel_t data;
} buffer_entry_t;

typedef struct {
    buffer_entry_t buf[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_int1_line = NULL;

/* ---- I2C helpers ---- */
static int i2c_read_byte(int fd, uint8_t reg)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0)
        fprintf(stderr, "I2C read 0x%02X failed: %s\n", reg, strerror(errno));
    return v;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    int r = i2c_smbus_write_byte_data(fd, reg, val);
    if (r < 0)
        fprintf(stderr, "I2C write 0x%02X <- 0x%02X failed: %s\n",
                reg, val, strerror(errno));
    return r;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int r = i2c_smbus_read_i2c_block_data(fd, reg, len, buf);
    if (r != len)
        fprintf(stderr, "I2C block read 0x%02X (%u) failed: got %d: %s\n",
                reg, len, r, strerror(errno));
    return r;
}

/* ---- LSM303D ---- */
static int lsm303d_init(int fd)
{
    int id = i2c_read_byte(fd, LSM303D_WHO_AM_I);
    if (id < 0)
        return -1;
    if (id != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                id, LSM303D_WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_byte(fd, LSM303D_CTRL_REG1_A, LSM303D_CTRL1_A_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_CTRL_REG4_A, LSM303D_CTRL4_A_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_INT1_CFG, LSM303D_INT_CFG_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_INT1_THS, LSM303D_INT_THS_VAL) < 0)
        return -1;
    if (i2c_write_byte(fd, LSM303D_INT1_DURATION, LSM303D_INT_DURATION_VAL) < 0)
        return -1;

    return 0;
}

static int lsm303d_read_accel(int fd, accel_t *out)
{
    uint8_t raw[6];
    /* Auto-increment: OR the MSB of the register address */
    if (i2c_read_block(fd, LSM303D_OUT_X_L_A | 0x80, raw, 6) != 6)
        return -1;

    out->x = (int16_t)((raw[1] << 8) | raw[0]);
    out->y = (int16_t)((raw[3] << 8) | raw[2]);
    out->z = (int16_t)((raw[5] << 8) | raw[4]);
    return 0;
}

/* ---- Circular buffer ---- */
static void buffer_init(circular_buffer_t *cb)
{
    cb->head = 0;
    cb->count = 0;
}

static void buffer_add(circular_buffer_t *cb, const buffer_entry_t *e)
{
    cb->buf[cb->head] = *e;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

/* ---- GPIO interrupt (libgpiod) ---- */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    g_int1_line = gpiod_chip_get_line(g_chip, INT1_BCM_PIN);
    if (!g_int1_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", INT1_BCM_PIN, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    /* Request rising-edge events */
    if (gpiod_line_request_rising_edge_events(g_int1_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events: %s\n", strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        g_int1_line = NULL;
        return -1;
    }
    return 0;
}

static int gpio_event_pending(void)
{
    return gpiod_line_event_pending(g_int1_line);
}

static int gpio_read_event(struct timespec *ts)
{
    struct gpiod_line_event ev;
    if (gpiod_line_event_read(g_int1_line, &ev) < 0) {
        fprintf(stderr, "gpiod_line_event_read: %s\n", strerror(errno));
        return -1;
    }
    *ts = ev.ts;
    return 0;
}

/* ---- Signal handling ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2c_write_byte(g_i2c_fd, LSM303D_CTRL_REG1_A, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_int1_line) {
        gpiod_line_release(g_int1_line);
        g_int1_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", LSM303D_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (lsm303d_init(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM303D init failed\n");
        cleanup();
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO init failed\n");
        cleanup();
        return 1;
    }

    circular_buffer_t cb;
    buffer_init(&cb);

    printf("LSM303D monitoring started. Press Ctrl-C to exit.\n");

    while (g_running) {
        accel_t a;
        if (lsm303d_read_accel(g_i2c_fd, &a) < 0) {
            fprintf(stderr, "Warning: accelerometer read failed, skipping sample\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        buffer_entry_t e;
        clock_gettime(CLOCK_MONOTONIC, &e.ts);
        e.data = a;
        buffer_add(&cb, &e);

        if (gpio_event_pending()) {
            struct timespec int_ts;
            if (gpio_read_event(&int_ts) == 0) {
                printf("\n--- Interrupt at %ld.%09ld ---\n",
                       (long)int_ts.tv_sec, int_ts.tv_nsec);
                int dump_count = (cb.count < 10) ? cb.count : 10;
                int start = (cb.head - dump_count + BUFFER_SIZE) % BUFFER_SIZE;
                for (int i = 0; i < dump_count; i++) {
                    int idx = (start + i) % BUFFER_SIZE;
                    printf("  [%d] %ld.%09ld  X=%d Y=%d Z=%d\n",
                           i,
                           cb.buf[idx].ts.tv_sec, cb.buf[idx].ts.tv_nsec,
                           cb.buf[idx].data.x, cb.buf[idx].data.y, cb.buf[idx].data.z);
                }
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

