#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define EXPECTED_CODE "123456"
#define CODE_LENGTH 6
#define TIMEOUT_SEC 5
#define UNLOCK_DURATION_MS 2000
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int serial_fd1 = -1;
static int serial_fd2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "Error clearing O_NDELAY on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 1;
    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr on %s: %s\n", port, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_code(int fd, char *code, size_t len) {
    if (fd < 0 || code == NULL || len == 0) return -1;
    memset(code, 0, len);
    time_t start = time(NULL);
    while (running) {
        if (time(NULL) - start >= TIMEOUT_SEC) return -1;
        char ch;
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                usleep(POLL_DELAY_US);
                continue;
            }
            fprintf(stderr, "Serial read error on fd %d: %s\n", fd, strerror(errno));
            return -1;
        }
        if (n == 0) {
            usleep(POLL_DELAY_US);
            continue;
        }
        if (ch >= '0' && ch <= '9') {
            size_t cur = strlen(code);
            if (cur < len - 1) {
                code[cur] = ch;
                code[cur + 1] = '\0';
            } else {
                fprintf(stderr, "Code too long, resetting\n");
                memset(code, 0, len);
            }
        } else if (ch == '\r' || ch == '\n') {
            if (strlen(code) == CODE_LENGTH) return 0;
            memset(code, 0, len);
        } else {
            memset(code, 0, len);
        }
    }
    return -1;
}

static int set_lock(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n", gpio, pigpio_error(gpioWrite(gpio, state)));
        return -1;
    }
    return 0;
}

static int unlock_doors(void) {
    if (set_lock(LOCK_1_GPIO, 1) != 0) return -1;
    if (set_lock(LOCK_2_GPIO, 1) != 0) return -1;
    printf("Doors unlocked.\n");
    gpioDelay(UNLOCK_DURATION_MS * 1000);
    if (set_lock(LOCK_1_GPIO, 0) != 0) return -1;
    if (set_lock(LOCK_2_GPIO, 0) != 0) return -1;
    printf("Doors locked.\n");
    return 0;
}

static int verify_code(const char *code1, const char *code2) {
    if (code1 == NULL || code2 == NULL) return 0;
    if (strlen(code1) != CODE_LENGTH || strlen(code2) != CODE_LENGTH) return 0;
    return strncmp(code1, code2, CODE_LENGTH) == 0;
}

static int verify_expected_code(const char *code) {
    if (code == NULL) return 0;
    return strncmp(code, EXPECTED_CODE, CODE_LENGTH) == 0;
}

int main(void) {
    char code1[CODE_LENGTH + 1] = {0};
    char code2[CODE_LENGTH + 1] = {0};

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LOCK_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LOCK_1_GPIO);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LOCK_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LOCK_2_GPIO);
        gpioTerminate();
        return 1;
    }
    if (set_lock(LOCK_1_GPIO, 0) != 0 || set_lock(LOCK_2_GPIO, 0) != 0) {
        gpioTerminate();
        return 1;
    }

    serial_fd1 = init_serial("/dev/serial0");
    if (serial_fd1 < 0) {
        gpioTerminate();
        return 1;
    }
    serial_fd2 = init_serial("/dev/serial1");
    if (serial_fd2 < 0) {
        close(serial_fd1);
        gpioTerminate();
        return 1;
    }

    printf("Dual-factor authentication system started. Waiting for codes...\n");

    while (running) {
        if (serial_fd1 >= 0 && strlen(code1) == 0) {
            if (read_code(serial_fd1, code1, sizeof(code1)) == 0) {
                printf("Primary UART: Code received: %s\n", code1);
            } else if (errno != EINTR) {
                fprintf(stderr, "Primary UART read timeout or error.\n");
            }
        }
        if (serial_fd2 >= 0 && strlen(code2) == 0) {
            if (read_code(serial_fd2, code2, sizeof(code2)) == 0) {
                printf("Secondary UART: Code received: %s\n", code2);
            } else if (errno != EINTR) {
                fprintf(stderr, "Secondary UART read timeout or error.\n");
            }
        }
        if (strlen(code1) > 0 && strlen(code2) > 0) {
            if (verify_code(code1, code2)) {
                if (verify_expected_code(code1)) {
                    printf("Codes match and are correct. Unlocking doors...\n");
                    if (unlock_doors() != 0) {
                        fprintf(stderr, "Error unlocking doors.\n");
                    }
                } else {
                    fprintf(stderr, "Codes match but are incorrect.\n");
                }
            } else {
                fprintf(stderr, "Codes do not match.\n");
            }
            memset(code1, 0, sizeof(code1));
            memset(code2, 0, sizeof(code2));
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_lock(LOCK_1_GPIO, 0);
    set_lock(LOCK_2_GPIO, 0);
    if (serial_fd1 >= 0) close(serial_fd1);
    if (serial_fd2 >= 0) close(serial_fd2);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

