            } else if (errno != EINTR) {
                fprintf(stderr, "Secondary UART read timeout or error.\n");
            }
        }
        if (strlen(code1) > 0 && strlen(code2) > 0) {
            if (verify_code(code1, code2)) {
                if (verify_expected_code(code1)) {
                    printf("Codes match and are correct. Unlocking doors...\n");
                    if (unlock_doors() != 0) {
                        fprintf(stderr, "Error unlocking doors.\n");
                    }
                } else {
                    fprintf(stderr, "Codes match but are incorrect.\n");
                }
            } else {
                fprintf(stderr, "Codes do not match.\n");
            }
            memset(code1, 0, sizeof(code1));
            memset(code2, 0, sizeof(code2));
        }
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    set_lock(LOCK_1_GPIO, 0);
    set_lock(LOCK_2_GPIO, 0);
    if (serial_fd1 >= 0) close(serial_fd1);
    if (serial_fd2 >= 0) close(serial_fd2);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

