#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define PIR_PIN      4
#define RELAY_PIN    17
#define STRIKE_MS    1000
#define POLL_MS      50
#define FAILSAFE_S   10

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_msg(int priority, const char *msg)
{
    time_t now = time(NULL);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));
    syslog(priority, "%s: %s", ts, msg);
}

int main(void)
{
    openlog("door_strike", LOG_PID | LOG_CONS, LOG_USER);
    log_msg(LOG_INFO, "Door strike controller starting");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_msg(LOG_ERR, "sigaction failed");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_msg(LOG_ERR, "Failed to open gpiochip0");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_msg(LOG_ERR, "Failed to get PIR line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_msg(LOG_ERR, "Failed to get relay line");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(pir_line, "door_strike_pir") < 0) {
        log_msg(LOG_ERR, "Failed to request PIR line as input");
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(relay_line, "door_strike_relay", 0) < 0) {
        log_msg(LOG_ERR, "Failed to request relay line as output");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        closelog();
        return EXIT_FAILURE;
    }

    log_msg(LOG_INFO, "PIR on GPIO4, relay on GPIO17");

    int relay_state = 0;
    time_t last_motion = 0;
    int failsafe_active = 0;

    while (g_running) {
        int pir = gpiod_line_get_value(pir_line);
        if (pir < 0) {
            log_msg(LOG_ERR, "PIR read error");
            usleep(POLL_MS * 1000);
            continue;
        }

        if (pir) {
            if (!failsafe_active) {
                log_msg(LOG_INFO, "Motion detected");
                last_motion = time(NULL);
            }

            if (relay_state == 0) {
                if (gpiod_line_set_value(relay_line, 1) < 0) {
                    log_msg(LOG_ERR, "Failed to energize relay");
                } else {
                    relay_state = 1;
                    log_msg(LOG_INFO, "Relay energized");
                }
            }

            if (last_motion && difftime(time(NULL), last_motion) > FAILSAFE_S) {
                if (!failsafe_active) {
                    log_msg(LOG_WARNING, "Failsafe triggered: PIR stuck HIGH for >10s");
                    failsafe_active = 1;
                }
            }
        } else {
            if (failsafe_active) {
                log_msg(LOG_WARNING, "Failsafe cleared: PIR returned LOW");
                failsafe_active = 0;
            }
        }

        if (relay_state && !g_running) {
            if (gpiod_line_set_value(relay_line, 0) < 0) {
                log_msg(LOG_ERR, "Failed to de-energize relay on shutdown");
            } else {
                relay_state = 0;
                log_msg(LOG_INFO, "Relay de-energized on shutdown");
            }
        }

        usleep(POLL_MS * 1000);
    }

    if (relay_state) {
        gpiod_line_set_value(relay_line, 0);
        relay_state = 0;
    }
    gpiod_line_release(pir_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    log_msg(LOG_INFO, "Door strike controller stopped");
    closelog();
    return EXIT_SUCCESS;
}

