#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

#define RELAY_ON_DURATION 300  /* seconds */
#define PAUSE_DURATION    60   /* seconds */
#define TIMER_INTERVAL    60   /* seconds */

#define NUM_RELAYS 4

static const int relay_gpios[NUM_RELAYS] = {
    RELAY1_GPIO, RELAY2_GPIO, RELAY3_GPIO, RELAY4_GPIO
};

/* Active-LOW relay: LOW = ON, HIGH = OFF */
#define RELAY_ON  0
#define RELAY_OFF 1

static volatile sig_atomic_t g_running = 1;

/* Timer state machine */
typedef enum {
    STATE_ACTIVATE,
    STATE_DEACTIVATE,
    STATE_PAUSE
} timer_state_t;

static timer_state_t g_timer_state = STATE_ACTIVATE;
static int g_current_relay = 0;
static int g_timer_active = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(int priority, const char *message)
{
    time_t now = time(NULL);
    char ts[32];
    struct tm tm_info;

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    syslog(priority, "%s: %s", ts, message);
}

static int set_relay(int gpio, int state)
{
    int rc = gpioWrite(gpio, state);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "gpioWrite failed on GPIO %d (state=%d): rc=%d",
                 gpio, state, rc);
        log_message(LOG_ERR, msg);
        return -1;
    }
    return 0;
}

static void timer_callback(int timer_id, void *user_data)
{
    (void)timer_id;
    (void)user_data;

    if (!g_timer_active) {
        g_timer_active = 1;
    }

    switch (g_timer_state) {
    case STATE_ACTIVATE: {
        int gpio = relay_gpios[g_current_relay];
        if (set_relay(gpio, RELAY_ON) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Relay %d (GPIO %d) activated (ON)",
                     g_current_relay + 1, gpio);
            log_message(LOG_INFO, msg);
        }
        g_timer_state = STATE_DEACTIVATE;
        break;
    }
    case STATE_DEACTIVATE: {
        int gpio = relay_gpios[g_current_relay];
        if (set_relay(gpio, RELAY_OFF) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Relay %d (GPIO %d) deactivated (OFF)",
                     g_current_relay + 1, gpio);
            log_message(LOG_INFO, msg);
        }
        g_timer_state = STATE_PAUSE;
        break;
    }
    case STATE_PAUSE: {
        g_current_relay = (g_current_relay + 1) % NUM_RELAYS;
        g_timer_state = STATE_ACTIVATE;
        break;
    }
    default:
        g_timer_state = STATE_ACTIVATE;
        break;
    }
}

static void cleanup(void)
{
    /* Deactivate all relays (set HIGH for active-LOW module) */
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_gpios[i], RELAY_OFF);
    }
    gpioTerminate();
    closelog();
}

int main(void)
{
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure all relay pins as outputs */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_gpios[i], PI_OUTPUT) < 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "gpioSetMode failed on GPIO %d",
                     relay_gpios[i]);
            log_message(LOG_ERR, msg);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Ensure all relays start in OFF state (HIGH for active-LOW module) */
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (set_relay(relay_gpios[i], RELAY_OFF) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_message(LOG_ERR, "sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message(LOG_ERR, "sigaction(SIGTERM) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start the 60-second timer */
    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL) < 0) {
        log_message(LOG_ERR, "gpioSetTimerFuncEx failed");
        cleanup();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Irrigation system started: 4 relays, 5 min on, 1 min pause");

    /* Main loop: sleep until signal received */
    while (g_running) {
        sleep(1);
    }

    log_message(LOG_INFO, "Shutting down irrigation system");
    cleanup();
    return EXIT_SUCCESS;
}

