#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define ACCEL_XOUT_H   0x3B
#define PWR_MGMT_1     0x6B
#define ACCEL_CONFIG   0x1C
#define ACCEL_SCALE    16384.0f
#define BUFFER_SIZE    100
#define TIMER_FREQ_HZ  100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *sysfs_latest = NULL;
static FILE *sysfs_data = NULL;
static volatile sig_atomic_t timer_fired = 0;
static struct sigevent sev;
static timer_t timerid;

typedef struct {
    float x, y, z;
    struct timespec ts;
} accel_data_t;

static accel_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
