#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define GPIO_CHIP "/dev/gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {18, 23, 24, 25};
static const int prime_intervals[NUM_RELAYS] = {2, 3, 5, 7};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Failed to set relay value");
    }
    return ret;
}

static int toggle_relay(struct gpiod_line *line) {
    int current = gpiod_line_get_value(line);
    if (current < 0) {
        perror("Failed to read relay state");
        return -1;
    }
    return set_relay(line, current ? 0 : 1);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    struct timespec last_toggle[NUM_RELAYS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u\n", relay_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "smart-lighting", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output\n", relay_pins[i]);
            goto cleanup;
        }
        if (clock_gettime(CLOCK_MONOTONIC, &last_toggle[i]) < 0) {
            perror("Failed to get initial time");
            goto cleanup;
        }
    }

    printf("Smart lighting system started. Press Ctrl+C to exit.\n");

    while (running) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            struct timespec now;
            if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
                perror("clock_gettime failed");
                continue;
            }

            long elapsed_ms = (now.tv_sec - last_toggle[i].tv_sec) * 1000L +
                              (now.tv_nsec - last_toggle[i].tv_nsec) / 1000000L;

            if (elapsed_ms >= prime_intervals[i] * 1000) {
                if (toggle_relay(lines[i]) == 0) {
                    printf("Relay %d toggled\n", i + 1);
                }
                last_toggle[i] = now;
            }
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            set_relay(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

