#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43

// Expected WHO_AM_I value for MPU-6050
#define MPU6050_WHO_AM_I 0x68

// Gyroscope sensitivity scale factor for +-250 dps range
#define GYRO_SCALE 131.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (degrees/second)
#define THRESHOLD 50.0f

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Function prototypes
int init_i2c(void);
int init_mpu6050(void);
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *cb, gyro_data_t data);
gyro_data_t get_from_buffer(circular_buffer_t *cb, int index);
void check_threshold(gyro_data_t data);
void signal_handler(int signal);
void cleanup(void);

// Initialize I2C bus
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize MPU-6050
int init_mpu6050(void) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000); // 100ms delay for stabilization

    // Verify device identity
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != MPU6050_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n", MPU6050_WHO_AM_I, who_am_i);
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buf[6];

    // Write the register address to read from
    if (write(i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }

    // Read 6 bytes of data
    if (read(i2c_fd, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees/second
    data->x = (float)x / GYRO_SCALE;
    data->y = (float)y / GYRO_SCALE;
    data->z = (float)z / GYRO_SCALE;

    return 0;
}

// Circular buffer functions
void add_to_buffer(circular_buffer_t *cb, gyro_data_t data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

gyro_data_t get_from_buffer(circular_buffer_t *cb, int index) {
    if (index < 0 || index >= cb->count) {
        gyro_data_t zero_data = {0.0f, 0.0f, 0.0f};
        return zero_data;
    }
    int actual_index = (cb->tail + index) % BUFFER_SIZE;
    return cb->buffer[actual_index];
}

// Threshold check function
void check_threshold(gyro_data_t data) {
    float magnitude = sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f (X: %.2f, Y: %.2f, Z: %.2f)\n", magnitude, data.x, data.y, data.z);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

// Cleanup function
void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    printf("Cleanup complete.\n");
}

int main(void) {
    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Initialize circular buffer
    circular_buffer_t gyro_buffer = {0};

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;

        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check threshold
            check_threshold(gyro_data);
        } else {
            fprintf(stderr, "Failed to read gyroscope data. Retrying...\n");
        }

        usleep(10000); // 10ms delay
    }

    // Cleanup
    cleanup();

    return 0;
}

