static int g_uart_handle = -1;
static FILE *g_log_fp = NULL;
static FILE *g_err_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    if (!g_err_fp) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_err_fp, "%s.%06ld: %s\n", tbuf, ts.tv_nsec / 1000, msg);
    fflush(g_err_fp);
}

static int init_uart(void) {
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, g_uart_handle);
        return -1;
    }
    return 0;
}

static int init_log_files(void) {
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("Error opening log file");
        return -1;
    }
    g_err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!g_err_fp) {
        perror("Error opening error log file");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return -1;
    }
    return 0;
}

static int send_command(int handle) {
    int rc = serWrite(handle, (char *)MH_Z19B_READ_CMD, READ_CMD_LEN);
    if (rc != READ_CMD_LEN) {
        log_error("Failed to write MH-Z19B read command");
        return -1;
    }
    return 0;
}

static int read_response(int handle, uint8_t *buf, int expected_len) {
    int total = 0;
    int elapsed = 0;
    while (total < expected_len && elapsed < READ_TIMEOUT_MS) {
        int avail = serDataAvailable(handle);
        if (avail < 0) {
            log_error("serDataAvailable failed");
            return -1;
        }
        if (avail > 0) {
            int to_read = (avail < (expected_len - total)) ? avail : (expected_len - total);
            int n = serRead(handle, (char *)(buf + total), to_read);
            if (n < 0) {
                log_error("serRead failed");
                return -1;
            }
            total += n;
        } else {
            gpioDelay(10000); /* 10 ms */
            elapsed += 10;
        }
    }
    if (total < expected_len) {
        log_error("Timeout waiting for MH-Z19B response");
        return -1;
    }
    return total;
}

static int validate_checksum(const uint8_t *buf, int len) {
    if (len < 9) return -1;
    uint8_t calc = 0;
    for (int i = 1; i < 8; i++) calc += buf[i];
    calc = (~calc) + 1;
    if (calc != buf[8]) {
        log_error("MH-Z19B checksum mismatch");
        return -1;
    }
    return 0;
}

static int extract_co2_ppm(const uint8_t *buf, int len, int *ppm) {
    if (len < 9) return -1;
    if (buf[0] != 0xFF) {
        log_error("MH-Z19B response header mismatch");
        return -1;
    }
    *ppm = (buf[2] << 8) | buf[3];
    return 0;
}

static void log_data(int co2_ppm, int error_flag) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log_fp, "{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %d, \"error\": %d}\n",
            tbuf, ts.tv_nsec / 1000, co2_ppm, error_flag);
    fflush(g_log_fp);
    printf("{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %d, \"error\": %d}\n",
           tbuf, ts.tv_nsec / 1000, co2_ppm, error_flag);
}

static void cleanup(void) {
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_log_files() != 0) {
        serClose(g_uart_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MH-Z19B CO2 monitor started. Logging to %s every %d seconds.\n",
           LOG_FILE, READ_INTERVAL_SEC);

    while (g_running) {
        if (send_command(g_uart_handle) != 0) {
            gpioDelay(READ_DELAY_MS * 1000);
            continue;
        }

        gpioDelay(READ_DELAY_MS * 1000);

        uint8_t resp[READ_RESP_LEN];
        int resp_len = read_response(g_uart_handle, resp, READ_RESP_LEN);
        if (resp_len < 0) {
            gpioDelay(READ_DELAY_MS * 1000);
            continue;
        }

        if (validate_checksum(resp, resp_len) != 0) {
            gpioDelay(READ_DELAY_MS * 1000);
            continue;
        }

        int co2_ppm = 0;
        int error_flag = 0;
        if (extract_co2_ppm(resp, resp_len, &co2_ppm) != 0) {
            error_flag = 1;
        }

        log_data(co2_ppm, error_flag);

        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++) {
            gpioDelay(1000000); /* 1 second */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

