#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA 0x03

#define TARGET_HEADING 90.0
#define HEADING_THRESHOLD 10.0
#define HARD_IRON_X 100.0
#define HARD_IRON_Y -50.0
#define BUFFER_SIZE 100
#define SAMPLE_DELAY_US 100000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float headings[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static CircularBuffer heading_buffer;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_hmc5883l(void) {
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing MODE\n");
        return -1;
    }
    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);
    return 0;
}

static float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2f((float)y, (float)x) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static float compensate_heading(float heading) {
    return heading - HARD_IRON_X + HARD_IRON_Y;
}

static void update_circular_buffer(float heading) {
    heading_buffer.head = (heading_buffer.head + 1) % BUFFER_SIZE;
    if (heading_buffer.count < BUFFER_SIZE) heading_buffer.count++;
    heading_buffer.headings[heading_buffer.head] = heading;
}

static void control_gpio(float compensated_heading) {
    int state = (fabsf(compensated_heading - TARGET_HEADING) > HEADING_THRESHOLD) ? 1 : 0;
    if (gpioWrite(17, state) < 0) {
        fprintf(stderr, "Error writing to GPIO17\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (init_hmc5883l() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO17 mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(17, 0);

    heading_buffer.head = 0;
    heading_buffer.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!terminate) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            float heading = calculate_heading(x, y);
            float compensated = compensate_heading(heading);
            update_circular_buffer(heading);
            control_gpio(compensated);
            printf("Heading: %.2f, Compensated: %.2f\n", heading, compensated);
        } else {
            fprintf(stderr, "Read failed, retrying...\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    gpioWrite(17, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

