#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define RED_RELAY_PIN   17
#define GREEN_RELAY_PIN 27
#define BLUE_RELAY_PIN  22
#define BH1750_ADDR     0x23
#define I2C_BUS         "/dev/i2c-1"
#define LOG_FILE        "lighting_log.txt"
#define BH1750_MODE     0x10
#define BH1750_CONV_MS  120

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }
    red_line = gpiod_chip_get_line(chip, RED_RELAY_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_RELAY_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_RELAY_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(red_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(green_line, "smart_lighting", 0) < 0 ||
        gpiod_line_request_output(blue_line, "smart_lighting", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_bh1750(float *lux) {
    unsigned char cmd = BH1750_MODE;
    if (write(i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to write BH1750 mode: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);
    unsigned char buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Failed to read BH1750 data: %s\n", strerror(errno));
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void control_relays(float lux) {
    int red_state = 0, green_state = 0, blue_state = 0;
    if (lux < 50.0f) red_state = 1;
    if (lux >= 50.0f && lux < 150.0f) green_state = 1;
    if (lux >= 150.0f && lux < 300.0f) blue_state = 1;
    if (lux >= 300.0f) { red_state = 1; green_state = 1; blue_state = 1; }
    gpiod_line_set_value(red_line, red_state);
    gpiod_line_set_value(green_line, green_state);
    gpiod_line_set_value(blue_line, blue_state);
}

static void log_data(float lux, int red, int green, int blue) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s, Lux: %.2f, Red: %d, Green: %d, Blue: %d\n",
            timestamp, lux, red, green, blue);
    fflush(log_file);
}

static void cleanup(void) {
    if (red_line) gpiod_line_set_value(red_line, 0);
    if (green_line) gpiod_line_set_value(green_line, 0);
    if (blue_line) gpiod_line_set_value(blue_line, 0);
    if (red_line) gpiod_line_release(red_line);
    if (green_line) gpiod_line_release(green_line);
    if (blue_line) gpiod_line_release(blue_line);
    if (chip) gpiod_chip_close(chip);
    if (i2c_fd >= 0) close(i2c_fd);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    if (init_i2c() < 0) { cleanup(); return 1; }
    if (init_gpio() < 0) { cleanup(); return 1; }

    while (running) {
        float lux;
        if (read_bh1750(&lux) < 0) {
            fprintf(stderr, "Sensor read error, turning off relays\n");
            gpiod_line_set_value(red_line, 0);
            gpiod_line_set_value(green_line, 0);
            gpiod_line_set_value(blue_line, 0);
            log_data(-1.0f, 0, 0, 0);
        } else {
            control_relays(lux);
            int red = gpiod_line_get_value(red_line);
            int green = gpiod_line_get_value(green_line);
            int blue = gpiod_line_get_value(blue_line);
            log_data(lux, red, green, blue);
        }
        sleep(1);
    }

    cleanup();
    return 0;
}

