#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255

#define MIN_DISTANCE 10.0f
#define MAX_DISTANCE 100.0f
#define THRESHOLD_DISTANCE 50.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) != PWM_FREQUENCY ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Error: failed to set PWM frequency\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) != PWM_RANGE ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Error: failed to set PWM range\n");
        gpioTerminate();
        return -1;
    }

    if (gpioPWM(MOTOR_A_IN2, 0) != 0 || gpioPWM(MOTOR_B_IN4, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM duty cycles\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void stop_motors(void) {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
}

static int map_distance_to_pwm(float distance) {
    if (distance <= MIN_DISTANCE) return 255;
    if (distance >= MAX_DISTANCE) return 0;
    return (int)((MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE) * 255.0f);
}

static void control_motor_a(float distance) {
    int pwm = map_distance_to_pwm(distance);
    if (distance < THRESHOLD_DISTANCE) {
        gpioWrite(MOTOR_A_IN1, 1);
        gpioPWM(MOTOR_A_IN2, pwm);
    } else {
        gpioWrite(MOTOR_A_IN1, 0);
        gpioPWM(MOTOR_A_IN2, pwm);
    }
}

static void control_motor_b(float distance) {
    int pwm = map_distance_to_pwm(distance);
    if (distance < THRESHOLD_DISTANCE) {
        gpioWrite(MOTOR_B_IN3, 1);
        gpioPWM(MOTOR_B_IN4, pwm);
    } else {
        gpioWrite(MOTOR_B_IN3, 0);
        gpioPWM(MOTOR_B_IN4, pwm);
    }
}

static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    float distance_a = 50.0f;
    float distance_b = 75.0f;

    while (g_running) {
        control_motor_a(distance_a);
        control_motor_b(distance_b);
        gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

