#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

#define SERVO_PIN "/sys/class/pwm/pwmchip2/pwm0"
#define SERVO_MIN_PULSE_US 1000
#define SERVO_MAX_PULSE_US 2000
#define SERVO_RANGE 180

#define LOG_FILE "solar_tracker.log"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    for (int attempt = 0; attempt < 3; attempt++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(10000 * (1 << attempt));
    }
    return -1;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < 3; attempt++) {
        if (write(fd, &reg, 1) == 1 && read(fd, buf, len) == len) return 0;
        usleep(10000 * (1 << attempt));
    }
    return -1;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_raw_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, buf, 14) < 0) {
        fprintf(stderr, "Error: Could not read MPU-6050 data: %s\n", strerror(errno));
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
