#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQ 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"
#define TRANSITION_SECONDS 1800
#define CHECK_INTERVAL_SEC 1

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t last_checked_sec = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int *hours, int *minutes, int *seconds,
                          int *relay, int *state, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        if (sscanf(line, "%d:%d:%d,%d,%d", hours, minutes, seconds, relay, state) == 5) {
            count++;
        } else {
            fprintf(stderr, "Warning: Invalid schedule entry: %s", line);
        }
    }

    fclose(fp);
    return count;
}

static int set_relay_state(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int fade_lamp(int pin, int target_state) {
    int current_state = gpioRead(pin);
    if (current_state < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }

    int current_duty = 0;
    if (current_state == 1) {
        current_duty = PWM_RANGE;
    }

    int step = (target_state == 1) ? -1 : 1;
    int steps = (PWM_RANGE / 10); /* 10 steps per second */

    for (int i = 0; i < steps && running; i++) {
        current_duty += step;
        if (current_duty < 0) current_duty = 0;
        if (current_duty > PWM_RANGE) current_duty = PWM_RANGE;

        if (gpioPWM(pin, current_duty) < 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            return -1;
        }
        gpioDelay(100000); /* 100 ms */
    }

    /* Final step to reach exact target */
    if (running) {
        if (gpioPWM(pin, target_state == 1 ? PWM_RANGE : 0) < 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            return -1;
        }
    }

    return 0;
}

static int check_schedule(int *hours, int *minutes, int *seconds,
                           int *relay, int *state, int num_entries) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        perror("localtime failed");
        return -1;
    }

    int current_hour = tm_info->tm_hour;
    int current_minute = tm_info->tm_min;
    int current_second = tm_info->tm_sec;

    if (current_second != last_checked_sec) {
        for (int i = 0; i < num_entries; i++) {
            if (hours[i] == current_hour &&
                minutes[i] == current_minute &&
                seconds[i] == current_second) {
                return i;
            }
        }
        last_checked_sec = current_second;
    }
    return -1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(relay_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(relay_pins[i], PWM_FREQ);
        gpioSetPWMrange(relay_pins[i], PWM_RANGE);
        if (gpioWrite(relay_pins[i], 0) < 0) {
            fprintf(stderr, "Failed to initialize GPIO %d\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        gpioTerminate();
        return 1;
    }

    int max_entries = 100;
    int *hours = malloc(max_entries * sizeof(int));
    int *minutes = malloc(max_entries * sizeof(int));
    int *seconds = malloc(max_entries * sizeof(int));
    int *relay = malloc(max_entries * sizeof(int));
    int *state = malloc(max_entries * sizeof(int));

    if (!hours || !minutes || !seconds || !relay || !state) {
        fprintf(stderr, "Memory allocation failed\n");
        free(hours); free(minutes); free(seconds); free(relay); free(state);
        gpioTerminate();
        return 1;
    }

    int num_entries = read_schedule(SCHEDULE_FILE, hours, minutes, seconds, relay, state, max_entries);
    if (num_entries < 0) {
        free(hours); free(minutes); free(seconds); free(relay); free(state);
        gpioTerminate();
        return 1;
    }

    printf("Loaded %d schedule entries. Starting lighting control...\n", num_entries);

    while (running) {
        int idx = check_schedule(hours, minutes, seconds, relay, state, num_entries);
        if (idx >= 0) {
            int target_state = state[idx];
            int target_pin = relay_pins[relay[idx]];

            if (target_state != gpioRead(target_pin)) {
                printf("Triggering relay %d (GPIO %d) to %s\n",
                       relay[idx], target_pin, target_state ? "ON" : "OFF");
                if (fade_lamp(target_pin, target_state) < 0) {
                    fprintf(stderr, "Fade failed for relay %d\n", relay[idx]);
                }
            }
        }
        sleep(CHECK_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
    free(hours); free(minutes); free(seconds); free(relay); free(state);
    return 0;
}

