#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms (~5 m round trip) */
#define LOOP_DELAY_US    60000   /* 60 ms between measurements */
#define LOOP_FREQ_HZ     50

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance (cm) from the HC-SR04.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on pigpio error.
 */
static float measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0f;
    }
    gpioDelay(5);

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -2.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -2.0f;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline = gpioTick() + ECHO_TIMEOUT_US;

    /* Wait for echo rising edge */
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() >= deadline) {
            fprintf(stderr, "Warning: echo rising-edge timeout\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() >= deadline) {
            fprintf(stderr, "Warning: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) {
        fprintf(stderr, "Warning: zero pulse width\n");
        return -1.0f;
    }

    /* distance = (pulse_us * speed_of_sound) / 2
     * speed_of_sound ~ 343 m/s = 0.0343 cm/us; divide by 2 for round trip */
    return (float)pulse_us * 0.0343f / 2.0f;
}

static int map_distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float normalized = (distance - MIN_DISTANCE_CM) /
                       (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    int freq = (int)(MIN_FREQUENCY_HZ +
                     normalized * (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ));

    if (freq < MIN_FREQUENCY_HZ) freq = MIN_FREQUENCY_HZ;
    if (freq > MAX_FREQUENCY_HZ) freq = MAX_FREQUENCY_HZ;
    return freq;
}

static void set_buzzer_frequency(int freq)
{
    if (gpioSetPWMfrequency(BUZZER_PIN, freq) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", freq);
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {
        fprintf(stderr, "Error: gpioPWM(128) failed\n");
    }
}

static void silence_buzzer(void)
{
    gpioPWM(BUZZER_PIN, 0);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(buzzer) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(BUZZER_PIN, 0);

    /* Register signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    printf("Theremin running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            silence_buzzer();
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int freq = map_distance_to_frequency(distance);
        set_buzzer_frequency(freq);

        /* Sleep for the remainder of the 60 ms loop period */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    silence_buzzer();
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

