#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_FREQ 1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int red, int green, int blue) {
    if (gpioPWM(RED_PIN, red) < 0) {
        fprintf(stderr, "Error: gpioPWM(RED_PIN) failed\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) < 0) {
        fprintf(stderr, "Error: gpioPWM(GREEN_PIN) failed\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) < 0) {
        fprintf(stderr, "Error: gpioPWM(BLUE_PIN) failed\n");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(RED_PIN) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(GREEN_PIN) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BLUE_PIN) failed\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(RED_PIN) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(GREEN_PIN) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(BLUE_PIN) failed\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(RED_PIN) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(GREEN_PIN) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(BLUE_PIN) failed\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    while (running) {
        double proximity = sin((double)gpioTick() / 1000000.0) * 0.5 + 0.5;

        int red   = (int)(proximity * 255.0);
        int green = (int)((1.0 - proximity) * 255.0);
        int blue  = (int)(proximity * (1.0 - proximity) * 255.0);

        if (set_led_color(red, green, blue) < 0) {
            cleanup();
            return EXIT_FAILURE;
        }

        gpioDelay(50000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

