#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3
#define DEFAULT_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_event(FILE *log_fp, int value) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s, GPIO%d, %d\n", timestamp, GPIO_LINE_OFFSET, value) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    if (fsync(fileno(log_fp)) != 0) {
        fprintf(stderr, "fsync failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void check_earthquake(int *window, int new_value) {
    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }
    if (high_count >= EARTHQUAKE_THRESHOLD) {
        time_t rawtime;
        struct tm timeinfo;
        char timestamp[32];

        time(&rawtime);
        if (localtime_r(&rawtime, &timeinfo) != NULL) {
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
            printf("EARTHQUAKE ALERT at %s\n", timestamp);
        } else {
            printf("EARTHQUAKE ALERT\n");
        }
        fflush(stdout);
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_event event;
    FILE *log_fp = NULL;
    int window[WINDOW_SIZE];
    int timeout_ms = DEFAULT_TIMEOUT_MS;
    int ret = EXIT_FAILURE;

    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT_MS);
            timeout_ms = DEFAULT_TIMEOUT_MS;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup_line;
    }

    for (int i = 0; i < WINDOW_SIZE; i++) {
        window[i] = 0;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d for %d ms events...\n", GPIO_LINE_OFFSET, timeout_ms);
    fflush(stdout);

    while (program_running) {
        int rv = gpiod_line_event_wait(line, &(struct timespec){timeout_ms / 1000, (timeout_ms % 1000) * 1000000L});
        if (rv < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            break;
        }
        if (rv == 0) {
            continue;
        }

        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            continue;
        }

        int value = event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0;

        if (log_event(log_fp, value) != 0) {
            fprintf(stderr, "Failed to log event\n");
        }

        for (int i = WINDOW_SIZE - 1; i > 0; i--) {
            window[i] = window[i - 1];
        }
        window[0] = value;

        check_earthquake(window, value);
    }

    ret = EXIT_SUCCESS;

    if (log_fp) {
        fclose(log_fp);
    }

cleanup_line:
    if (line) {
        gpiod_line_release(line);
    }

cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

