/*
 * LSM303DLHC Magnetometer Logger for Raspberry Pi Zero W
 * Uses Linux I2C-dev interface (no wiringPi).
 *
 * Wiring:
 *   LSM303DLHC SDA -> GPIO2 (physical pin 3)
 *   LSM303DLHC SCL -> GPIO3 (physical pin 5)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *
 * Build: gcc -O2 -Wall -o mag_logger mag_logger.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ---- LSM303DLHC magnetometer constants ---- */
#define LSM303_MAG_ADDR        0x1E
#define LSM303_MAG_REG_STATUS  0x02
#define LSM303_MAG_REG_OUT_X_H 0x03
#define LSM303_MAG_REG_OUT_X_L 0x04
#define LSM303_MAG_REG_OUT_Z_H 0x05
#define LSM303_MAG_REG_OUT_Z_L 0x06
#define LSM303_MAG_REG_OUT_Y_H 0x07
#define LSM303_MAG_REG_OUT_Y_L 0x08
#define LSM303_MAG_REG_CRA     0x00
#define LSM303_MAG_REG_MR      0x02

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "mag_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define CALIB_X_OFFSET 10.0f
#define CALIB_Y_OFFSET (-5.0f)
#define CALIB_Z_OFFSET 20.0f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers using Linux SMBus ioctl interface                       */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    data.byte = value;
    args.read_write = I2C_SMBUS_WRITE;
    args.command = reg;
    args.size = I2C_SMBUS_BYTE_DATA;
    args.data = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_write_byte(0x%02X, 0x%02X): %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    args.read_write = I2C_SMBUS_READ;
    args.command = reg;
    args.size = I2C_SMBUS_BYTE_DATA;
    args.data = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_read_byte(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)data.byte;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len)
{
    union i2c_smbus_data data;
    struct i2c_smbus_ioctl_data args;

    data.block[0] = len;
    memcpy(&data.block[1], buf, len);

    args.read_write = I2C_SMBUS_READ;
    args.command = reg;
    args.size = I2C_SMBUS_I2C_BLOCK_DATA;
    args.data = &data;

    if (ioctl(fd, I2C_SMBUS, &args) < 0) {
        fprintf(stderr, "i2c_read_block(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    memcpy(buf, &data.block[1], len);
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303DLHC magnetometer                                             */
/* ------------------------------------------------------------------ */
static int mag_init(int fd)
{
    /* CRA_REG_M: 0x14 = 15 Hz ODR, continuous-conversion mode */
    if (i2c_write_byte(fd, LSM303_MAG_REG_CRA, 0x14) < 0)
        return -1;

    /* MR_REG_M: 0x00 = continuous-conversion mode */
    if (i2c_write_byte(fd, LSM303_MAG_REG_MR, 0x00) < 0)
        return -1;

    return 0;
}

static int mag_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t status;
    uint8_t raw[6];

    /* Check status register (0x02) for data-ready bit (DRDY = bit 0) */
    if (i2c_read_byte(fd, LSM303_MAG_REG_STATUS, &status) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data yet — skip this sample */
        return 1;
    }

    /* Read 6 bytes: X_H, X_L, Z_H, Z_L, Y_H, Y_L */
    if (i2c_read_block(fd, LSM303_MAG_REG_OUT_X_H, raw, 6) < 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *z = (int16_t)((raw[2] << 8) | raw[3]);
    *y = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration & heading                                              */
/* ------------------------------------------------------------------ */
static void calibrate(int16_t x, int16_t y, int16_t z,
                      float *cx, float *cy, float *cz)
{
    *cx = (float)x - CALIB_X_OFFSET;
    *cy = (float)y - CALIB_Y_OFFSET;
    *cz = (float)z - CALIB_Z_OFFSET;
}

static float calculate_heading(float cx, float cy)
{
    float heading = atan2f(cy, cx) * 180.0f / (float)M_PI;
    if (heading < 0.0f)
        heading += 360.0f;
    return heading;
}

static const char *heading_direction(float heading)
{
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading >= 22.5f  && heading < 67.5f) return "NE";
    if (heading >= 67.5f  && heading < 112.5f) return "E";
    if (heading >= 112.5f && heading < 157.5f) return "SE";
    if (heading >= 157.5f && heading < 202.5f) return "S";
    if (heading >= 202.5f && heading < 247.5f) return "SW";
    if (heading >= 247.5f && heading < 292.5f) return "W";
    return "NW";
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    int need_header = 0;

    g_log_fp = fopen(LOG_FILE, "r");
    if (g_log_fp == NULL) {
        /* File does not exist yet — write header */
        g_log_fp = fopen(LOG_FILE, "w");
        if (g_log_fp == NULL) {
            fprintf(stderr, "fopen(%s, w): %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
        need_header = 1;
    } else {
        /* File exists — check if it is empty */
        if (fseek(g_log_fp, 0, SEEK_END) == 0) {
            long sz = ftell(g_log_fp);
            if (sz == 0) {
                need_header = 1;
            }
        }
        rewind(g_log_fp);
    }

    if (need_header) {
        fprintf(g_log_fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
        fflush(g_log_fp);
    }

    return 0;
}

static int log_sample(float cx, float cy, float cz, float heading)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f,%.2f\n",
                ts, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw_x, raw_y, raw_z;
    float cx, cy, cz, heading;

    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize magnetometer */
    if (mag_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303DLHC magnetometer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log */
    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int rc = mag_read_xyz(g_i2c_fd, &raw_x, &raw_y, &raw_z);
        if (rc < 0) {
            /* I2C error — skip this sample */
            sleep(1);
            continue;
        }
        if (rc == 1) {
            /* No new data yet — brief sleep and retry */
            usleep(100000);
            continue;
        }

        calibrate(raw_x, raw_y, raw_z, &cx, &cy, &cz);
        heading = calculate_heading(cx, cy);
        const char *dir = heading_direction(heading);

        printf("X: %6d  Y: %6d  Z: %6d  ->  %s  (%.1f deg)\n",
               raw_x, raw_y, raw_z, dir, heading);

        if (log_sample(cx, cy, cz, heading) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

