            long sz = ftell(g_log_fp);
            if (sz == 0) {
                need_header = 1;
            }
        }
        rewind(g_log_fp);
    }

    if (need_header) {
        fprintf(g_log_fp, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
        fflush(g_log_fp);
    }

    return 0;
}

static int log_sample(float cx, float cy, float cz, float heading)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(g_log_fp, "%s,%.2f,%.2f,%.2f,%.2f\n",
                ts, cx, cy, cz, heading) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw_x, raw_y, raw_z;
    float cx, cy, cz, heading;

    if (install_signal_handlers() < 0)
        return EXIT_FAILURE;

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                LSM303_MAG_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize magnetometer */
    if (mag_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize LSM303DLHC magnetometer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV log */
    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LSM303DLHC magnetometer logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int rc = mag_read_xyz(g_i2c_fd, &raw_x, &raw_y, &raw_z);
        if (rc < 0) {
            /* I2C error — skip this sample */
            sleep(1);
            continue;
        }
        if (rc == 1) {
            /* No new data yet — brief sleep and retry */
            usleep(100000);
            continue;
        }

        calibrate(raw_x, raw_y, raw_z, &cx, &cy, &cz);
        heading = calculate_heading(cx, cy);
        const char *dir = heading_direction(heading);

        printf("X: %6d  Y: %6d  Z: %6d  ->  %s  (%.1f deg)\n",
               raw_x, raw_y, raw_z, dir, heading);

        if (log_sample(cx, cy, cz, heading) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

