#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_MS 200
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_touch_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(const char *state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", ts, state);
    } else {
        fprintf(fp, "{\"timestamp\":\"unknown\",\"relay_state\":\"%s\"}\n", state);
    }
    fclose(fp);
}

static void touch_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 1) return;

    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_MS * 1000) return;
    last_touch_tick = tick;

    int relay_state = gpioRead(RELAY_PIN);
    if (relay_state < 0) {
        fprintf(stderr, "gpioRead(%d) failed\n", RELAY_PIN);
        return;
    }
    int new_state = (relay_state == 0) ? 1 : 0;

    if (gpioWrite(RELAY_PIN, new_state) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", RELAY_PIN, new_state);
        return;
    }

    log_relay_state(new_state ? "ON" : "OFF");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 0, touch_callback) != 0) {
        fprintf(stderr, "gpioSetISRFunc(%d) failed\n", TOUCH_PIN);
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Relay control started. Touch GPIO%d to toggle relay on GPIO%d.\n", TOUCH_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);
    }

    gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 0, NULL);
    gpioWrite(RELAY_PIN, 0);
    log_relay_state("OFF");
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

