#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define RELAY_ON_TIME 5
#define RELAY_GAP_TIME 1
#define LOG_FILE "irrigation_log.txt"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_lines[4] = {NULL, NULL, NULL, NULL};

static const int relay_pins[4] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < 4; i++) {
        if (relay_lines[i]) {
            if (gpiod_line_set_value(relay_lines[i], 1) < 0)
                fprintf(stderr, "Warning: failed to deactivate relay %d: %s\n",
                        i + 1, strerror(errno));
            gpiod_line_release(relay_lines[i]);
            relay_lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

static int log_event(int relay_num, int moisture_level) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s - Relay %d activated (Moisture: %d)\n",
                timestamp, relay_num, moisture_level) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) == EOF) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_relay(struct gpiod_line *line, int relay_num) {
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to activate relay %d: %s\n",
                relay_num, strerror(errno));
        return -1;
    }
    if (log_event(relay_num, -1) < 0)
        return -1;
    sleep(RELAY_ON_TIME);
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d: %s\n",
                relay_num, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    for (int i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(relay_lines[i], "irrigation", 1) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    srand((unsigned int)time(NULL));

    while (program_running) {
        int moisture_level = rand() % 101;
        printf("Simulated moisture level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 0; i < 4 && program_running; i++) {
                if (activate_relay(relay_lines[i], i + 1) < 0) {
                    fprintf(stderr, "Error activating relay %d, continuing...\n", i + 1);
                }
                if (i < 3)
                    sleep(RELAY_GAP_TIME);
            }
        }
        sleep(10);
    }

    cleanup();
    return 0;
}

