/*
 * Automated Plant Watering System — Raspberry Pi Zero W
 * Library : pigpio (modern, actively maintained)
 * Servos  : SG90 on GPIO17 (water valve) and GPIO18 (nozzle)
 * Pulse   : 500-2500 us (500=0 deg, 1500=90 deg, 2500=180 deg)
 * Logic   : moisture < 50 ? open valve 90 deg, sweep nozzle, hold 5 s, close valve 0 deg
 *           moisture >=50 ? skip
 * Safety  : SIGINT/SIGTERM -> stop servos, terminate pigpio, exit cleanly
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_SERVO_PIN  17
#define NOZZLE_SERVO_PIN 18

#define MOISTURE_THRESHOLD 50
#define SERVO_MIN_PULSE  500   /* 0 degrees   */
#define SERVO_MID_PULSE 1500   /* 90 degrees  */
#define SERVO_MAX_PULSE 2500   /* 180 degrees */
#define SERVO_RETRY_COUNT 3
#define SERVO_RETRY_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Retry gpioServo() up to SERVO_RETRY_COUNT times on failure. */
static int servo_set_pulse(int pin, int pulsewidth)
{
    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; ++attempt) {
        if (gpioServo(pin, pulsewidth) == 0)
            return 0;
        if (attempt < SERVO_RETRY_COUNT - 1)
