#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23
#define STEPS_PER_ROTATION 512
#define STEP_DELAY_US 3000
#define DEBOUNCE_US 50000

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned gpio, unsigned level) {
    if (gpioWrite(gpio, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", gpio, level);
        return -1;
    }
    return 0;
}

static int safe_set_mode(unsigned gpio, unsigned mode) {
    if (gpioSetMode(gpio, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", gpio, mode);
        return -1;
    }
    return 0;
}

static int safe_pull_up_down(unsigned gpio, unsigned pud) {
    if (gpioSetPullUpDown(gpio, pud) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%u, %u) failed\n", gpio, pud);
        return -1;
    }
    return 0;
}

static void deenergize(void) {
    safe_write(IN1, 0);
    safe_write(IN2, 0);
    safe_write(IN3, 0);
    safe_write(IN4, 0);
}

static int init_gpio(void) {
    if (safe_set_mode(IN1, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(IN2, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(IN3, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(IN4, PI_OUTPUT) < 0) return -1;
    if (safe_set_mode(LOCK_BUTTON, PI_INPUT) < 0) return -1;
    if (safe_set_mode(UNLOCK_BUTTON, PI_INPUT) < 0) return -1;
    if (safe_pull_up_down(LOCK_BUTTON, PI_PUD_UP) < 0) return -1;
    if (safe_pull_up_down(UNLOCK_BUTTON, PI_PUD_UP) < 0) return -1;
    deenergize();
    return 0;
}

static void step(int a, int b, int c, int d) {
    safe_write(IN1, a);
    safe_write(IN2, b);
    safe_write(IN3, c);
    safe_write(IN4, d);
}

static void rotate(int steps, int direction) {
    int a, b, c, d;
    for (int i = 0; i < steps && running; i++) {
        if (direction == 1) {
            a = 1; b = 0; c = 0; d = 0;
        } else {
            a = 0; b = 0; c = 0; d = 1;
        }
        step(a, b, c, d);
        gpioDelay(STEP_DELAY_US);
    }
    deenergize();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0) {
        fprintf(stderr, "Error: GPIO initialization failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automatic Door Lock System\n");
    printf("Press LOCK (GPIO24) to rotate clockwise, UNLOCK (GPIO23) to rotate counter-clockwise.\n");
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        int lock_state = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        if (lock_state == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(LOCK_BUTTON) == 0) {
                printf("Locking...\n");
                rotate(STEPS_PER_ROTATION, 1);
                while (gpioRead(LOCK_BUTTON) == 0 && running) {
                    gpioDelay(10000);
                }
            }
        }

        if (unlock_state == 0) {
            gpioDelay(DEBOUNCE_US);
            if (gpioRead(UNLOCK_BUTTON) == 0) {
                printf("Unlocking...\n");
                rotate(STEPS_PER_ROTATION, 0);
                while (gpioRead(UNLOCK_BUTTON) == 0 && running) {
                    gpioDelay(10000);
                }
            }
        }

        gpioDelay(10000);
    }

    deenergize();
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

