#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN  17
#define ECHO_PIN     18
#define LOG_FILE     "distance_log.txt"
#define TIMEOUT_US   50000   /* 50 ms timeout for echo edges */
#define TRIG_PULSE_US 10
#define MEASURE_INTERVAL_S 1
#define ECHO_GUARD_US  60000 /* 60 ms between measurements */

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* Busy-wait for a line to reach the requested value, with timeout. */
static int wait_for_value(struct gpiod_line *line, int value, long timeout_us)
{
    struct timespec start, now;
    long elapsed;

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("clock_gettime");
        return -1;
    }

    for (;;) {
        int v = gpiod_line_get_value(line);
        if (v < 0) {
            perror("gpiod_line_get_value");
            return -1;
        }
        if (v == value)
            return 0;

        if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
            perror("clock_gettime");
            return -1;
        }
        elapsed = (now.tv_sec - start.tv_sec) * 1000000L +
                  (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed > timeout_us)
            return -1;
    }
}

static long measure_pulse(struct gpiod_line *echo)
{
    struct timespec start, end;
    long duration;

    /* Wait for echo to go high (timeout if sensor absent or stuck low). */
    if (wait_for_value(echo, 1, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &start) < 0) {
        perror("clock_gettime");
        return -1;
    }

    /* Wait for echo to go low (timeout if stuck high). */
    if (wait_for_value(echo, 0, TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1;
    }

    if (clock_gettime(CLOCK_MONOTONIC, &end) < 0) {
        perror("clock_gettime");
        return -1;
    }

    duration = (end.tv_sec - start.tv_sec) * 1000000L +
               (end.tv_nsec - start.tv_nsec) / 1000L;
    return duration;
}

static float calculate_distance(long duration_us)
{
    /* speed of sound 343 m/s => 0.01715 cm/us */
    return (float)duration_us * 0.01715f;
}

static void log_distance(float distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (distance < 0.0f)
            fprintf(log_file, "%s, -1\n", timestamp);
        else
            fprintf(log_file, "%s, %.2f\n", timestamp, distance);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the log file once in append mode. */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip4 on Raspberry Pi 4 Bookworm). */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (trigger == NULL) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (echo == NULL) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    /* Request trigger as output, initial value low. */
    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    /* Request echo as input. */
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    /* Allow sensor to settle. */
    usleep(100000);

    printf("HC-SR04 distance logger started. Press Ctrl+C to exit.\n");

    while (program_running) {
        /* Ensure trigger starts low. */
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value(trigger, 0)");
            break;
        }
        usleep(5);

        /* 10 microsecond trigger pulse. */
        if (gpiod_line_set_value(trigger, 1) < 0) {
            perror("gpiod_line_set_value(trigger, 1)");
            break;
        }
        usleep(TRIG_PULSE_US);
        if (gpiod_line_set_value(trigger, 0) < 0) {
            perror("gpiod_line_set_value(trigger, 0)");
            break;
        }

        /* Guard to avoid false echoes from previous measurement. */
        usleep(ECHO_GUARD_US);

        long duration = measure_pulse(echo);
        if (duration < 0) {
            log_distance(-1.0f);
        } else {
            float distance = calculate_distance(duration);
            log_distance(distance);
        }

        /* Sleep for the remainder of the 1-second interval. */
        sleep(MEASURE_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger != NULL)
        gpiod_line_release(trigger);
    if (echo != NULL)
        gpiod_line_release(echo);
    if (chip != NULL)
        gpiod_chip_close(chip);
    if (log_file != NULL)
        fclose(log_file);

    printf("Program terminated.\n");
    return ret;
}

