    uint8_t msb = 0, lsb = 0;

    /* Check data-ready interrupt status */
    if (vl53l1x_read_reg(handle, REG_INT_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Error: failed to read interrupt status\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        return 1; /* not ready yet */
    }

    /* Read 16-bit distance result */
    if (vl53l1x_read_reg(handle, REG_RESULT_DISTANCE_MSB, &msb, 1) < 0) {
        fprintf(stderr, "Error: failed to read distance MSB\n");
        return -1;
    }
    if (vl53l1x_read_reg(handle, REG_RESULT_DISTANCE_LSB, &lsb, 1) < 0) {
        fprintf(stderr, "Error: failed to read distance LSB\n");
        return -1;
    }

    *distance_mm = ((uint16_t)msb << 8) | lsb;

    /* Clear interrupt by writing to the status register */
    if (vl53l1x_write_reg8(handle, REG_INT_STATUS, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt status\n");
    }

    return 0;
}

static void control_relay(int distance_cm)
{
    int level = (distance_cm <= DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (gpioWrite(RELAY_GPIO, level) < 0) {
        fprintf(stderr, "Error: failed to write relay GPIO %d\n", RELAY_GPIO);
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Check wiring and address 0x%02X.\n",
                g_i2c_handle, VL53L1X_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed. Sensor may be absent or bus error.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    printf("Proximity door system started. Threshold = %d cm. Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD_CM);

    while (g_running) {
        uint16_t distance_mm = 0;
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance_mm);

        if (rc == 0) {
            int distance_cm = distance_mm / 10;
            printf("Distance: %d cm\n", distance_cm);
            control_relay(distance_cm);
        } else if (rc < 0) {
            fprintf(stderr, "Error: I2C read failure from sensor\n");
        }
        /* rc == 1: not ready yet, just loop */

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

