#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define WATERING_DURATION 5
#define WATERING_INTERVAL 86400
#define POLL_INTERVAL 60
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_watering_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;

    if (!buf || len < 20) return -1;

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) return -1;

    if (strftime(buf, len, "%Y-%m-%d %H:%M:%S", timeinfo) == 0) return -1;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_RELAYS; i++) lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "watering_system", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as output: %s\n", relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        time_t now = time(NULL);
        char timestamp[20];

        if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
            fprintf(stderr, "Failed to get timestamp\n");
        } else {
            printf("Watering relay at %s\n", timestamp);
            if (log_watering_event(timestamp) != 0) {
                fprintf(stderr, "Failed to log watering event\n");
            }
        }

        for (i = 0; i < NUM_RELAYS && program_running; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to activate relay on GPIO %u: %s\n", relay_pins[i], strerror(errno));
            }
            sleep(WATERING_DURATION);
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to deactivate relay on GPIO %u: %s\n", relay_pins[i], strerror(errno));
            }
        }

        if (program_running) {
            sleep(WATERING_INTERVAL);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) gpiod_chip_close(chip);
    return ret;
}

