#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_SMPLRT_DIV   0x19
#define MPU6050_GYRO_CONFIG  0x1B
#define MPU6050_GYRO_XOUT_H  0x43
#define MPU6050_PWR_MGMT_1   0x6B
#define MPU6050_WHO_AM_I     0x75
#define MPU6050_WHO_AM_I_VAL 0x68

/* GPIO pin for LED */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Gyroscope threshold (degrees/second) */
#define GYRO_THRESHOLD 250.0f

/* I2C bus on Raspberry Pi 3 Model B+ */
#define I2C_BUS 1

/* Sensitivity for ±250 deg/s range: 131 LSB per deg/s */
#define GYRO_SENSITIVITY 131.0f

/* Sampling period in microseconds (20 Hz) */
#define SAMPLE_PERIOD_US 50000

/* Maximum re-initialisation attempts */
#define MAX_REINIT_ATTEMPTS 3

/* Data structure for gyroscope readings */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;

/* Global state */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Initialise MPU-6050                                                  */
/* ------------------------------------------------------------------ */
static int init_mpu6050(int handle)
{
    /* Verify device identity */
    int who = i2cReadByteData(handle, MPU6050_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I register (pigpio error %d)\n", who);
        return -1;
    }
    if (who != MPU6050_WHO_AM_I_VAL) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                who, MPU6050_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2cWriteByteData(handle, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); /* 100 ms settle */

    /* Sample rate: 1 kHz / (1 + 0) = 1 kHz internal sample rate */
    if (i2cWriteByteData(handle, MPU6050_SMPLRT_DIV, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* Gyro config: ±250 deg/s, no FCHOICE_B */
    if (i2cWriteByteData(handle, MPU6050_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read gyroscope data (6 bytes from GYRO_XOUT_H)                      */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(handle, MPU6050_GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte gyro block\n");
        return -1;
    }

    raw_x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Check threshold and control LED                                     */
/* ------------------------------------------------------------------ */
static void check_threshold_and_control_led(float x, float y, float z)
{
    bool above = (fabsf(x) > GYRO_THRESHOLD ||
                  fabsf(y) > GYRO_THRESHOLD ||
                  fabsf(z) > GYRO_THRESHOLD);

    if (above) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X (pigpio error %d)\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 gyroscope monitoring started (20 Hz, threshold %.1f deg/s)\n",
           GYRO_THRESHOLD);

    /* Main loop */
    while (!terminate) {
        float x, y, z;

        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            /* Store in circular buffer */
            gyro_buffer[buffer_index].timestamp = (struct timespec){0, 0};
            clock_gettime(CLOCK_MONOTONIC, &gyro_buffer[buffer_index].timestamp);
            gyro_buffer[buffer_index].x = x;
            gyro_buffer[buffer_index].y = y;
            gyro_buffer[buffer_index].z = z;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            /* Threshold check and LED control */
            check_threshold_and_control_led(x, y, z);
        } else {
            fprintf(stderr, "Warning: gyro read failed, attempting re-initialisation...\n");
            int attempt = 0;
            while (attempt < MAX_REINIT_ATTEMPTS && !terminate) {
                i2cClose(i2c_handle);
                i2c_handle = -1;
                gpioDelay(100000); /* 100 ms */
                i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
                if (i2c_handle >= 0) {
                    if (init_mpu6050(i2c_handle) == 0) {
                        printf("Re-initialisation successful\n");
                        break;
                    } else {
                        fprintf(stderr, "Re-initialisation failed (attempt %d/%d)\n",
                                attempt + 1, MAX_REINIT_ATTEMPTS);
                    }
                } else {
                    fprintf(stderr, "i2cOpen failed (attempt %d/%d)\n",
                            attempt + 1, MAX_REINIT_ATTEMPTS);
                }
                attempt++;
                gpioDelay(100000);
            }
            if (attempt >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Error: re-initialisation failed after %d attempts, exiting\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

