#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8

#define CS_GPIO_CHIP "gpiochip0"
#define CS_GPIO_LINE 8

#define MPU6050_REG_GYRO_XOUT_H 0x43
#define MPU6050_REG_GYRO_YOUT_H 0x45
#define MPU6050_REG_GYRO_ZOUT_H 0x47

#define GYRO_SENSITIVITY 131.0f
#define STABILITY_THRESHOLD 200.0f
#define LED_GPIO_LINE 17
#define BUFFER_SIZE 64
#define SAMPLE_DELAY_MS 100

#define GYRO_X_MIN -32768
#define GYRO_X_MAX 32767
#define GYRO_Y_MIN -32768
#define GYRO_Y_MAX 32767
#define GYRO_Z_MIN -32768
#define GYRO_Z_MAX 32767

typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static struct gpiod_chip *cs_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static struct gpiod_chip *led_chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int cs_init(void) {
    cs_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!cs_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(cs_chip, CS_GPIO_LINE);
    if (!cs_line) {
        perror("Failed to get CS GPIO line");
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu6050-cs", 1) < 0) {
        perror("Failed to request CS GPIO line as output");
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
        cs_line = NULL;
        return -1;
    }

    return 0;
}

static int led_init(void) {
    led_chip = gpiod_chip_open_by_name(CS_GPIO_CHIP);
    if (!led_chip) {
        perror("Failed to open GPIO chip for LED");
        return -1;
    }

    led_line = gpiod_chip_get_line(led_chip, LED_GPIO_LINE);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(led_chip);
        led_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(led_line, "mpu6050-led", 0) < 0) {
        perror("Failed to request LED GPIO line as output");
        gpiod_chip_close(led_chip);
        led_chip = NULL;
        led_line = NULL;
        return -1;
    }

    return 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Failed to assert CS");
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        gpiod_line_set_value(cs_line, 1);
        return -1;
    }

    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Failed to deassert CS");
        return -1;
    }

    return 0;
}

static int read_gyro_axis(uint8_t reg, int16_t *value) {
    uint8_t tx[3] = {0x80 | reg, 0x00, 0x00};
    uint8_t rx[3] = {0};

    if (spi_transfer(tx, rx, 3) < 0) {
        return -1;
    }

    *value = (int16_t)((rx[1] << 8) | rx[2]);
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;

    if (read_gyro_axis(MPU6050_REG_GYRO_XOUT_H, &raw_x) < 0) return -1;
    if (read_gyro_axis(MPU6050_REG_GYRO_YOUT_H, &raw_y) < 0) return -1;
    if (read_gyro_axis(MPU6050_REG_GYRO_ZOUT_H, &raw_z) < 0) return -1;

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    if (*x < -32768.0f || *x > 32767.0f ||
        *y < -32768.0f || *y > 32767.0f ||
        *z < -32768.0f || *z > 32767.0f) {
        fprintf(stderr, "Invalid gyro data: X=%.2f, Y=%.2f, Z=%.2f\n", *x, *y, *z);
        return -1;
    }

    return 0;
}

static void add_to_buffer(circular_buffer_t *buf, float x, float y, float z) {
    time(&buf->data[buf->head].timestamp);
    buf->data[buf->head].x = x;
    buf->data[buf->head].y = y;
    buf->data[buf->head].z = z;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) buf->count++;
}

static void print_buffer(const circular_buffer_t *buf) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&buf->data[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(time_str, "UNKNOWN", sizeof(time_str));
        }
        printf("%s,%.2f,%.2f,%.2f\n", time_str, buf->data[idx].x, buf->data[idx].y, buf->data[idx].z);
    }
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (led_chip) {
        gpiod_chip_close(led_chip);
        led_chip = NULL;
    }
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (cs_chip) {
        gpiod_chip_close(cs_chip);
        cs_chip = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }

    if (cs_init() < 0) {
        fprintf(stderr, "CS GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    if (led_init() < 0) {
        fprintf(stderr, "LED GPIO initialization failed\n");
        cleanup();
        return 1;
    }

    circular_buffer_t gyro_buffer = {0};
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    printf("Gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    while (running) {
        float x, y, z;

        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(&gyro_buffer, x, y, z);

            if (fabsf(x) > STABILITY_THRESHOLD ||
                fabsf(y) > STABILITY_THRESHOLD ||
                fabsf(z) > STABILITY_THRESHOLD) {
                printf("Stability breach detected! X=%.2f, Y=%.2f, Z=%.2f\n", x, y, z);
                if (led_line) {
                    gpiod_line_set_value(led_line, 1);
                    usleep(500000);
                    gpiod_line_set_value(led_line, 0);
                    usleep(500000);
                }
            }
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nExiting gracefully...\n");
    print_buffer(&gyro_buffer);
    cleanup();
    return 0;
}

