#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define SI1145_ADDR     0x5A
#define REG_ALS_DATA    0x20
#define REG_PS_DATA     0x22
#define GPIO_CHIP       "gpiochip0"
#define GPIO_LINE       17
#define PROX_THRESHOLD  100
#define LOG_FILE        "biometric_log.txt"
#define I2C_RETRIES     3
#define I2C_RETRY_DELAY 10000  /* microseconds */

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            retries--;
            if (retries > 0) usleep(I2C_RETRY_DELAY);
            continue;
        }
        if (read(fd, buf, 2) != 2) {
            retries--;
            if (retries > 0) usleep(I2C_RETRY_DELAY);
            continue;
        }
        *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
        return 0;
    }
    return -1;
}

static int init_i2c(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", SI1145_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    led_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(led_line, "si1145-presence", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        chip = NULL;
        led_line = NULL;
        return -1;
    }
    return 0;
}

static void log_data(uint16_t als, uint16_t ps) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, als, ps);
    fflush(log_fp);
}

static void cleanup(void) {
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() < 0) {
        return 1;
    }

    if (init_gpio() < 0) {
        cleanup();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Si1145 sensor interface started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t als = 0, ps = 0;

        if (i2c_read_reg16(i2c_fd, REG_ALS_DATA, &als) < 0) {
            fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }
        if (i2c_read_reg16(i2c_fd, REG_PS_DATA, &ps) < 0) {
            fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
            usleep(100000);
            continue;
        }

        log_data(als, ps);

        if (ps > PROX_THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

