#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_MODE    0        /* CPOL=0, CPHA=0 */
#define X_REG       0x02
#define Y_REG       0x04
#define READ_BIT    0x80
#define SENSITIVITY 200.0f   /* LSB per deg/s */
#define MAX_RETRIES 3
#define SAMPLE_US  10000     /* 10 ms -> ~100 Hz */

static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_spi(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %s\n",
                SPI_CHANNEL, pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, int16_t *value) {
    char tx[2] = { (char)(reg | READ_BIT), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    *value = (int16_t)(((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

static int log_data(double timestamp, int16_t x, int16_t y) {
    if (fprintf(fp, "%.6f,%d,%d\n", timestamp, x, y) < 0) {
        fprintf(stderr, "Error writing to CSV: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing CSV: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv: %s\n", strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(fp, "timestamp,x_rate_raw,y_rate_raw\n") < 0) {
        fprintf(stderr, "Error writing CSV header: %s\n", strerror(errno));
        fclose(fp);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fflush(fp);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }

    int16_t x_rate = 0, y_rate = 0;
    int retries = 0;

    while (!terminate) {
        if (read_register(X_REG, &x_rate) != 0) {
            retries++;
            fprintf(stderr, "X-axis read failed (%d/%d)\n", retries, MAX_RETRIES);
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            gpioDelay(100000); /* 100 ms backoff */
            if (init_spi() != 0) {
                fprintf(stderr, "SPI reinit failed, exiting.\n");
                break;
            }
            continue;
        }
        retries = 0;

        if (read_register(Y_REG, &y_rate) != 0) {
            retries++;
            fprintf(stderr, "Y-axis read failed (%d/%d)\n", retries, MAX_RETRIES);
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            gpioDelay(100000);
            if (init_spi() != 0) {
                fprintf(stderr, "SPI reinit failed, exiting.\n");
                break;
            }
            continue;
        }
        retries = 0;

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            break;
        }
        double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

        if (log_data(timestamp, x_rate, y_rate) != 0) {
            fprintf(stderr, "Logging failed, exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_US);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

