#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_MS 2000
#define LOG_FILE "seismic_events.txt"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        strncpy(timestamp, "UNKNOWN", sizeof(timestamp) - 1);
        timestamp[sizeof(timestamp) - 1] = '\0';
    }
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file);
}

static void trigger_alert(void) {
    if (gpioWrite(ALERT_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set alert pin HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_MS * 1000);
    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set alert pin LOW\n");
    }
}

static void sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)tick;
    (void)userdata;

    if (gpio != SENSOR_1_PIN && gpio != SENSOR_2_PIN) return;

    static uint32_t sensor1_start_tick = 0;
    static uint32_t sensor2_start_tick = 0;
    static int sensor1_active = 0;
    static int sensor2_active = 0;

    if (level == 1) {
        if (gpio == SENSOR_1_PIN) {
            sensor1_start_tick = tick;
            sensor1_active = 1;
        } else {
            sensor2_start_tick = tick;
            sensor2_active = 1;
        }
    } else if (level == 0) {
        if (gpio == SENSOR_1_PIN) {
            sensor1_active = 0;
        } else {
            sensor2_active = 0;
        }
    }

    if (sensor1_active && sensor2_active) {
        uint32_t elapsed1 = tick - sensor1_start_tick;
        uint32_t elapsed2 = tick - sensor2_start_tick;
        if (elapsed1 >= SEISMIC_THRESHOLD_MS * 1000 &&
            elapsed2 >= SEISMIC_THRESHOLD_MS * 1000) {
            log_event("Seismic event detected!");
            trigger_alert();
            sensor1_active = 0;
            sensor2_active = 0;
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down resistors\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise alert pin LOW\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0 ||
        gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error: failed to register sensor callbacks\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");
    log_event("Monitoring started.");

    while (program_running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    log_event("Monitoring stopped.");
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

