    log_event("Monitoring started.");

    while (program_running) {
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    log_event("Monitoring stopped.");
    gpioSetAlertFuncEx(SENSOR_1_PIN, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_2_PIN, NULL, NULL);
    gpioWrite(ALERT_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

