#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// ADXRS290 Register Addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_FLAGS 0        // Mode 0: CPOL=0, CPHA=0

// LED GPIO Pin
#define LED_PIN 17

// Circular Buffer Configuration
#define BUFFER_SIZE 100

// Angular Velocity Threshold (degrees/second)
#define ANGULAR_VELOCITY_THRESHOLD 20.0

// Global Variables
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

// Structure for storing timestamp and angular velocity
typedef struct {
    struct timespec timestamp;
    float angular_velocity;
} gyro_data_t;

// Circular Buffer Structure
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Function Prototypes
int read_gyro_data(int spi_handle, float *angular_velocity);
void add_to_buffer(circular_buffer_t *cb, struct timespec timestamp, float angular_velocity);
bool check_threshold(float angular_velocity, float threshold);
void signal_handler(int signal);
void cleanup();

// Circular Buffer Initialization
void circular_buffer_init(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

// Function to read gyroscope data
int read_gyro_data(int spi_handle, float *angular_velocity) {
    char tx_buf[3];
    char rx_buf[3];
    int result;

    // Read X-axis angular rate (2 bytes)
    tx_buf[0] = RATE_XL | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00;           // Dummy byte for clocking data out
    tx_buf[2] = 0x00;           // Dummy byte for clocking data out

    result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit two's complement value
    int16_t raw_rate = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);

    // Convert to degrees per second (200 LSB/deg/s)
    *angular_velocity = (float)raw_rate / 200.0;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *cb, struct timespec timestamp, float angular_velocity) {
    cb->buffer[cb->head].timestamp = timestamp;
    cb->buffer[cb->head].angular_velocity = angular_velocity;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
}

// Function to check if the angular velocity exceeds the threshold
bool check_threshold(float angular_velocity, float threshold) {
    return fabs(angular_velocity) > threshold;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    // Initialize circular buffer
    circular_buffer_t gyro_buffer;
    circular_buffer_init(&gyro_buffer);

    // Set up signal handling for Ctrl+C and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float angular_velocity;
    struct timespec timestamp;

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &angular_velocity) == 0) {
            // Get timestamp
            clock_gettime(CLOCK_MONOTONIC, &timestamp);

            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, timestamp, angular_velocity);

            // Check if angular velocity exceeds threshold
            if (check_threshold(angular_velocity, ANGULAR_VELOCITY_THRESHOLD)) {
                gpioWrite(LED_PIN, 1); // Turn on LED
            } else {
                gpioWrite(LED_PIN, 0); // Turn off LED
            }

            // Print angular velocity
            printf("Angular Velocity: %.2f deg/s\n", angular_velocity);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        gpioDelay(10000); // Delay for 10 milliseconds (10000 microseconds)
    }

    // Cleanup
    cleanup();

    return 0;
}

