#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27
#define PWM_RANGE 255
#define PWM_FREQ 100

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    if (gpioSetMode(LAMP1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(LAMP3_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", LAMP1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", LAMP2_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", LAMP3_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void set_lamp_brightness(int gpio, int brightness) {
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(gpio, brightness);
}

static void fade_lamp(int gpio, int duration_seconds) {
    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration_seconds);
    fflush(stdout);
    for (int i = PWM_RANGE; i >= 0 && running; i--) {
        set_lamp_brightness(gpio, i);
        sleep(1);
    }
    set_lamp_brightness(gpio, 0);
    printf("Lamp on GPIO %d faded to off.\n", gpio);
    fflush(stdout);
}

static void cleanup(void) {
    set_lamp_brightness(LAMP1_GPIO, 0);
    set_lamp_brightness(LAMP2_GPIO, 0);
    set_lamp_brightness(LAMP3_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <fade_duration_seconds>\n", argv[0]);
        fprintf(stderr, "  fade_duration_seconds: 1-3600\n");
        return EXIT_FAILURE;
    }

    char *endptr;
    long duration = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || duration < 1 || duration > 3600) {
        fprintf(stderr, "Error: invalid duration '%s'. Must be 1-3600 seconds.\n", argv[1]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Smart Sunset Simulator started. Fade duration: %ld seconds.\n", duration);
    printf("Lamps on GPIO %d, %d, %d. Press Ctrl+C to stop.\n", LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO);
    fflush(stdout);

    fade_lamp(LAMP1_GPIO, duration);
    if (!running) goto terminate;

    fade_lamp(LAMP2_GPIO, duration);
    if (!running) goto terminate;

    fade_lamp(LAMP3_GPIO, duration);
    if (!running) goto terminate;

    printf("All lamps faded to off. Exiting.\n");
    fflush(stdout);
    cleanup();
    return EXIT_SUCCESS;

terminate:
    printf("\nInterrupt received. Shutting down gracefully...\n");
    fflush(stdout);
    cleanup();
    return EXIT_FAILURE;
}

