#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define MPR121_ADDR 0x5A

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5D
#define MPR121_DEBOUNCE 0x5B
#define MPR121_FILTER_CFG 0x5C
#define MPR121_ELECTRODE_CFG 0x5D
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_SOFTRESET 0x80
#define MPR121_MODE_STOP 0x00
#define MPR121_MODE_RUN 0x0D

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write error: reg=0x%02X, val=0x%02X, rc=%d", reg, value, rc);
        log_message(buf);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_MODE_STOP, MPR121_MODE_STOP) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_ELECTRODE_CFG, 0x00) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_TOUCHTH_0, 0x0A) < 0) return -1;
    if (mpr121_write(MPR121_RELEASETH_0, 0x08) < 0) return -1;
    if (mpr121_write(MPR121_DEBOUNCE, 0x21) < 0) return -1;
    if (mpr121_write(MPR121_FILTER_CFG, 0x0D) < 0) return -1;

    if (mpr121_write(MPR121_ELECTRODE_CFG, 0x01) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write(MPR121_MODE_RUN, MPR121_MODE_RUN) < 0) return -1;
    gpioDelay(10000);

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (log_file) {
        log_message("Program terminated.");
        fclose(log_file);
        log_file = NULL;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen("touch_relay.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_message("Program started.");

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        log_message("Failed to set GPIO17 as output.");
        cleanup();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "Failed to open I2C device at bus %d, addr 0x%02X: rc=%d", I2C_BUS, MPR121_ADDR, i2c_handle);
        log_message(buf);
        cleanup();
        return 1;
    }

    if (mpr121_init() < 0) {
        log_message("MPR121 initialization failed.");
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int relay_state = 0;
    int last_touch = 0;

    while (running) {
        int lsb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
        int msb = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);

        if (lsb < 0 || msb < 0) {
            char buf[128];
            snprintf(buf, sizeof(buf), "I2C read error: lsb=%d, msb=%d", lsb, msb);
            log_message(buf);
            gpioDelay(100000);
            continue;
        }

        int touch_status = (msb << 8) | lsb;
        int current_touch = (touch_status & 0x01) ? 1 : 0;

        if (current_touch && !last_touch) {
            relay_state = !relay_state;
            gpioWrite(RELAY_GPIO, relay_state);
            char buf[128];
            snprintf(buf, sizeof(buf), "Touch detected on electrode 0, relay toggled to %s", relay_state ? "ON" : "OFF");
            log_message(buf);
        }
        last_touch = current_touch;
        gpioDelay(10000);
    }

    cleanup();
    return 0;
}

