    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    struct gpiod_line *led_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (flame_line == NULL || buzzer_line == NULL || led_line == NULL) {
        fprintf(stderr, "Error getting GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = 0;
        int raw_value;

        for (int i = 0; i < 3; i++) {
            raw_value = gpiod_line_get_value(flame_line);
            if (raw_value < 0) {
                fprintf(stderr, "Error reading flame sensor: %s\n", strerror(errno));
                goto cleanup;
            }
            if (raw_value == 0) {
                flame_detected = 1;
            }
            usleep(DEBOUNCE_DELAY_MS * 1000);
        }

        if (flame_detected) {
            printf("Flame detected!\n");
            if (gpiod_line_set_value(buzzer_line, 1) < 0) {
                fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
                goto cleanup;
            }
            if (gpiod_line_set_value(led_line, 1) < 0) {
                fprintf(stderr, "Error activating LED: %s\n", strerror(errno));
                goto cleanup;
            }
            if (log_event(log_file, "Flame Detected") < 0) {
                goto cleanup;
            }
        } else {
            if (gpiod_line_set_value(buzzer_line, 0) < 0) {
                fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
                goto cleanup;
            }
            if (gpiod_line_set_value(led_line, 0) < 0) {
                fprintf(stderr, "Error deactivating LED: %s\n", strerror(errno));
                goto cleanup;
            }
        }

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (buzzer_line != NULL) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (flame_line != NULL) {
        gpiod_line_release(flame_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Program terminated gracefully.\n");
    }
    return ret;
}

