#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define CYCLE_INTERVAL_MS 5000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_dispense_event(int pin1, int pin2, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening dispense_log.txt: %s\n", strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Solenoid1: %d, Solenoid2: %d, Duration: %d ms\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                pin1, pin2, duration_ms);
    } else {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing dispense_log.txt: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int dispense_cycle(int pin1, int pin2, int duration_ms) {
    int half_duration = duration_ms / 2;
    if (gpioWrite(pin1, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on pin %d\n", pin1);
        return -1;
    }
    if (gpioDelay(half_duration * 1000) != 0) {
        fprintf(stderr, "Error during delay for solenoid %d\n", pin1);
        gpioWrite(pin1, 0);
        return -1;
    }
    if (gpioWrite(pin2, 1) != 0) {
        fprintf(stderr, "Error activating solenoid on pin %d\n", pin2);
        gpioWrite(pin1, 0);
        return -1;
    }
    if (gpioDelay(half_duration * 1000) != 0) {
        fprintf(stderr, "Error during delay for solenoid %d\n", pin2);
        gpioWrite(pin1, 0);
        gpioWrite(pin2, 0);
        return -1;
    }
    if (gpioWrite(pin1, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on pin %d\n", pin1);
        return -1;
    }
    if (gpioWrite(pin2, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid on pin %d\n", pin2);
        return -1;
    }
    return 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(SOLENOID_1_PIN, 0) != 0) {
        fprintf(stderr, "Error setting GPIO%d low on init\n", SOLENOID_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(SOLENOID_2_PIN, 0) != 0) {
        fprintf(stderr, "Error setting GPIO%d low on init\n", SOLENOID_2_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(SOLENOID_1_PIN, 0);
    gpioWrite(SOLENOID_2_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (setup_gpio() != 0) {
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    while (running) {
        if (dispense_cycle(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION_MS) != 0) {
            fprintf(stderr, "Dispense cycle failed, continuing...\n");
        }
        if (running) {
            if (gpioDelay(CYCLE_INTERVAL_MS * 1000) != 0) {
                fprintf(stderr, "Error during cycle interval delay\n");
                break;
            }
        }
    }

    cleanup_gpio();
    printf("Pneumatic dispensing system stopped.\n");
    return 0;
}

