#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

#define MOTOR_A_FORWARD  17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD  22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE   24
#define MOTOR_B_ENABLE   25

#define KP 1.0
#define KI 0.01
#define KD 0.1
#define PWM_RANGE 255
#define LOOP_DELAY_US 50000
#define OBSTACLE_THRESHOLD 20.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void stop_motors(void) {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(MOTOR_A_ENABLE, 0);
    gpioPWM(MOTOR_B_ENABLE, 0);
}

static void set_motor_speed(char motor, int speed) {
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (speed < -PWM_RANGE) speed = -PWM_RANGE;

    int forward_pin, backward_pin, enable_pin;

    if (motor == 'A' || motor == 'a') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin = MOTOR_A_ENABLE;
    } else if (motor == 'B' || motor == 'b') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin = MOTOR_B_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor character: %c\n", motor);
        if (log_file) {
            fprintf(log_file, "Error: Invalid motor character: %c\n", motor);
            fflush(log_file);
        }
        return;
    }

    if (speed > 0) {
        gpioWrite(backward_pin, 0);
        gpioWrite(forward_pin, 1);
        gpioPWM(enable_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(enable_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, 0);
    }
}

static float calculate_pid(float setpoint, float actual, float *integral, float *previous_error, float dt) {
    float error = setpoint - actual;
    *integral += error * dt;
    float derivative = (error - *previous_error) / dt;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

static float simulate_tilt_error(void) {
    return ((float)rand() / (float)RAND_MAX) * 20.0f - 10.0f;
}

static float simulate_distance(void) {
    return ((float)rand() / (float)RAND_MAX) * 380.0f + 2.0f;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %d, %d\n",
            timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    gpioSetPWMrange(MOTOR_A_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_ENABLE, PWM_RANGE);

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    srand((unsigned int)time(NULL));

    float integral = 0.0f;
    float previous_error = 0.0f;
    float setpoint = 0.0f;

    while (running) {
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        float pid_output = calculate_pid(setpoint, tilt_error, &integral, &previous_error, 0.05f);

        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -50;
            motor_b_speed = -50;
        }

        set_motor_speed('A', motor_a_speed);
        set_motor_speed('B', motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    stop_motors();
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

