    gpioSetPWMrange(MOTOR_B_ENABLE, PWM_RANGE);

    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    srand((unsigned int)time(NULL));

    float integral = 0.0f;
    float previous_error = 0.0f;
    float setpoint = 0.0f;

    while (running) {
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        float pid_output = calculate_pid(setpoint, tilt_error, &integral, &previous_error, 0.05f);

        int motor_a_speed = (int)pid_output;
        int motor_b_speed = (int)pid_output;

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -50;
            motor_b_speed = -50;
        }

        set_motor_speed('A', motor_a_speed);
        set_motor_speed('B', motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    stop_motors();
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

