/*
 * mood_light.c — Raspberry Pi 3 Model B+
 * ALSA audio capture (RMS) drives a common-cathode RGB LED via pigpio software PWM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound -lm
 * Run:    sudo ./mood_light [sensitivity_scale]
 *
 * Sensitivity scale > 0.0; default 1.0.  Negative values are clamped to 1.0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif

/* ---- Pin assignments (BCM numbering) ---- */
#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

/* ---- Audio capture parameters ---- */
#define SAMPLE_RATE      8000
#define NUM_CHANNELS     1
#define PERIOD_SIZE_FRAMES 1024
#define BUFFER_SIZE_FRAMES (PERIOD_SIZE_FRAMES * 4)   /* 4 x period */

/* ---- Timing ---- */
#define UPDATE_DELAY_US  10000   /* 10 ms between LED updates */
#define MAX_AMPLITUDE    32767.0 /* 16-bit signed max */

/* ---- Globals for signal handler cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_ready = 0;

#ifdef ALSA_AVAILABLE
static snd_pcm_t *g_pcm = NULL;
#endif

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and resources are      */
/* released cleanly.                                                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure RGB LED pins for software PWM.      */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    g_pigpio_ready = 1;

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RED_PIN);
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GREEN_PIN);
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BLUE_PIN);
        return -1;
    }

    /* Start with LED off (0% duty cycle) */
    if (gpioPWM(RED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n", RED_PIN);
        return -1;
    }
    if (gpioPWM(GREEN_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n", GREEN_PIN);
        return -1;
    }
    if (gpioPWM(BLUE_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise PWM on GPIO%d.\n", BLUE_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Release all pigpio resources.                                       */
/* ------------------------------------------------------------------ */
static void cleanup_gpio(void)
{
    if (g_pigpio_ready) {
        /* Best-effort LED off */
        gpioPWM(RED_PIN, 0);
        gpioPWM(GREEN_PIN, 0);
        gpioPWM(BLUE_PIN, 0);
        gpioTerminate();
        g_pigpio_ready = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Initialize ALSA capture device.                                     */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
#ifdef ALSA_AVAILABLE
static int initialize_alsa(void)
{
    int err;

    err = snd_pcm_open(&g_pcm, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Error: cannot open ALSA default capture device: %s\n",
                snd_strerror(err));
        return -1;
    }

    err = snd_pcm_set_params(g_pcm,
                            SND_PCM_FORMAT_S16_LE,
                            SND_PCM_ACCESS_RW_INTERLEAVED,
                            NUM_CHANNELS,
                            SAMPLE_RATE,
                            1,          /* allow resampling */
                            500000);    /* 0.5 s latency */
    if (err < 0) {
        fprintf(stderr, "Error: cannot set ALSA parameters: %s\n",
                snd_strerror(err));
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
        return -1;
    }

    return 0;
}
#endif

/* ------------------------------------------------------------------ */
/* Release all ALSA resources.                                         */
/* ------------------------------------------------------------------ */
#ifdef ALSA_AVAILABLE
static void cleanup_alsa(void)
{
    if (g_pcm != NULL) {
        snd_pcm_drain(g_pcm);
        snd_pcm_close(g_pcm);
        g_pcm = NULL;
    }
}
#endif

/* ------------------------------------------------------------------ */
/* Read one period of audio data from ALSA.                            */
/* Returns 0 on success, -1 on error (caller may retry).               */
/* ------------------------------------------------------------------ */
#ifdef ALSA_AVAILABLE
static int read_audio_period(int16_t *buffer, int num_frames)
{
    int err;

    err = snd_pcm_readi(g_pcm, buffer, num_frames);
    if (err == num_frames) {
        return 0;
    }

    if (err == -EPIPE) {
        /* Overrun — recover */
        fprintf(stderr, "Warning: ALSA overrun, recovering...\n");
        err = snd_pcm_prepare(g_pcm);
        if (err < 0) {
            fprintf(stderr, "Error: snd_pcm_prepare failed: %s\n",
                    snd_strerror(err));
            return -1;
        }
        return 0;
    }

    if (err == -ESTRPIPE) {
        /* Device suspended — resume */
        fprintf(stderr, "Warning: ALSA suspended, resuming...\n");
        err = snd_pcm_resume(g_pcm);
        if (err < 0) {
            fprintf(stderr, "Error: snd_pcm_resume failed: %s\n",
                    snd_strerror(err));
            return -1;
        }
        return 0;
    }

    if (err < 0) {
        fprintf(stderr, "Error: ALSA read failed: %s\n", snd_strerror(err));
        return -1;
    }

    /* err < num_frames — partial read, caller may retry */
    return 0;
}
#endif

/* ------------------------------------------------------------------ */
/* Compute RMS amplitude of a buffer of signed 16-bit samples.         */
/* ------------------------------------------------------------------ */
static double calculate_amplitude(const int16_t *buffer, int num_frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < num_frames; i++) {
        double v = (double)buffer[i];
        sum_sq += v * v;
    }
    return sqrt(sum_sq / (double)num_frames);
}

/* ------------------------------------------------------------------ */
/* Map amplitude to RGB values using a non-linear transition.          */
/* Low amplitude -> cool colors (blue-ish), high amplitude -> warm     */
/* colors (red-ish).  Sensitivity scales the transition range.         */
/* ------------------------------------------------------------------ */
static void map_amplitude_to_rgb(double amplitude, double sensitivity,
                                 int *red, int *green, int *blue)
{
    double scaled = amplitude * sensitivity;
    if (scaled < 0.0) scaled = 0.0;
    if (scaled > MAX_AMPLITUDE) scaled = MAX_AMPLITUDE;

    /* Normalize to [0, 1] */
    double norm = scaled / MAX_AMPLITUDE;

    /* Non-linear transition: low -> blue, high -> red */
    double r, g, b;
    if (norm < 0.5) {
        /* Blue to cyan */
        r = 0.0;
        g = norm * 2.0;          /* 0 .. 1 */
        b = 1.0;
    } else {
        /* Cyan to red */
        r = (norm - 0.5) * 2.0;  /* 0 .. 1 */
        g = 1.0;
        b = 0.0;
    }

    /* Scale to 0-255 PWM range */
    *red   = (int)(r * 255.0);
    *green = (int)(g * 255.0);
    *blue  = (int)(b * 255.0);
}

/* ------------------------------------------------------------------ */
/* Set RGB LED color via pigpio software PWM.                           */
/* ------------------------------------------------------------------ */
static void set_led_color(int red, int green, int blue)
{
    if (red   < 0) red   = 0; if (red   > 255) red   = 255;
    if (green < 0) green = 0; if (green > 255) green = 255;
    if (blue  < 0) blue  = 0; if (blue  > 255) blue  = 255;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

/* ------------------------------------------------------------------ */
/* Simulated audio input (sine wave) when ALSA is unavailable.         */
/* Returns amplitude value.                                            */
/* ------------------------------------------------------------------ */
#ifndef ALSA_AVAILABLE
static double simulate_audio_input(void)
{
    static double phase = 0.0;
    phase += 2.0 * M_PI * 1.0 / SAMPLE_RATE;
    if (phase > 2.0 * M_PI) phase -= 2.0 * M_PI;
    return (sin(phase) + 1.0) * MAX_AMPLITUDE / 2.0;
}
#endif

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    double sensitivity = 1.0;

    if (argc > 1) {
        sensitivity = atof(argv[1]);
        if (sensitivity <= 0.0) {
            fprintf(stderr, "Warning: sensitivity must be positive; using 1.0.\n");
            sensitivity = 1.0;
        }
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    /* Initialize ALSA if available */
#ifdef ALSA_AVAILABLE
    if (initialize_alsa() != 0) {
        fprintf(stderr, "Warning: ALSA initialization failed; "
                        "using simulated audio input.\n");
    }
#endif

    int16_t *audio_buffer = malloc((size_t)PERIOD_SIZE_FRAMES * sizeof(int16_t));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Error: out of memory allocating audio buffer.\n");
        cleanup_gpio();
#ifdef ALSA_AVAILABLE
        cleanup_alsa();
#endif
        return EXIT_FAILURE;
    }

    printf("Mood light started. Sensitivity scale: %.2f\n", sensitivity);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
#ifdef ALSA_AVAILABLE
        if (g_pcm != NULL) {
            if (read_audio_period(audio_buffer, PERIOD_SIZE_FRAMES) != 0) {
                /* Error already reported; wait and retry */
                gpioDelay(UPDATE_DELAY_US);
                continue;
            }
        } else {
            /* Simulated audio input when ALSA is unavailable */
            double amp = simulate_audio_input();
            double norm = amp / MAX_AMPLITUDE;
            int red   = (int)(norm * 255.0);
            int green = (int)(norm * 255.0);
            int blue  = (int)((1.0 - norm) * 255.0);
            set_led_color(red, green, blue);
            gpioDelay(UPDATE_DELAY_US);
            continue;
        }
#endif

        double amplitude = calculate_amplitude(audio_buffer, PERIOD_SIZE_FRAMES);
        int red, green, blue;
        map_amplitude_to_rgb(amplitude, sensitivity, &red, &green, &blue);
        set_led_color(red, green, blue);

        gpioDelay(UPDATE_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    set_led_color(0, 0, 0);   /* LED off */
    free(audio_buffer);

#ifdef ALSA_AVAILABLE
    cleanup_alsa();
#endif

    cleanup_gpio();

    printf("Mood light stopped.\n");
    return EXIT_SUCCESS;
}

