#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int tcs34725_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, TCS34725_COMMAND_BIT | reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int tcs34725_read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, TCS34725_COMMAND_BIT | reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int tcs34725_init(void) {
    if (tcs34725_write_reg(TCS34725_ENABLE, 0x03) < 0) return -1;
    if (tcs34725_write_reg(TCS34725_ATIME, 0xD5) < 0) return -1;
    return 0;
}

static int tcs34725_read_crgb(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];
    int rc = i2cReadI2CBlockData(i2c_handle, TCS34725_COMMAND_BIT | TCS34725_CDATA, (char *)buf, 8);
    if (rc < 0) {
        fprintf(stderr, "Error reading CRGB block: %d\n", rc);
        return -1;
    }
    *clear = (uint16_t)buf[1] << 8 | buf[0];
    *red   = (uint16_t)buf[3] << 8 | buf[2];
    *green = (uint16_t)buf[5] << 8 | buf[4];
    *blue  = (uint16_t)buf[7] << 8 | buf[6];
    return 0;
}

static void log_data(time_t timestamp, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    fprintf(fp, "%ld,%u,%u,%u,%u\n", (long)timestamp, clear, red, green, blue);
    fflush(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (tcs34725_init() < 0) {
        fprintf(stderr, "TCS34725 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fp = fopen("color_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(fp, "timestamp,clear,red,green,blue\n");
    fflush(fp);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_crgb(&clear, &red, &green, &blue) == 0) {
            time_t now = time(NULL);
            log_data(now, clear, red, green, blue);
        } else {
            fprintf(stderr, "Sensor read failed; logging zeros.\n");
            time_t now = time(NULL);
            log_data(now, 0, 0, 0, 0);
        }
        gpioDelay(500000);
    }

    if (fp) fclose(fp);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

