#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SUNRISE_DURATION 3600
#define DAY_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHT_DURATION 518400
#define NUM_RELAYS 4
#define CHIP_NAME "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 27, 22, 23};
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[NUM_RELAYS];
static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u\n", relay_pins[i]);
            return -1;
        }
        if (gpiod_line_request_output(lines[i], "sunlight_sim", 1) < 0) {
            perror("gpiod_line_request_output");
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_set_value(lines[i], 1);
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static void set_all_relays(int value) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) gpiod_line_set_value(lines[i], value);
    }
}

static void sunrise_phase(void) {
    for (int elapsed = 0; elapsed < SUNRISE_DURATION && running; elapsed += 100) {
        int duty = (int)(((float)elapsed / SUNRISE_DURATION) * 100.0f);
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], duty > 0 ? 0 : 1);
        }
        usleep(100000);
    }
}

static void daytime_phase(void) {
    for (int elapsed = 0; elapsed < DAY_DURATION && running; elapsed += 100) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], 0);
        }
        usleep(100000);
    }
}

static void sunset_phase(void) {
    for (int elapsed = 0; elapsed < SUNSET_DURATION && running; elapsed += 100) {
        int duty = (int)(((float)elapsed / SUNSET_DURATION) * 100.0f);
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], duty > 0 ? 0 : 1);
        }
        usleep(100000);
    }
}

static void nighttime_phase(void) {
    for (int elapsed = 0; elapsed < NIGHT_DURATION && running; elapsed += 100) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], 1);
        }
        usleep(100000);
    }
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() != 0) {
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (running) {
        sunrise_phase();
        if (!running) break;
        daytime_phase();
        if (!running) break;
        sunset_phase();
        if (!running) break;
        nighttime_phase();
    }

    set_all_relays(1);
    cleanup_gpio();
    return EXIT_SUCCESS;
}

