#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define VIDEO_DURATION 5
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", t);
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static int record_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d -w 1280 -h 720 -fps 25",
             filename, VIDEO_DURATION * 1000);
    int result = system(command);
    if (result == -1) {
        perror("system() failed");
        return -1;
    }
    if (WIFEXITED(result) && WEXITSTATUS(result) != 0) {
