#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 low) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

/* Sensitivity for ±250°/s range: 131 LSB per °/s */
#define GYRO_SENSITIVITY 131.0f

/* Sampling interval: 10 ms -> 100 Hz */
#define SAMPLE_INTERVAL_US 10000

/* Re-initialization retry count */
#define REINIT_RETRIES 3

/* Global state */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Initialize MPU-6050: wake, set sample rate, set gyro range */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms settle */

    /* Set sample rate divider to 125 Hz (1 kHz / (1 + 125) = 7.8125 Hz) */
    if (i2cWriteByteData(handle, SMPLRT_DIV, 125) < 0) {
        fprintf(stderr, "Error: failed to write SMPLRT_DIV\n");
        return -1;
    }

    /* Set gyroscope full-scale range to ±250°/s (FS_SEL = 0) */
    if (i2cWriteByteData(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write GYRO_CONFIG\n");
        return -1;
    }

    return 0;
}

/* Read gyroscope data (X, Y, Z) in degrees per second */
static int read_gyro_data(int handle, float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting at GYRO_XOUT_H using a combined block read */
    if (i2cReadI2CBlockData(handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read gyroscope data block\n");
        return -1;
    }

    raw_x = (int16_t)(((uint16_t)buf[0] << 8) | (uint8_t)buf[1]);
    raw_y = (int16_t)(((uint16_t)buf[2] << 8) | (uint8_t)buf[3]);
    raw_z = (int16_t)(((uint16_t)buf[4] << 8) | (uint8_t)buf[5]);

    *x = (float)raw_x / GYRO_SENSITIVITY;
    *y = (float)raw_y / GYRO_SENSITIVITY;
    *z = (float)raw_z / GYRO_SENSITIVITY;

    return 0;
}

/* Log a gyroscope reading to CSV with timestamp (seconds.milliseconds) */
static void log_gyro_data(FILE *fp, float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
    fprintf(fp, "%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

/* Re-initialize the MPU-6050 with retries */
static int reinit_mpu6050(int handle) {
    for (int attempt = 0; attempt < REINIT_RETRIES; attempt++) {
        if (init_mpu6050(handle) == 0) {
            fprintf(stderr, "MPU-6050 re-initialized successfully.\n");
            return 0;
        }
        fprintf(stderr, "MPU-6050 re-initialization attempt %d/%d failed.\n",
                attempt + 1, REINIT_RETRIES);
        gpioDelay(100000); /* 100 ms backoff */
    }
    fprintf(stderr, "MPU-6050 re-initialization failed after %d attempts.\n",
            REINIT_RETRIES);
    return -1;
}

int main(void) {
    float x, y, z;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at address 0x%02X.\n",
                MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open gyro_log.csv for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,x_degps,y_degps,z_degps\n");
        fflush(log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    fprintf(stderr, "Gyroscope monitoring started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (!terminate) {
        if (read_gyro_data(i2c_handle, &x, &y, &z) == 0) {
            log_gyro_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Error: failed to read gyroscope data.\n");
            if (reinit_mpu6050(i2c_handle) < 0) {
                fprintf(stderr, "Error: sensor re-initialization failed. Exiting.\n");
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    fprintf(stderr, "Gyroscope monitoring stopped.\n");
    return EXIT_SUCCESS;
}

