#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define ZONE1 4
#define ZONE2 17
#define ZONE3 27
#define ZONE4 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    int pins[] = {ZONE1, ZONE2, ZONE3, ZONE4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Failed to set GPIO %d HIGH\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static int read_moisture_sensor(void) {
    return rand() % 101;
}

static int control_relay(int pin, int moisture_level) {
    int state = (moisture_level < MOISTURE_THRESHOLD) ? 0 : 1;
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static void log_data(int zone, int moisture_level, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s - Zone %d: Moisture = %d, Relay = %s\n",
            timestamp, zone, moisture_level, relay_state ? "ON" : "OFF");
    fflush(log_file);
}

static void cleanup(void) {
    int pins[] = {ZONE1, ZONE2, ZONE3, ZONE4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], 1);
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    srand((unsigned int)time(NULL));
    signal(SIGINT, signal_handler);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int moisture1 = read_moisture_sensor();
        int moisture2 = read_moisture_sensor();
        int moisture3 = read_moisture_sensor();
        int moisture4 = read_moisture_sensor();

        if (control_relay(ZONE1, moisture1) != 0 ||
            control_relay(ZONE2, moisture2) != 0 ||
            control_relay(ZONE3, moisture3) != 0 ||
            control_relay(ZONE4, moisture4) != 0) {
            fprintf(stderr, "Relay control error, exiting.\n");
            break;
        }

        log_data(1, moisture1, (moisture1 < MOISTURE_THRESHOLD) ? 0 : 1);
        log_data(2, moisture2, (moisture2 < MOISTURE_THRESHOLD) ? 0 : 1);
        log_data(3, moisture3, (moisture3 < MOISTURE_THRESHOLD) ? 0 : 1);
        log_data(4, moisture4, (moisture4 < MOISTURE_THRESHOLD) ? 0 : 1);

        gpioDelay(POLL_INTERVAL_SEC * 1000000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

