#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ALARM_GPIO 27
#define FREEFALL_THRESHOLD 0.2f
#define FREEFALL_DURATION_MS 500
#define SAMPLE_INTERVAL_US 100000
#define ALARM_HOLD_US 5000000

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int adxl345_init(void) {
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to clear POWER_CTL\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error: Failed to set DATA_FORMAT\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to set POWER_CTL to measure mode\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

static int detect_freefall(float x, float y, float z) {
    return (fabsf(x) < FREEFALL_THRESHOLD && fabsf(y) < FREEFALL_THRESHOLD && fabsf(z) < FREEFALL_THRESHOLD);
}

static void trigger_alarm(void) {
    gpioWrite(ALARM_GPIO, 1);
    gpioDelay(ALARM_HOLD_US);
    gpioWrite(ALARM_GPIO, 0);
}

