    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at 0x%02X\n", ADXL345_ADDRESS);
        gpioTerminate();
        return 1;
    }

    if (adxl345_init() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int freefall_count = 0;
    int freefall_confirmed = 0;

    while (running) {
        float x, y, z;
        if (read_accelerometer(&x, &y, &z) == 0) {
            if (detect_freefall(x, y, z)) {
                freefall_count++;
                if (freefall_count >= (FREEFALL_DURATION_MS / 100)) {
                    freefall_confirmed = 1;
