#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US 100000
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US 200000

static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t echo_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
        echo_received = 1;
    }
}

static double calculate_distance_cm(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) return -1.0;
    double distance = (double)pulse_width_us * 0.0343 / 2.0;
    if (distance > MAX_DISTANCE_CM) return -1.0;
    return distance;
}

static void log_distance(double distance_cm) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long long timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    if (log_file != NULL) {
        fprintf(log_file, "%lld,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize TRIGGER_PIN low\n");
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_received = 0;
        start_tick = 0;
        end_tick = 0;

        if (gpioWrite(TRIGGER_PIN, 1) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN high\n");
            break;
        }
        gpioDelay(TRIGGER_PULSE_US);
        if (gpioWrite(TRIGGER_PIN, 0) != 0) {
            fprintf(stderr, "Failed to set TRIGGER_PIN low\n");
            break;
        }

        uint32_t start_wait = gpioTick();
        while (!echo_received && running) {
            if ((gpioTick() - start_wait) > TIMEOUT_US) {
                break;
            }
            gpioDelay(100);
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue;
        }

        uint32_t pulse_width;
        if (end_tick >= start_tick) {
            pulse_width = end_tick - start_tick;
        } else {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick + 1;
        }

        double distance = calculate_distance_cm(pulse_width);
        if (distance > 0.0) {
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance reading\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&echo_mutex);
    printf("Program terminated.\n");
    return 0;
}

