#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define DEFAULT_FREEFALL_THRESHOLD 0.2f
#define DEFAULT_IMPACT_THRESHOLD 1.5f
#define I2C_RETRIES 3
#define SAMPLE_DELAY_US 10000

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_lis3dh(void) {
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int retries = I2C_RETRIES;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) == 6) {
            int16_t x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);
            *x = (float)x_raw / 16384.0f;
            *y = (float)y_raw / 16384.0f;
            *z = (float)z_raw / 16384.0f;
            return 0;
        }
        fprintf(stderr, "I2C read error, retries left: %d\n", retries - 1);
        retries--;
        gpioDelay(1000);
    }
    return -1;
