#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 2.0f
#define DEFAULT_I2C_ADDRESS 0x18
#define LOG_FILE "/var/log/high_acceleration.log"
#define SAMPLE_INTERVAL_US 100000
#define MAX_I2C_ADDRESS 0x77
#define MIN_I2C_ADDRESS 0x08

#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X\n", val, reg);
        return -1;
    }
    return 0;
}

static int init_lis3dh(uint8_t address) {
    if (address < MIN_I2C_ADDRESS || address > MAX_I2C_ADDRESS) {
        fprintf(stderr, "Invalid I2C address 0x%02X (must be 0x08-0x77)\n", address);
        return -1;
    }

    i2c_handle = i2cOpen(1, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device at 0x%02X: %d\n", address, i2c_handle);
        return -1;
    }

    int who = i2cReadByteData(i2c_handle, LIS3DH_REG_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }
    if (who != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, LIS3DH_WHO_AM_I_VAL);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    if (write_reg(LIS3DH_REG_CTRL1, 0x57) < 0) { i2cClose(i2c_handle); i2c_handle = -1; return -1; }
    if (write_reg(LIS3DH_REG_CTRL4, 0x88) < 0) { i2cClose(i2c_handle); i2c_handle = -1; return -1; }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = *y = *z = 0.0f;
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *x = (float)(raw_x >> 4) * 0.0009765625f;
    *y = (float)(raw_y >> 4) * 0.0009765625f;
    *z = (float)(raw_z >> 4) * 0.0009765625f;
    return 0;
}

static void log_event(float x, float y, float z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - High acceleration detected: X=%.3f g, Y=%.3f g, Z=%.3f g\n", ts, x, y, z);
    fclose(fp);
}

static void shutdown_system(void) {
    printf("Shutting down system...\n");
    fflush(stdout);
    system("sudo shutdown -h now");
}

int main(int argc, char *argv[]) {
    float threshold = DEFAULT_THRESHOLD;
    uint8_t address = DEFAULT_I2C_ADDRESS;

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0 && i + 1 < argc) {
            address = (uint8_t)strtol(argv[++i], NULL, 16);
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = strtof(argv[++i], NULL);
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address_hex] [-t threshold_g]\n", argv[0]);
            return 1;
        }
    }

    if (threshold <= 0.0f) {
        fprintf(stderr, "Threshold must be greater than 0\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 0;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_lis3dh(address) != 0) {
        fprintf(stderr, "LIS3DH initialization failed\n");
        gpioTerminate();
        return 0;
    }

    printf("Monitoring acceleration (threshold: %.2f g)...\n", threshold);
    fflush(stdout);

    while (!terminate) {
        float x, y, z;
        if (read_acceleration(&x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold || fabsf(z) > threshold) {
                log_event(x, y, z);
                shutdown_system();
                break;
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

