/*
 * Line-following robot for Raspberry Pi 5 using libgpiod.
 * Sensors : SunFounder 3-Way Tracking Sensor (IR reflectance, digital)
 *   LEFT   -> GPIO4  (0 = line detected, 1 = no line)
 *   CENTER -> GPIO17 (0 = line detected, 1 = no line)
 *   RIGHT  -> GPIO27 (0 = line detected, 1 = no line)
 * Alert  : GPIO22 (active-high LED/buzzer)
 *
 * Build: gcc -O2 -Wall -Wextra -o line_follower line_follower.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN   4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define ALERT_PIN         22

#define BUFFER_SIZE 5
#define POLL_MS     10
#define ALERT_MS    2000
#define CONSECUTIVE_NO_LINE 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static void buffer_init(circular_buffer_t *buf)
{
    buf->head = 0;
    buf->count = 0;
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void log_data(sensor_data_t d)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    printf("[%s] L=%d C=%d R=%d\n", ts, d.left, d.dcenter, d.right);
}

static void motor_forward(void)
{
    printf("Motor: Forward\n");
}

static void motor_turn_left(void)
{
    printf("Motor: Turn Left\n");
}

static void motor_turn_right(void)
{
    printf("Motor: Turn Right\n");
}

static void motor_stop(void)
{
    printf("Motor: Stop\n");
}

static void alert_on(struct gpiod_line *alert)
{
    if (gpiod_line_set_value(alert, 1) < 0)
        perror("Failed to set alert HIGH");
    else
        printf("Alert: ON\n");
}

static void alert_off(struct gpiod_line *alert)
{
    if (gpiod_line_set_value(alert, 0) < 0)
        perror("Failed to set alert LOW");
    else
        printf("Alert: OFF\n");
}

static void run_alert(struct gpiod_line *alert)
{
    printf("Alert triggered! Running for %d ms...\n", ALERT_MS);
    alert_on(alert);
    struct timespec ts = { ALERT_MS / 1000, (ALERT_MS % 1000) * 1000000L };
    nanosleep(&ts, NULL);
    alert_off(alert);
}

static void process_data(sensor_data_t d, struct gpiod_line *alert)
{
    buffer_add(&buf, d);
    log_data(d);

    if (d.center == 1) {
        motor_forward();
        return;
    }
    if (d.left == 1) {
        motor_turn_left();
        return;
    }
    if (d.right == 1) {
        motor_turn_right();
        return;
    }

    static int no_line_count = 0;
    if (d.center == 1) {
        no_line_count++;
        if (no_line_count >= CONSECUTIVE_NO_LINE) {
            run_alert(alert);
            no_line_count = 0;
        }
    } else {
        no_line_count = 0;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left = NULL, *center = NULL, *right = NULL, *alert = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    left   = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    center = gpiod_chip_get_line(chip, CENTER_SENSOR_PIN);
    right  = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    alert  = gpiod_chip_get_line(chip, ALERT_PIN);
    if (!left || !center || !right || !alert) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(left, "line_follower") < 0 ||
        gpiod_line_request_input(center, "line_follower") < 0 ||
        gpiod_line_request_input(right, "line_follower") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    if (gpiod_line_request_output(alert, "line_follower", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    buffer_init(&buf);

    printf("Line follower started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int lv = gpiod_line_get_value(left);
        int cv = gpiod_line_get_value(center);
        int rv = gpiod_line_get_value(right);

        if (lv < 0 || cv < 0 || rv < 0) {
            fprintf(stderr, "Sensor read error: %s\n", strerror(errno));
            break;
        }

        sensor_data_t d = { lv, cv, rv };
        process_data(d, alert);

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (alert)
        gpiod_line_set_value(alert, 0);
    if (left)   gpiod_line_release(left);
    if (center) gpiod_line_release(center);
    if (right)  gpiod_line_release(right);
    if (alert)  gpiod_line_release(alert);
    if (chip)   gpiod_chip_close(chip);
    printf("Exiting.\n");
    return ret;
}

