#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x30
#define GPIO_RELAY     17
#define THRESHOLD_MT   5.0f
#define POLL_TIMEOUT   50
#define SAMPLE_US      100000
#define LOG_FILE       "magnetic_events.txt"

#define REG_DATA       0xC0
#define REG_STATUS     0xC1
#define CMD_START      0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[timestamp error] %s\n", msg);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_field_raw(int handle, int16_t *out) {
    if (i2cWriteByteData(handle, REG_STATUS, CMD_START) < 0) {
        log_event("Error: failed to start conversion");
        return -1;
    }
    for (int i = 0; i < POLL_TIMEOUT; i++) {
        int status = i2cReadByteData(handle, REG_STATUS);
        if (status < 0) {
            log_event("Error: failed to read status register");
            return -1;
        }
        if ((status & 0x01) == 0) break;
        gpioDelay(1000);
        if (i == POLL_TIMEOUT - 1) {
            log_event("Error: conversion timeout");
            return -1;
        }
    }
    int lsb = i2cReadByteData(handle, REG_DATA);
    if (lsb < 0) {
        log_event("Error: failed to read LSB");
        return -1;
    }
    int msb = i2cReadByteData(handle, REG_DATA + 1);
    if (msb < 0) {
        log_event("Error: failed to read MSB");
        return -1;
    }
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        log_event("Error: failed to write relay GPIO");
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        log_event("Error: i2cOpen failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        log_event("Error: failed to set relay GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("System started");
    while (g_running) {
        int16_t raw;
        if (read_field_raw(g_i2c_handle, &raw) < 0) {
            control_relay(0);
            gpioDelay(SAMPLE_US);
            continue;
        }
        float field_mt = (float)raw * 25.0f / 1000.0f;
        int relay_state = (field_mt > THRESHOLD_MT) ? 1 : 0;
        control_relay(relay_state);
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Field: %.2f mT, Relay: %s",
                 field_mt, relay_state ? "ON" : "OFF");
        log_event(msg);
        gpioDelay(SAMPLE_US);
    }
    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

