    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        log_event("Error: failed to write relay GPIO");
    }
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
}

