        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        log_event("Error: i2cOpen failed");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        log_event("Error: failed to set relay GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_RELAY, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("System started");
    while (g_running) {
        int16_t raw;
        if (read_field_raw(g_i2c_handle, &raw) < 0) {
            control_relay(0);
            gpioDelay(SAMPLE_US);
            continue;
        }
        float field_mt = (float)raw * 25.0f / 1000.0f;
        int relay_state = (field_mt > THRESHOLD_MT) ? 1 : 0;
        control_relay(relay_state);
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Field: %.2f mT, Relay: %s",
                 field_mt, relay_state ? "ON" : "OFF");
        log_event(msg);
        gpioDelay(SAMPLE_US);
    }
    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

