#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

static void cleanup(void) {
    if (client_fd >= 0) { close(client_fd); client_fd = -1; }
    if (server_fd >= 0) { close(server_fd); server_fd = -1; }
    if (log_file) { fclose(log_file); log_file = NULL; }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_socket(void) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) { perror("socket"); return -1; }

    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt"); close(fd); return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); close(fd); return -1;
    }

    if (listen(fd, 3) < 0) {
        perror("listen"); close(fd); return -1;
    }

    return fd;
}

static int parse_command(const char *buf) {
    if (!buf || !*buf) return -1;
    char cmd[16];
    strncpy(cmd, buf, sizeof(cmd) - 1);
    cmd[sizeof(cmd) - 1] = '\0';
    cmd[strcspn(cmd, "\r\n")] = '\0';
    char *p = cmd + strlen(cmd) - 1;
    while (p >= cmd && (*p == ' ' || *p == '\t' || *p == '\r' || *p == '\n')) *p-- = '\0';

    if (strcasecmp(cmd, "ON") == 0) return 1;
    if (strcasecmp(cmd, "OFF") == 0) return 0;
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction"); return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return 1;
    }

    server_fd = setup_socket();
    if (server_fd < 0) {
        cleanup();
        return 1;
    }

    log_event("Server started");
    printf("Listening on port %d...\n", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            continue;
        }

        char ip[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip, sizeof(ip));
        printf("Connection from %s\n", ip);

        char buffer[BUFFER_SIZE];
        ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (n > 0) {
            buffer[n] = '\0';
            int state = parse_command(buffer);
            if (state == 1) {
                if (gpioWrite(GPIO_PIN, 1) == 0) {
                    log_event("Relay activated");
                    printf("Relay ON\n");
                } else {
                    log_event("Error: failed to activate relay");
                }
            } else if (state == 0) {
                if (gpioWrite(GPIO_PIN, 0) == 0) {
                    log_event("Relay deactivated");
                    printf("Relay OFF\n");
                } else {
                    log_event("Error: failed to deactivate relay");
                }
            } else {
                log_event("Invalid command received");
                printf("Invalid command: %s\n", buffer);
            }
        } else if (n == 0) {
            printf("Client disconnected\n");
        } else {
            perror("recv");
        }

        close(client_fd);
        client_fd = -1;
    }

    log_event("Server shutting down");
    cleanup();
    return 0;
}

