#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO   18
#define FLOW_THRESHOLD 5.0f
#define SCALE_FACTOR  1.0f / 1500.0f
#define POLL_DELAY_US 100000
#define LOG_FILE      "flow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int init_sensor(int handle)
{
    uint8_t cmd[2] = {0x36, 0x08};
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: failed to send start-measurement command to handle %d\n", handle);
        return -1;
    }
    return 0;
}

static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buf[3];
    int n = i2cReadDevice(handle, (char *)buf, 3);
    if (n != 3) {
        fprintf(stderr, "Error: I2C read returned %d bytes (expected 3) on handle %d\n", n, handle);
        return -1;
    }
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "Error: CRC mismatch on handle %d\n", handle);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw * SCALE_FACTOR;
    return 0;
}

static void control_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", state);
    }
}

static void log_flow_rates(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s for append\n", LOG_FILE);
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min\n",
            ts_str, ts.tv_nsec / 1000000, f1, f2);
    fflush(fp);
    fclose(fp);
}

static void cleanup(void)
{
    control_relay(0);
    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle1 = i2cOpen(1, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "Error: i2cOpen failed for sensor 1 (addr 0x%02X): %d\n",
                SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(1, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "Error: i2cOpen failed for sensor 2 (addr 0x%02X): %d\n",
                SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_handle1) != 0 || init_sensor(g_i2c_handle2) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    control_relay(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &f1);
        int ok2 = read_flow_rate(g_i2c_handle2, &f2);

        if (ok1 != 0 || ok2 != 0) {
            fprintf(stderr, "Warning: sensor read error, skipping cycle\n");
        } else {
            log_flow_rates(f1, f2);
            if (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) {
                control_relay(1);
            } else {
                control_relay(0);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

