    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int ok1 = read_flow_rate(g_i2c_handle1, &f1);
        int ok2 = read_flow_rate(g_i2c_handle2, &f2);

        if (ok1 != 0 || ok2 != 0) {
            fprintf(stderr, "Warning: sensor read error, skipping cycle\n");
        } else {
            log_flow_rates(f1, f2);
            if (f1 < FLOW_THRESHOLD || f2 < FLOW_THRESHOLD) {
                control_relay(1);
            } else {
                control_relay(0);
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

