#define POLL_INTERVAL_US  200000   /* 200 ms */
#define MOTOR_RUN_US      5000000  /* 5 s   */
#define DRY_THRESHOLD     3        /* consecutive dry polls */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_write(unsigned pin, unsigned level, const char *label)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(%u, %u) failed for %s", pin, level, label);
        return -1;
    }
    return 0;
}

static int motor_stop(void)
{
    int rc = 0;
    rc |= safe_write(MOTOR_ENABLE_PIN, 0, "ENA");
    rc |= safe_write(MOTOR_INPUT1_PIN, 0, "IN1");
    rc |= safe_write(MOTOR_INPUT2_PIN, 0, "IN2");
    return rc;
}

static int motor_close_window(void)
{
    syslog(LOG_INFO, "Closing window: ENA=1 IN1=1 IN2=0");
    if (safe_write(MOTOR_ENABLE_PIN, 1, "ENA") < 0) return -1;
    if (safe_write(MOTOR_INPUT1_PIN, 1, "IN1") < 0) return -1;
    if (safe_write(MOTOR_INPUT2_PIN, 0, "IN2") < 0) return -1;

    /* gpioDelay is a pigpio microsecond sleep; busy-wait-free. */
    gpioDelay(MOTOR_RUN_US);

    syslog(LOG_INFO, "Window close sequence complete");
    return motor_stop();
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain window controller started");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN) failed");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_INPUT2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR) failed");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

