       defined when the sensor is disconnected or the output is high-Z. */
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_WARNING, "gpioSetPullUpDown(RAIN) failed; continuing");
    }

    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Initial motor stop failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int dry_count = 0;
    int last_rain = 0;   /* 0 = dry, 1 = wet */
    int first_poll = 1;

    while (g_running) {
        int rain = gpioRead(RAIN_SENSOR_PIN);
        if (rain < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN) failed");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        int is_wet = (rain == 0);  /* active-low DO */

        if (first_poll) {
            last_rain = is_wet;
            first_poll = 0;
        }

        if (is_wet && !last_rain) {
            syslog(LOG_INFO, "Rain detected (wet HIGH on DO)");
            if (motor_close_window() < 0) {
                syslog(LOG_ERR, "Window close sequence failed");
            }
            /* Re-arm: suppress re-trigger until sensor reads dry for DRY_THRESHOLD polls. */
            dry_count = 0;
        } else if (!is_wet) {
            dry_count++;
            if (dry_count >= DRY_THRESHOLD) {
                syslog(LOG_INFO, "Sensor dry for %d polls; re-arming", DRY_THRESHOLD);
                dry_count = 0;
            }
        } else {
            dry_count = 0;
        }

        last_rain = is_wet;
        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down: stopping motor and cleaning up");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

