#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US   2000
#define UNLOCK_PULSE_US 1000
#define DEBOUNCE_US     50000   /* 50 ms debounce */
#define POLL_US         10000   /* 10 ms poll interval */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", SERVO_PIN, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure button pins as inputs with pull-ups --- */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Ensure servo is in a known unlocked state --- */
    if (set_servo(UNLOCK_PULSE_US) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    printf("Servo initialized to unlocked position (%d us).\n", UNLOCK_PULSE_US);
    fflush(stdout);

    int last_lock_state   = 1;   /* pulled high = not pressed */
    int last_unlock_state = 1;

    while (g_running) {
        int lock_state   = gpioRead(LOCK_BUTTON);
        int unlock_state = gpioRead(UNLOCK_BUTTON);

        /* --- Lock button: pressed (low) --- */
        if (lock_state == 0 && last_lock_state == 1) {
            /* Wait for release to avoid re-triggering */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            if (set_servo(LOCK_PULSE_US) == 0) {
                printf("Door locked (servo pulse %d us).\n", LOCK_PULSE_US);
                fflush(stdout);
            }
        }

        /* --- Unlock button: pressed (low) --- */
        if (unlock_state == 0 && last_unlock_state == 1) {
            /* Wait for release to avoid re-triggering */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(POLL_US);
            }
            if (set_servo(UNLOCK_PULSE_US) == 0) {
                printf("Door unlocked (servo pulse %d us).\n", UNLOCK_PULSE_US);
                fflush(stdout);
            }
        }

        last_lock_state   = lock_state;
        last_unlock_state = unlock_state;

        gpioDelay(POLL_US);
    }

    /* --- Clean shutdown: stop servo pulses and release pigpio --- */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

