#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 4
#define FLOODLIGHT_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000
#define FLOODLIGHT_DURATION_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s - %s\n", timestamp, event_type, message) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

static int set_floodlight(int state) {
    if (gpioWrite(FLOODLIGHT_PIN, state) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", FLOODLIGHT_PIN, state);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(FLOODLIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FLOODLIGHT_PIN);
        gpioTerminate();
        return -1;
    }

    if (set_floodlight(0) != 0) {
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    set_floodlight(0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    int last_pir_state = gpioRead(PIR_PIN);
    if (last_pir_state < 0) {
        fprintf(stderr, "gpioRead(%d) failed\n", PIR_PIN);
        cleanup();
        return 1;
    }

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", PIR_PIN);
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected!\n");

            if (log_event("Motion", "Motion detected") != 0) {
                fprintf(stderr, "Failed to log motion event.\n");
            }

            if (set_floodlight(1) != 0) {
                break;
            }

            time_t start_time = time(NULL);
            if (start_time == (time_t)-1) {
                perror("time()");
                break;
            }

            while (g_running) {
                int current_state = gpioRead(FLOODLIGHT_PIN);
                if (current_state < 0) {
                    fprintf(stderr, "gpioRead(%d) failed\n", FLOODLIGHT_PIN);
                    break;
                }
                if (current_state == 0) {
                    break;
                }
                gpioDelay(POLL_INTERVAL_US);
            }

            if (set_floodlight(0) != 0) {
                break;
            }

            time_t end_time = time(NULL);
            if (end_time == (time_t)-1) {
                perror("time()");
            } else {
                double duration = difftime(end_time, start_time);
                if (log_event("Floodlight", duration > 0.0 ? "Floodlight deactivated" : "Floodlight deactivated (error)") != 0) {
                    fprintf(stderr, "Failed to log floodlight deactivation.\n");
                }
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("Shutting down...\n");
    cleanup();
    printf("Smart Security Light System stopped.\n");
    return 0;
}

