#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n", reg, val, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(0x80, 0x63) < 0) return -1; /* Soft reset */
    gpioDelay(10000); /* 10 ms */

    /* Baseline filtering — rising */
    if (mpr121_write(0x2B, 0x01) < 0) return -1;
    if (mpr121_write(0x2C, 0x01) < 0) return -1;
    if (mpr121_write(0x2D, 0x00) < 0) return -1;
    if (mpr121_write(0x2E, 0x00) < 0) return -1;

    /* Baseline filtering — falling */
    if (mpr121_write(0x2F, 0x01) < 0) return -1;
    if (mpr121_write(0x30, 0x01) < 0) return -1;
    if (mpr121_write(0x31, 0x00) < 0) return -1;
    if (mpr121_write(0x32, 0x00) < 0) return -1;

    /* Debounce: 3 samples for both rising and falling */
    if (mpr121_write(0x5B, 0x33) < 0) return -1;

    /* FFI=6 samples, SFI=4 samples, CDT=0.5us */
    if (mpr121_write(0x2C, 0x10) < 0) return -1;

    /* Auto-config registers */
    if (mpr121_write(0x7B, 0x0B) < 0) return -1;
    if (mpr121_write(0x7D, 0x04) < 0) return -1;
    if (mpr121_write(0x7C, 0x00) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (mpr121_write(0x5E, 0x0C) < 0) return -1;

    return 0;
}

static int read_touch_status(uint16_t *status) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed: %d\n", rc);
        return -1;
    }
    *status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %d\n", MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed — sensor may be absent or bus error\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        fprintf(stderr, "Failed to initialize relay GPIO %d to OFF\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPR121 relay controller running. Touch electrode 0 to toggle relay.\n");

    int relay_state = 0;
    uint32_t last_touch_tick = 0;

    while (running) {
        uint16_t touch_status = 0;
        if (read_touch_status(&touch_status) < 0) {
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        uint32_t now = gpioTick();
        int electrode0_touched = (touch_status & 0x0001) != 0;

        if (electrode0_touched) {
            if (now - last_touch_tick > DEBOUNCE_MS * 1000) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                    fprintf(stderr, "Failed to write relay GPIO %d\n", RELAY_GPIO);
                } else {
                    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                }
                last_touch_tick = now;
            }
        }

        gpioDelay(50000); /* 50 ms poll interval */
    }

    /* Clean shutdown */
    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

