#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pthread.h>
#include <gpiod.h>
#include <stdarg.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PWM_PERIOD_NS 20000000  /* 20 ms = 50 Hz */
#define SERVO_MIN_NS 1000000     /* 1 ms */
#define SERVO_MAX_NS 2000000     /* 2 ms */
#define SERVO_RANGE 180

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_file = NULL;
static pthread_t pwm_thread;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;

static void log_message(const char *level, const char *fmt, ...) {
    va_list ap;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }
    if (log_file) {
        fprintf(log_file, "%s [%s] ", ts, level);
        va_start(ap, fmt);
        vfprintf(log_file, fmt, ap);
        va_end(ap);
        fprintf(log_file, "\n");
        fflush(log_file);
    }
    if (level[0] == 'E') {
        syslog(LOG_ERR, "%s", fmt);
    } else {
        syslog(LOG_INFO, "%s", fmt);
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void *servo_pwm_thread(void *arg) {
    (void)arg;
    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC, &next);
    while (running) {
        int val = (next.tv_nsec / 1000000) % 2;
        if (gpiod_line_set_value(servo_line, val) < 0) {
            log_message("ERROR", "Failed to set servo line value: %s", strerror(errno));
        }
        next.tv_nsec += PWM_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_sec += 1;
            next.tv_nsec -= 1000000000L;
        }
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long diff_ns = (next.tv_sec - now.tv_sec) * 1000000000L +
                       (next.tv_nsec - now.tv_nsec);
        if (diff_ns > 0) {
            struct timespec ts = { .tv_sec = diff_ns / 1000000000L,
                                   .tv_nsec = diff_ns % 1000000000L };
            nanosleep(&ts, NULL);
        }
    }
    return NULL;
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        log_message("ERROR", "Failed to open gpiochip4: %s", strerror(errno));
        return -1;
    }
    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_message("ERROR", "Failed to get servo line %d: %s", SERVO_PIN, strerror(errno));
        return -1;
    }
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message("ERROR", "Failed to get PIR line %d: %s", PIR_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_message("ERROR", "Failed to request servo line as output: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_message("ERROR", "Failed to request PIR line as input: %s", strerror(errno));
        return -1;
    }
    if (pthread_create(&pwm_thread, NULL, servo_pwm_thread, NULL) != 0) {
        log_message("ERROR", "Failed to create PWM thread: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int set_servo_angle(int angle) {
    if (angle < 0 || angle > SERVO_RANGE) {
        log_message("ERROR", "Invalid servo angle: %d", angle);
        return -1;
    }
    long pulse_ns = SERVO_MIN_NS +
                    (long)angle * (SERVO_MAX_NS - SERVO_MIN_NS) / SERVO_RANGE;
    /* Set the line to the desired value; PWM thread toggles it at 50 Hz */
    if (gpiod_line_set_value(servo_line, (pulse_ns >= SERVO_MIN_NS + (SERVO_MAX_NS - SERVO_MIN_NS) / 2) ? 1 : 0) < 0) {
        log_message("ERROR", "Failed to set servo line value: %s", strerror(errno));
        return -1;
    }
    log_message("INFO", "Servo angle set to: %d", angle);
    return 0;
}

static int read_pir(void) {
    int val = gpiod_line_get_value(pir_line);
    if (val < 0) {
        log_message("ERROR", "Failed to read PIR line: %s", strerror(errno));
        return -1;
    }
    return val;
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n < 0) {
        log_message("ERROR", "recv failed: %s", strerror(errno));
        return;
    }
    if (n == 0) {
        log_message("INFO", "Client disconnected");
        return;
    }
    buffer[n] = '\0';
    char *cmd = strtok(buffer, " \r\n");
    if (!cmd) {
        log_message("ERROR", "Empty command received");
        return;
    }
    if (strcmp(cmd, "SERVO") == 0) {
        char *angle_str = strtok(NULL, " \r\n");
        if (!angle_str) {
            log_message("ERROR", "SERVO command requires an angle");
            return;
        }
        int angle = atoi(angle_str);
        if (set_servo_angle(angle) < 0) {
            send(client_fd, "ERROR: Invalid angle\n", 20, 0);
        } else {
            send(client_fd, "OK\n", 3, 0);
        }
    } else if (strcmp(cmd, "PIR") == 0) {
        int pir = read_pir();
        if (pir < 0) {
            send(client_fd, "ERROR: PIR read failed\n", 23, 0);
        } else {
            char resp[32];
            snprintf(resp, sizeof(resp), "PIR:%d\n", pir);
            send(client_fd, resp, strlen(resp), 0);
        }
    } else {
        log_message("ERROR", "Unknown command: %s", cmd);
        send(client_fd, "ERROR: Unknown command\n", 22, 0);
    }
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (servo_line) {
        gpiod_line_set_value(servo_line, 0);
        gpiod_line_release(servo_line);
        servo_line = NULL;
    }
    if (pir_line) {
        gpiod_line_release(pir_line);
        pir_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (pwm_thread) {
        pthread_join(pwm_thread, NULL);
    }
    closelog();
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);
    log_message("INFO", "Starting security system");

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message("ERROR", "Failed to open log file: %s", strerror(errno));
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_message("ERROR", "Failed to set signal handlers: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (init_gpio() < 0) {
        log_message("ERROR", "GPIO initialization failed");
        cleanup();
        return 1;
    }

