#include <errno.h>

#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS 120
#define SAMPLE_INTERVAL_S 2

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_lux(float *lux_out) {
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C handle invalid\n");
        return -1;
    }

    if (i2cWriteByte(i2c_handle, BH1750_CMD_OT_HRES) < 0) {
        fprintf(stderr, "Error writing BH1750 command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(BH1750_CONV_MS * 1000);

    char buf[2];
    int bytes = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "Error reading BH1750 data (got %d bytes): %s\n",
                bytes, bytes < 0 ? strerror(errno) : "short read");
        return -1;
    }

    unsigned int raw = ((unsigned int)(unsigned char)buf[0] << 8) | (unsigned char)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_grow_light(float lux) {
    int state = (lux < LUX_THRESHOLD) ? 1 : 0;
    if (gpioWrite(GROW_LIGHT_GPIO, state) < 0) {
        fprintf(stderr, "Error writing GPIO %d: %s\n", GROW_LIGHT_GPIO, strerror(errno));
    }
}

static void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file) {
        fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GROW_LIGHT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GROW_LIGHT_GPIO, 0);

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Grow light controller started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float lux;
        if (read_lux(&lux) == 0) {
            control_grow_light(lux);
            log_data(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

