#include <gpiod.h>

#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 100.0
#define DEFAULT_DURATION 500
#define HX711_TIMEOUT_US 1000000
#define HX711_SETTLE_US 1
#define HX711_READ_RETRIES 3
#define NUM_READINGS 5
#define TARE_READINGS 10

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_msg(int priority, const char *msg) {
    syslog(priority, "%s", msg);
}

static int read_hx711(struct gpiod_line *dout, struct gpiod_line *sck, long *out) {
    int i;
    unsigned long data = 0;
    int ready;

    for (i = 0; i < HX711_READ_RETRIES; i++) {
        ready = gpiod_line_get_value(dout);
        if (ready < 0) {
            log_msg(LOG_ERR, "HX711: failed to read DOUT");
            usleep(10000);
            continue;
        }
        if (ready == 0) break;
        usleep(10000);
    }
    if (ready != 0) {
        log_msg(LOG_ERR, "HX711: DOUT never went LOW (sensor absent or wiring fault)");
        return -1;
    }

    for (i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            log_msg(LOG_ERR, "HX711: SCK set HIGH failed");
            return -1;
        }
        usleep(1);
        data <<= 1;
        if (gpiod_line_set_value(sck, 0) < 0) {
            log_msg(LOG_ERR, "HX711: SCK set LOW failed");
            return -1;
        }
        usleep(1);
        if (gpiod_line_get_value(dout) < 0) {
            log_msg(LOG_ERR, "HX711: DOUT read failed");
            return -1;
        }
        if (gpiod_line_get_value(dout)) data |= 1;
    }

    if (gpiod_line_set_value(sck, 1) < 0) {
        log_msg(LOG_ERR, "HX711: 25th SCK set HIGH failed");
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        log_msg(LOG_ERR, "HX711: 25th SCK set LOW failed");
        return -1;
    }
    usleep(1);

    if (data & 0x800000) data |= 0xFF000000UL;
    *out = (long)data;
    return 0;
}

static long average_reading(struct gpiod_line *dout, struct gpiod_line *sck, int n) {
    long sum = 0, val;
    int ok = 0;
    for (int i = 0; i < n; i++) {
        if (read_hx711(dout, sck, &val) == 0) { sum += val; ok++; }
        else { log_msg(LOG_WARNING, "HX711 read failed, skipping"); }
    }
    return (ok > 0) ? (sum / ok) : 0;
