#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID      "relay_controller_1"
#define MQTT_TOPIC          "home/lights/control"
#define GPIO_PIN            17
#define KEEPALIVE_SEC       60
#define RECONNECT_DELAY_SEC 5

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static void log_mqtt_event(const char *level, const char *msg)
{
    syslog(LOG_INFO, "%s: %s", level, msg);
}

static void log_mqtt_error(const char *level, const char *msg)
{
    syslog(LOG_ERR, "%s: %s", level, msg);
}

static int set_relay(int state)
{
    if (gpioWrite(GPIO_PIN, state) != 0) {
        log_mqtt_error("GPIO_WRITE", "Failed to write GPIO17");
        return -1;
    }
    return 0;
}

static void message_callback(struct mosquitto *mosq, void *userdata,
                              const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_mqtt_error("MESSAGE", "Empty payload received");
        return;
    }

    char payload[32];
    int len = message->payloadlen < (int)sizeof(payload) - 1
              ? message->payloadlen : (int)sizeof(payload) - 1;
    memcpy(payload, message->payload, len);
    payload[len] = '\0';

    if (strcmp(payload, "ON") == 0) {
        if (set_relay(1) == 0) {
            log_mqtt_event("MESSAGE", "Relay ON");
        }
    } else if (strcmp(payload, "OFF") == 0) {
        if (set_relay(0) == 0) {
            log_mqtt_event("MESSAGE", "Relay OFF");
        }
    } else {
        char err[128];
        snprintf(err, sizeof(err),
                 "Invalid payload: %s (len=%d)", payload, len);
        log_mqtt_error("MESSAGE", err);
    }
}

static void connect_callback(struct mosquitto *mosq, void *userdata,
                              int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_mqtt_event("CONNECT", "Connected to MQTT broker");
        int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            char err[128];
            snprintf(err, sizeof(err),
                     "Subscribe failed: %s", mosquitto_strerror(rc));
            log_mqtt_error("CONNECT", err);
        } else {
            log_mqtt_event("SUBSCRIBE", "Subscribed to home/lights/control");
        }
    } else {
        char err[128];
        snprintf(err, sizeof(err),
                 "Connect failed: %s", mosquitto_strerror(result));
        log_mqtt_error("CONNECT", err);
    }
}

static void disconnect_callback(struct mosquitto *mosq, void *userdata,
                                 int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS) {
        log_mqtt_event("DISCONNECT", "Clean disconnect from broker");
    } else {
        log_mqtt_error("DISCONNECT", "Broker disconnected unexpectedly");
    }
}

static int connect_mqtt(void)
{
    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS,
                               MQTT_BROKER_PORT, KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        char err[128];
        snprintf(err, sizeof(err),
                 "mosquitto_connect failed: %s",
                 mosquitto_strerror(rc));
        log_mqtt_error("CONNECT", err);
        return -1;
    }
    return 0;
}

static void cleanup_mqtt(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 as output");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (set_relay(0) != 0) {
        syslog(LOG_ERR, "Failed to initialise relay to OFF");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(g_mosq, connect_callback);
    mosquitto_disconnect_callback_set(g_mosq, disconnect_callback);
    mosquitto_message_callback_set(g_mosq, message_callback);

    if (connect_mqtt() != 0) {
        syslog(LOG_ERR, "Initial MQTT connection failed; entering retry loop");
    }

    while (g_running) {
        int rc = mosquitto_loop(g_mosq, 1000, 1);
        if (rc == MOSQ_ERR_SUCCESS) {
            continue;
        }
        char err[128];
        snprintf(err, sizeof(err),
                 "mosquitto_loop error: %s", mosquitto_strerror(rc));
        log_mqtt_error("LOOP", err);
        sleep(RECONNECT_DELAY_SEC);
        if (g_mosq) {
            cleanup_mqtt();
            if (connect_mqtt() != 0) {
                syslog(LOG_ERR, "Reconnect failed; retrying in %d s",
                       RECONNECT_DELAY_SEC);
            }
        }
    }

    if (g_mosq) {
        cleanup_mqtt();
    }
    set_relay(0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

