#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define NUM_SERVOS 5
#define PWM_FREQ 50
#define PWM_RANGE 20000
#define HOLD_TIME_MS 3000

static const int servo_pins[NUM_SERVOS] = {7, 8, 9, 10, 11};
static const int pulse_widths[NUM_SERVOS] = {1000, 1500, 2000, 500, 2500};

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SERVOS; i++) {
        gpioSetMode(servo_pins[i], PI_OUTPUT);
        gpioSetPWMfrequency(servo_pins[i], PWM_FREQ);
        gpioSetPWMrange(servo_pins[i], PWM_RANGE);
        gpioPWM(servo_pins[i], pulse_widths[i]);
    }

    printf("Servos moving to positions: ");
    for (int i = 0; i < NUM_SERVOS; i++) {
        printf("%d ", pulse_widths[i]);
    }
    printf("us\n");

    gpioDelay(HOLD_TIME_MS * 1000);

    for (int i = 0; i < NUM_SERVOS; i++) {
        gpioPWM(servo_pins[i], 0);
    }

    gpioTerminate();
    printf("Servos stopped. Exiting.\n");
    return EXIT_SUCCESS;
}

