#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <stdatomic.h>
#include <math.h>

/* ---- Pin assignments ---- */
#define MOTOR_A_PWM_PIN  17
#define MOTOR_A_DIR_PIN  18
#define MOTOR_B_PWM_PIN  22
#define MOTOR_B_DIR_PIN  23

#define ENCODER_A_A_PIN  4
#define ENCODER_A_B_PIN  5
#define ENCODER_B_A_PIN  6
#define ENCODER_B_B_PIN  12

/* ---- Constants ---- */
#define ENCODER_TICKS_PER_REV 64.0
#define PWM_FREQUENCY         10000   /* Hz */
#define PWM_RANGE             255
#define PI                    3.14159265358979323846
#define TARGET_RPM            50.0
#define LOOP_PERIOD_US        100000  /* 100 ms */
#define STALL_TIMEOUT_S       2.0
#define Kp                    0.5
#define Ki                    0.05

/* ---- Shared state ---- */
static volatile sig_atomic_t g_running = 1;
static atomic_int g_enc_a_count = 0;
static atomic_int g_enc_b_count = 0;

/* ---- PI controller ---- */
typedef struct {
    double Kp, Ki;
    double integral;
    double last_error;
} PIController;

static PIController g_motor_a_pi = { Kp, Ki, 0.0, 0.0 };
static PIController g_motor_b_pi = { Kp, Ki, 0.0, 0.0 };

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
static double calculate_rpm(int encoder_count, double dt);
static int  pi_control(double target, double actual, PIController *c, double dt);
static void set_motor_pwm(int pwm_pin, int dir_pin, int duty);
static void stop_motors(void);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Encoder A ISR ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        int b = gpioRead(ENCODER_A_B_PIN);
        if (b == 1) {
            atomic_fetch_add(&g_enc_a_count, 1);
        } else {
            atomic_fetch_add(&g_enc_a_count, -1);
        }
    }
}

/* ---- Encoder B ISR ---- */
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        int b = gpioRead(ENCODER_B_B_PIN);
        if (b == 1) {
            atomic_fetch_add(&g_enc_b_count, 1);
        } else {
            atomic_fetch_add(&g_enc_b_count, -1);
        }
    }
}

/* ---- Calculate RPM from encoder ticks ---- */
static double calculate_rpm(int encoder_count, double dt) {
    if (dt <= 0.0) return 0.0;
    double ticks_per_sec = (double)encoder_count / dt;
    return (ticks_per_sec * 60.0) / ENCODER_TICKS_PER_REV;
}

/* ---- PI controller with anti-windup ---- */
static int pi_control(double target, double actual, PIController *c, double dt) {
    if (dt <= 0.0) return 0;

    double error = target - actual;
    c->integral += error * dt;
    if (c->integral > 127.0)  c->integral = 127.0;
    if (c->integral < -127.0) c->integral = -127.0;

    double output = c->Kp * error + c->Ki * c->integral;
    if (output > 255.0)  output = 255.0;
    if (output < -255.0) output = -255.0;

    double delta = output - c->last_error;
    c->last_error = output;
    return (int)output;
}

/* ---- Set motor PWM with direction ---- */
static void set_motor_pwm(int pwm_pin, int dir_pin, int duty) {
    if (duty > 0) {
        gpioWrite(dir_pin, 1);
        gpioPWM(pwm_pin, duty);
    } else if (duty < 0) {
        gpioWrite(dir_pin, 0);
        gpioPWM(pwm_pin, -duty);
    } else {
        gpioWrite(dir_pin, 0);
        gpioPWM(pwm_pin, 0);
    }
}

/* ---- Stop both motors ---- */
static void stop_motors(void) {
    gpioPWM(MOTOR_A_PWM_PIN, 0);
    gpioPWM(MOTOR_B_PWM_PIN, 0);
}

/* ---- Cleanup: stop motors, terminate pigpio ---- */
static void cleanup(void) {
    stop_motors();
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN,  PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN,  PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENCODER_A_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_B_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable pull-ups on encoder A phase pins (active-high quadrature) */
    gpioSetPullUpDown(ENCODER_A_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_A_B_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B_B_PIN, PI_PUD_UP);

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR for encoder A */
    if (gpioSetISRFuncEx(ENCODER_A_A_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder A.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR for encoder B */
    if (gpioSetISRFuncEx(ENCODER_B_A_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR for encoder B.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize encoder counts to zero */
    atomic_store(&g_enc_a_count, 0);
    atomic_store(&g_enc_b_count, 0);

    /* Initialize stall timers */
    double last_a_tick = 0.0;
    double last_b_tick = 0.0;
    double last_loop = 0.0;

    printf("Closed-loop speed control started. Target RPM: %.2f\n", TARGET_RPM);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        double now = time_time();

        /* Read encoder counts atomically */
        int enc_a = atomic_load(&g_enc_a_count);
        int enc_b = atomic_load(&g_enc_b_count);

        /* Calculate time deltas */
        double dt = now - last_loop;
        if (dt <= 0.0) dt = 0.001;

        /* Calculate RPM */
        double rpm_a = calculate_rpm(enc_a, dt);
        double rpm_b = calculate_rpm(enc_b, dt);

        /* PI control */
        int duty_a = pi_control(TARGET_RPM, rpm_a, &g_motor_a_pi, dt);
        int duty_b = pi_control(TARGET_RPM, rpm_b, &g_motor_b_pi, dt);

        /* Apply PWM */
        set_motor_pwm(MOTOR_A_PWM_PIN, MOTOR_A_DIR_PIN, duty_a);
        set_motor_pwm(MOTOR_B_PWM_PIN, MOTOR_B_DIR_PIN, duty_b);

        /* Stall detection */
        if (dt > 0.0) {
            double stall_a = now - last_a_tick;
            double stall_b = now - last_b_tick;
            if (stall_a > STALL_TIMEOUT_S) {
                fprintf(stderr, "Warning: Motor A encoder stall (no ticks for %.2f s)\n", stall_a);
                last_a_tick = now;
            }
            if (stall_b > STALL_TIMEOUT_S) {
                fprintf(stderr, "Warning: Motor B encoder stall (no ticks for %.2f s)\n", stall_b);
                last_b_tick = now;
            }
        }

        /* Print status */
        printf("Motor A: RPM=%.2f  PWM=%d  |  Motor B: RPM=%.2f  PWM=%d\n",
               rpm_a, duty_a, rpm_b, duty_b);

        /* Reset encoder counts for next iteration */
        atomic_store(&g_enc_a_count, 0);
        atomic_store(&g_enc_b_count, 0);

        /* Update stall timers */
        last_a_tick = now;
        last_b_tick = now;
        last_loop = now;

        /* Sleep for loop period */
        gpioDelay(LOOP_PERIOD_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

