#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms */
#define MAIN_LOOP_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);
    printf("[%s] Relay state: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void)
{
    int relay_state = 0;
    int last_touch_state = 0;
    int ret;

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    ret = gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input (code %d).\n",
                TOUCH_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output (code %d).\n",
                RELAY_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in the OFF state */
    ret = gpioWrite(RELAY_PIN, 0);
    if (ret != 0) {
        fprintf(stderr, "Error: failed to initialize relay state (code %d).\n", ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_state = 0;
    log_relay_state(relay_state);

    /* Main loop */
    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read GPIO %d (code %d).\n",
                    TOUCH_SENSOR_PIN, touch_state);
            break;
        }

        /* Detect rising edge: touch sensor goes HIGH */
        if (touch_state == 1 && last_touch_state == 0) {
            /* Debounce: wait and re-read */
            gpioDelay(DEBOUNCE_DELAY_US);
            int debounced_state = gpioRead(TOUCH_SENSOR_PIN);
            if (debounced_state < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d during debounce (code %d).\n",
                        TOUCH_SENSOR_PIN, debounced_state);
                break;
            }
            if (debounced_state == 1) {
                /* Valid touch confirmed; toggle relay */
                relay_state = !relay_state;
                ret = gpioWrite(RELAY_PIN, relay_state);
                if (ret != 0) {
                    fprintf(stderr, "Error: failed to write GPIO %d (code %d).\n",
                            RELAY_PIN, ret);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        /* Detect falling edge: touch sensor goes LOW */
        if (touch_state == 0 && last_touch_state == 1) {
            /* Wait for sensor to return LOW to avoid repeated toggles */
            gpioDelay(DEBOUNCE_DELAY_US);
            int post_release = gpioRead(TOUCH_SENSOR_PIN);
            if (post_release < 0) {
                fprintf(stderr, "Error: failed to read GPIO %d after release (code %d).\n",
                        TOUCH_SENSOR_PIN, post_release);
                break;
            }
            if (post_release == 0) {
                /* Sensor still released; reset last state */
                last_touch_state = 0;
            }
        }

        last_touch_state = touch_state;
        gpioDelay(MAIN_LOOP_DELAY_US);
    }

    /* Graceful shutdown: turn relay OFF and release pigpio */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

