#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define FLOW_CALIBRATION 450.0
#define HIGH_FLOW_THRESHOLD 5.0
#define LOW_FLOW_THRESHOLD 4.5
#define LOG_FILE "water_flow.log"
#define DEBOUNCE_TIMEOUT_MS 1000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int pulse_count = 0;
static volatile uint32_t last_pulse_tick = 0;

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)userdata;
    uint32_t last = last_pulse_tick;
    uint32_t diff = tick - last;
    if (diff > DEBOUNCE_TIMEOUT_MS * 1000) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        last_pulse_tick = tick;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

static double calculate_lpm(int pulses) {
    return ((double)pulses / FLOW_CALIBRATION) * 60.0;
}

static int set_solenoid(int state) {
    int rc = gpioWrite(SOLENOID_GPIO, state);
    if (rc < 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Error writing solenoid GPIO %d: %d", SOLENOID_GPIO, rc);
        log_message(msg);
        return -1;
    }
    char msg[128];
    snprintf(msg, sizeof(msg), "Solenoid set to %s", state ? "OPEN" : "CLOSED");
    log_message(msg);
    return 0;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(SOLENOID_GPIO, 1) < 0) {
        fprintf(stderr, "Failed to initialize solenoid to OPEN state\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioWrite(SOLENOID_GPIO, 1);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        fclose(log_file);
        gpioWrite(SOLENOID_GPIO, 1);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("Water flow monitoring started");

    int solenoid_state = 1;

    while (running) {
        sleep(1);

        pthread_mutex_lock(&pulse_mutex);
        int pulses = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = calculate_lpm(pulses);
        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f L/min", lpm);
        log_message(msg);

        if (lpm > HIGH_FLOW_THRESHOLD && solenoid_state == 1) {
            if (set_solenoid(0) == 0) solenoid_state = 0;
        } else if (lpm < LOW_FLOW_THRESHOLD && solenoid_state == 0) {
            if (set_solenoid(1) == 0) solenoid_state = 1;
        }
    }

    log_message("Shutting down gracefully");
    set_solenoid(1);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    return 0;
}

