#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

#define DEFAULT_CALIBRATION_FACTOR 1000.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_PULSE_WIDTH_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define HX711_TIMEOUT_ATTEMPTS 1000
#define HX711_SETTLE_DELAY_US 1000000
#define HX711_READ_DELAY_US 1000000
#define SERVO_OPEN_DELAY_US 1000000
#define SERVO_CLOSE_DELAY_US 1000000
#define LOG_FILE "dispensing_log.json"
#define CONFIG_FILE "config.ini"

static volatile sig_atomic_t running = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[64] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int server_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n", filename, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=\n");
        char *value = strtok(NULL, "=\n");
        if (!key || !value) continue;
        if (strcmp(key, "calibration_factor") == 0) calibration_factor = atof(value);
        else if (strcmp(key, "server_ip") == 0) {
            strncpy(server_ip, value, sizeof(server_ip) - 1);
            server_ip[sizeof(server_ip) - 1] = '\0';
        } else if (strcmp(key, "server_port") == 0) server_port = atoi(value);
    }
    fclose(fp);
    printf("Config loaded: calibration_factor=%.2f, server_ip=%s, server_port=%d\n", calibration_factor, server_ip, server_port);
    return 0;
}

static int read_hx711(void) {
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);
    int32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) data |= 1;
        if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);
    }
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) return -1;
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) return -1;
    gpioDelay(1);
    if (data & 0x800000) data |= 0xFF000000;
    return data;
}

static double get_weight(void) {
    int raw = read_hx711();
    if (raw == -1) {
        fprintf(stderr, "Error: HX711 read failed.\n");
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width %d (must be %d-%d).\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse width %d.\n", pulse_width);
        return -1;
    }
    return 0;
}

static int dispense(double target_weight) {
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((target_weight / 100.0) * SERVO_PULSE_WIDTH_RANGE);
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) pulse_width = SERVO_MIN_PULSE_WIDTH;
    if (pulse_width > SERVO_MAX_PULSE_WIDTH) pulse_width = SERVO_MAX_PULSE_WIDTH;
    if (set_servo_pulse_width(pulse_width) < 0) return -1;
    gpioDelay(SERVO_OPEN_DELAY_US);
    if (set_servo_pulse_width(SERVO_MIN_PULSE_WIDTH) < 0) return -1;
    gpioDelay(SERVO_CLOSE_DELAY_US);
    return 0;
}

static int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Could not open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "{\"date\": \"%04d-%02d-%02d\", \"time\": \"%02d:%02d:%02d\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, target_weight, actual_weight, error_message);
    fclose(fp);
    return 0;
}

static int send_data_to_client(int client_socket, double actual_weight) {
    char buffer[64];
    int len = snprintf(buffer, sizeof(buffer), "%.2f", actual_weight);
    if (len < 0 || len >= (int)sizeof(buffer)) {
        fprintf(stderr, "Error: snprintf failed or buffer too small.\n");
        return -1;
    }
    if (send(client_socket, buffer, (size_t)len, 0) < 0) {
        fprintf(stderr, "Error: send failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int receive_target_weight(int client_socket, double *target_weight) {
    char buffer[64];
    ssize_t bytes = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes < 0) {
        fprintf(stderr, "Error: recv failed: %s\n", strerror(errno));
        return -1;
    }
    if (bytes == 0) {
        fprintf(stderr, "Error: Client disconnected.\n");
        return -1;
    }
    buffer[bytes] = '\0';
    *target_weight = atof(buffer);
    return 0;
}

static void cleanup(void) {
    if (server_socket >= 0) {
        close(server_socket);
        server_socket = -1;
    }
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, 0);
    read_config(CONFIG_FILE);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        fprintf(stderr, "Error: Could not create socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    int opt = 1;
    setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(server_ip);
    server_addr.sin_port = htons(server_port);
    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Could not bind socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (listen(server_socket, 3) < 0) {
        fprintf(stderr, "Error: Could not listen on socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    printf("Server listening on %s:%d\n", server_ip, server_port);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error: accept failed: %s\n", strerror(errno));
            continue;
        }
        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        double target_weight = 0.0;
        if (receive_target_weight(client_socket, &target_weight) < 0) {
            log_dispensing_event(target_weight, 0.0, "Client disconnected");
            close(client_socket);
            continue;
        }
        printf("Target weight: %.2f g\n", target_weight);
        if (dispense(target_weight) < 0) {
            log_dispensing_event(target_weight, 0.0, "Servo control failed");
            close(client_socket);
            continue;
        }
        gpioDelay(HX711_SETTLE_DELAY_US);
        double actual_weight = get_weight();
        if (actual_weight < 0) {
            log_dispensing_event(target_weight, 0.0, "HX711 read failed");
            close(client_socket);
            continue;
        }
        printf("Actual weight: %.2f g\n", actual_weight);
        if (send_data_to_client(client_socket, actual_weight) < 0) {
            log_dispensing_event(target_weight, actual_weight, "Failed to send data to client");
        } else {
            log_dispensing_event(target_weight, actual_weight, "");
        }
        close(client_socket);
    }
    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

