#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int relay_state = 0;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s Relay: %s\n", ts, state ? "ON" : "OFF");
    fflush(stdout);
}

static int set_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: gpioWrite failed for relay pin %d\n", RELAY_PIN);
        return -1;
    }
    relay_state = state;
    log_relay_state(state);
    return 0;
}

static int toggle_relay(void) {
    int new_state = !relay_state;
    return set_relay(new_state);
}

static int parse_debounce_arg(int argc, char *argv[]) {
    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0' || val <= 0) {
            fprintf(stderr, "Invalid debounce value: '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_DEBOUNCE_MS);
            return DEFAULT_DEBOUNCE_MS;
        }
        return (int)val;
    }
    return DEFAULT_DEBOUNCE_MS;
}

int main(int argc, char *argv[]) {
    debounce_ms = parse_debounce_arg(argc, argv);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for touch pin %d\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
