#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define SERVO_MIN_US   500
#define SERVO_MAX_US   2500
#define SERVO_RANGE    180
#define SERVO_START_US 900
#define STEP_DEG       10
#define STEP_US        ((SERVO_MAX_US - SERVO_MIN_US) / SERVO_RANGE)

static volatile sig_atomic_t g_running = 1;
static struct termios g_orig_termios;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static int setup_terminal(void) {
    if (tcgetattr(STDIN_FILENO, &g_orig_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }
    struct termios raw = g_orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    raw.c_cc[VMIN]  = 1;
    raw.c_cc[VTIME] = 0;
    if (tcsetattr(STDIN_FILENO, TCSANOW, &raw) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static void restore_terminal(void) {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &g_orig_termios) != 0) {
        perror("tcsetattr (restore)");
    }
}

static int angle_to_pulse_us(int angle) {
    if (angle < 0) angle = 0;
    if (angle > SERVO_RANGE) angle = SERVO_RANGE;
    return SERVO_MIN_US + (angle * STEP_US);
}

static int set_servo_angle(int angle) {
    int pulse = angle_to_pulse_us(angle);
    if (pulse < SERVO_MIN_US || pulse > SERVO_MAX_US) {
        fprintf(stderr, "Warning: pulse %d out of range [%d, %d]\n",
                pulse, SERVO_MIN_US, SERVO_MAX_US);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse) != 0) {
        fprintf(stderr, "gpioServo failed for pin %d, pulse %d\n", SERVO_PIN, pulse);
        return -1;
    }
    return 0;
}

int main(void) {
    int angle = 90;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (setup_signal_handler() != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (setup_terminal() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SERVO_PIN);
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (set_servo_angle(angle) != 0) {
        restore_terminal();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Servo control ready. '+' = +10°, '-' = -10°, 'q' = quit.\n");
    fflush(stdout);

    while (g_running) {
        char ch = getchar();
        if (ch == EOF) {
            break;
        }
        switch (ch) {
            case '+':
                angle += STEP_DEG;
                if (angle > SERVO_RANGE) angle = SERVO_RANGE;
                break;
            case '-':
                angle -= STEP_DEG;
                if (angle < 0) angle = 0;
                break;
            case 'q':
            case 'Q':
                g_running = 0;
                break;
            default:
                continue;
        }
        if (set_servo_angle(angle) == 0) {
            printf("Angle: %3d°  (pulse: %4d µs)\n", angle,
                   angle_to_pulse_us(angle));
            fflush(stdout);
        }
    }

    gpioServo(SERVO_PIN, 0);
    restore_terminal();
    gpioTerminate();
    printf("\nServo stopped. Goodbye.\n");
    return EXIT_SUCCESS;
}

