#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define DEBOUNCE_US 2000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static int log_rpm(FILE *fp, double rpm) {
    char ts[32];
    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Failed to generate timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s,%.2f\n", ts, rpm) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* A3144 open-collector output requires pull-up; request it via bias flag */
    if (gpiod_line_request_input_flags(line, "motor_rpm_monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring motor RPM on GPIO %d (chip %s). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET, GPIO_CHIP_NAME);

    unsigned int pulse_count = 0;
    struct timespec last_event_ts = {0, 0};
    int first_event = 1;

    while (program_running) {
        struct timespec ts_wait = {0, 100000000}; /* 100 ms poll timeout */
        int ev_ret = gpiod_line_event_wait(line, &ts_wait);

        if (ev_ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error waiting for GPIO event: %s\n", strerror(errno));
            goto cleanup;
        }

        if (ev_ret == 0) {
            /* Timeout, no event — loop back and check program_running */
            continue;
        }

        /* Event detected — read it to clear the event queue */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) != 0) {
            fprintf(stderr, "Error reading GPIO event: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        struct timespec now = event.ts;

        /* Debounce: ignore events within DEBOUNCE_US of the last accepted event */
        long long elapsed_us = (now.tv_sec - last_event_ts.tv_sec) * 1000000LL +
                               (now.tv_nsec - last_event_ts.tv_nsec) / 1000LL;

        if (first_event || elapsed_us > DEBOUNCE_US) {
            pulse_count++;
            last_event_ts = now;
            first_event = 0;
        }
    }

    /* Compute RPM over the sample interval */
    double rpm = ((double)pulse_count / (double)SAMPLE_INTERVAL_S) * 60.0;

    if (log_rpm(log_fp, rpm) != 0) {
        fprintf(stderr, "Failed to log RPM value\n");
    } else {
        printf("RPM: %.2f\n", rpm);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    return ret;
}

