#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define POLL_DELAY_US    50000   /* 50 ms */
#define FAILSAFE_TIMEOUT 10      /* seconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "Error: gpioRead(%u) returned PI_BAD_GPIO\n", pin);
        return -1;
    }
    return v;
}

int main(void)
{
    int relay_state = 0;
    int touch_state = 0;
    int failsafe_active = 0;
    uint32_t failsafe_start = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_write(RELAY_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install signal handlers\n");
    }

    printf("Touch-activated relay control started. Touch GPIO4 to toggle relay on GPIO17.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int v = safe_read(TOUCH_SENSOR_PIN);
        if (v < 0) {
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (v == 1) {
            if (!failsafe_active) {
                touch_state = 1;
                if (!relay_state) {
                    if (safe_write(RELAY_PIN, 1) != 0) {
                        gpioTerminate();
                        return EXIT_FAILURE;
                    }
                    relay_state = 1;
                    printf("Relay ON\n");
                } else {
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        gpioTerminate();
                        return EXIT_FAILURE;
                    }
                    relay_state = 0;
                    printf("Relay OFF\n");
                }
            }

            if (!failsafe_active) {
                failsafe_start = gpioTick();
                failsafe_active = 1;
            } else {
                uint32_t now = gpioTick();
                uint32_t elapsed = now - failsafe_start;
                if (elapsed > (uint32_t)(FAILSAFE_TIMEOUT * 1000000)) {
                    if (safe_write(RELAY_PIN, 0) != 0) {
                        gpioTerminate();
                        return EXIT_FAILURE;
                    }
                    relay_state = 0;
                    printf("Failsafe: relay forced OFF (touch held for > %d s)\n",
                           FAILSAFE_TIMEOUT);
                }
            }
        } else {
            if (failsafe_active) {
                failsafe_active = 0;
                touch_state = 0;
                printf("Touch released, failsafe cleared\n");
            }
        }

        usleep(POLL_DELAY_US);
    }

    /* Clean exit path — do NOT call gpioTerminate() inside a signal handler */
    if (safe_write(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn relay OFF during cleanup\n");
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

