#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24
#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define PULSES_PER_LITER   450.0
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE           "flow_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile int g_pulse_count = 0;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void pulse_counter(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static double calculate_flow_rate(int pulses, double dt_sec) {
    if (dt_sec <= 0.0) return 0.0;
    return (double)pulses / PULSES_PER_LITER / dt_sec * 60.0;
}

static int set_valve_position(int position) {
    if (position < 0 || position > 255) {
        fprintf(stderr, "Error: Valve position %d out of range [0, 255]\n", position);
        return -1;
    }
    if (gpioPWM(VALVE_PWM_PIN, position) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", VALVE_ENABLE_PIN);
        return -1;
    }
    return 0;
}

static void log_data(double flow_rate, int valve_position) {
    if (!g_log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);
    fprintf(g_log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(g_log_file);
}

int main(int argc, char *argv[]) {
    double target_flow_rate = 0.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = atof(optarg);
                if (target_flow_rate <= 0.0) {
                    fprintf(stderr, "Error: Target flow rate must be positive (e.g. -t 5.0)\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (target_flow_rate == 0.0) {
        fprintf(stderr, "Error: Target flow rate not specified (e.g. -t 5.0)\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", VALVE_ENABLE_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency on GPIO %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range on GPIO %d\n", VALVE_PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialize valve enable pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_valve_position(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set ISR for flow sensor on GPIO %d\n", FLOW_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set signal handlers\n");
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow rate: %.2f L/min\n", target_flow_rate);
    printf("Press Ctrl+C to stop.\n");

    int last_pulse_count = 0;
    int valve_position = 0;
    double dt_sec = 0.1;

    while (g_running) {
        int current_pulse_count = g_pulse_count;
        int pulses_in_interval = current_pulse_count - last_pulse_count;
        last_pulse_count = current_pulse_count;

        double flow_rate = calculate_flow_rate(pulses_in_interval, dt_sec);

        double error = target_flow_rate - flow_rate;
        int new_position = valve_position + (int)(error * 1.0);
        if (new_position < 0) new_position = 0;
        if (new_position > 255) new_position = 255;

        if (new_position != valve_position) {
            if (set_valve_position(new_position) == 0) {
                valve_position = new_position;
            }
        }

        log_data(flow_rate, valve_position);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    set_valve_position(0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    printf("Flow control stopped.\n");
    return EXIT_SUCCESS;
}

