#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define BUTTON_GPIO 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define SPI_BYTES 10
#define LOG_FILE "/var/log/door_access.log"
#define DEBOUNCE_US 50000
#define LOCK_RELEASE_MS 5000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int spi_handle = -1;

static const unsigned char valid_tag[SPI_BYTES] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    fprintf(log_file, "%s - %s\n", ts, event);
    fflush(log_file);
}

static int read_rfid_tag(unsigned char *tag_data) {
    if (spi_handle < 0) return -1;
    char tx[SPI_BYTES] = {0};
    char rx[SPI_BYTES] = {0};
    int ret = spiXfer(spi_handle, tx, rx, SPI_BYTES);
    if (ret != SPI_BYTES) {
        log_event("RFID read failure");
        return -1;
    }
