#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define ENA 23
#define IN1 24
#define IN2 25
#define ENB 12
#define IN3 16
#define IN4 20
#define ENC_A1 5
#define ENC_B1 6
#define ENC_A2 26
#define ENC_B2 19

#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100
#define PWM_FREQ_HZ 100
#define PWM_PERIOD_US (1000000 / PWM_FREQ_HZ)
#define PPR 600.0
#define TARGET_RPM 60.0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *ena_line = NULL, *enb_line = NULL;
static struct gpiod_line *in1_line = NULL, *in2_line = NULL;
static struct gpiod_line *in3_line = NULL, *in4_line = NULL;
static struct gpiod_line *enc_a1_line = NULL, *enc_b1_line = NULL;
static struct gpiod_line *enc_a2_line = NULL, *enc_b2_line = NULL;
static pthread_mutex_t enc_mutex = PTHREAD_MUTEX_INITIALIZER;
static long enc_count1 = 0, enc_count2 = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (ena_line) gpiod_line_set_value(ena_line, 0);
    if (enb_line) gpiod_line_set_value(enb_line, 0);
    if (in1_line) gpiod_line_set_value(in1_line, 0);
    if (in2_line) gpiod_line_set_value(in2_line, 0);
    if (in3_line) gpiod_line_set_value(in3_line, 0);
    if (in4_line) gpiod_line_set_value(in4_line, 0);
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

static int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) { perror("gpiod_chip_open_by_name"); return -1; }

    int pins[] = {ENA, IN1, IN2, ENB, IN3, IN4, ENC_A1, ENC_B1, ENC_A2, ENC_B2};
    for (size_t i = 0; i < sizeof(pins)/sizeof(pins[0]); i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, pins[i]);
        if (!line) { fprintf(stderr, "get_line %d failed\n", pins[i]); return -1; }
        if (i < 4) {
            if (gpiod_line_request_output(line, "motor", 0) < 0) {
                fprintf(stderr, "request_output %d failed\n", pins[i]);
                return -1;
            }
        } else {
            if (gpiod_line_request_input(line, "encoder") < 0) {
                fprintf(stderr, "request_input %d failed\n", pins[i]);
                return -1;
            }
        }
    }
    ena_line = gpiod_chip_get_line(chip, ENA); in1_line = gpiod_chip_get_line(chip, IN1);
    in2_line = gpiod_chip_get_line(chip, IN2); enb_line = gpiod_chip_get_line(chip, ENB);
    in3_line = gpiod_chip_get_line(chip, IN3); in4_line = gpiod_chip_get_line(chip, IN4);
    enc_a1_line = gpiod_chip_get_line(chip, ENC_A1); enc_b1_line = gpiod_chip_get_line(chip, ENC_B1);
    enc_a2_line = gpiod_chip_get_line(chip, ENC_A2); enc_b2_line = gpiod_chip_get_line(chip, ENC_B2);
    if (!ena_line || !in1_line || !in2_line || !enb_line || !in3_line || !in4_line ||
        !enc_a1_line || !enc_b1_line || !enc_a2_line || !enc_b2_line) {
        fprintf(stderr, "Failed to get all lines\n"); return -1;
    }
    return 0;
}

static void set_motor_speed(struct gpiod_line *ena, struct gpiod_line *in1, struct gpiod_line *in2, int speed) {
    if (speed > 0) {
        gpiod_line_set_value(in1, 1); gpiod_line_set_value(in2, 0);
        gpiod_line_set_value(ena, 1);
    } else if (speed < 0) {
        gpiod_line_set_value(in1, 0); gpiod_line_set_value(in2, 1);
        gpiod_line_set_value(ena, 1);
    } else {
        gpiod_line_set_value(ena, 0);
    }
}

static void *encoder_thread(void *arg) {
    (void)arg;
    struct gpiod_line *a_line = enc_a1_line, *b_line = enc_b1_line;
    int enc_num = 1;
    if (a_line == enc_a2_line) { a_line = enc_a2_line; b_line = enc_b2_line; enc_num = 2; }

    struct gpiod_line_event event;
    while (running) {
        int ret = gpiod_line_event_wait(a_line, NULL);
        if (ret < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "event_wait failed on enc%d\n", enc_num);
            break;
        }
        if (ret == 0) continue;
        if (gpiod_line_event_read(a_line, &event) < 0) continue;
        int b_val = gpiod_line_get_value(b_line);
        if (b_val < 0) continue;
        pthread_mutex_lock(&enc_mutex);
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            enc_count1 += (b_val == 0) ? 1 : -1;
        } else if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            enc_count1 += (b_val == 1) ? 1 : -1;
        }
        pthread_mutex_unlock(&enc_mutex);
    }
    return NULL;
}

static double calculate_pid(double target, double actual, double *integral, double *prev_error, double dt) {
    double error = target - actual;
    *integral += error * dt;
    double derivative = (error - *prev_error) / dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

static void log_data(double s1, double p1, double i1, double d1, double o1,
                     double s2, double p2, double i2, double d2, double o2) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            tm.tm_year+1900, tm.tm_mon+1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            s1,p1,i1,d1,o1, s2,p2,i2,d2,o2);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_gpio() < 0) { cleanup(); return 1; }

    log_file = fopen("motor_log.csv", "a");
    if (!log_file) { perror("fopen"); cleanup(); return 1; }
    fprintf(log_file, "timestamp,motor1_speed_rpm,p1,i1,d1,out1,motor2_speed_rpm,p2,i2,d2,out2\n");
    fflush(log_file);

    pthread_t t1, t2;
    if (pthread_create(&t1, NULL, encoder_thread, NULL) < 0 || pthread_create(&t2, NULL, encoder_thread, NULL) < 0) {
        fprintf(stderr, "pthread_create failed\n"); cleanup(); return 1;
    }

    double integral1 = 0, prev_err1 = 0, integral2 = 0, prev_err2 = 0;
    struct timespec ts = {0, SAMPLE_TIME_MS * 1000000L};

    while (running) {
        nanosleep(&ts, NULL);

        pthread_mutex_lock(&enc_mutex);
        long c1 = enc_count1; enc_count1 = 0;
        long c2 = enc_count2; enc_count2 = 0;
        pthread_mutex_unlock(&enc_mutex);

        double speed1 = (double)c1 / PPR * 60.0;
        double speed2 = (double)c2 / PPR * 60.0;

        double pid1 = calculate_pid(TARGET_RPM, speed1, &integral1, &prev_err1, SAMPLE_TIME_MS / 1000.0);
        double pid2 = calculate_pid(TARGET_RPM, speed2, &integral2, &prev_err2, SAMPLE_TIME_MS / 1000.0);

        int pwm1 = (int)(pid1 * 100.0);
        int pwm2 = (int)(pid2 * 100.0);
        if (pwm1 > 100) pwm1 = 100; else if (pwm1 < -100) pwm1 = -100;
        if (pwm2 > 100) pwm2 = 100; else if (pwm2 < -100) pwm2 = -100;

        set_motor_speed(ena_line, in1_line, in2_line, pwm1);
        set_motor_speed(enb_line, in3_line, in4_line, pwm2);

        log_data(speed1, KP, KI, KD, pid1, speed2, KP, KI, KD, pid2);
    }

    pthread_join(t1, NULL); pthread_join(t2, NULL);
    cleanup();
    return 0;
}

