#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1
#define LOG_FILE "relay_log.txt"
#define POLL_DELAY_US 50000

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80
#define MPR121_MHD_RISING 0x2B
#define MPR121_NHD_RISING 0x2C
#define MPR121_NCL_RISING 0x2D
#define MPR121_FDL_RISING 0x2E
#define MPR121_MHD_FALLING 0x2F
#define MPR121_NHD_FALLING 0x30
#define MPR121_NCL_FALLING 0x31
#define MPR121_FDL_FALLING 0x32
#define MPR121_NHD_PROX 0x33
#define MPR121_NCL_PROX 0x34
#define MPR121_FDL_PROX 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

int mpr121_init() {
    // Soft reset
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000); // 10ms delay after reset

    // Configure filtering
    if (mpr121_write_reg(MPR121_MHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_RISING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_RISING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_RISING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_FALLING, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_FALLING, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHD_PROX, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCL_PROX, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDL_PROX, 0x00) < 0) return -1;

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_E0TTH + 2 * i, 0x0F) < 0) return -1; // Touch threshold
        if (mpr121_write_reg(MPR121_E0RTH + 2 * i, 0x0A) < 0) return -1; // Release threshold
    }

    // Debounce: 3 samples for both touch and release
    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x33) < 0) return -1;

    // FFI=6 samples, CDC=16µA
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;

    // CDT=0.5µs, SFI=4 samples, ESI=4ms
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;

    // Enable all 12 electrodes in run mode
    if (mpr121_write_reg(MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading touch status: %d\n", result);
        return -1;
    }
    *touch_status = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

void log_relay_state(int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s - Relay State: %d\n", timestamp, state);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    int relay_state = 0;
    uint16_t touch_status = 0;

    while (running) {
        if (read_touch_status(&touch_status) == 0) {
            int any_touched = (touch_status & 0x0FFF) != 0;
            if (any_touched && !relay_state) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                log_relay_state(1);
            } else if (!any_touched && relay_state) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_relay_state(0);
            }
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

