#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return -1;
    }
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }
    return 0;
}

void stop_motors(void) {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
}

void generate_pattern(int *duties1, int *duties2, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        duties1[i] = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
        duties2[i] = (rand() % (MAX_DUTY - MIN_DUTY + 1)) + MIN_DUTY;
        durations[i] = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }
}

void play_pattern(int *duties1, int *duties2, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        if (shutdown_flag) break;
        gpioPWM(MOTOR1_PIN, duties1[i]);
        gpioPWM(MOTOR2_PIN, duties2[i]);
        gpioDelay(durations[i] * 1000);
    }
}

int main(void) {
    signal(SIGINT, signal_handler);

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    srand(time(NULL));

    int *duties1 = malloc(MAX_STEPS * sizeof(int));
    int *duties2 = malloc(MAX_STEPS * sizeof(int));
    int *durations = malloc(MAX_STEPS * sizeof(int));

    if (!duties1 || !duties2 || !durations) {
        fprintf(stderr, "Error: Memory allocation failed\n");
        free(duties1);
        free(duties2);
        free(durations);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!shutdown_flag) {
        int num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
        generate_pattern(duties1, duties2, durations, num_steps);
        play_pattern(duties1, duties2, durations, num_steps);
        if (!shutdown_flag) {
            gpioDelay(500000);
        }
    }

    stop_motors();
    free(duties1);
    free(duties2);
    free(durations);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

