#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define HX711_TIMEOUT_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int count = 0;
    int i;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(data_pin)) {
            count++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (count & 0x800000) {
        count |= ~0xFFFFFF;
    }

    return count;
}

static double calibrate_hx711(int data_pin, int clock_pin) {
    double sum = 0.0;
    int i;

    printf("Starting calibration. Remove all weight from the load cell.\n");
    gpioDelay(2000000);

    for (i = 0; i < NUM_CALIBRATION_READINGS; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == 0) {
            fprintf(stderr, "Error: HX711 returned 0 during calibration.\n");
            return 0.0;
        }
        sum += raw;
        gpioDelay(10000);
    }

    double offset = sum / NUM_CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %.2f\n", offset);
    return offset;
}

static double get_weight(int data_pin, int clock_pin, double scale_factor, double offset) {
    int raw = read_hx711(data_pin, clock_pin);
    if (raw == 0) {
        return 0.0;
    }
    return (raw - offset) / scale_factor;
}

static void control_solenoid(int solenoid_pin, int state) {
    gpioWrite(solenoid_pin, state);
}

static void log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, weight);
    fclose(fp);
}

int main(void) {
    double scale_factor = 1.0;
    double offset = 0.0;
