#include <unistd.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define PWM_DUTY_CYCLE 150

#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define MOTOR_RUN_TIME_S 5
#define CHECK_INTERVAL_S 60
#define CLOSE_WAIT_S 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int val = gpioRead(RAIN_SENSOR_PIN);
        if (val == 0) {
            low_count++;
        }
        if (i < DEBOUNCE_READINGS - 1) {
            gpioDelay(DEBOUNCE_DELAY_MS * 1000);
        }
    }
    return (low_count >= 3) ? 1 : 0;
}

static void close_window(void) {
    syslog(LOG_INFO, "Closing window...");
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        return;
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        return;
    }
    if (gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM duty cycle");
        return;
    }
    for (int i = 0; i < MOTOR_RUN_TIME_S && running; i++) {
        sleep(1);
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 low");
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
    }
    if (gpioPWM(MOTOR_PWM_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to stop PWM");
    }
    syslog(LOG_INFO, "Window closed.");
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        fprintf(stderr, "pigpio initialisation failed\n");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set PWM pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_PWM_PIN, PWM_RANGE) < 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set SIGINT handler");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set SIGTERM handler");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    log_event("Window control system started.");

    while (running) {
        if (read_rain_sensor()) {
            log_event("Rain detected!");
            close_window();
            for (int i = 0; i < CLOSE_WAIT_S && running; i++) {
                sleep(1);
            }
        } else {
            log_event("No rain detected.");
        }
        for (int i = 0; i < CHECK_INTERVAL_S && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

