#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17
#define WEIGHT_THRESHOLD 100
#define SOLENOID_DURATION 5
#define LOG_FILE "stock_events.txt"
#define HX711_TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int dt, int sck) {
    int count = 0;
    int i;

    gpioSetMode(dt, PI_INPUT);
    gpioSetMode(sck, PI_OUTPUT);
    gpioWrite(sck, 0);

    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(sck, 1);
        gpioDelay(1);
        count = count << 1;
        if (gpioRead(dt)) {
            count++;
        }
        gpioWrite(sck, 0);
        gpioDelay(1);
    }

    gpioWrite(sck, 1);
    gpioDelay(1);
    gpioWrite(sck, 0);
    gpioDelay(1);

    if (count & 0x800000) {
        count |= ~0xFFFFFF;
    }

    return count;
}

static int activate_solenoid(int pin, int duration) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid on GPIO %d\n", pin);
        return -1;
    }
    gpioDelay(duration * 1000000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int log_event(const char *filename, const char *event) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    if (fprintf(fp, "%s: %s\n", timestamp, event) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Failed to close log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set solenoid pin mode\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(SOLENOID_PIN, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Stock monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int weight = read_hx711(HX711_DT, HX711_SCK);

        if (weight == 0) {
            fprintf(stderr, "Error: HX711 read returned 0 (possible timeout or data line stuck)\n");
            gpioDelay(1000000);
            continue;
        }

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold (%d g < %d g). Activating solenoid.\n", weight, WEIGHT_THRESHOLD);
            if (activate_solenoid(SOLENOID_PIN, SOLENOID_DURATION) != 0) {
                fprintf(stderr, "Error: Solenoid activation failed\n");
            }
            if (log_event(LOG_FILE, "Solenoid activated") != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
        }

        gpioDelay(1000000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Stock monitoring stopped.\n");
    return 0;
}

