    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Stock monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int weight = read_hx711(HX711_DT, HX711_SCK);

        if (weight == 0) {
            fprintf(stderr, "Error: HX711 read returned 0 (possible timeout or data line stuck)\n");
            gpioDelay(1000000);
            continue;
        }

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold (%d g < %d g). Activating solenoid.\n", weight, WEIGHT_THRESHOLD);
            if (activate_solenoid(SOLENOID_PIN, SOLENOID_DURATION) != 0) {
                fprintf(stderr, "Error: Solenoid activation failed\n");
            }
            if (log_event(LOG_FILE, "Solenoid activated") != 0) {
                fprintf(stderr, "Error: Failed to log event\n");
            }
        }

        gpioDelay(1000000);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Stock monitoring stopped.\n");
    return 0;
}

