#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define SECURITY_LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000  /* 100 ms timeout waiting for data line */

static volatile sig_atomic_t program_running = 1;
static double calibration_factor = 1.0;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Read 24-bit signed value from HX711. Returns 0 on success, -1 on timeout. */
static int read_hx711(int *raw_value) {
    int data = 0;
    int i;

    /* Wait for data line to go low (data ready) with timeout */
    int waited = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (waited >= HX711_TIMEOUT_US) {
            fprintf(stderr, "Error: HX711 data line stuck high (timeout).\n");
            return -1;
        }
        gpioDelay(1);
        waited++;
    }

    /* Read 24 data bits */
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1);  /* >= 1 us high */
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN) == 1) {
            data |= 1;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);  /* >= 1 us low */
    }

    /* 25th pulse to set gain to 128 for next reading */
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    /* Convert 24-bit two's complement to signed 32-bit */
    if (data & 0x800000) {
        data |= ~0xFFFFFF;  /* sign extend */
    }

    *raw_value = data;
    return 0;
}

static double calculate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

static int calibrate_sensor(void) {
    double known_weight;
    int raw_value;

    printf("Calibration mode. Remove any weight from the load cell.\n");
    printf("Press Enter to continue...");
    getchar();

    printf("Enter the known weight in kilograms: ");
    if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
        fprintf(stderr, "Invalid input for known weight.\n");
        return -1;
    }
    getchar();  /* consume newline */

    printf("Place the known weight on the load cell and press Enter to read...\n");
    getchar();

    if (read_hx711(&raw_value) != 0) {
        fprintf(stderr, "Failed to read HX711 during calibration.\n");
        return -1;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        perror("Error writing calibration file");
        return -1;
    }
    fprintf(fp, "%lf\n", calibration_factor);
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        perror("Error opening calibration file");
        return -1;
    }
    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor from file.\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration factor loaded: %lf\n", calibration_factor);
    return 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(SECURITY_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening security log file");
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

static void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

static void cleanup(void) {
    control_solenoid(0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    /* Ensure clock starts low */
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration() != 0) {
        if (calibrate_sensor() != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            cleanup();
            return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return 1;
    }

    printf("Weight-based access control system started.\n");
    printf("Threshold: %.2f kg. Press Ctrl+C to exit.\n", WEIGHT_THRESHOLD);

    while (program_running) {
        int raw_value;
        if (read_hx711(&raw_value) != 0) {
            fprintf(stderr, "HX711 read error, retrying...\n");
            gpioDelay(100000);  /* 100 ms backoff */
            continue;
        }

        double weight = calculate_weight(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Activating solenoid lock.\n");
            log_event("Weight threshold exceeded, solenoid activated.");
            control_solenoid(1);
            gpioDelay(5000000);  /* 5 seconds */
            control_solenoid(0);
            printf("Solenoid lock deactivated.\n");
        }

        gpioDelay(100000);  /* 100 ms polling interval */
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

