#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(FILE *log_file, int relay_state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay State: %s\n", timestamp, relay_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_line = NULL;
    struct gpiod_line *relay_line = NULL;
    FILE *log_file = NULL;
    int relay_state = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (sensor_line == NULL) {
        fprintf(stderr, "Error: Failed to get sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (relay_line == NULL) {
        fprintf(stderr, "Error: Failed to get relay line %d: %s\n", RELAY_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(sensor_line, "ky022_sensor") < 0) {
        fprintf(stderr, "Error: Failed to request sensor line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(relay_line, "srd05_relay", 0) < 0) {
        fprintf(stderr, "Error: Failed to request relay line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring KY-022 on GPIO%d, relay on GPIO%d. Press Ctrl+C to exit.\n", SENSOR_PIN, RELAY_PIN);

    while (running) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error: Failed to read sensor value: %s\n", strerror(errno));
            break;
        }

        if (sensor_value == 0) {
            relay_state = !relay_state;
            if (gpiod_line_set_value(relay_line, relay_state) < 0) {
                fprintf(stderr, "Error: Failed to set relay value: %s\n", strerror(errno));
                break;
            }

            if (log_event(log_file, relay_state) < 0) {
                fprintf(stderr, "Warning: Failed to log event\n");
            }

            printf("Obstacle detected! Relay toggled to %s\n", relay_state ? "ON" : "OFF");
        }

        struct timespec sleep_time = {0, 100000000}; /* 100 ms */
        nanosleep(&sleep_time, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (relay_line != NULL) {
        gpiod_line_release(relay_line);
    }
    if (sensor_line != NULL) {
        gpiod_line_release(sensor_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return ret;
}

