#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define CONFIG_FILE "watering.conf"
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define MIN_DURATION 1
#define MAX_DURATION 3600

static volatile sig_atomic_t g_stop = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_watering_duration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Error: config file '%s' is empty.\n", filename);
        } else {
            fprintf(stderr, "Error reading config file '%s': %s\n",
                    filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *token = strtok(line, "=\n\r");
    if (token == NULL || strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: config file '%s' does not contain 'duration='.\n",
                filename);
        return -1;
    }

    token = strtok(NULL, "=\n\r");
    if (token == NULL) {
        fprintf(stderr, "Error: config file '%s' missing value after 'duration='.\n",
                filename);
        return -1;
    }

    char *endptr = NULL;
    errno = 0;
    long val = strtol(token, &endptr, 10);
    if (errno != 0 || endptr == token) {
        fprintf(stderr, "Error: invalid duration value '%s' in config file.\n",
                token);
        return -1;
    }

    if (val < MIN_DURATION || val > MAX_DURATION) {
        fprintf(stderr, "Error: duration %ld out of range [%d, %d].\n",
                val, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

static void sleep_interruptible(unsigned int seconds)
{
    unsigned int remaining = seconds;
    while (remaining > 0 && !g_stop) {
        remaining = sleep(remaining);
    }
}

int main(void)
{
    int duration = 0;
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve OFF\n");

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error activating valve: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve ON\n");

    sleep_interruptible((unsigned int)duration);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error deactivating valve: %s\n", strerror(errno));
    }

    printf("Valve OFF\n");

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (g_stop) {
        printf("Interrupted by signal.\n");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

