#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_PWM 22
#define RIGHT_PWM 23
#define LEFT_IN1 24
#define RIGHT_IN1 25

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio) {
    int val = gpioRead(gpio);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, pigpio_error(val));
        return -1;
    }
    return val;
}

static void set_motor_speed(int left_speed, int right_speed) {
    if (left_speed < 0) left_speed = 0;
    if (left_speed > PWM_RANGE) left_speed = PWM_RANGE;
    if (right_speed < 0) right_speed = 0;
    if (right_speed > PWM_RANGE) right_speed = PWM_RANGE;

    if (left_speed == 0) {
        gpioWrite(LEFT_IN1, 0);
        gpioPWM(LEFT_PWM, 0);
    } else if (left_speed > 0) {
        gpioWrite(LEFT_IN1, 1);
        gpioPWM(LEFT_PWM, left_speed);
    }

    if (right_speed == 0) {
        gpioWrite(RIGHT_IN1, 0);
        gpioPWM(RIGHT_PWM, 0);
    } else if (right_speed > 0) {
        gpioWrite(RIGHT_IN1, 1);
        gpioPWM(RIGHT_PWM, right_speed);
    }
}

static void log_data(int left, int middle, int right, int left_speed, int right_speed) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left, middle, right, left_speed, right_speed);
    fflush(log_file);
}

static void cleanup(void) {
    set_motor_speed(0, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {LEFT_SENSOR, MIDDLE_SENSOR, RIGHT_SENSOR, LEFT_PWM, RIGHT_PWM, LEFT_IN1, RIGHT_IN1};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Failed to set pull-up on GPIO %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMfrequency(LEFT_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", LEFT_PWM);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(RIGHT_PWM, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", RIGHT_PWM);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(LEFT_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", LEFT_PWM);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(RIGHT_PWM, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", RIGHT_PWM);
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("trace_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening trace_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        int left = read_sensor(LEFT_SENSOR);
        int middle = read_sensor(MIDDLE_SENSOR);
        int right = read_sensor(RIGHT_SENSOR);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error, stopping motors\n");
            set_motor_speed(0, 0);
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int left_speed = 150;
        int right_speed = 150;

        if (left == 0 && middle == 0 && right == 0) {
            set_motor_speed(0, 0);
        } else if (left == 0 && middle == 0 && right == 1) {
            right_speed = left_speed / 2;
            set_motor_speed(left_speed, right_speed);
        } else if (left == 0 && middle == 1 && right == 0) {
            left_speed = right_speed / 2;
            set_motor_speed(left_speed, right_speed);
        } else if (left == 1 && middle == 0 && right == 0) {
            set_motor_speed(left_speed, right_speed);
        } else {
            set_motor_speed(left_speed, right_speed);
        }

        log_data(left, middle, right, left_speed, right_speed);
        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

