#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR 0x23
#define GROW_LAMP_GPIO 23
#define I2C_BUS 1
#define LUX_THRESHOLD 150.0f
#define MEASUREMENT_DELAY_US 180000
#define LOG_FILE "grow_log.txt"

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen log");
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, message);
    fclose(fp);
}

static int read_bh1750(int handle, float *lux_out) {
    if (i2cWriteByte(handle, 0x10) < 0) {
        log_event("Error: failed to write measurement command to BH1750");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_US);

    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        log_event("Error: failed to read 2 bytes from BH1750");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_lamp(int gpio, int state) {
    if (gpioWrite(gpio, state) < 0) {
        log_event("Error: failed to write to GPIO for grow lamp");
        return;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Grow lamp %s", state ? "ON" : "OFF");
    log_event(msg);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, BH1750_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GROW_LAMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GROW_LAMP_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GROW_LAMP_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started: monitoring illuminance");

    int lamp_state = 0;
    while (running) {
        float lux;
        if (read_bh1750(i2c_handle, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);

            if (lux < LUX_THRESHOLD && lamp_state == 0) {
                control_lamp(GROW_LAMP_GPIO, 1);
                lamp_state = 1;
            } else if (lux >= LUX_THRESHOLD && lamp_state == 1) {
                control_lamp(GROW_LAMP_GPIO, 0);
                lamp_state = 0;
            }
        }
        gpioDelay(500000);
    }

    log_event("Shutting down: cleaning up");
    control_lamp(GROW_LAMP_GPIO, 0);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

