#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18

#define LOCKED_PULSE 1000
#define UNLOCKED_PULSE 2000
#define MIN_PULSE 500
#define MAX_PULSE 2500

#define DEBOUNCE_MS 100

static volatile int running = 1;

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo(int pin, int pulse) {
    if (pulse < MIN_PULSE || pulse > MAX_PULSE) {
        fprintf(stderr, "Error: pulse %d out of range [%d, %d]\n", pulse, MIN_PULSE, MAX_PULSE);
        return -1;
    }
    gpioServo(pin, pulse);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        fprintf(stderr, "Error: cannot register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    int locked = 0;

    while (running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (!locked) {
                printf("Locking door...\n");
                if (set_servo(SERVO_PIN, LOCKED_PULSE) != 0) {
                    fprintf(stderr, "Error: failed to set servo to locked position\n");
                } else {
                    locked = 1;
                }
                gpioDelay(DEBOUNCE_MS * 1000);
            }
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (locked) {
                printf("Unlocking door...\n");
                if (set_servo(SERVO_PIN, UNLOCKED_PULSE) != 0) {
                    fprintf(stderr, "Error: failed to set servo to unlocked position\n");
                } else {
                    locked = 0;
                }
                gpioDelay(DEBOUNCE_MS * 1000);
            }
        }

        gpioDelay(10000); // 10 ms loop delay
    }

    gpioServo(SERVO_PIN, 0); // stop PWM
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

