#include <errno.h>
#include <gpiod.h>
#include <zmq.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_SUB_ENDPOINT "tcp://localhost:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int sound_sensor_mode(struct gpiod_line *sound_line, struct gpiod_line *led_line) {
    int rc;
    int ret = 0;

    rc = gpiod_line_request_input(sound_line, "sound_sensor");
    if (rc < 0) {
        fprintf(stderr, "Failed to request sound sensor line as input: %s\n", strerror(errno));
        return -1;
    }

    rc = gpiod_line_request_output(led_line, "alarm_led", 0);
    if (rc < 0) {
        fprintf(stderr, "Failed to request LED line as output: %s\n", strerror(errno));
        return -1;
    }

    printf("Sound sensor mode started. Polling GPIO%d every %d us.\n", SOUND_SENSOR_PIN, POLL_INTERVAL_US);

    while (running) {
        int val = gpiod_line_get_value(sound_line);
        if (val < 0) {
            fprintf(stderr, "Failed to read sound sensor: %s\n", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val == 0) {
            printf("Sound detected! Publishing alert.\n");
            rc = gpiod_line_set_value(led_line, 1);
            if (rc < 0) {
                fprintf(stderr, "Failed to turn on LED: %s\n", strerror(errno));
            }
            usleep(1000000);
            rc = gpiod_line_set_value(led_line, 0);
            if (rc < 0) {
                fprintf(stderr, "Failed to turn off LED: %s\n", strerror(errno));
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    return ret;
}

static int alarm_node_mode(void) {
    void *context = NULL;
    void *socket = NULL;
    int rc;
    int ret = 0;

    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context: %s\n", zmq_strerror(errno));
        return -1;
    }

    socket = zmq_socket(context, ZMQ_SUB);
    if (!socket) {
        fprintf(stderr, "Failed to create ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_ctx_destroy(context);
        return -1;
    }

    rc = zmq_connect(socket, ZMQ_SUB_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to connect to %s: %s\n", ZMQ_SUB_ENDPOINT, zmq_strerror(errno));
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }

    rc = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (rc != 0) {
        fprintf(stderr, "Failed to subscribe to topic %s: %s\n", ZMQ_TOPIC, zmq_strerror(errno));
        zmq_close(socket);
        zmq_ctx_destroy(context);
        return -1;
    }

    printf("Alarm node mode started. Listening on %s for topic %s.\n", ZMQ_SUB_ENDPOINT, ZMQ_TOPIC);

    while (running) {
        char buffer[256];
        zmq_msg_t msg;
        int msg_size;

        msg_size = zmq_recvmsg(socket, &msg, 0);
        if (msg_size < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Failed to receive message: %s\n", zmq_strerror(errno));
            break;
        }

        if (msg_size > 0) {
            memcpy(buffer, zmq_msg_data(&msg), (size_t)msg_size);
            buffer[msg_size] = '\0';
            printf("Received alert: %s\n", buffer);
        }

        zmq_msg_close(&msg);
    }

    zmq_close(socket);
    zmq_ctx_destroy(context);
    return ret;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "  sound_sensor  - Polls an LM393 sound sensor on GPIO17\n");
        fprintf(stderr, "  alarm_node    - Subscribes to sound alerts on tcp://localhost:5555\n");
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "sound_sensor") != 0 && strcmp(argv[1], "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s. Use 'sound_sensor' or 'alarm_node'.\n", argv[1]);
        return EXIT_FAILURE;
    }

    if (setup_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (!sound_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", SOUND_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", ALARM_LED_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        int ret = sound_sensor_mode(sound_line, led_line);
        gpiod_chip_close(chip);
        return ret;
    } else {
        int ret = alarm_node_mode();
        gpiod_chip_close(chip);
        return ret;
    }
}

