#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 68
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_RPT_SPACE 2250
#define NEC_TOL 200

static volatile sig_atomic_t running = 1;
static MQTTClient mqtt_client;
static volatile int pulse_count = 0;
static volatile uint32_t pulses[MAX_PULSES];
static volatile int have_frame = 0;
static volatile uint32_t decoded_address = 0;
static volatile uint32_t decoded_command = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int in_range(int val, int target, int tol) {
    return (val >= target - tol) && (val <= target + tol);
}

static void ir_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level != 0) return;
    if (pulse_count >= MAX_PULSES) {
        pulse_count = 0;
        return;
    }
    pulses[pulse_count++] = tick;
}

static int decode_nec(void) {
    if (pulse_count < 34) return -1;
    if (!in_range((int)pulses[0], NEC_HDR_MARK, NEC_TOL)) return -1;
    if (!in_range((int)pulses[1], NEC_HDR_SPACE, NEC_TOL)) return -1;
    uint32_t address = 0, command = 0;
    for (int i = 0; i < 16; i++) {
        int idx = 2 + i * 2;
        if (!in_range((int)pulses[idx], NEC_BIT_MARK, NEC_TOL)) return -1;
        int space = (int)pulses[idx + 1];
        if (in_range(space, NEC_ONE_SPACE, NEC_TOL)) {
            address = (address << 1) | 1;
        } else if (in_range(space, NEC_ZERO_SPACE, NEC_TOL)) {
            address = (address << 1) | 0;
        } else {
            return -1;
        }
    }
    for (int i = 0; i < 16; i++) {
        int idx = 34 + i * 2;
        if (!in_range((int)pulses[idx], NEC_BIT_MARK, NEC_TOL)) return -1;
        int space = (int)pulses[idx + 1];
        if (in_range(space, NEC_ONE_SPACE, NEC_TOL)) {
            command = (command << 1) | 1;
        } else if (in_range(space, NEC_ZERO_SPACE, NEC_TOL)) {
            command = (command << 1) | 0;
        } else {
            return -1;
        }
    }
    uint32_t inv_addr = ((~address) & 0xFF) << 8;
    uint32_t inv_cmd  = ((~command) & 0xFF) << 8;
    if ((address & 0xFF) != ((inv_addr >> 8) & 0xFF)) return -1;
    if ((command & 0xFF) != ((inv_cmd >> 8) & 0xFF)) return -1;
    decoded_address = address;
    decoded_command = command;
    have_frame = 1;
    return 0;
}

static void mqtt_connect(void) {
    int rc = MQTTClient_connect(mqtt_client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", MQTTClient_strerror(rc));
    } else {
        syslog(LOG_INFO, "MQTT connected");
    }
}

static void mqtt_publish(uint32_t addr, uint32_t cmd) {
    char payload[128];
    snprintf(payload, sizeof(payload),
             "{\"address\":%u,\"command\":%u}", addr, cmd);
    MQTTClient_message msg = MQTTClient_message_initializer;
    msg.payload = payload;
    msg.payloadlen = (int)strlen(payload);
    msg.qos = 1;
    msg.retained = 0;
    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC, &msg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", MQTTClient_strerror(rc));
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio init failed");
        closelog();
        return 1;
    }
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFunc(IR_GPIO, ir_callback) != 0) {
        syslog(LOG_ERR, "gpioSetAlertFunc failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    MQTTClient_create(&mqtt_client, MQTT_BROKER, "rpi_ir_decoder",
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.cleansession = 1;
    mqtt_connect();

    syslog(LOG_INFO, "IR decoder started on GPIO%d", IR_GPIO);

    while (running) {
        if (have_frame) {
            have_frame = 0;
            if (decode_nec() == 0) {
                syslog(LOG_INFO, "Decoded: addr=0x%02X cmd=0x%02X",
                       decoded_address, decoded_command);
                mqtt_publish(decoded_address, decoded_command);
            } else {
                syslog(LOG_WARNING, "NEC decode failed");
            }
            pulse_count = 0;
        }
        gpioDelay(10000);
    }

    syslog(LOG_INFO, "Shutting down");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioSetAlertFunc(IR_GPIO, NULL);
    gpioTerminate();
    closelog();
    return 0;
}

