#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define BH1750_CMD_OT_HRES 0x20
#define BH1750_CONV_MS    180

static const int sensor_addrs[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
    }
    return fd;
}

static int i2c_set_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read(int fd, int addr, float *lux_out) {
    if (i2c_set_slave(fd, addr) < 0) return -1;

    unsigned char cmd = BH1750_CMD_OT_HRES;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "write(0x%02X) to 0x%02X: %s\n", cmd, addr, strerror(errno));
        return -1;
    }

    usleep(BH1750_CONV_MS * 1000);

    unsigned char data[2];
    ssize_t n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "read(0x%02X): got %zd bytes (%s)\n", addr, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    unsigned int raw = ((unsigned int)data[0] << 8) | data[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sock, const char *msg) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sock, msg, strlen(msg), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) return 1;

    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        fprintf(stderr, "socket: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "setsockopt(IP_MULTICAST_TTL): %s\n", strerror(errno));
        close(sock);
        close(i2c_fd);
        return 1;
    }

    while (g_running) {
        char msg[256];
        int off = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            float lux = NAN;
            if (bh1750_read(i2c_fd, sensor_addrs[i], &lux) < 0) {
                lux = NAN;
            }
            char val[20];
            snprintf(val, sizeof(val), "%s%.1f", i > 0 ? ";" : "", lux);
            int need = (int)strlen(val);
            if (off + need >= (int)sizeof(msg)) {
                fprintf(stderr, "Message buffer overflow\n");
                break;
            }
            memcpy(msg + off, val, need);
            off += need;
        }
        msg[off] = '\0';

        if (send_multicast(sock, msg) < 0) {
            fprintf(stderr, "Failed to send multicast\n");
        } else {
            printf("Sent: %s\n", msg);
        }

        for (int s = 0; s < 10 && g_running; s++) {
            sleep(1);
        }
    }

    close(sock);
    close(i2c_fd);
    return 0;
}

