#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x28
#define LOG_FILE       "airflow_log.txt"
#define SAMPLE_PERIOD  1
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void msleep(unsigned ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static int i2c_write_zero(int fd)
{
    /* Zero-length write: issues a start condition without sending data. */
    if (write(fd, NULL, 0) < 0) {
        if (errno == ENXIO)
            fprintf(stderr, "I2C write failed: sensor not present at 0x%02X (ENXIO)\n", SENSOR_ADDR);
        else if (errno == EIO)
            fprintf(stderr, "I2C write failed: bus error (EIO)\n");
        else
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        if (errno == EIO)
            fprintf(stderr, "I2C read failed: bus error (EIO)\n");
        else
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read failed: short read (%zd of %zu bytes)\n", n, len);
        return -1;
    }
    return 0;
}

static int read_airflow_raw(int fd, uint16_t *raw_out)
{
    uint8_t buf[2];
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_zero(fd) < 0) {
            msleep(RETRY_DELAY_MS);
            continue;
        }
        if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0) {
            msleep(RETRY_DELAY_MS);
            continue;
        }
        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *raw_out = raw & 0x3FFF;
        return 0;
    }
    fprintf(stderr, "Failed to read airflow after %d attempts\n", MAX_RETRIES);
    return -1;
}

static float convert_to_slpm(uint16_t raw)
{
    return ((float)raw - 3277.0f) * 0.1f;
}

static int log_data(FILE *fp, float slpm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.2f SLPM\n", ts, slpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", SENSOR_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw;
        if (read_airflow_raw(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "Skipping sample due to read failure\n");
        } else {
            float slpm = convert_to_slpm(raw);
            if (log_data(g_log_fp, slpm) < 0)
                fprintf(stderr, "Logging failed; continuing\n");
            printf("Flow: %.2f SLPM (raw=0x%04X)\n", slpm, raw);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

