#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define I2C_BUS "/dev/i2c-1"
#define ACCEL_REG 0x28
#define ACCEL_DATA_LEN 6
#define SCALE_FACTOR 0.000244f
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *data_file = NULL;
static FILE *error_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *msg) {
    if (!error_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(error_file, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
    fflush(error_file);
}

static int i2c_write_byte(int fd, uint8_t reg) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (write(fd, &reg, 1) == 1) return 0;
        log_error("I2C write byte failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read(fd, buf, len) == len) return 0;
        log_error("I2C read bytes failed");
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t reg = ACCEL_REG;
    uint8_t data[ACCEL_DATA_LEN];

    if (i2c_write_byte(fd, reg) != 0) return -1;
    if (i2c_read_bytes(fd, data, ACCEL_DATA_LEN) != 0) return -1;

    int16_t x_raw = (int16_t)((data[1] << 8) | data[0]);
    int16_t y_raw = (int16_t)((data[3] << 8) | data[2]);
    int16_t z_raw = (int16_t)((data[5] << 8) | data[4]);

    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x, y, z);
    fflush(fp);
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    const char *filename = DEFAULT_FILENAME;

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a': i2c_address = (int)strtol(optarg, NULL, 0); break;
            case 'i': interval = atoi(optarg); break;
            case 'f': filename = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    error_file = fopen("seismic_error.log", "a");
    if (!error_file) {
        perror("Failed to open error log");
        return EXIT_FAILURE;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        fclose(error_file);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        fclose(error_file);
        return EXIT_FAILURE;
    }

    data_file = fopen(filename, "a");
    if (!data_file) {
        log_error("Failed to open data file");
        close(i2c_fd);
        fclose(error_file);
        return EXIT_FAILURE;
    }

    fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
    fflush(data_file);

    float x, y, z;
    while (running) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            log_data(data_file, x, y, z);
        } else {
            log_error("Failed to read acceleration data");
        }
        sleep(interval);
    }

    if (data_file) fclose(data_file);
    if (i2c_fd >= 0) close(i2c_fd);
    if (error_file) fclose(error_file);
    return EXIT_SUCCESS;
}

