#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define POWER_ON_CMD 0x01
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define I2C_RETRY_DELAY_SEC 1
#define LOOP_DELAY_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int sockfd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, unsigned char byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int init_bh1750(int fd) {
    if (i2c_write_byte(fd, POWER_ON_CMD) < 0) return -1;
    usleep(10000); /* 10 ms power-on delay */
    if (i2c_write_byte(fd, CONTINUOUS_HIGH_RES_MODE) < 0) return -1;
    usleep(180000); /* 180 ms for first measurement */
    return 0;
}

static int read_light_level(int fd, float *lux) {
    unsigned char buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int send_udp_multicast(float lux) {
    struct sockaddr_in addr;
    char message[64];
    int len = snprintf(message, sizeof(message), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(message)) {
        fprintf(stderr, "Message formatting error\n");
        return -1;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        return -1;
    }

    int ttl = 1;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Set TTL failed: %s\n", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(sockfd, message, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Sendto failed: %s\n", strerror(errno));
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    close(sockfd);
    sockfd = -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor\n");
        close(i2c_fd);
        return 1;
    }

    printf("BH1750 sensor initialized. Broadcasting to %s:%d\n", MULTICAST_ADDR, MULTICAST_PORT);

    while (running) {
        float lux;
        if (read_light_level(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Failed to read light level, retrying in %d second(s)...\n", I2C_RETRY_DELAY_SEC);
            sleep(I2C_RETRY_DELAY_SEC);
            continue;
        }

        if (send_udp_multicast(lux) < 0) {
            fprintf(stderr, "Failed to send UDP multicast, retrying in %d second(s)...\n", I2C_RETRY_DELAY_SEC);
            sleep(I2C_RETRY_DELAY_SEC);
            continue;
        }

        printf("Light level: %.2f lux\n", lux);
        sleep(LOOP_DELAY_SEC);
    }

    printf("\nShutting down...\n");
    if (i2c_fd >= 0) close(i2c_fd);
    if (sockfd >= 0) close(sockfd);
    return 0;
}

