#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 8192
#define MAGIC_WORD_SIZE 8
#define TLV_HEADER_SIZE 8
#define TLV_TYPE_DETECTED_POINTS 1
#define DETECTED_POINT_SIZE 12

static const uint8_t MAGIC_WORD[MAGIC_WORD_SIZE] = {0x02, 0x04, 0x03, 0x06, 0x08, 0x05, 0x07, 0x09};

static int uart_handle = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float range;
    float velocity;
} RadarData;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_uart(void) {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %d\n", UART_DEVICE, uart_handle);
        return -1;
    }
    return 0;
}

static int init_csv(void) {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s\n", CSV_FILE);
        return -1;
    }
    fseek(csv_file, 0, SEEK_END);
    if (ftell(csv_file) == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    return 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", ts, msg);
}

static int find_magic_word(const uint8_t *buf, int len) {
    for (int i = 0; i <= len - MAGIC_WORD_SIZE; i++) {
        if (memcmp(buf + i, MAGIC_WORD, MAGIC_WORD_SIZE) == 0) {
            return i;
        }
    }
    return -1;
}

static int parse_tlv(const uint8_t *frame, int frame_len, FILE *csv) {
    int offset = MAGIC_WORD_SIZE;
    int obj_idx = 0;

    while (offset + TLV_HEADER_SIZE <= frame_len) {
        uint32_t tlv_type = *(const uint32_t *)(frame + offset);
        uint32_t tlv_len = *(const uint32_t *)(frame + offset + 4);
        offset += TLV_HEADER_SIZE;

        if (offset + tlv_len > frame_len) {
            log_error("TLV length exceeds frame bounds");
            return -1;
        }

        if (tlv_type == TLV_TYPE_DETECTED_POINTS) {
            int num_points = tlv_len / DETECTED_POINT_SIZE;
            for (int i = 0; i < num_points; i++) {
                const uint8_t *pt = frame + offset + i * DETECTED_POINT_SIZE;
                int16_t range_raw, velocity_raw;
                memcpy(&range_raw, pt, 2);
                memcpy(&velocity_raw, pt + 2, 2);
                RadarData rd;
                rd.range = (float)range_raw / 100.0f;
                rd.velocity = (float)velocity_raw / 100.0f;
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char ts[32];
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
                fprintf(csv, "%s,%d,%.2f,%.2f\n", ts, obj_idx++, rd.range, rd.velocity);
            }
        }
        offset += tlv_len;
    }
    fflush(csv);
    return 0;
}

static void cleanup(void) {
    if (uart_handle >= 0) {
        serClose(uart_handle);
        uart_handle = -1;
    }
    if (csv_file) {
        fflush(csv_file);
        fclose(csv_file);
        csv_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_csv() != 0) {
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t *frame_buf = malloc(MAX_FRAME_SIZE);
    if (!frame_buf) {
        log_error("Failed to allocate frame buffer");
        cleanup();
        return 1;
    }

    int frame_len = 0;
    int last_sync = -1;

    while (!terminate) {
        int space = MAX_FRAME_SIZE - frame_len;
        if (space <= 0) {
            frame_len = 0;
            space = MAX_FRAME_SIZE;
        }

        int bytes_read = serRead(uart_handle, (char *)(frame_buf + frame_len), space);
        if (bytes_read < 0) {
            log_error("UART read error");
            break;
        }
        if (bytes_read == 0) {
            gpioDelay(1000);
            continue;
        }

        frame_len += bytes_read;

        int sync_pos = find_magic_word(frame_buf, frame_len);
        if (sync_pos < 0) {
            if (frame_len > MAGIC_WORD_SIZE) {
                memmove(frame_buf, frame_buf + frame_len - MAGIC_WORD_SIZE, MAGIC_WORD_SIZE);
                frame_len = MAGIC_WORD_SIZE;
            }
            continue;
        }

        if (last_sync >= 0 && sync_pos > last_sync + 1) {
            int lost = sync_pos - last_sync - 1;
            if (lost > 0 && lost + last_sync < frame_len) {
                memmove(frame_buf, frame_buf + last_sync + 1, lost);
                frame_len = lost;
            }
        }
        last_sync = sync_pos;

        if (frame_len >= MAGIC_WORD_SIZE + 4) {
            uint32_t total_packet_len = *(const uint32_t *)(frame_buf + MAGIC_WORD_SIZE);
            if (total_packet_len > MAX_FRAME_SIZE) {
                log_error("Packet length exceeds buffer");
                frame_len = 0;
                continue;
            }
            if (frame_len >= (int)total_packet_len) {
                if (parse_tlv(frame_buf, total_packet_len, csv_file) != 0) {
                    log_error("TLV parse failed");
                }
                int remaining = frame_len - total_packet_len;
                if (remaining > 0) {
                    memmove(frame_buf, frame_buf + total_packet_len, remaining);
                }
                frame_len = remaining;
            }
        }
    }

    free(frame_buf);
    cleanup();
    return 0;
}

