#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE   B115200
#define LINE_BUF_SZ 512
#define READ_BUF_SZ 256
#define POLL_TIMEOUT_SEC 2
#define IBT_TIMEOUT_SEC  0
#define IBT_TIMEOUT_USEC 500000  /* 0.5 s inter-byte timeout */

static volatile sig_atomic_t g_running = 1;
static int g_uart_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", device, strerror(errno));
        return -1;
    }

    /* Clear O_NONBLOCK so blocking reads can be interrupted by signals */
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags < 0 || fcntl(fd, F_SETFL, flags & ~O_NONBLOCK) < 0) {
        fprintf(stderr, "Warning: could not clear O_NONBLOCK: %s\n", strerror(errno));
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    /* 8N1, no flow control */
    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |=  CS8 | CREAD | CLOCAL;

    /* Raw input */
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG);

    /* Raw output */
    tty.c_oflag &= ~OPOST;

    /* Disable software flow control and special handling of CR/NL */
    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK |
                     ISTRIP | INLCR | IGNCR | ICRNL);

    /* VMIN=0, VTIME=0 => non-blocking reads; we use select() for timeout */
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void timestamp_str(time_t ts, char *buf, size_t len)
{
    struct tm tm_info;
    if (localtime_r(&ts, &tm_info) == NULL) {
        snprintf(buf, len, "1970-01-01 00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        return EXIT_FAILURE;
    }

    char line_buf[LINE_BUF_SZ];
    size_t line_len = 0;
    char read_buf[READ_BUF_SZ];

    printf("AWR1642 range detection reader started on %s @ 115200 8N1.\n", UART_DEVICE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(g_uart_fd, &readfds);

        struct timeval tv;
        tv.tv_sec  = POLL_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int sel = select(g_uart_fd + 1, &readfds, NULL, NULL, &tv);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (sel == 0) {
            /* Timeout — no data for 2 s; check g_running */
            continue;
        }

        ssize_t n = read(g_uart_fd, read_buf, sizeof(read_buf));
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "read() error: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            /* Should not happen on a tty, but handle defensively */
            fprintf(stderr, "read() returned 0 (EOF on tty).\n");
            break;
        }

        for (ssize_t i = 0; i < n && g_running; i++) {
            char c = read_buf[i];

            if (c == '\n') {
                line_buf[line_len] = '\0';

                char *nl = strchr(line_buf, '\r');
                if (nl) *nl = '\0';

                char *comma = strchr(line_buf, ',');
                if (comma) {
                    *comma = '\0';
                    char *endptr = NULL;
                    time_t ts = (time_t)strtoll(line_buf, &endptr, 10);
                    if (endptr != line_buf) {
                        char ts_str[32];
                        timestamp_str(ts, ts_str, sizeof(ts_str));
                        printf("Timestamp: %s, Range: %.2f meters\n",
                               ts_str, strtof(comma + 1, &endptr));
                        fflush(stdout);
                    }
                }

                line_len = 0;
            } else if (c != '\r') {
                if (line_len < LINE_BUF_SZ - 1) {
                    line_buf[line_len++] = c;
                } else {
                    fprintf(stderr, "Line overflow, discarding.\n");
                    line_len = 0;
                }
            }
        }
    }

    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

