#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN   4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27

#define SERIAL_PORT       "/dev/ttyAMA0"
#define BAUD_RATE         115200
#define LOOP_DELAY_US     100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int g_serial_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", gpioInitialise());
        return -1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", MIDDLE_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int init_serial(void)
{
    g_serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (g_serial_fd < 0) {
        fprintf(stderr, "Error: failed to open serial port %s (code %d).\n",
                SERIAL_PORT, g_serial_fd);
        return -1;
    }
    return 0;
}

static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Warning: gpioRead failed on pin %d (code %d).\n", pin, value);
        return -1;
    }
    return value;
}

static void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static void check_emergency_stop(int left, int middle, int right)
{
    if (left == 0 && middle == 0 && right == 0) {
        printf("EMERGENCY STOP!\n");
        fflush(stdout);

        if (g_serial_fd >= 0) {
            int rc = serWrite(g_serial_fd, "EMERGENCY STOP!\n", 18);
            if (rc < 0) {
                fprintf(stderr, "Error: serial write failed (code %d).\n", rc);
            }
        }
    }
}

static void cleanup(void)
{
    if (g_serial_fd >= 0) {
        serClose(g_serial_fd);
        g_serial_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_serial() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor started.\n");
    printf("Left: GPIO%d, Middle: GPIO%d, Right: GPIO%d\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Serial port: %s @ %d baud\n", SERIAL_PORT, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int left   = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left >= 0 && middle >= 0 && right >= 0) {
            log_sensor_data(left, middle, right);
            check_emergency_stop(left, middle, right);
        } else {
            fprintf(stderr, "Warning: sensor read error, skipping cycle.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

