        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static void check_emergency_stop(int left, int middle, int right)
{
    if (left == 0 && middle == 0 && right == 0) {
        printf("EMERGENCY STOP!\n");
        fflush(stdout);

        if (g_serial_fd >= 0) {
            int rc = serWrite(g_serial_fd, "EMERGENCY STOP!\n", 18);
            if (rc < 0) {
                fprintf(stderr, "Error: serial write failed (code %d).\n", rc);
            }
        }
    }
}

static void cleanup(void)
{
    if (g_serial_fd >= 0) {
        serClose(g_serial_fd);
        g_serial_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    if (init_serial() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("KY-033 3-Way Tracking Sensor Monitor started.\n");
    printf("Left: GPIO%d, Middle: GPIO%d, Right: GPIO%d\n",
           LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN);
    printf("Serial port: %s @ %d baud\n", SERIAL_PORT, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int left   = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left >= 0 && middle >= 0 && right >= 0) {
            log_sensor_data(left, middle, right);
            check_emergency_stop(left, middle, right);
        } else {
            fprintf(stderr, "Warning: sensor read error, skipping cycle.\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}
